export const RACK_SOURCES = {
  iphone: "\"\"\"The iPhone side of the rack program: finding iPhones over USB and driving\none through WebDriverAgent, Apple's own test tool, the way uiautomator2\ndrives an Android.\n\nPhone farm file 08 (parts 48, 49 and 50). `promo_rack.py` never speaks to an\niPhone except through this file, and this file never speaks to Promo.\n\nHow it fits:\n\n- `list_iphones()` is the iPhone half of `promo_rack.list_phones()`: one dict\n  per iPhone, in the same shape adb's phones use, with `\"kind\": \"iphone\"`.\n- `IphoneScreen(udid)` is handed to `promo_rack.Walk` as its `device`. It\n  answers the same calls a uiautomator2 device does, so every step walk\n  works unchanged: `device(**selector)` finds an element, `device.click(x, y)`\n  taps, `device.swipe(...)`, `device.screenshot()` returns a PIL image,\n  `device.dump_hierarchy()` returns the screen as XML, `device.press(\"home\")`,\n  `device.app_start(bundle_id)`, `device.app_stop(bundle_id)`,\n  `device.send_keys(text)`, `device.window_size()`, `device.answers()`.\n- `vitals(udid)` is the iPhone half of the once-a-minute reading.\n- `wda_expires_at()` is when the WebDriverAgent signature runs out, for the\n  check-in. A free Apple ID signs it for 7 days (Tyler, 18 Oct 2026).\n\nTools on the rack computer:\n\n- pymobiledevice3, Apple's USB channel from Python, for the list, the\n  model, the iOS version, the time zone, battery, storage and uptime. It\n  works on a Mac and on Linux (through usbmuxd).\n- WebDriverAgent, built once by `install.sh` with Xcode and signed with the\n  rack owner's Apple ID, for reading and tapping the screen. The rack\n  starts it on each iPhone over USB with `xcodebuild test-without-building`\n  and the built `.xctestrun`, and talks to it over HTTP through a USB\n  tunnel that pymobiledevice3 opens (`usbmux forward`).\n\nElement selectors, mapped from uiautomator2's words:\n\n- `text` / `textMatches`: the element's label, name or value.\n- `resourceId` / `resourceIdMatches`: the accessibility identifier (`name`).\n- `className`: `android.widget.EditText` means a text field or text view;\n  anything else is matched against the XCUIElementType name.\n- `packageName`: the app the tree belongs to. WebDriverAgent gives the\n  frontmost app's tree, so this only checks that app is in front.\n- `description`: the label.\n\nUnits: WebDriverAgent measures the screen in points, and a screenshot comes\nin pixels, two or three to a point. Everything this file hands out (bounds,\nwindow size) and takes in (taps, swipes) is in pixels, the unit of the\nscreenshot, so `Walk.press` and the screen window land where they look.\n\nNothing here is proved except on a real iPhone: the tests stand in for\npymobiledevice3 and WebDriverAgent and prove the parts around them.\n\"\"\"\n\nimport atexit\nimport base64\nimport glob\nimport io\nimport json\nimport os\nimport re\nimport socket\nimport subprocess\nimport sys\nimport threading\nimport time\nimport xml.etree.ElementTree as ElementTree\nfrom datetime import datetime, timedelta\nfrom urllib import error as urlerror\nfrom urllib import request as urlrequest\n\nOLDEST_IOS = 17\n\n# WebDriverAgent listens on this port on the phone; the rack reaches it\n# through a USB tunnel on a free local port, one per phone.\nWDA_PORT = 8100\n# The first start of WebDriverAgent on a phone takes xcodebuild up to a\n# minute or so (it installs the runner, then boots it). Within this time the\n# phone is reported as connected and a job that arrives waits for it.\nDRIVER_START_GRACE_SECONDS = 90\n# A driver that died, or never answered, is started again no sooner than\n# this, so a dead signature does not run xcodebuild every 15 seconds.\nDRIVER_RETRY_SECONDS = 120\nHTTP_TIMEOUT_SECONDS = 30\nSTATUS_TIMEOUT_SECONDS = 3\nWAIT_STEP_SECONDS = 0.5\n\n# Apple's own model numbers, as lockdown's ProductType says them.\nMODEL_NAMES = {\n    \"iPhone12,1\": \"iPhone 11\",\n    \"iPhone12,3\": \"iPhone 11 Pro\",\n    \"iPhone12,5\": \"iPhone 11 Pro Max\",\n    \"iPhone12,8\": \"iPhone SE (2nd generation)\",\n    \"iPhone13,1\": \"iPhone 12 mini\",\n    \"iPhone13,2\": \"iPhone 12\",\n    \"iPhone13,3\": \"iPhone 12 Pro\",\n    \"iPhone13,4\": \"iPhone 12 Pro Max\",\n    \"iPhone14,2\": \"iPhone 13 Pro\",\n    \"iPhone14,3\": \"iPhone 13 Pro Max\",\n    \"iPhone14,4\": \"iPhone 13 mini\",\n    \"iPhone14,5\": \"iPhone 13\",\n    \"iPhone14,6\": \"iPhone SE (3rd generation)\",\n    \"iPhone14,7\": \"iPhone 14\",\n    \"iPhone14,8\": \"iPhone 14 Plus\",\n    \"iPhone15,2\": \"iPhone 14 Pro\",\n    \"iPhone15,3\": \"iPhone 14 Pro Max\",\n    \"iPhone15,4\": \"iPhone 15\",\n    \"iPhone15,5\": \"iPhone 15 Plus\",\n    \"iPhone16,1\": \"iPhone 15 Pro\",\n    \"iPhone16,2\": \"iPhone 15 Pro Max\",\n    \"iPhone17,1\": \"iPhone 16 Pro\",\n    \"iPhone17,2\": \"iPhone 16 Pro Max\",\n    \"iPhone17,3\": \"iPhone 16\",\n    \"iPhone17,4\": \"iPhone 16 Plus\",\n    \"iPhone17,5\": \"iPhone 16e\",\n}\n\n# uiautomator2's Android class names and the XCUIElementType names they mean.\nCLASS_NAMES = {\n    \"android.widget.EditText\": (\n        \"XCUIElementTypeTextField\",\n        \"XCUIElementTypeTextView\",\n        \"XCUIElementTypeSecureTextField\",\n        \"XCUIElementTypeSearchField\",\n    ),\n    \"android.widget.Button\": (\"XCUIElementTypeButton\",),\n    \"android.widget.ImageButton\": (\"XCUIElementTypeButton\",),\n    \"android.widget.TextView\": (\"XCUIElementTypeStaticText\",),\n    \"android.widget.ImageView\": (\"XCUIElementTypeImage\",),\n    \"android.widget.Switch\": (\"XCUIElementTypeSwitch\",),\n    \"android.widget.CheckBox\": (\"XCUIElementTypeSwitch\", \"XCUIElementTypeCheckBox\"),\n    \"android.widget.RadioButton\": (\"XCUIElementTypeRadioButton\",),\n    \"android.widget.ScrollView\": (\"XCUIElementTypeScrollView\", \"XCUIElementTypeTable\", \"XCUIElementTypeCollectionView\"),\n}\nSCROLLING_TYPES = (\"XCUIElementTypeScrollView\", \"XCUIElementTypeTable\", \"XCUIElementTypeCollectionView\")\nCHECKABLE_TYPES = (\"XCUIElementTypeSwitch\", \"XCUIElementTypeCheckBox\", \"XCUIElementTypeRadioButton\")\n\n\nclass IphoneError(RuntimeError):\n    \"\"\"Something the iPhone or WebDriverAgent refused, in words a log can show.\"\"\"\n\n\nclass _Refused(IphoneError):\n    \"\"\"WebDriverAgent answered with an error of its own, such as an invalid session.\"\"\"\n\n    def __init__(self, error, message):\n        IphoneError.__init__(self, \"%s: %s\" % (error, message) if message else str(error))\n        self.error = error or \"\"\n\n\nclass _NotTrusted(Exception):\n    \"\"\"The phone has not been told to trust this computer yet, or is locked.\"\"\"\n\n\ndef log(message):\n    stamp = time.strftime(\"%Y-%m-%d %H:%M:%S\")\n    print(\"%s %s\" % (stamp, message), flush=True)\n\n\n# The same folder promo_rack.py uses; the two lines are copied so this file\n# never imports it.\ndef _default_home():\n    if sys.platform == \"darwin\":\n        return os.path.expanduser(\"~/Library/Application Support/PromoRack\")\n    base = os.environ.get(\"XDG_DATA_HOME\") or os.path.expanduser(\"~/.local/share\")\n    return os.path.join(base, \"promo-rack\")\n\n\ndef rack_home():\n    return os.environ.get(\"PROMO_RACK_HOME\") or _default_home()\n\n\ndef wda_dir():\n    return os.path.join(rack_home(), \"WebDriverAgent\")\n\n\ndef wda_json_path():\n    return os.path.join(rack_home(), \"wda.json\")\n\n\ndef sign_hint():\n    return \"Run on the rack Mac: bash \\\"%s\\\"\" % os.path.join(rack_home(), \"wda.sh\")\n\n\n# ---------------------------------------------------------------------------\n# pymobiledevice3: the list, each phone's values, battery and storage. Every\n# call into it goes through one of these small functions so a test can stand\n# a fake in, and an Android-only rack without the package keeps working.\n\n_NO_TOOL_LOGGED = False\n\n\ndef _pymobiledevice3():\n    \"\"\"The pieces of pymobiledevice3 this file uses, or None when it is not\n    installed, which is logged once.\"\"\"\n    global _NO_TOOL_LOGGED\n    try:\n        from pymobiledevice3 import exceptions, usbmux\n        from pymobiledevice3.lockdown import create_using_usbmux\n    except ImportError:\n        if not _NO_TOOL_LOGGED:\n            log(\"pymobiledevice3 is not installed, so no iPhone is looked for. Run the install command again to add it.\")\n            _NO_TOOL_LOGGED = True\n        return None\n    return {\"exceptions\": exceptions, \"usbmux\": usbmux, \"create_using_usbmux\": create_using_usbmux}\n\n\ndef _pairing_errors(tool):\n    \"\"\"The exceptions pymobiledevice3 raises while a phone is not yet trusted\n    or is locked, whichever of them this version has.\"\"\"\n    names = (\n        \"NotTrustedError\", \"PairingError\", \"NotPairedError\", \"PasswordRequiredError\",\n        \"UserDeniedPairingError\", \"PairingDialogResponsePendingError\",\n    )\n    found = tuple(getattr(tool[\"exceptions\"], name) for name in names if hasattr(tool[\"exceptions\"], name))\n    return found or (Exception,)\n\n\ndef _usb_udids():\n    \"\"\"The UDIDs of the iPhones on USB, in the order usbmux lists them.\"\"\"\n    tool = _pymobiledevice3()\n    udids = []\n    for device in tool[\"usbmux\"].list_devices():\n        if str(getattr(device, \"connection_type\", \"USB\")).upper() != \"USB\":\n            continue\n        serial = getattr(device, \"serial\", \"\")\n        if serial and serial not in udids:\n            udids.append(serial)\n    return udids\n\n\ndef _open_lockdown(udid):\n    \"\"\"A lockdown connection to one phone. Asks the phone to trust this\n    computer when it does not yet, which puts the Trust dialog on its screen,\n    and raises _NotTrusted until the person taps Trust.\"\"\"\n    tool = _pymobiledevice3()\n    try:\n        return tool[\"create_using_usbmux\"](serial=udid, autopair=True)\n    except _pairing_errors(tool) as failure:\n        raise _NotTrusted(str(failure))\n\n\ndef _close(lockdown):\n    try:\n        lockdown.close()\n    except Exception:  # A fake, or a connection already gone.\n        pass\n\n\ndef _read_lockdown(udid):\n    \"\"\"ProductType, iOS version and time zone from the phone's lockdown values.\"\"\"\n    lockdown = _open_lockdown(udid)\n    try:\n        values = getattr(lockdown, \"all_values\", None) or {}\n        if not values:\n            values = {\n                key: lockdown.get_value(key=key)\n                for key in (\"ProductType\", \"ProductVersion\", \"TimeZone\")\n            }\n        return {\n            \"productType\": str(values.get(\"ProductType\") or \"\"),\n            \"android\": str(values.get(\"ProductVersion\") or \"\"),\n            \"timezone\": str(values.get(\"TimeZone\") or \"\"),\n        }\n    finally:\n        _close(lockdown)\n\n\ndef _diagnostics(lockdown):\n    from pymobiledevice3.services.diagnostics import DiagnosticsService\n    return DiagnosticsService(lockdown)\n\n\ndef _installation_proxy(lockdown):\n    from pymobiledevice3.services.installation_proxy import InstallationProxyService\n    return InstallationProxyService(lockdown)\n\n\n# The apps whose versions Promo tracks, by the bundle id Apple knows them by.\nTRACKED_APPS = {\n    \"com.reddit.Reddit\": \"reddit\",\n    \"com.burbn.instagram\": \"instagram\",\n    \"com.zhiliaoapp.musically\": \"tiktok\",\n    \"com.atebits.Tweetie2\": \"x\",\n    \"com.linkedin.LinkedIn\": \"linkedin\",\n}\n\n_NO_VERSIONS_LOGGED = set()\n\n\ndef app_versions(udid):\n    \"\"\"{\"reddit\": \"2024.40.0\", ...} for the tracked apps on the phone, read\n    through Apple's installation proxy; an app not installed is left out.\n    Never raises: None and one log line when the phone cannot be asked, so\n    a phone that cannot be read never looks like one that lost its apps.\"\"\"\n    global _NO_VERSIONS_LOGGED\n    try:\n        lockdown = _open_lockdown(udid)\n    except Exception as failure:\n        if udid not in _NO_VERSIONS_LOGGED:\n            log(\"Could not read app versions on iPhone %s: %s\" % (udid, failure))\n            _NO_VERSIONS_LOGGED.add(udid)\n        return None\n    try:\n        apps = _installation_proxy(lockdown).get_apps(application_type=\"User\", calculate_sizes=False)\n    except Exception as failure:\n        if udid not in _NO_VERSIONS_LOGGED:\n            log(\"Could not read app versions on iPhone %s: %s\" % (udid, failure))\n            _NO_VERSIONS_LOGGED.add(udid)\n        return None\n    finally:\n        _close(lockdown)\n    _NO_VERSIONS_LOGGED.discard(udid)\n    # Newer pymobiledevice3 answers {bundle id: info}; older ones a list of infos.\n    records = list(apps.values()) if isinstance(apps, dict) else list(apps or [])\n    versions = {}\n    for record in records:\n        if not isinstance(record, dict):\n            continue\n        name = TRACKED_APPS.get(str(record.get(\"CFBundleIdentifier\") or \"\"))\n        version = record.get(\"CFBundleShortVersionString\") or record.get(\"CFBundleVersion\")\n        if name and version:\n            versions[name] = str(version)\n    return versions\n\n\ndef restart(udid):\n    \"\"\"Restarts the phone through Apple's diagnostics channel.\"\"\"\n    try:\n        lockdown = _open_lockdown(udid)\n    except _NotTrusted as failure:\n        raise IphoneError(\"iPhone %s is not trusted or is locked, so it cannot be restarted: %s\" % (udid, failure))\n    except Exception as failure:\n        raise IphoneError(\"iPhone %s could not be reached to restart it: %s\" % (udid, failure))\n    try:\n        _diagnostics(lockdown).restart()\n    except Exception as failure:\n        raise IphoneError(\"iPhone %s refused the restart: %s\" % (udid, failure))\n    finally:\n        _close(lockdown)\n    with _LOCK:\n        _SESSIONS.pop(udid, None)\n\n\ndef model_name(product_type):\n    \"\"\"Apple's model number as a person says it, or the number itself.\"\"\"\n    return MODEL_NAMES.get(product_type or \"\", product_type or \"\")\n\n\ndef ios_major(version):\n    \"\"\"17 from \"17.6.1\"; None when the version cannot be read.\"\"\"\n    found = re.match(r\"^\\s*(\\d+)\", str(version or \"\"))\n    return int(found.group(1)) if found else None\n\n\n# Each phone's model, iOS version and time zone, read once while it stays plugged in.\n_VALUES = {}\n\n\ndef list_iphones():\n    \"\"\"One dict per iPhone plugged in, in the shape `promo_rack.parse_devices`\n    uses: serial (the UDID), state, usb (empty: Apple does not say the port),\n    model, android (the iOS version), timezone, kind \"iphone\".\n\n    state is \"device\" when trusted and WebDriverAgent answers,\n    \"unauthorized\" while the phone still asks Trust this computer,\n    \"too_old\" under iOS 17, and \"no_driver\" when WebDriverAgent cannot be\n    started or its signature has died.\n    \"\"\"\n    if _pymobiledevice3() is None:\n        return []\n    try:\n        udids = _usb_udids()\n    except Exception as failure:  # usbmuxd down, or the package half installed.\n        log(\"Could not list iPhones: %s\" % failure)\n        return []\n    phones = []\n    for udid in udids:\n        phone = {\"serial\": udid, \"state\": \"device\", \"usb\": \"\", \"model\": \"\", \"android\": \"\", \"timezone\": \"\", \"kind\": \"iphone\"}\n        try:\n            values = _VALUES.get(udid) or _read_lockdown(udid)\n        except _NotTrusted:\n            phone[\"state\"] = \"unauthorized\"\n            phones.append(phone)\n            continue\n        except Exception as failure:  # One bad phone must not hide the others.\n            log(\"Could not read iPhone %s: %s\" % (udid, failure))\n            continue\n        _VALUES[udid] = values\n        phone[\"model\"] = model_name(values.get(\"productType\"))\n        phone[\"android\"] = values.get(\"android\") or \"\"\n        phone[\"timezone\"] = values.get(\"timezone\") or \"\"\n        major = ios_major(phone[\"android\"])\n        if major is not None and major < OLDEST_IOS:\n            phone[\"state\"] = \"too_old\"\n        else:\n            try:\n                phone[\"state\"] = driver_state(udid)\n            except Exception as failure:  # Anything unforeseen in starting the driver.\n                log(\"WebDriverAgent on %s: %s\" % (udid, failure))\n                phone[\"state\"] = \"no_driver\"\n        phones.append(phone)\n    forget_missing(set(udids))\n    return phones\n\n\ndef forget_missing(present):\n    \"\"\"Drops what was kept for phones no longer plugged in: their values,\n    their session and their WebDriverAgent, whose tunnel is dead anyway.\"\"\"\n    for udid in list(_VALUES):\n        if udid not in present:\n            del _VALUES[udid]\n    with _LOCK:\n        for udid in list(_DRIVERS):\n            if udid not in present:\n                _stop_entry(_DRIVERS.pop(udid))\n                _SESSIONS.pop(udid, None)\n\n\n# ---------------------------------------------------------------------------\n# The signature\n\ndef wda_expires_at():\n    \"\"\"When the WebDriverAgent signature runs out, as an ISO 8601 string with\n    an offset, or None when it was never signed on this computer.\"\"\"\n    try:\n        with open(wda_json_path()) as handle:\n            record = json.load(handle)\n        signed_at = str(record[\"signedAt\"]).strip()\n        days = float(record.get(\"days\", 7))\n    except (OSError, ValueError, KeyError, TypeError):\n        return None\n    if signed_at.endswith(\"Z\"):\n        signed_at = signed_at[:-1] + \"+00:00\"\n    try:\n        signed = datetime.fromisoformat(signed_at)\n    except ValueError:\n        return None\n    if signed.tzinfo is None:\n        signed = signed.astimezone()\n    return (signed + timedelta(days=days)).isoformat()\n\n\n# ---------------------------------------------------------------------------\n# Vitals\n\ndef _percent(part, whole):\n    if not whole:\n        return None\n    return max(0, min(100, int(round(100.0 * part / whole))))\n\n\ndef _battery_percent(battery):\n    current = battery.get(\"CurrentCapacity\")\n    maximum = battery.get(\"MaxCapacity\")\n    if current is None:\n        return None\n    if maximum:\n        return _percent(float(current), float(maximum))\n    return max(0, min(100, int(round(float(current)))))\n\n\ndef _battery_temperature(battery):\n    \"\"\"AppleSmartBattery reports hundredths of a degree (2787 is 27.87 C).\"\"\"\n    raw = battery.get(\"Temperature\")\n    if raw is None:\n        return None\n    raw = float(raw)\n    if raw > 1000:\n        return round(raw / 100.0, 1)\n    if raw > 150:\n        return round(raw / 10.0, 1)\n    return round(raw, 1)\n\n\ndef _find_key(record, pattern):\n    \"\"\"The first value under a key matching the pattern, anywhere in a nest of dicts.\"\"\"\n    if isinstance(record, dict):\n        for key, value in record.items():\n            if re.search(pattern, str(key), re.I) and not isinstance(value, (dict, list)):\n                return value\n        for value in record.values():\n            found = _find_key(value, pattern)\n            if found is not None:\n                return found\n    elif isinstance(record, list):\n        for value in record:\n            found = _find_key(value, pattern)\n            if found is not None:\n                return found\n    return None\n\n\ndef vitals(udid):\n    \"\"\"Battery (percent and temperature), storage used (percent), uptime in\n    seconds. `signal` is \"not_reported\": Apple's channel does not give it.\"\"\"\n    reading = {\n        \"batteryPercent\": None,\n        \"temperatureC\": None,\n        \"storageUsedPercent\": None,\n        \"signal\": \"not_reported\",\n        \"upSeconds\": None,\n        \"apps\": None,\n    }\n    try:\n        lockdown = _open_lockdown(udid)\n    except Exception as failure:  # Unplugged, or not trusted yet: nothing can be read.\n        log(\"No reading from iPhone %s: %s\" % (udid, failure))\n        return reading\n    try:\n        try:\n            disk = lockdown.get_value(domain=\"com.apple.disk_usage\") or {}\n            total = float(disk.get(\"TotalDataCapacity\") or 0)\n            free = float(disk.get(\"TotalDataAvailable\") or 0)\n            reading[\"storageUsedPercent\"] = _percent(total - free, total) if total else None\n        except Exception as failure:\n            log(\"No storage reading from iPhone %s: %s\" % (udid, failure))\n        diagnostics = None\n        try:\n            diagnostics = _diagnostics(lockdown)\n        except Exception as failure:\n            log(\"No diagnostics on iPhone %s: %s\" % (udid, failure))\n        if diagnostics is not None:\n            try:\n                battery = diagnostics.get_battery() or {}\n                reading[\"batteryPercent\"] = _battery_percent(battery)\n                reading[\"temperatureC\"] = _battery_temperature(battery)\n            except Exception as failure:\n                log(\"No battery reading from iPhone %s: %s\" % (udid, failure))\n            try:\n                up = _find_key(diagnostics.info() or {}, r\"^up.?time$\")\n                reading[\"upSeconds\"] = int(float(up)) if up is not None else None\n            except Exception:  # Apple's diagnostics do not always say; None is the honest answer.\n                reading[\"upSeconds\"] = None\n    finally:\n        _close(lockdown)\n    return reading\n\n\n# ---------------------------------------------------------------------------\n# WebDriverAgent: started per phone with xcodebuild, reached through a USB\n# tunnel, one session per phone.\n\n_LOCK = threading.RLock()\n# udid -> {\"port\", \"started_at\", \"attempts\", \"process\", \"forward\", \"log\", \"gave_up\"}\n_DRIVERS = {}\n# udid -> WebDriverAgent session id\n_SESSIONS = {}\n\n\ndef _free_port():\n    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n    try:\n        sock.bind((\"127.0.0.1\", 0))\n        return sock.getsockname()[1]\n    finally:\n        sock.close()\n\n\ndef xctestrun_path():\n    \"\"\"The file xcodebuild wrote when install.sh built WebDriverAgent, or None.\"\"\"\n    found = sorted(glob.glob(os.path.join(wda_dir(), \"build\", \"Build\", \"Products\", \"WebDriverAgentRunner_iphoneos*.xctestrun\")))\n    return found[-1] if found else None\n\n\ndef _start_with_xcodebuild(udid, log_handle):\n    \"\"\"Starts WebDriverAgent on the phone from the build install.sh made.\n    Runs until stopped; its output goes to the phone's wda log.\"\"\"\n    xctestrun = xctestrun_path()\n    if not xctestrun:\n        raise IphoneError(\"WebDriverAgent is not built on this computer. %s\" % sign_hint())\n    command = [\n        \"xcodebuild\", \"test-without-building\",\n        \"-xctestrun\", xctestrun,\n        \"-destination\", \"id=%s\" % udid,\n    ]\n    return subprocess.Popen(command, stdout=log_handle, stderr=subprocess.STDOUT, cwd=wda_dir())\n\n\ndef _forward_with_pymobiledevice3(udid, local_port, log_handle):\n    \"\"\"A USB tunnel from a local port to WebDriverAgent's port on the phone.\"\"\"\n    command = [\n        sys.executable, \"-m\", \"pymobiledevice3\", \"usbmux\", \"forward\",\n        str(local_port), str(WDA_PORT), \"--udid\", udid,\n    ]\n    return subprocess.Popen(command, stdout=log_handle, stderr=subprocess.STDOUT)\n\n\n# Swapped for fakes by the tests; swap for another way of starting it here.\nSTART_DRIVER = _start_with_xcodebuild\nSTART_FORWARD = _forward_with_pymobiledevice3\n\n\ndef _alive(process):\n    return process is not None and process.poll() is None\n\n\ndef _stop_entry(entry):\n    for key in (\"process\", \"forward\"):\n        process = entry.get(key)\n        if _alive(process):\n            try:\n                process.terminate()\n            except Exception:\n                pass\n    handle = entry.get(\"log\")\n    if handle is not None:\n        try:\n            handle.close()\n        except Exception:\n            pass\n\n\ndef stop_drivers():\n    \"\"\"Stops every WebDriverAgent and tunnel this program started.\"\"\"\n    with _LOCK:\n        for udid in list(_DRIVERS):\n            _stop_entry(_DRIVERS.pop(udid))\n        _SESSIONS.clear()\n\n\natexit.register(stop_drivers)\n\n\ndef _ensure_driver(udid):\n    \"\"\"The driver record for a phone, starting WebDriverAgent and its tunnel\n    when there is none, or when the last one died and the retry wait is over.\"\"\"\n    with _LOCK:\n        now = time.time()\n        entry = _DRIVERS.get(udid)\n        if entry is not None:\n            if _alive(entry[\"process\"]) and not entry[\"gave_up\"]:\n                return entry\n            if now - entry[\"started_at\"] < DRIVER_RETRY_SECONDS:\n                return entry\n            _stop_entry(entry)\n            attempts = entry[\"attempts\"]\n        else:\n            attempts = 0\n        entry = {\n            \"port\": _free_port(), \"started_at\": now, \"attempts\": attempts + 1,\n            \"process\": None, \"forward\": None, \"log\": None, \"gave_up\": False, \"ready\": False,\n        }\n        _DRIVERS[udid] = entry\n        _SESSIONS.pop(udid, None)\n        # Written fresh on every start. Appending would grow it for good on a\n        # phone whose signature is dead and is retried every two minutes.\n        try:\n            entry[\"log\"] = open(os.path.join(rack_home(), \"wda-%s.log\" % udid), \"wb\")\n        except OSError:\n            entry[\"log\"] = None\n        output = entry[\"log\"] if entry[\"log\"] is not None else subprocess.DEVNULL\n        try:\n            entry[\"forward\"] = START_FORWARD(udid, entry[\"port\"], output)\n            entry[\"process\"] = START_DRIVER(udid, output)\n            log(\"Starting WebDriverAgent on %s through port %d (try %d).\" % (udid, entry[\"port\"], entry[\"attempts\"]))\n        except Exception as failure:\n            log(\"Could not start WebDriverAgent on %s: %s\" % (udid, failure))\n            entry[\"error\"] = str(failure)\n        return entry\n\n\ndef _status_ok(port):\n    try:\n        _http(port, \"GET\", \"/status\", timeout=STATUS_TIMEOUT_SECONDS)\n        return True\n    except IphoneError:\n        return False\n\n\ndef driver_state(udid):\n    \"\"\"\"device\" when WebDriverAgent answers on the phone, or is still on its\n    first start; \"no_driver\" when it died or never answered.\"\"\"\n    entry = _ensure_driver(udid)\n    if _status_ok(entry[\"port\"]):\n        entry[\"ready\"] = True\n        return \"device\"\n    entry[\"ready\"] = False\n    starting = _alive(entry[\"process\"]) and time.time() - entry[\"started_at\"] < DRIVER_START_GRACE_SECONDS\n    if starting and entry[\"attempts\"] == 1:\n        return \"device\"\n    if not starting:\n        entry[\"gave_up\"] = True\n    return \"no_driver\"\n\n\ndef _port(udid):\n    \"\"\"The local port WebDriverAgent answers on, waiting out its start. Once\n    it has answered, the port is handed back without asking again.\"\"\"\n    entry = _ensure_driver(udid)\n    if entry.get(\"ready\") and _alive(entry[\"process\"]):\n        return entry[\"port\"]\n    deadline = entry[\"started_at\"] + DRIVER_START_GRACE_SECONDS\n    while True:\n        if _status_ok(entry[\"port\"]):\n            entry[\"ready\"] = True\n            return entry[\"port\"]\n        if not _alive(entry[\"process\"]) or time.time() >= deadline:\n            entry[\"gave_up\"] = True\n            why = entry.get(\"error\") or \"it did not answer\"\n            raise IphoneError(\"WebDriverAgent is not running on %s (%s). %s\" % (udid, why, sign_hint()))\n        time.sleep(1)\n\n\ndef _http(port, method, path, body=None, timeout=HTTP_TIMEOUT_SECONDS):\n    \"\"\"One call to WebDriverAgent. Returns its whole JSON answer; an answer\n    that carries an error is raised as _Refused.\"\"\"\n    data = None\n    if method == \"POST\":\n        data = json.dumps(body if body is not None else {}).encode(\"utf-8\")\n    request = urlrequest.Request(\n        \"http://127.0.0.1:%d%s\" % (port, path), data=data, method=method,\n        headers={\"Content-Type\": \"application/json\", \"Accept\": \"application/json\"},\n    )\n    try:\n        with urlrequest.urlopen(request, timeout=timeout) as answer:\n            raw = answer.read()\n    except urlerror.HTTPError as failure:\n        raw = failure.read()\n    except (urlerror.URLError, socket.timeout, OSError, ValueError) as failure:\n        raise IphoneError(\"WebDriverAgent did not answer %s %s: %s\" % (method, path, failure))\n    try:\n        parsed = json.loads(raw.decode(\"utf-8\"))\n    except (ValueError, UnicodeDecodeError):\n        raise IphoneError(\"WebDriverAgent gave no JSON for %s %s: %s\" % (method, path, raw[:200]))\n    value = parsed.get(\"value\") if isinstance(parsed, dict) else None\n    if isinstance(value, dict) and value.get(\"error\"):\n        raise _Refused(value.get(\"error\"), value.get(\"message\"))\n    return parsed\n\n\ndef _session_id(udid, fresh=False):\n    \"\"\"The WebDriverAgent session for a phone, made on first use and remade\n    when WebDriverAgent says the old one is gone.\"\"\"\n    with _LOCK:\n        if not fresh and udid in _SESSIONS:\n            return _SESSIONS[udid]\n    port = _port(udid)\n    answer = _http(port, \"POST\", \"/session\", {\"capabilities\": {\"alwaysMatch\": {}}})\n    value = answer.get(\"value\") if isinstance(answer, dict) else None\n    session = (value or {}).get(\"sessionId\") if isinstance(value, dict) else None\n    session = session or (answer.get(\"sessionId\") if isinstance(answer, dict) else None)\n    if not session:\n        raise IphoneError(\"WebDriverAgent on %s opened no session: %s\" % (udid, str(answer)[:200]))\n    with _LOCK:\n        _SESSIONS[udid] = session\n    return session\n\n\ndef _invalid_session(failure):\n    \"\"\"WebDriverAgent's \"invalid session id\", or any error that says the session is gone.\"\"\"\n    error = failure.error.lower()\n    return \"invalid session\" in error or (\"session\" in error and \"not\" in error)\n\n\ndef _call(udid, method, path, body=None, timeout=HTTP_TIMEOUT_SECONDS):\n    \"\"\"One call under the phone's session, retried once on a fresh session\n    when WebDriverAgent says the old one is invalid.\"\"\"\n    session = _session_id(udid)\n    try:\n        return _http(_port(udid), method, \"/session/%s%s\" % (session, path), body, timeout)\n    except _Refused as failure:\n        if not _invalid_session(failure):\n            raise\n        session = _session_id(udid, fresh=True)\n        return _http(_port(udid), method, \"/session/%s%s\" % (session, path), body, timeout)\n\n\ndef _value(answer):\n    return answer.get(\"value\") if isinstance(answer, dict) else answer\n\n\n# ---------------------------------------------------------------------------\n# The screen tree, in the shape promo_rack.py's Android readers expect.\n\ndef _number(text):\n    try:\n        return float(text)\n    except (TypeError, ValueError):\n        return 0.0\n\n\ndef convert_source(source_xml, scale, package=\"\"):\n    \"\"\"WebDriverAgent's source XML as uiautomator XML: one <node> per element\n    under <hierarchy>, with text, resource-id, class, package, content-desc\n    and bounds in pixels, and label, name, value and type kept as they were.\"\"\"\n    root = ElementTree.fromstring(source_xml)\n    hierarchy = ElementTree.Element(\"hierarchy\", {\"rotation\": \"0\"})\n    _convert_node(root, hierarchy, scale, package, 0)\n    return ElementTree.tostring(hierarchy, encoding=\"unicode\")\n\n\ndef _convert_node(source, parent, scale, package, index):\n    attributes = source.attrib\n    element_type = attributes.get(\"type\") or source.tag\n    label = attributes.get(\"label\") or \"\"\n    name = attributes.get(\"name\") or \"\"\n    value = attributes.get(\"value\") or \"\"\n    x, y = _number(attributes.get(\"x\")), _number(attributes.get(\"y\"))\n    width, height = _number(attributes.get(\"width\")), _number(attributes.get(\"height\"))\n    left, top = int(round(x * scale)), int(round(y * scale))\n    right, bottom = int(round((x + width) * scale)), int(round((y + height) * scale))\n    checkable = element_type in CHECKABLE_TYPES\n    node = ElementTree.SubElement(parent, \"node\", {\n        \"index\": str(index),\n        \"text\": label or value or name,\n        \"resource-id\": name,\n        \"class\": element_type,\n        \"package\": package or \"\",\n        \"content-desc\": label,\n        \"label\": label,\n        \"name\": name,\n        \"value\": value,\n        \"type\": element_type,\n        \"enabled\": attributes.get(\"enabled\", \"true\"),\n        \"visible\": attributes.get(\"visible\", \"true\"),\n        \"checkable\": \"true\" if checkable else \"false\",\n        \"checked\": \"true\" if checkable and value in (\"1\", \"true\", \"on\") else \"false\",\n        \"scrollable\": \"true\" if element_type in SCROLLING_TYPES else \"false\",\n        \"bounds\": \"[%d,%d][%d,%d]\" % (left, top, right, bottom),\n    })\n    for child_index, child in enumerate(source):\n        _convert_node(child, node, scale, package, child_index)\n\n\ndef parse_bounds(text):\n    \"\"\"\"[l,t][r,b]\" as the dict uiautomator2's element.info[\"bounds\"] holds.\"\"\"\n    found = re.match(r\"^\\[(-?\\d+),(-?\\d+)\\]\\[(-?\\d+),(-?\\d+)\\]$\", text or \"\")\n    if not found:\n        return {\"left\": 0, \"top\": 0, \"right\": 0, \"bottom\": 0}\n    left, top, right, bottom = (int(part) for part in found.groups())\n    return {\"left\": left, \"top\": top, \"right\": right, \"bottom\": bottom}\n\n\ndef _class_matches(wanted, element_type):\n    names = CLASS_NAMES.get(wanted)\n    if names:\n        return element_type in names\n    return element_type == wanted or element_type == \"XCUIElementType\" + wanted\n\n\ndef _truth(value):\n    return \"true\" if value in (True, \"true\", \"True\", 1, \"1\") else \"false\"\n\n\ndef matches(node, selector):\n    \"\"\"True when one converted node answers every word of a uiautomator2 selector.\"\"\"\n    text, label, name = node.get(\"text\", \"\"), node.get(\"content-desc\", \"\"), node.get(\"resource-id\", \"\")\n    for key, wanted in selector.items():\n        if key == \"instance\":\n            continue\n        if key == \"text\":\n            ok = text == str(wanted)\n        elif key == \"textMatches\":\n            ok = re.fullmatch(str(wanted), text) is not None\n        elif key == \"textContains\":\n            ok = str(wanted) in text\n        elif key == \"textStartsWith\":\n            ok = text.startswith(str(wanted))\n        elif key == \"description\":\n            ok = label == str(wanted)\n        elif key == \"descriptionMatches\":\n            ok = re.fullmatch(str(wanted), label) is not None\n        elif key == \"descriptionContains\":\n            ok = str(wanted) in label\n        elif key == \"descriptionStartsWith\":\n            ok = label.startswith(str(wanted))\n        elif key == \"resourceId\":\n            ok = name == str(wanted)\n        elif key == \"resourceIdMatches\":\n            ok = re.fullmatch(str(wanted), name) is not None\n        elif key == \"className\":\n            ok = _class_matches(str(wanted), node.get(\"class\", \"\"))\n        elif key == \"classNameMatches\":\n            ok = re.fullmatch(str(wanted), node.get(\"class\", \"\")) is not None\n        elif key == \"packageName\":\n            ok = node.get(\"package\", \"\") == str(wanted)\n        elif key in (\"scrollable\", \"checkable\", \"checked\", \"enabled\"):\n            ok = node.get(key, \"false\") == _truth(wanted)\n        elif key == \"index\":\n            ok = node.get(\"index\") == str(wanted)\n        else:\n            raise IphoneError(\"The selector word %r has no iPhone meaning.\" % key)\n        if not ok:\n            return False\n    return True\n\n\ndef find_nodes(nodes, selector):\n    return [node for node in nodes if matches(node, selector)]\n\n\ndef nodes_of(hierarchy_xml):\n    \"\"\"Every node's attributes, in screen order.\"\"\"\n    return [dict(node.attrib) for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\")]\n\n\ndef _image_from_png(data):\n    from PIL import Image\n    image = Image.open(io.BytesIO(data))\n    image.load()\n    return image\n\n\n# ---------------------------------------------------------------------------\n# Touch: W3C actions, which WebDriverAgent takes at /actions. Points, not pixels.\n\ndef tap_actions(x, y):\n    return {\"actions\": [{\n        \"type\": \"pointer\", \"id\": \"finger\", \"parameters\": {\"pointerType\": \"touch\"},\n        \"actions\": [\n            {\"type\": \"pointerMove\", \"duration\": 0, \"x\": x, \"y\": y},\n            {\"type\": \"pointerDown\", \"button\": 0},\n            {\"type\": \"pause\", \"duration\": 60},\n            {\"type\": \"pointerUp\", \"button\": 0},\n        ],\n    }]}\n\n\ndef swipe_actions(x1, y1, x2, y2, duration_ms, hold_ms=0):\n    steps = [\n        {\"type\": \"pointerMove\", \"duration\": 0, \"x\": x1, \"y\": y1},\n        {\"type\": \"pointerDown\", \"button\": 0},\n        {\"type\": \"pause\", \"duration\": 50},\n        {\"type\": \"pointerMove\", \"duration\": int(duration_ms), \"x\": x2, \"y\": y2},\n    ]\n    if hold_ms:\n        steps.append({\"type\": \"pause\", \"duration\": int(hold_ms)})\n    steps.append({\"type\": \"pointerUp\", \"button\": 0})\n    return {\"actions\": [{\"type\": \"pointer\", \"id\": \"finger\", \"parameters\": {\"pointerType\": \"touch\"}, \"actions\": steps}]}\n\n\nclass _Scroll(object):\n    \"\"\"`element.scroll.forward()` and friends, as uiautomator2 spells them:\n    a swipe inside the element, the way a thumb scrolls a list.\"\"\"\n\n    def __init__(self, element):\n        self.element = element\n\n    @property\n    def vert(self):\n        return self\n\n    def _swipe(self, start, end):\n        bounds = self.element.info[\"bounds\"]\n        x = (bounds[\"left\"] + bounds[\"right\"]) / 2.0\n        height = bounds[\"bottom\"] - bounds[\"top\"]\n        self.element.screen.swipe(x, bounds[\"top\"] + height * start, x, bounds[\"top\"] + height * end, 0.4)\n        return True\n\n    def forward(self, steps=None):\n        return self._swipe(0.75, 0.3)\n\n    def backward(self, steps=None):\n        return self._swipe(0.3, 0.75)\n\n    def toBeginning(self, steps=None, max_swipes=10):\n        for _ in range(max_swipes):\n            self.backward()\n        return True\n\n    def toEnd(self, steps=None, max_swipes=10):\n        for _ in range(max_swipes):\n            self.forward()\n        return True\n\n\nclass IphoneElement(object):\n    \"\"\"One element on an iPhone's screen, answering like a uiautomator2 element.\"\"\"\n\n    def __init__(self, screen, selector):\n        self.screen = screen\n        self.selector = dict(selector)\n\n    def _find(self):\n        found = find_nodes(self.screen._nodes(), self.selector)\n        instance = int(self.selector.get(\"instance\", 0) or 0)\n        return found[instance] if len(found) > instance else None\n\n    def _found(self):\n        node = self._find()\n        if node is None:\n            raise IphoneError(\"Nothing on the screen matches %s.\" % json.dumps(self.selector))\n        return node\n\n    @property\n    def exists(self):\n        return self._find() is not None\n\n    @property\n    def info(self):\n        \"\"\"At least {\"bounds\": {\"left\", \"top\", \"right\", \"bottom\"}, \"text\": ...}.\"\"\"\n        node = self._found()\n        info = dict(node)\n        info[\"bounds\"] = parse_bounds(node.get(\"bounds\"))\n        info[\"className\"] = node.get(\"class\", \"\")\n        info[\"resourceName\"] = node.get(\"resource-id\", \"\")\n        info[\"contentDescription\"] = node.get(\"content-desc\", \"\")\n        info[\"packageName\"] = node.get(\"package\", \"\")\n        return info\n\n    @property\n    def scroll(self):\n        return _Scroll(self)\n\n    def wait(self, timeout=10):\n        deadline = time.time() + timeout\n        while True:\n            if self.exists:\n                return True\n            if time.time() >= deadline:\n                return False\n            time.sleep(WAIT_STEP_SECONDS)\n\n    def click(self):\n        bounds = self.info[\"bounds\"]\n        self.screen.click((bounds[\"left\"] + bounds[\"right\"]) / 2.0, (bounds[\"top\"] + bounds[\"bottom\"]) / 2.0)\n\n    def get_text(self):\n        return self._found().get(\"text\", \"\")\n\n    def set_text(self, text):\n        self.click()\n        time.sleep(0.3)\n        self._erase()\n        if text:\n            self.screen.send_keys(text)\n\n    def clear_text(self):\n        self.click()\n        time.sleep(0.3)\n        self._erase()\n\n    def _erase(self):\n        \"\"\"Backspaces over what the field holds. A text field's value is its\n        contents; its label is the placeholder, which is not erased.\"\"\"\n        node = self._found()\n        length = len(node.get(\"value\") or \"\")\n        if length:\n            self.screen.send_keys(\"\\b\" * (length + 2))\n\n\nclass IphoneScreen(object):\n    \"\"\"One iPhone's screen through WebDriverAgent, answering like a uiautomator2 device.\"\"\"\n\n    def __init__(self, udid):\n        self.udid = udid\n        self._scale = None\n        self._points = None\n\n    def _call(self, method, path, body=None, timeout=HTTP_TIMEOUT_SECONDS):\n        return _value(_call(self.udid, method, path, body, timeout))\n\n    def __call__(self, **selector):\n        return IphoneElement(self, selector)\n\n    def active_app(self):\n        \"\"\"The bundle id of the app in front, or \"\" when WebDriverAgent cannot say.\"\"\"\n        try:\n            return str((self._call(\"GET\", \"/wda/activeAppInfo\") or {}).get(\"bundleId\") or \"\")\n        except Exception:  # Older WebDriverAgent, or nothing in front.\n            return \"\"\n\n    def answers(self):\n        \"\"\"True when WebDriverAgent on this phone answers GET /status right\n        now, within STATUS_TIMEOUT_SECONDS. Nothing cached counts, so a\n        driver that died since the last call says False. A phone whose\n        driver was never started says False too.\"\"\"\n        with _LOCK:\n            entry = _DRIVERS.get(self.udid)\n        if entry is None:\n            return False\n        return _status_ok(entry[\"port\"])\n\n    def _nodes(self):\n        return nodes_of(self.dump_hierarchy())\n\n    def _size_in_points(self):\n        if self._points is None:\n            size = self._call(\"GET\", \"/window/size\") or {}\n            self._points = (float(size.get(\"width\") or 0), float(size.get(\"height\") or 0))\n        return self._points\n\n    def scale(self):\n        \"\"\"Pixels per point: WebDriverAgent says it, or the screenshot's width\n        over the window's width says it.\"\"\"\n        if self._scale:\n            return self._scale\n        try:\n            self._scale = float((self._call(\"GET\", \"/wda/screen\") or {})[\"scale\"])\n        except Exception:\n            width = self._size_in_points()[0]\n            image = self.screenshot()\n            self._scale = (image.width / width) if width else 1.0\n        if not self._scale or self._scale <= 0:\n            self._scale = 1.0\n        return self._scale\n\n    def click(self, x, y):\n        scale = self.scale()\n        self._call(\"POST\", \"/actions\", tap_actions(x / scale, y / scale))\n\n    def swipe(self, x1, y1, x2, y2, duration=0.3):\n        self._swipe(x1, y1, x2, y2, duration)\n\n    def _swipe(self, x1, y1, x2, y2, duration=0.3, hold=0):\n        scale = self.scale()\n        self._call(\"POST\", \"/actions\", swipe_actions(\n            x1 / scale, y1 / scale, x2 / scale, y2 / scale, duration * 1000, hold * 1000,\n        ))\n\n    def screenshot(self):\n        \"\"\"A PIL image of the screen, in the phone's own pixels.\"\"\"\n        encoded = self._call(\"GET\", \"/screenshot\")\n        if not isinstance(encoded, str) or not encoded:\n            raise IphoneError(\"WebDriverAgent on %s gave no picture.\" % self.udid)\n        return _image_from_png(base64.b64decode(encoded))\n\n    def dump_hierarchy(self):\n        \"\"\"The screen as XML, each element a node with text, label, name,\n        value, type and bounds attributes, so the same readers work.\"\"\"\n        source = self._call(\"GET\", \"/source?format=xml\")\n        if not isinstance(source, str) or not source.strip():\n            raise IphoneError(\"WebDriverAgent on %s gave no screen tree.\" % self.udid)\n        return convert_source(source, self.scale(), self.active_app())\n\n    def window_size(self):\n        width, height = self._size_in_points()\n        scale = self.scale()\n        return int(round(width * scale)), int(round(height * scale))\n\n    def press(self, key):\n        \"\"\"\"home\", \"back\" (the swipe in from the left edge), \"recents\" (the\n        swipe up and hold), \"enter\", \"delete\".\"\"\"\n        if key == \"home\":\n            self._call(\"POST\", \"/wda/homescreen\")\n        elif key == \"back\":\n            width, height = self.window_size()\n            self._swipe(2, height / 2.0, width * 0.4, height / 2.0, 0.3)\n        elif key == \"recents\":\n            width, height = self.window_size()\n            self._swipe(width / 2.0, height - 1, width / 2.0, height * 0.55, 0.4, hold=0.6)\n        elif key == \"enter\":\n            self.send_keys(\"\\n\")\n        elif key == \"delete\":\n            self.send_keys(\"\\b\")\n        else:\n            raise IphoneError(\"An iPhone has no %r key.\" % key)\n\n    def screen_on(self):\n        \"\"\"Wakes the screen. A phone with a passcode stays on its lock screen.\"\"\"\n        try:\n            self._call(\"POST\", \"/wda/unlock\", timeout=10)\n        except IphoneError as failure:\n            log(\"Could not wake %s: %s\" % (self.udid, failure))\n\n    def app_start(self, bundle_id):\n        self._call(\"POST\", \"/wda/apps/launch\", {\"bundleId\": bundle_id, \"shouldWaitForQuiescence\": False})\n\n    def app_stop(self, bundle_id):\n        self._call(\"POST\", \"/wda/apps/terminate\", {\"bundleId\": bundle_id})\n\n    def open_url(self, url):\n        \"\"\"Opens an address in Safari, or in the app that owns it.\"\"\"\n        self._call(\"POST\", \"/url\", {\"url\": url})\n\n    def send_keys(self, text, clear=False):\n        \"\"\"Types into the focused field, any letter or emoji. `clear` is\n        uiautomator2's word for emptying the field first.\"\"\"\n        if clear:\n            self.send_keys(\"\\b\" * 60)\n        self._call(\"POST\", \"/wda/keys\", {\"value\": list(str(text))})\n",
  install: "#!/bin/bash\n# Installs Promo's rack program on the computer the phones plug into, pairs it\n# with one code from its rack's page in Promo, and sets it up to start with the\n# computer. Promo serves this file at /api/rack/install.sh with its own\n# address written in below. Run it again with a new code to pair afresh.\n#\n#   curl -fsSL https://promo.example/api/rack/install.sh | bash -s -- ABCD-EFGH\n#\n# Everything goes in one folder of the person's own: nothing needs sudo except\n# keeping a Linux service running while nobody is signed in.\nset -euo pipefail\n\nPROMO_URL=\"__PROMO_URL__\"\nCODE=\"${1:-}\"\nUIAUTOMATOR2_VERSION=\"3.7.0\"\n# The iPhone tools: Apple's USB channel from Python, and WebDriverAgent,\n# the test tool that reads and taps an iPhone's screen. Both need a Mac\n# with Xcode for the signing; a Linux rack drives Androids only.\nPYMOBILEDEVICE3_VERSION=\"11.34.1\"\n# WDA_VERSION is only words for the messages. A tag can be moved, so the\n# download is pinned to one commit and refused if what arrived is any other.\nWDA_VERSION=\"v16.15.3\"\n# The commit the v16.15.3 tag pointed at on 18 Oct 2026, so a moved tag can never change what gets signed.\nWDA_COMMIT=\"02cb92f0e93c8b021443bcbb8eeb80932c113220\"\nWDA_REPO=\"https://github.com/appium/WebDriverAgent.git\"\n\nif [ -z \"$CODE\" ]; then\n  echo \"Give the code from the rack's page in Promo: ... | bash -s -- ABCD-EFGH\" >&2\n  exit 1\nfi\n\ncase \"$(uname -s)\" in\n  Darwin)\n    RACK_HOME=\"$HOME/Library/Application Support/PromoRack\"\n    TOOLS_ZIP=\"platform-tools-latest-darwin.zip\"\n    ;;\n  Linux)\n    RACK_HOME=\"${XDG_DATA_HOME:-$HOME/.local/share}/promo-rack\"\n    TOOLS_ZIP=\"platform-tools-latest-linux.zip\"\n    ;;\n  *)\n    echo \"The rack program runs on macOS or Linux.\" >&2\n    exit 1\n    ;;\nesac\nmkdir -p \"$RACK_HOME\"\n\nif ! command -v python3 >/dev/null 2>&1; then\n  echo \"Python 3 is missing. On a Mac run: xcode-select --install. On Linux: sudo apt install python3 python3-venv\" >&2\n  exit 1\nfi\nif ! python3 -c 'import sys; sys.exit(0 if sys.version_info >= (3, 9) else 1)'; then\n  echo \"Python 3.9 or newer is needed. This computer has $(python3 --version).\" >&2\n  exit 1\nfi\n\n# Android's own USB tools, kept in the rack's folder so nothing else changes.\nif [ ! -x \"$RACK_HOME/platform-tools/adb\" ]; then\n  if ! command -v unzip >/dev/null 2>&1; then\n    echo \"unzip is missing. On Linux run: sudo apt install unzip\" >&2\n    exit 1\n  fi\n  echo \"Downloading Android's platform tools...\"\n  curl -fsSL \"https://dl.google.com/android/repository/$TOOLS_ZIP\" -o \"$RACK_HOME/platform-tools.zip\"\n  (cd \"$RACK_HOME\" && unzip -q -o platform-tools.zip && rm platform-tools.zip)\nfi\n\necho \"Setting up Python...\"\nif [ ! -x \"$RACK_HOME/venv/bin/python\" ]; then\n  python3 -m venv \"$RACK_HOME/venv\"\nfi\n\"$RACK_HOME/venv/bin/pip\" install --quiet --disable-pip-version-check \"uiautomator2==$UIAUTOMATOR2_VERSION\"\n\necho \"Downloading the rack program...\"\ncurl -fsSL \"$PROMO_URL/api/rack/launcher.py\" -o \"$RACK_HOME/launcher.py\"\ncurl -fsSL \"$PROMO_URL/api/rack/program.py\" -o \"$RACK_HOME/incoming.py\"\n# The iPhone driver sits beside the program, whichever computer this is; an\n# Android-only rack simply never imports it.\ncurl -fsSL \"$PROMO_URL/api/rack/iphone.py\" -o \"$RACK_HOME/incoming_iphone.py\"\n\nexport PROMO_RACK_HOME=\"$RACK_HOME\"\n\"$RACK_HOME/venv/bin/python\" \"$RACK_HOME/launcher.py\" pair \\\n  --url \"$PROMO_URL\" --code \"$CODE\" --program \"$RACK_HOME/incoming.py\" --driver \"$RACK_HOME/incoming_iphone.py\"\nrm -f \"$RACK_HOME/incoming.py\" \"$RACK_HOME/incoming_iphone.py\"\n\nPYTHON=\"$RACK_HOME/venv/bin/python\"\nLAUNCHER=\"$RACK_HOME/launcher.py\"\nTOOLS_PATH=\"$RACK_HOME/platform-tools:/usr/bin:/bin:/usr/sbin:/sbin\"\n\nif [ \"$(uname -s)\" = \"Darwin\" ]; then\n  PLIST=\"$HOME/Library/LaunchAgents/com.systemeverything.promo-rack.plist\"\n  mkdir -p \"$HOME/Library/LaunchAgents\"\n  cat > \"$PLIST\" <<PLIST\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\">\n<dict>\n  <key>Label</key><string>com.systemeverything.promo-rack</string>\n  <key>ProgramArguments</key>\n  <array><string>$PYTHON</string><string>$LAUNCHER</string><string>run</string></array>\n  <key>EnvironmentVariables</key>\n  <dict>\n    <key>PROMO_RACK_HOME</key><string>$RACK_HOME</string>\n    <key>PATH</key><string>$TOOLS_PATH</string>\n  </dict>\n  <key>RunAtLoad</key><true/>\n  <key>KeepAlive</key><true/>\n  <key>StandardOutPath</key><string>$RACK_HOME/rack.log</string>\n  <key>StandardErrorPath</key><string>$RACK_HOME/rack.log</string>\n</dict>\n</plist>\nPLIST\n  launchctl bootout \"gui/$(id -u)/com.systemeverything.promo-rack\" >/dev/null 2>&1 || true\n  launchctl bootstrap \"gui/$(id -u)\" \"$PLIST\"\n  echo \"Started. It starts again by itself whenever you sign in to this Mac. Its log is $RACK_HOME/rack.log\"\nelse\n  UNIT_DIR=\"${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user\"\n  mkdir -p \"$UNIT_DIR\"\n  cat > \"$UNIT_DIR/promo-rack.service\" <<UNIT\n[Unit]\nDescription=Promo rack program\nAfter=network-online.target\n\n[Service]\nEnvironment=PROMO_RACK_HOME=$RACK_HOME\nEnvironment=PATH=$TOOLS_PATH\nExecStart=$PYTHON $LAUNCHER run\nRestart=always\nRestartSec=5\n\n[Install]\nWantedBy=default.target\nUNIT\n  systemctl --user daemon-reload\n  systemctl --user enable --now promo-rack.service\n  if ! loginctl enable-linger \"$USER\" >/dev/null 2>&1; then\n    echo \"To keep it running when nobody is signed in, run once: sudo loginctl enable-linger $USER\"\n  fi\n  echo \"Started. It starts again by itself with the computer. Its log: journalctl --user -u promo-rack\"\nfi\n\n# ---------------------------------------------------------------------------\n# iPhones. Only a Mac with Xcode (the full app, not just the command line\n# tools) can sign WebDriverAgent, so anything else prints why and moves on.\n# The Android install above is finished by now, so nothing here can break it.\n\nhas_xcode() {\n  [ \"$(uname -s)\" = \"Darwin\" ] || return 1\n  local developer_dir\n  developer_dir=\"$(xcode-select -p 2>/dev/null || true)\"\n  case \"$developer_dir\" in\n    *Xcode.app*) xcodebuild -version >/dev/null 2>&1 ;;\n    *) return 1 ;;\n  esac\n}\n\n# Fetches the one pinned commit into $WDA_DIR and refuses to go on if what\n# is checked out is any other commit, so a moved tag or a wrong fetch can\n# never put a different WebDriverAgent on the rack.\nfetch_wda_commit() {\n  git -C \"$WDA_DIR\" fetch --quiet --depth 1 origin \"$WDA_COMMIT\"\n  git -C \"$WDA_DIR\" checkout --quiet FETCH_HEAD\n  local checked_out\n  checked_out=\"$(git -C \"$WDA_DIR\" rev-parse HEAD)\"\n  if [ \"$checked_out\" != \"$WDA_COMMIT\" ]; then\n    echo \"WebDriverAgent is not the pinned version: wanted commit $WDA_COMMIT, got $checked_out. Nothing was built.\" >&2\n    exit 1\n  fi\n}\n\n# The script a person runs to sign WebDriverAgent with their Apple ID, and\n# again every week when the free signature runs out. Written here so the\n# install command stays one file.\nwrite_wda_script() {\n  cat > \"$RACK_HOME/wda.sh\" <<'WDA'\n#!/bin/bash\n# Builds WebDriverAgent and signs it with the Apple ID set up in Xcode, so\n# the rack can read and tap the iPhones. A free Apple ID's signature lasts\n# 7 days; run this again when the rack's page in Promo says it is running out:\n#\n#   bash ~/Library/Application\\ Support/PromoRack/wda.sh\n#\n# The first time, with no Apple ID in Xcode yet, it opens the project in\n# Xcode and says what to click. `--quiet` (used by the install command)\n# never opens Xcode; it builds if signing is set up and otherwise prints\n# the command to run.\nset -euo pipefail\n\nRACK_HOME=\"$(cd \"$(dirname \"$0\")\" && pwd)\"\nWDA=\"$RACK_HOME/WebDriverAgent\"\nPROJECT=\"$WDA/WebDriverAgent.xcodeproj\"\nTEAM_FILE=\"$RACK_HOME/wda-team.txt\"\nBUILD_LOG=\"$RACK_HOME/wda-build.log\"\nQUIET=0\n[ \"${1:-}\" = \"--quiet\" ] && QUIET=1\n\nif [ ! -d \"$PROJECT\" ]; then\n  echo \"WebDriverAgent is not downloaded. Run the install command from the rack's page in Promo again.\" >&2\n  exit 1\nfi\nif ! xcodebuild -version >/dev/null 2>&1; then\n  echo \"Xcode is not installed, or the command line tools are selected instead of it.\" >&2\n  echo \"Install Xcode from the App Store, open it once, then run: sudo xcode-select -s /Applications/Xcode.app\" >&2\n  exit 1\nfi\n\n# The team is the Apple ID's own ten-letter id, read off the signing\n# certificate Xcode made when the Apple ID was added, and kept in a file so\n# a second certificate later does not change it.\nTEAM=\"$(cat \"$TEAM_FILE\" 2>/dev/null || true)\"\nif [ -z \"$TEAM\" ]; then\n  TEAM=\"$(security find-identity -v -p codesigning 2>/dev/null \\\n    | grep 'Apple Development' | head -1 | sed -n 's/.*(\\([A-Z0-9]\\{10\\}\\)).*/\\1/p' || true)\"\nfi\nif [ -z \"$TEAM\" ]; then\n  if [ \"$QUIET\" = 1 ]; then\n    echo \"No Apple ID is set up in Xcode yet, so WebDriverAgent is not signed and iPhones cannot be driven.\"\n    echo \"To drive iPhones, run: bash \\\"$RACK_HOME/wda.sh\\\"\"\n    exit 0\n  fi\n  echo \"Xcode has no Apple ID yet. Opening WebDriverAgent in Xcode. In Xcode:\"\n  echo \"  1. Xcode > Settings > Accounts, press +, pick Apple ID, and sign in. A free Apple ID is fine.\"\n  echo \"  2. In the left list, click the WebDriverAgent project, then WebDriverAgentRunner under Targets.\"\n  echo \"  3. Open Signing & Capabilities, tick Automatically manage signing, and choose your name as the Team.\"\n  echo \"  4. Close Xcode and run this again: bash \\\"$RACK_HOME/wda.sh\\\"\"\n  open \"$PROJECT\"\n  exit 0\nfi\necho \"$TEAM\" > \"$TEAM_FILE\"\n\n# A free Apple ID needs its own bundle id, and its signature only runs on\n# phones it has registered, so every iPhone plugged in now is registered\n# before the final build.\nBUNDLE_ID=\"com.promorack.$(echo \"$TEAM\" | tr '[:upper:]' '[:lower:]').WebDriverAgentRunner\"\nbuild() {\n  xcodebuild build-for-testing \\\n    -project \"$PROJECT\" -scheme WebDriverAgentRunner \\\n    -derivedDataPath \"$WDA/build\" \\\n    -allowProvisioningUpdates \"$@\" \\\n    DEVELOPMENT_TEAM=\"$TEAM\" CODE_SIGN_STYLE=Automatic \\\n    PRODUCT_BUNDLE_IDENTIFIER=\"$BUNDLE_ID\" \\\n    >> \"$BUILD_LOG\" 2>&1\n}\n\n: > \"$BUILD_LOG\"\nUDIDS=\"$(\"$RACK_HOME/venv/bin/python\" -c '\nfrom pymobiledevice3 import usbmux\nfor device in usbmux.list_devices():\n    if device.connection_type == \"USB\":\n        print(device.serial)\n' 2>/dev/null || true)\"\nfor UDID in $UDIDS; do\n  echo \"Registering the iPhone $UDID with the Apple ID...\"\n  if ! build -destination \"id=$UDID\" -allowProvisioningDeviceRegistration; then\n    echo \"Could not register $UDID; the last lines of $BUILD_LOG:\"\n    tail -20 \"$BUILD_LOG\"\n    echo \"If the phone shows Trust this computer, tap Trust and run this again.\"\n    exit 1\n  fi\ndone\n\necho \"Building WebDriverAgent signed by $TEAM (a few minutes the first time)...\"\nif ! build -destination 'generic/platform=iOS'; then\n  echo \"The build failed; the last lines of $BUILD_LOG:\"\n  tail -30 \"$BUILD_LOG\"\n  echo \"If Xcode asks for the Apple ID's password or a two-factor code, open the project once in Xcode, finish signing there, and run this again.\"\n  exit 1\nfi\nif ! ls \"$WDA\"/build/Build/Products/WebDriverAgentRunner_iphoneos*.xctestrun >/dev/null 2>&1; then\n  echo \"The build finished but wrote no .xctestrun file; see $BUILD_LOG\" >&2\n  exit 1\nfi\nprintf '{\"signedAt\": \"%s\", \"days\": 7}\\n' \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\" > \"$RACK_HOME/wda.json\"\necho \"WebDriverAgent is signed. A free Apple ID's signature runs out in 7 days; the rack's page in Promo will say when to run this again.\"\necho \"An iPhone plugged in after this needs registering: run this script again with it plugged in.\"\nWDA\n  chmod +x \"$RACK_HOME/wda.sh\"\n}\n\nif has_xcode; then\n  echo \"Setting up the iPhone tools...\"\n  \"$RACK_HOME/venv/bin/pip\" install --quiet --disable-pip-version-check \"pymobiledevice3==$PYMOBILEDEVICE3_VERSION\"\n  if ! command -v git >/dev/null 2>&1; then\n    echo \"git is missing, so WebDriverAgent was not downloaded. Run: xcode-select --install, then the install command again.\"\n  else\n    WDA_DIR=\"$RACK_HOME/WebDriverAgent\"\n    if [ ! -d \"$WDA_DIR/.git\" ]; then\n      echo \"Downloading WebDriverAgent $WDA_VERSION...\"\n      mkdir -p \"$WDA_DIR\"\n      git -C \"$WDA_DIR\" init --quiet\n      git -C \"$WDA_DIR\" remote add origin \"$WDA_REPO\"\n      fetch_wda_commit\n    elif [ \"$(git -C \"$WDA_DIR\" rev-parse HEAD 2>/dev/null || true)\" != \"$WDA_COMMIT\" ]; then\n      echo \"Moving WebDriverAgent to $WDA_VERSION...\"\n      fetch_wda_commit\n      rm -rf \"$WDA_DIR/build\"\n    fi\n    write_wda_script\n    bash \"$RACK_HOME/wda.sh\" --quiet || echo \"WebDriverAgent did not build; see $RACK_HOME/wda-build.log. To try again, run: bash \\\"$RACK_HOME/wda.sh\\\"\"\n    echo \"To drive iPhones, or to re-sign WebDriverAgent when its week is up, run: bash \\\"$RACK_HOME/wda.sh\\\"\"\n  fi\nelif [ \"$(uname -s)\" = \"Darwin\" ]; then\n  echo \"iPhones: skipped. Driving an iPhone needs Xcode (the full app from the App Store, not only the command line tools) to sign WebDriverAgent.\"\n  echo \"Install Xcode, open it once, run: sudo xcode-select -s /Applications/Xcode.app, and run this install command again.\"\nelse\n  echo \"iPhones: skipped. Driving an iPhone needs a Mac with Xcode to sign WebDriverAgent; this rack drives Androids only.\"\nfi\necho \"The rack shows as checking in on its page in Promo within a minute.\"\n",
  launcher: "#!/usr/bin/env python3\n\"\"\"Keeps Promo's rack program running, and undoes a bad update by itself.\n\nThe service the install command sets up starts this file, never the program\ndirectly. It runs whichever version state.json names as current. After an\nupdate, the new version has two minutes to check in with Promo. If it stops\nfirst, or is still running without having checked in, this goes back to the\nversion before it, never tries that version again, and leaves a note the\nprogram reports to Promo on its next check-in, so the Phones dashboard says\nwhat happened.\n\nThis file is deliberately small and is not updated from Promo: it is the part\nthat has to keep working when a new version does not.\n\nCommands:\n  launcher.py run\n  launcher.py pair --url URL --code CODE --program PATH [--name NAME]\n  launcher.py selftest-rollback   (installs a version that cannot start, to\n                                   watch the rollback happen)\n\"\"\"\n\nimport argparse\nimport json\nimport os\nimport re\nimport shutil\nimport signal\nimport subprocess\nimport sys\nimport time\n\nEXIT_SWITCH = 75\nCHECK_IN_GRACE_SECONDS = 120\nBROKEN_VERSION = \"0.0.0-broken\"\n\n\ndef default_home():\n    if sys.platform == \"darwin\":\n        return os.path.expanduser(\"~/Library/Application Support/PromoRack\")\n    base = os.environ.get(\"XDG_DATA_HOME\") or os.path.expanduser(\"~/.local/share\")\n    return os.path.join(base, \"promo-rack\")\n\n\nHOME = os.environ.get(\"PROMO_RACK_HOME\") or default_home()\nSTATE_PATH = os.path.join(HOME, \"state.json\")\n\n\ndef log(message):\n    print(\"%s launcher: %s\" % (time.strftime(\"%Y-%m-%d %H:%M:%S\"), message), flush=True)\n\n\ndef load_state():\n    try:\n        with open(STATE_PATH, \"r\", encoding=\"utf-8\") as handle:\n            return json.load(handle)\n    except (OSError, ValueError):\n        return {}\n\n\ndef save_state(state):\n    temporary = \"%s.%d.tmp\" % (STATE_PATH, os.getpid())\n    with open(temporary, \"w\", encoding=\"utf-8\") as handle:\n        json.dump(state, handle, indent=2)\n    os.replace(temporary, STATE_PATH)\n\n\ndef program_path(version):\n    return os.path.join(HOME, \"versions\", version, \"promo_rack.py\")\n\n\ndef roll_back(bad, why):\n    \"\"\"Goes back to the version before `bad` and never offers `bad` again.\"\"\"\n    state = load_state()\n    previous = state.get(\"previous\")\n    failed = [version for version in (state.get(\"failed\") or []) if version != bad] + [bad]\n    if not previous or not os.path.exists(program_path(previous)):\n        log(\"%s failed (%s) and there is no earlier version to go back to.\" % (bad, why))\n        state.update(pending=None, failed=failed)\n        save_state(state)\n        return False\n    state.update(\n        current=previous,\n        previous=None,\n        pending=None,\n        failed=failed,\n        rolledBack={\n            \"from\": bad,\n            \"to\": previous,\n            \"at\": time.strftime(\"%Y-%m-%dT%H:%M:%SZ\", time.gmtime()),\n            \"why\": why,\n        },\n    )\n    save_state(state)\n    log(\"Went back to %s because %s %s.\" % (previous, bad, why))\n    return True\n\n\ndef run():\n    # A stop sent to the launcher, by the service manager or a person, stops\n    # the program with it, so a second copy is never left running alone.\n    running = {\"process\": None}\n\n    def stop(signum, frame):\n        process = running[\"process\"]\n        if process is not None and process.poll() is None:\n            process.terminate()\n            try:\n                process.wait(timeout=10)\n            except subprocess.TimeoutExpired:\n                process.kill()\n        raise SystemExit(0)\n\n    signal.signal(signal.SIGTERM, stop)\n    signal.signal(signal.SIGINT, stop)\n\n    failures = 0\n    while True:\n        state = load_state()\n        version = state.get(\"current\")\n        if not version or not os.path.exists(program_path(version)):\n            log(\"No program to run. Run the install command from the Phones dashboard.\")\n            time.sleep(60)\n            continue\n        pending = state.get(\"pending\") or {}\n        watching = pending.get(\"version\") == version\n        since = float(pending.get(\"since\") or time.time())\n\n        started = time.time()\n        process = subprocess.Popen([sys.executable, program_path(version), \"run\"])\n        running[\"process\"] = process\n        rolled = False\n        while process.poll() is None:\n            time.sleep(2)\n            if not watching:\n                continue\n            if load_state().get(\"checkedIn\") == version:\n                watching = False\n                log(\"%s checked in. Keeping it.\" % version)\n            elif time.time() - since > CHECK_IN_GRACE_SECONDS:\n                process.terminate()\n                try:\n                    process.wait(timeout=10)\n                except subprocess.TimeoutExpired:\n                    process.kill()\n                rolled = roll_back(version, \"did not check in within two minutes\")\n                break\n\n        if rolled:\n            failures = 0\n            continue\n        code = process.returncode\n        if code == EXIT_SWITCH:\n            failures = 0\n            continue\n        if watching and load_state().get(\"checkedIn\") != version:\n            if roll_back(version, \"stopped with code %s before it checked in\" % code):\n                failures = 0\n                continue\n        # A crash after a good start: start it again, waiting longer each time\n        # it crashes quickly, up to a minute.\n        failures = failures + 1 if time.time() - started < 60 else 1\n        wait = min(60, 2 ** min(failures, 6))\n        log(\"The program stopped with code %s. Starting it again in %d seconds.\" % (code, wait))\n        time.sleep(wait)\n\n\ndef version_of(path):\n    with open(path, \"r\", encoding=\"utf-8\") as handle:\n        found = re.search(r'^VERSION = \"([^\"]+)\"', handle.read(), re.M)\n    if not found:\n        raise SystemExit(\"%s does not say which version it is.\" % path)\n    return found.group(1)\n\n\ndef pair(url, code, program, name, driver=\"\"):\n    \"\"\"Puts the downloaded program in place, with the iPhone driver beside it\n    when one was downloaded, and lets it pair itself.\"\"\"\n    version = version_of(program)\n    folder = os.path.dirname(program_path(version))\n    os.makedirs(folder, exist_ok=True)\n    shutil.copyfile(program, program_path(version))\n    if driver and os.path.exists(driver):\n        shutil.copyfile(driver, os.path.join(folder, \"iphone.py\"))\n    command = [sys.executable, program_path(version), \"pair\", \"--url\", url, \"--code\", code]\n    if name:\n        command += [\"--name\", name]\n    raise SystemExit(subprocess.call(command))\n\n\ndef selftest_rollback():\n    \"\"\"Switches to a version that stops at once, so the rollback can be watched.\"\"\"\n    state = load_state()\n    current = state.get(\"current\")\n    if not current:\n        raise SystemExit(\"This rack is not paired yet.\")\n    folder = os.path.dirname(program_path(BROKEN_VERSION))\n    os.makedirs(folder, exist_ok=True)\n    with open(program_path(BROKEN_VERSION), \"w\", encoding=\"utf-8\") as handle:\n        handle.write('VERSION = \"%s\"\\nraise SystemExit(\"This version is broken on purpose.\")\\n' % BROKEN_VERSION)\n    state.update(\n        previous=current,\n        current=BROKEN_VERSION,\n        pending={\"version\": BROKEN_VERSION, \"since\": time.time()},\n        failed=[version for version in (state.get(\"failed\") or []) if version != BROKEN_VERSION],\n    )\n    save_state(state)\n    print(\n        \"Switched to %s. The launcher should go back to %s within a minute, and the Phones dashboard \"\n        \"says so after the next check-in.\" % (BROKEN_VERSION, current)\n    )\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Keeps Promo's rack program running.\")\n    commands = parser.add_subparsers(dest=\"command\", required=True)\n    commands.add_parser(\"run\")\n    pairing = commands.add_parser(\"pair\")\n    pairing.add_argument(\"--url\", required=True)\n    pairing.add_argument(\"--code\", required=True)\n    pairing.add_argument(\"--program\", required=True)\n    pairing.add_argument(\"--name\", default=\"\")\n    pairing.add_argument(\"--driver\", default=\"\")\n    commands.add_parser(\"selftest-rollback\")\n    arguments = parser.parse_args()\n    os.makedirs(HOME, exist_ok=True)\n    if arguments.command == \"pair\":\n        pair(arguments.url, arguments.code, arguments.program, arguments.name, arguments.driver)\n    elif arguments.command == \"selftest-rollback\":\n        selftest_rollback()\n    else:\n        run()\n\n\nif __name__ == \"__main__\":\n    main()\n",
  program: "#!/usr/bin/env python3\n\"\"\"Promo's rack program: the only thing that touches the phones.\n\nIt runs on the computer the phones are plugged into, at home. It dials out to\nPromo, so no port is ever opened at the house. Every 15 seconds it tells Promo\nwhich phones adb can see, and every few seconds it asks for the next action.\nOnly the actions named in ACTIONS below are ever run; any other name is\nrefused. Every message both ways is signed with the key this rack was given\nwhen it was paired, and a reply without the right signature is thrown away.\n\nThreads besides the main loop's own: each action runs on a thread of its\nown, so two phones work side by side (Promo hands a phone one action at a\ntime); one sends the screens of the phones someone is watching, a few\npictures a second, and carries their taps back; and one reads each phone's\nbattery, heat, storage and signal once a minute, restarting a phone that has\nstopped answering.\n\nEvery action keeps a picture of each step. An app that freezes during an\naction is closed and opened again, and a phone that stops answering is\nrestarted; the action itself is never run again here, because Promo decides\nwhat is tried twice and a comment never is. After any app action the screen\nis checked for the app's suspended, locked and \"confirm it's you\" screens.\n\nReddit runs through the Reddit app itself: who is signed in, the account's\nhealth and the comment, answering in the browser's own shapes. Instagram and\nTikTok run only here, in their apps: who is signed in, the daily reading with\nthe Account status page, the profile, a post, and reading and answering\nmessages and comments, which the phones' own notifications say have arrived. Taps land a\nlittle off the middle of a button, swipes bend, and typing keeps a person's\nrhythm. The setup check reads what a platform could notice about a phone\n(Wi-Fi beside a SIM, location allowed, a clock or language from another\ncountry, apps updating themselves, the address the internet sees), and the\nwipe erases a phone through its own Settings before it gets a new account.\n\nCommands:\n  promo_rack.py pair --url https://promo.example --code ABCD-EFGH [--name \"Rack\"]\n  promo_rack.py run\n  promo_rack.py phones        (prints what adb sees, for checking by hand)\n\nIt is written for the Python that ships with macOS (3.9) and for Linux, using\nonly the standard library, except uiautomator2, which reads phone screens and\nis only imported by the actions that need it. iPhones are driven through the\nfile beside this one, iphone.py (phone farm file 08), which owns every word\nspoken to pymobiledevice3 and WebDriverAgent; this file only asks it for the\nlist of iPhones, a screen that answers like a uiautomator2 device, the\nminute's reading, each app's version when it offers that, and when the\nWebDriverAgent signature runs out. A rack without that file, or with a\ndriver that fails, lists no iPhones and says so once in the log. On an\niPhone the three apps run through their own iOS buttons (APP_SCREENS, keyed\nby bundle id), the setup check reads iOS's Settings and Safari, updates come\nfrom the App Store, a wipe is refused until Promo says the Apple ID is\nsigned out, and a post's file reaches Photos through a one-time link opened\nin Safari, since a computer cannot drop a file into an iPhone's Photos.\n\nThe launcher beside it (launcher.py) starts this file, swaps in a new version\nwhen Promo offers one, and goes back to the old one if the new one does not\ncheck in within two minutes. The file's own VERSION is the only version there\nis: Promo reads it out of the same file it serves.\n\"\"\"\n\nimport argparse\nimport base64\nimport calendar\nimport collections\nimport hashlib\nimport hmac\nimport io\nimport json\nimport math\nimport os\nimport platform\nimport random\nimport re\nimport secrets\nimport shutil\nimport subprocess\nimport sys\nimport threading\nimport time\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nimport xml.etree.ElementTree as ElementTree\n\n# The iPhone driver lives beside this file. A rack without it is an\n# adb-only rack, exactly as before iPhones joined; nothing below may fail\n# because it is missing.\ntry:\n    import iphone\n    _IPHONE_IMPORT_ERROR = None\nexcept Exception as _failure:  # A missing file, or one its own imports break.\n    iphone = None\n    _IPHONE_IMPORT_ERROR = _failure\n\nVERSION = \"2026.11.26.1\"\n\n# The launcher restarts the program when it exits with this code: a new\n# version was written, or someone switched versions on disk.\nEXIT_SWITCH = 75\n\n# How often to ask for work when there is none. Check-ins are less often.\nPOLL_SECONDS = 3\nDEFAULT_CHECK_IN_SECONDS = 15\n\n# A signed reply whose clock is further off than this is refused.\nCLOCK_WINDOW_SECONDS = 300\n\nHTTP_TIMEOUT_SECONDS = 30\n\n# Screenshots are shrunk to this width before they are sent.\nSCREENSHOT_WIDTH = 540\n\n\ndef default_home():\n    if sys.platform == \"darwin\":\n        return os.path.expanduser(\"~/Library/Application Support/PromoRack\")\n    base = os.environ.get(\"XDG_DATA_HOME\") or os.path.expanduser(\"~/.local/share\")\n    return os.path.join(base, \"promo-rack\")\n\n\nHOME = os.environ.get(\"PROMO_RACK_HOME\") or default_home()\nCONFIG_PATH = os.path.join(HOME, \"config.json\")\nSTATE_PATH = os.path.join(HOME, \"state.json\")\n# Where the Mac's LaunchAgent (rack/install.sh) sends this program's output.\n# On Linux the journal holds it and there is no file.\nLOG_PATH = os.path.join(HOME, \"rack.log\")\n\n\ndef log(message):\n    stamp = time.strftime(\"%Y-%m-%d %H:%M:%S\")\n    print(\"%s %s\" % (stamp, message), flush=True)\n\n\n# ---------------------------------------------------------------------------\n# Files on disk\n\ndef read_json(path, fallback):\n    try:\n        with open(path, \"r\", encoding=\"utf-8\") as handle:\n            return json.load(handle)\n    except (OSError, ValueError):\n        return fallback\n\n\ndef write_json(path, value, private=False):\n    \"\"\"Writes through a temporary file and a rename, so a reader never sees half.\"\"\"\n    os.makedirs(os.path.dirname(path), exist_ok=True)\n    temporary = \"%s.%d.tmp\" % (path, os.getpid())\n    with open(temporary, \"w\", encoding=\"utf-8\") as handle:\n        json.dump(value, handle, indent=2)\n    if private:\n        os.chmod(temporary, 0o600)\n    os.replace(temporary, path)\n\n\ndef load_state():\n    return read_json(STATE_PATH, {})\n\n\ndef update_state(**changes):\n    state = load_state()\n    state.update(changes)\n    write_json(STATE_PATH, state)\n    return state\n\n\n# ---------------------------------------------------------------------------\n# Signing. The same rule as src/server/phones/signing.ts.\n\ndef sha256_hex(data):\n    return hashlib.sha256(data).hexdigest()\n\n\ndef request_signature(key, method, path, stamp, nonce, body):\n    canonical = \"\\n\".join([method, path, str(stamp), nonce, sha256_hex(body)])\n    return hmac.new(key.encode(\"utf-8\"), canonical.encode(\"utf-8\"), hashlib.sha256).hexdigest()\n\n\ndef reply_signature(key, status, nonce, stamp, body):\n    canonical = \"\\n\".join([\"reply\", str(status), nonce, str(stamp), sha256_hex(body)])\n    return hmac.new(key.encode(\"utf-8\"), canonical.encode(\"utf-8\"), hashlib.sha256).hexdigest()\n\n\nclass Refused(Exception):\n    \"\"\"Promo refused this rack: a cancelled key, a used code, a bad signature.\"\"\"\n\n\nclass CallFailed(Exception):\n    \"\"\"Promo could not be reached, or answered with something not to be trusted.\"\"\"\n\n\ndef call(config, path, payload):\n    \"\"\"One signed request to Promo, and its reply checked before it is read.\"\"\"\n    body = json.dumps(payload).encode(\"utf-8\")\n    stamp = int(time.time())\n    nonce = secrets.token_hex(16)\n    request = urllib.request.Request(\n        config[\"url\"].rstrip(\"/\") + path,\n        data=body,\n        method=\"POST\",\n        headers={\n            \"content-type\": \"application/json\",\n            \"x-rack-id\": config[\"rackId\"],\n            \"x-rack-time\": str(stamp),\n            \"x-rack-nonce\": nonce,\n            \"x-rack-signature\": request_signature(config[\"key\"], \"POST\", path, stamp, nonce, body),\n        },\n    )\n    try:\n        with urllib.request.urlopen(request, timeout=HTTP_TIMEOUT_SECONDS) as response:\n            status = response.status\n            text = response.read()\n            headers = response.headers\n    except urllib.error.HTTPError as error:\n        text = error.read()\n        if error.code == 401:\n            raise Refused(answer_message(text) or \"Promo refused this rack.\")\n        status = error.code\n        headers = error.headers\n    except (urllib.error.URLError, OSError) as error:\n        raise CallFailed(\"Could not reach Promo: %s\" % error)\n\n    signature = headers.get(\"x-promo-signature\") or \"\"\n    reply_stamp = headers.get(\"x-promo-time\") or \"\"\n    if not signature or not reply_stamp.isdigit():\n        # A refusal before Promo knew which rack this was carries no\n        # signature. Its words are logged and nothing is acted on.\n        if status >= 400:\n            raise CallFailed(answer_message(text) or \"Promo answered %s with %d.\" % (path, status))\n        raise CallFailed(\"Promo's reply to %s was not signed, so it was ignored.\" % path)\n    expected = reply_signature(config[\"key\"], status, nonce, reply_stamp, text)\n    if not hmac.compare_digest(signature, expected):\n        raise CallFailed(\"Promo's reply to %s had the wrong signature, so it was ignored.\" % path)\n    if abs(int(time.time()) - int(reply_stamp)) > CLOCK_WINDOW_SECONDS:\n        raise CallFailed(\"Promo's reply to %s was too old, so it was ignored.\" % path)\n\n    try:\n        parsed = json.loads(text.decode(\"utf-8\")) if text else {}\n    except ValueError:\n        raise CallFailed(\"Promo's reply to %s was not JSON.\" % path)\n    if status >= 400:\n        raise CallFailed(parsed.get(\"error\") or \"Promo answered %s with %d.\" % (path, status))\n    return parsed\n\n\ndef answer_message(text):\n    try:\n        return json.loads(text.decode(\"utf-8\")).get(\"error\", \"\")\n    except (ValueError, AttributeError):\n        return \"\"\n\n\n# ---------------------------------------------------------------------------\n# adb\n\ndef adb_path():\n    configured = os.environ.get(\"PROMO_RACK_ADB\")\n    if configured:\n        return configured\n    bundled = os.path.join(HOME, \"platform-tools\", \"adb\")\n    if os.path.exists(bundled):\n        return bundled\n    found = shutil.which(\"adb\")\n    if found:\n        return found\n    raise RuntimeError(\"adb is not installed on this computer. Run the install command again.\")\n\n\ndef adb(args, serial=None, timeout=30):\n    command = [adb_path()] + ([\"-s\", serial] if serial else []) + list(args)\n    completed = subprocess.run(command, capture_output=True, text=True, timeout=timeout)\n    if completed.returncode != 0:\n        raise RuntimeError((completed.stderr or completed.stdout).strip() or \"adb failed\")\n    return completed.stdout\n\n\ndef shell(serial, command, timeout=30):\n    return adb([\"shell\", command], serial=serial, timeout=timeout).strip()\n\n\ndef parse_devices(output):\n    \"\"\"`adb devices -l`, one dict per line: serial, adb's state, USB port, model.\"\"\"\n    phones = []\n    for line in output.splitlines():\n        line = line.strip()\n        if not line or line.startswith(\"List of devices\") or line.startswith(\"*\"):\n            continue\n        parts = line.split()\n        if len(parts) < 2:\n            continue\n        fields = dict(part.split(\":\", 1) for part in parts[2:] if \":\" in part)\n        phones.append({\n            \"serial\": parts[0],\n            \"state\": parts[1],\n            \"usb\": (\"usb:\" + fields[\"usb\"]) if \"usb\" in fields else \"\",\n            \"model\": fields.get(\"model\", \"\").replace(\"_\", \" \"),\n            \"android\": \"\",\n            \"kind\": \"android\",\n        })\n    return phones\n\n\n# Each phone's model, system version and time zone, read once while it stays\n# plugged in. An iPhone's come with the driver's list and are kept here too,\n# so phone/android-version can check the screen against them.\n_PROPS = {}\n\n# Which kind each serial is, \"android\" or \"iphone\", filled by list_phones()\n# and never emptied, so a running action still knows its phone's kind after\n# the phone is unplugged mid-way.\n_KINDS = {}\n\n# Failures of the iPhone driver already written to the log, so a rack\n# without iPhones does not say so every 15 seconds.\n_IPHONE_WARNED = set()\n\n\ndef is_iphone(serial):\n    return _KINDS.get(serial) == \"iphone\"\n\n\ndef warn_once(key, words):\n    if key not in _IPHONE_WARNED:\n        _IPHONE_WARNED.add(key)\n        log(words)\n\n\ndef list_iphones_safely():\n    \"\"\"The driver's list of iPhones, or none when there is no driver or it\n    fails, said once in the log. The Android list never waits on this.\"\"\"\n    if iphone is None:\n        warn_once(\"import\", \"The iPhone driver (iphone.py) is not beside the program, so no iPhones are listed: %s\" % _IPHONE_IMPORT_ERROR)\n        return []\n    try:\n        phones = [dict(phone) for phone in (iphone.list_iphones() or []) if isinstance(phone, dict) and phone.get(\"serial\")]\n    except Exception as failure:  # The driver's own trouble; the Androids are still listed.\n        warn_once(\"list\", \"The iPhone driver could not list iPhones, so none are listed: %s\" % (str(failure) or failure.__class__.__name__))\n        return []\n    _IPHONE_WARNED.discard(\"list\")\n    for phone in phones:\n        phone[\"kind\"] = \"iphone\"\n        for key in (\"state\", \"usb\", \"model\", \"android\"):\n            phone.setdefault(key, \"\")\n    return phones\n\n\ndef wda_expires_at():\n    \"\"\"When WebDriverAgent's signature runs out, for the check-in, or None\n    when there is no driver, it was never signed, or the driver cannot say.\"\"\"\n    if iphone is None:\n        return None\n    try:\n        value = iphone.wda_expires_at()\n    except Exception as failure:  # Not knowing is answered as unknown, never as a crash.\n        warn_once(\"wda\", \"The iPhone driver could not say when WebDriverAgent's signature runs out: %s\" % (str(failure) or failure.__class__.__name__))\n        return None\n    _IPHONE_WARNED.discard(\"wda\")\n    return str(value) if value else None\n\n\ndef list_phones():\n    androids = parse_devices(adb([\"devices\", \"-l\"], timeout=15))\n    for phone in androids:\n        _KINDS[phone[\"serial\"]] = \"android\"\n    iphones = list_iphones_safely()\n    for phone in iphones:\n        _KINDS[phone[\"serial\"]] = \"iphone\"\n    phones = restarting_as_such(androids + iphones)\n    present = set()\n    for phone in phones:\n        serial = phone[\"serial\"]\n        present.add(serial)\n        if phone[\"state\"] != \"device\":\n            continue\n        if phone.get(\"kind\") == \"iphone\":\n            _PROPS[serial] = {key: str(phone.get(key) or \"\") for key in (\"model\", \"android\", \"timezone\")}\n            continue\n        if serial not in _PROPS:\n            try:\n                _PROPS[serial] = {\n                    \"model\": shell(serial, \"getprop ro.product.model\", timeout=10),\n                    \"android\": shell(serial, \"getprop ro.build.version.release\", timeout=10),\n                    \"timezone\": shell(serial, \"getprop persist.sys.timezone\", timeout=10),\n                }\n            except (RuntimeError, subprocess.TimeoutExpired):\n                continue\n        phone.update({key: value for key, value in _PROPS[serial].items() if value})\n    # A phone unplugged and plugged back may have been updated in between.\n    for serial in list(_PROPS):\n        if serial not in present:\n            del _PROPS[serial]\n    for serial in list(_IPHONE_SCREENS):\n        if serial not in present:\n            _IPHONE_SCREENS.pop(serial, None)\n    return phones\n\n\ndef iphone_system_version(serial):\n    \"\"\"The iOS version the phone itself reports over USB, from the last list.\"\"\"\n    version = _PROPS.get(serial, {}).get(\"android\", \"\")\n    if not version:\n        for phone in list_iphones_safely():\n            if phone[\"serial\"] == serial:\n                version = str(phone.get(\"android\") or \"\")\n    return version\n\n\n# ---------------------------------------------------------------------------\n# Steps. Every action that touches the screen walks it as named steps, each\n# with a small picture, so a failed one shows where it stopped. The self-test\n# walks the same steps with `rehearse` on, and `final` (the Post, Send or\n# Share button) then only finds the button and never presses it.\n\nclass Cancelled(Exception):\n    \"\"\"The action was given up on because the phone or app froze; nothing more is pressed.\"\"\"\n\n\nclass StepFailed(RuntimeError):\n    \"\"\"A step could not find what it was looking for on the screen.\"\"\"\n\n    def __init__(self, step, why):\n        RuntimeError.__init__(self, why)\n        self.step = step\n\n\n# One screen object per iPhone, shared by every helper below and the screen\n# window, dropped when the phone leaves the list.\n_IPHONE_SCREENS = {}\n\n\ndef iphone_screen(serial):\n    \"\"\"The iPhone's screen through the driver, which answers like a uiautomator2 device.\"\"\"\n    if iphone is None:\n        raise RuntimeError(\"The iPhone driver (iphone.py) is not beside the program, so %s cannot be driven.\" % serial)\n    screen = _IPHONE_SCREENS.get(serial)\n    if screen is None:\n        screen = iphone.IphoneScreen(serial)\n        _IPHONE_SCREENS[serial] = screen\n    return screen\n\n\ndef connect_screen(serial):\n    if is_iphone(serial):\n        return iphone_screen(serial)\n    try:\n        import uiautomator2\n    except ImportError:\n        raise RuntimeError(\"uiautomator2 is not installed on the rack. Run the install command again.\")\n    return uiautomator2.connect(serial)\n\n\ndef wake_screen(device):\n    \"\"\"Turns the screen on: uiautomator2's screen_on, or the iPhone driver's,\n    which is WebDriverAgent's unlock.\"\"\"\n    device.screen_on()\n\n\ndef screenshot_jpeg(device):\n    image = device.screenshot()\n    if image.width > SCREENSHOT_WIDTH:\n        height = round(image.height * SCREENSHOT_WIDTH / image.width)\n        image = image.resize((SCREENSHOT_WIDTH, height))\n    buffer = io.BytesIO()\n    image.convert(\"RGB\").save(buffer, format=\"JPEG\", quality=70)\n    return buffer.getvalue()\n\n\n# The buttons that send something. A rehearsal may find them, never press them.\n# Reddit's comment box sends with Post, Reply or Comment, depending on the version.\n# The App Store's Install and a wipe's Erase are last buttons too.\nLAST_BUTTONS = (\"post\", \"send\", \"share\", \"reply\", \"comment\", \"install\", \"erase\")\n\n\ndef selector_words(selector):\n    for key in (\"text\", \"textMatches\", \"description\", \"descriptionMatches\", \"resourceId\", \"resourceIdMatches\"):\n        if key in selector:\n            return '\"%s\"' % selector[key]\n    return \"the button\"\n\n\ndef could_be_last_button(selector):\n    \"\"\"True when a selector could find Post, Send or Share, by its words or a pattern.\"\"\"\n    for key in (\"text\", \"description\"):\n        if plain(str(selector.get(key, \"\"))) in LAST_BUTTONS:\n            return True\n    for key in (\"textMatches\", \"descriptionMatches\"):\n        pattern = selector.get(key)\n        if pattern:\n            try:\n                if any(re.match(pattern, word) or re.match(pattern, word.title()) for word in LAST_BUTTONS):\n                    return True\n            except re.error:\n                return True\n    return False\n\n\ndef element_bounds(element):\n    \"\"\"An element's place on screen as (left, top, right, bottom), or None when it cannot say.\"\"\"\n    try:\n        bounds = element.info[\"bounds\"]\n        return (int(bounds[\"left\"]), int(bounds[\"top\"]), int(bounds[\"right\"]), int(bounds[\"bottom\"]))\n    except Exception:  # A fake screen, or an element that went away; pressed the plain way.\n        return None\n\n\nclass Walk(object):\n    \"\"\"One action's steps on one phone, each with a picture of the screen.\"\"\"\n\n    def __init__(self, serial, rehearse=False, cancelled=None, connect=None):\n        self.serial = serial\n        self.rehearse = rehearse\n        self.cancelled = cancelled or threading.Event()\n        # Looked up when used, so a test can stand a fake screen in.\n        self.connect = connect or (lambda serial: connect_screen(serial))\n        self.device = None\n        # (step name, JPEG bytes), in order.\n        self.steps = []\n        # The step being worked on, for a failure that is not a StepFailed.\n        self.current = \"\"\n\n    def screen(self):\n        if self.device is None:\n            self.device = self.connect(self.serial)\n        return self.device\n\n    def check(self):\n        if self.cancelled.is_set():\n            raise Cancelled(\"The phone or app froze, so the action was stopped here.\")\n\n    def shot(self, step):\n        \"\"\"Keeps a picture of the screen as it is now, named for the step that got it there.\n        A walk given up on takes no more pictures.\"\"\"\n        self.current = step\n        if self.cancelled.is_set():\n            return\n        try:\n            self.steps.append((step, screenshot_jpeg(self.screen())))\n        except Exception as failure:  # A step with no picture still counts.\n            log(\"No picture for %s on %s: %s\" % (step, self.serial, failure))\n\n    def find(self, step, timeout=10, **selector):\n        self.check()\n        self.current = step\n        element = self.screen()(**selector)\n        if not element.wait(timeout=timeout):\n            self.shot(step)\n            raise StepFailed(step, \"Could not find %s on the screen.\" % selector_words(selector))\n        return element\n\n    def home(self):\n        \"\"\"Back to the home screen, unless the walk was given up on: a frozen\n        action's thread that wakes later must not move the phone under the next.\"\"\"\n        if not self.cancelled.is_set():\n            go_home(self.serial)\n\n    def tap(self, step, timeout=10, **selector):\n        if self.rehearse and plain(str(selector.get(\"text\", \"\"))) in LAST_BUTTONS:\n            # The self-test must never press Post, Send or Share; those go through final().\n            raise RuntimeError(\"A rehearsal tried to tap %s; the last button is only ever found, with final().\" % selector[\"text\"])\n        element = self.find(step, timeout, **selector)\n        self.check()\n        self.press(element)\n        time.sleep(1)\n        self.shot(step)\n\n    def press(self, element):\n        \"\"\"Presses a found element a little off its middle, the way a thumb\n        lands, after a short look. An element that cannot say where it is\n        (a test's fake screen) is pressed the plain way.\"\"\"\n        bounds = element_bounds(element)\n        device = self.screen()\n        if bounds and hasattr(device, \"click\"):\n            time.sleep(random.uniform(*LOOK_BEFORE_TAP_SECONDS))\n            self.check()\n            x, y = tap_point(bounds)\n            device.click(x, y)\n        else:\n            element.click()\n\n    def find_first(self, step, timeout=10, selectors=()):\n        \"\"\"The first of several shapes of one button to show within the time.\n        An app update often renames or moves a button, so each known shape is\n        tried, and the failure names them all.\"\"\"\n        self.check()\n        self.current = step\n        device = self.screen()\n        deadline = time.time() + timeout\n        while True:\n            for selector in selectors:\n                element = device(**selector)\n                if element.exists:\n                    return element\n            if time.time() >= deadline:\n                break\n            time.sleep(0.5)\n            self.check()\n        self.shot(step)\n        raise StepFailed(step, \"Could not find %s on the screen.\" % \" or \".join(selector_words(one) for one in selectors))\n\n    def tap_first(self, step, timeout=10, selectors=()):\n        if self.rehearse and any(could_be_last_button(one) for one in selectors):\n            raise RuntimeError(\"A rehearsal tried to tap %s; the last button is only ever found, with final().\" % selector_words(selectors[0]))\n        element = self.find_first(step, timeout, selectors)\n        self.check()\n        self.press(element)\n        time.sleep(1)\n        self.shot(step)\n\n    def final_first(self, step, timeout=10, selectors=()):\n        \"\"\"final() for a button with several known shapes. Only one press ever\n        happens: a press that raised may still have sent it.\"\"\"\n        element = self.find_first(step, timeout, selectors)\n        if self.rehearse:\n            self.shot(\"%s (found, not pressed)\" % step)\n            return False\n        self.check()\n        self.press(element)\n        time.sleep(1)\n        self.shot(step)\n        return True\n\n    def final(self, step, timeout=10, **selector):\n        \"\"\"The last button, such as Post. Pressed once in a real run; in the\n        self-test it is only found, and this returns False without a press.\"\"\"\n        element = self.find(step, timeout, **selector)\n        if self.rehearse:\n            self.shot(\"%s (found, not pressed)\" % step)\n            return False\n        self.check()\n        self.press(element)\n        time.sleep(1)\n        self.shot(step)\n        return True\n\n\ndef go_home(serial):\n    try:\n        if is_iphone(serial):\n            iphone_screen(serial).press(\"home\")\n        else:\n            shell(serial, \"input keyevent KEYCODE_HOME\", timeout=10)\n    except Exception:  # A phone pulled out; the next step will say so.\n        pass\n\n\ndef go_back(serial):\n    \"\"\"Back: Android's key, or the iPhone's swipe in from the left edge, which the driver makes.\"\"\"\n    try:\n        if is_iphone(serial):\n            iphone_screen(serial).press(\"back\")\n        else:\n            shell(serial, \"input keyevent KEYCODE_BACK\", timeout=10)\n    except Exception:\n        pass\n\n\n# ---------------------------------------------------------------------------\n# Hands. A thumb never lands on the exact middle of a button twice, a swipe\n# bends and changes speed on the way, and typing has an uneven rhythm with a\n# stop at the end of each sentence. The numbers are the browser's own, from\n# docker/browser/human.py, so an account behaves the same on a phone as in a\n# browser. Every timing is drawn from a range, never picked from a list.\n\n# Between two keys; after the end of a sentence; now and then, mid-sentence.\nKEY_GAP_SECONDS = (0.06, 0.17)\nSENTENCE_PAUSE_SECONDS = (0.35, 1.1)\nTHINKING_CHANCE = 0.02\nTHINKING_PAUSE_SECONDS = (0.5, 1.8)\n\n# Reading the post before replying, longer for a longer post, within a floor and a ceiling.\nREAD_SECONDS_PER_CHARACTER = 0.012\nREAD_SECONDS = (4.0, 25.0)\n\n# Between the last key and pressing Post, and a look at a button before tapping it.\nBEFORE_SUBMIT_SECONDS = (0.8, 2.6)\nLOOK_BEFORE_TAP_SECONDS = (0.3, 1.2)\n\n# Where a tap lands, as a share of the button's width and height away from\n# its middle: mostly near the middle, never in the outer fifth on either side.\nTAP_SPREAD = 0.15\nTAP_INNER = 0.3\n\n# A swipe: a few points on a line that bows sideways, sent over a time drawn\n# from a range, with the points bunched at the start and end so the thumb\n# speeds up and slows down.\nSWIPE_POINTS = (4, 7)\nSWIPE_BEND = 0.12\nSWIPE_MIN_BEND = 0.03\nSWIPE_SECONDS = (0.25, 0.7)\n\n# One scroll moves a share of the screen's height; uneven gaps between\n# scrolls, now and then a stop to read, now and then a little way back up.\nSCROLL_SHARE = (0.2, 0.5)\nSCROLL_GAP_SECONDS = (0.4, 2.4)\nREADING_CHANCE = 0.15\nREADING_SECONDS = (2.5, 8.0)\nSCROLL_BACK_CHANCE = 0.12\n\n\ndef tap_point(bounds, rng=random):\n    \"\"\"Where on a button with these bounds a tap lands: a little off its middle,\n    different every time, always inside the button's inner part.\"\"\"\n    left, top, right, bottom = bounds\n\n    def axis(low, high):\n        size = high - low\n        offset = rng.gauss(0, TAP_SPREAD) * size\n        limit = TAP_INNER * size\n        point = int(round(low + size / 2 + max(-limit, min(limit, offset))))\n        return max(low, min(high - 1, point)) if size >= 2 else low\n\n    return axis(left, right), axis(top, bottom)\n\n\ndef swipe_path(x1, y1, x2, y2, rng=random):\n    \"\"\"The points of one swipe from (x1, y1) to (x2, y2): a line bowed to one\n    side, never straight, its points closer together at both ends so the\n    thumb speeds up and slows down.\"\"\"\n    count = rng.randint(*SWIPE_POINTS)\n    length = ((x2 - x1) ** 2 + (y2 - y1) ** 2) ** 0.5 or 1.0\n    bend = rng.gauss(0, SWIPE_BEND)\n    if abs(bend) < SWIPE_MIN_BEND:\n        bend = SWIPE_MIN_BEND if bend >= 0 else -SWIPE_MIN_BEND\n    bend *= length\n    # The unit step at right angles to the swipe.\n    across_x, across_y = -(y2 - y1) / length, (x2 - x1) / length\n    points = []\n    for index in range(count):\n        share = index / (count - 1)\n        along = 0.5 - 0.5 * math.cos(math.pi * share)\n        bow = bend * math.sin(math.pi * along)\n        points.append((\n            int(round(x1 + (x2 - x1) * along + across_x * bow)),\n            int(round(y1 + (y2 - y1) * along + across_y * bow)),\n        ))\n    return points\n\n\ndef typing_plan(text, rng=random):\n    \"\"\"Each character to type and the wait after it. A sentence's end waits\n    longer, and now and then a space is a stop to think. The last key has\n    no wait.\"\"\"\n    plan = []\n    for index, character in enumerate(text):\n        if index == len(text) - 1:\n            plan.append((character, 0.0))\n            break\n        gap = rng.uniform(*KEY_GAP_SECONDS)\n        if character in \".!?\" and text[index + 1:index + 2] in (\" \", \"\\n\"):\n            gap += rng.uniform(*SENTENCE_PAUSE_SECONDS)\n        elif character == \" \" and rng.random() < THINKING_CHANCE:\n            gap += rng.uniform(*THINKING_PAUSE_SECONDS)\n        plan.append((character, gap))\n    return plan\n\n\ndef type_key(serial, device, character):\n    \"\"\"One character into the box in focus: a plain one as a key press, a\n    new line as Enter, anything else (an accent, an emoji) through\n    uiautomator2, which Android's own `input text` cannot type. An iPhone\n    types every character through WebDriverAgent, one at a time, so the\n    rhythm between keys is the same on both kinds.\"\"\"\n    if is_iphone(serial):\n        if character == \"\\n\":\n            device.press(\"enter\")\n        else:\n            device.send_keys(character)\n    elif character == \"\\n\":\n        shell(serial, \"input keyevent KEYCODE_ENTER\", timeout=10)\n    elif 32 <= ord(character) < 127:\n        shell(serial, \"input text %s\" % typed_text(character), timeout=10)\n    else:\n        device.send_keys(character, clear=False)\n\n\ndef type_like_a_person(serial, device, text, check=lambda: None):\n    \"\"\"Types `text` one key at a time with a person's rhythm. Returns the gaps.\"\"\"\n    gaps = []\n    for character, gap in typing_plan(text):\n        check()\n        type_key(serial, device, character)\n        if gap:\n            gaps.append(gap)\n            time.sleep(gap)\n    return gaps\n\n\ndef screen_size(device):\n    try:\n        width, height = device.window_size()\n        return int(width), int(height)\n    except Exception:  # A fake screen; a common phone's size.\n        return 1080, 2400\n\n\ndef tap_at(serial, device, x, y):\n    if hasattr(device, \"click\"):\n        device.click(x, y)\n    else:\n        shell(serial, \"input tap %d %d\" % (x, y), timeout=10)\n\n\ndef swipe_like_a_person(serial, device, x1, y1, x2, y2):\n    points = swipe_path(x1, y1, x2, y2)\n    seconds = random.uniform(*SWIPE_SECONDS)\n    if is_iphone(serial):\n        # WebDriverAgent draws a straight swipe; its speed still varies.\n        device.swipe(x1, y1, x2, y2, duration=seconds)\n    elif hasattr(device, \"swipe_points\"):\n        device.swipe_points(points, seconds)\n    else:\n        shell(serial, \"input swipe %d %d %d %d %d\" % (x1, y1, x2, y2, int(seconds * 1000)), timeout=10)\n\n\ndef scroll_once(serial, device, direction=1):\n    \"\"\"One scroll as a thumb makes it: a bent swipe of uneven length, up the\n    screen to go down the page. Returns how far it moved, in pixels.\"\"\"\n    width, height = screen_size(device)\n    distance = int(height * random.uniform(*SCROLL_SHARE))\n    x = int(width * random.uniform(0.35, 0.65))\n    start = int(height * random.uniform(0.62, 0.78))\n    end = start - distance\n    if direction > 0:\n        swipe_like_a_person(serial, device, x, start, x + random.randint(-30, 30), end)\n    else:\n        swipe_like_a_person(serial, device, x, end, x + random.randint(-30, 30), start)\n    return distance\n\n\ndef scroll_pause(until=None):\n    pause = random.uniform(*SCROLL_GAP_SECONDS)\n    if random.random() < READING_CHANCE:\n        pause += random.uniform(*READING_SECONDS)\n    if until is not None:\n        pause = max(0.0, min(pause, until - time.monotonic()))\n    time.sleep(pause)\n\n\n# ---------------------------------------------------------------------------\n# The named actions. Each takes the phone's serial, its arguments and its\n# Walk, and returns its answer; its pictures are the Walk's steps.\n\ndef action_list(serial, args, walk):\n    return {\"phones\": list_phones()}\n\n\ndef action_health(serial, args, walk):\n    if is_iphone(serial):\n        # The same figures the minute's reading takes, from the same channel.\n        reading = iphone_vitals(serial)\n        return dict(\n            reading,\n            kind=\"iphone\",\n            upHours=round(reading[\"upSeconds\"] / 3600, 1) if reading[\"upSeconds\"] is not None else None,\n            android=iphone_system_version(serial),\n            model=_PROPS.get(serial, {}).get(\"model\", \"\"),\n        )\n    battery = shell(serial, \"dumpsys battery\")\n    level = re.search(r\"^\\s*level:\\s*(\\d+)\", battery, re.M)\n    temperature = re.search(r\"^\\s*temperature:\\s*(\\d+)\", battery, re.M)\n    charging = re.search(r\"^\\s*status:\\s*(\\d+)\", battery, re.M)\n    storage = shell(serial, \"df /data\").splitlines()\n    free_kb = None\n    if len(storage) >= 2:\n        columns = storage[-1].split()\n        if len(columns) >= 4 and columns[3].isdigit():\n            free_kb = int(columns[3])\n    awake = re.search(r\"mWakefulness=(\\w+)\", shell(serial, \"dumpsys power\"))\n    uptime = shell(serial, \"cat /proc/uptime\").split()\n    return {\n        \"batteryPercent\": int(level.group(1)) if level else None,\n        # dumpsys reports tenths of a degree.\n        \"temperatureC\": int(temperature.group(1)) / 10 if temperature else None,\n        # 2 is charging and 5 is full, in Android's BatteryManager.\n        \"charging\": bool(charging and charging.group(1) in (\"2\", \"5\")),\n        \"freeStorageMb\": free_kb // 1024 if free_kb is not None else None,\n        \"screen\": awake.group(1) if awake else \"\",\n        \"upHours\": round(float(uptime[0]) / 3600, 1) if uptime else None,\n        \"android\": shell(serial, \"getprop ro.build.version.release\"),\n        \"model\": shell(serial, \"getprop ro.product.model\"),\n    }\n\n\nVERSION_TEXT = re.compile(r\"^\\d+(\\.\\d+)*$\")\n\n\ndef node_words(node):\n    \"\"\"A node's own words: its text, or its description when it has no text.\n    An iPhone's tree carries them as label or value instead.\"\"\"\n    return \" \".join((node.get(\"text\") or node.get(\"content-desc\") or node.get(\"label\") or node.get(\"value\") or \"\").split())\n\n\ndef value_beside_label(hierarchy_xml, label, pattern):\n    \"\"\"The text matching `pattern` printed beside `label` in a screen dump.\n\n    A label and its value are two text views under one row or one column, so\n    the value is looked for inside the label's parent first, then the\n    parent's parent on screens that nest deeper. Within one holder the match\n    nearest the label wins, so a row of two figures (karma, then the\n    account's age) gives each label its own.\n    \"\"\"\n    root = ElementTree.fromstring(hierarchy_xml)\n    parents = {child: parent for parent in root.iter() for child in parent}\n    wanted = plain(label)\n    for node in root.iter(\"node\"):\n        if plain(node_words(node)) != wanted:\n            continue\n        holder = parents.get(node)\n        for _ in range(3):\n            if holder is None:\n                break\n            nodes = list(holder.iter(\"node\"))\n            here = nodes.index(node) if node in nodes else 0\n            matches = [\n                (abs(index - here), node_words(other))\n                for index, other in enumerate(nodes)\n                if other is not node and pattern.match(node_words(other))\n            ]\n            if matches:\n                return min(matches, key=lambda match: match[0])[1]\n            holder = parents.get(holder)\n    return None\n\n\ndef version_beside_label(hierarchy_xml):\n    \"\"\"The version printed beside \"Android version\" in a Settings screen dump.\"\"\"\n    return value_beside_label(hierarchy_xml, \"Android version\", VERSION_TEXT)\n\n\n# iOS's Settings, General, About. The row reads \"iOS Version\" with the number\n# beside it; older builds said \"Software Version\". A tree may also give the\n# whole row as one label, \"iOS Version, 17.6.1\".\nIOS_VERSION_LABELS = (\"iOS Version\", \"Software Version\")\nIOS_VERSION_INLINE = re.compile(r\"(?i)\\b(?:ios|software) version\\b[,:]?\\s*(\\d+(?:\\.\\d+)*)\")\n\n\ndef ios_version_beside_label(hierarchy_xml):\n    \"\"\"The version printed beside \"iOS Version\" on the About screen. The label\n    and the value are two sibling elements of one cell, so the same reader\n    as Android's finds it; a row given as one label is read whole.\"\"\"\n    for label in IOS_VERSION_LABELS:\n        found = value_beside_label(hierarchy_xml, label, VERSION_TEXT)\n        if found:\n            return found\n    for node in ElementTree.fromstring(hierarchy_xml).iter():\n        match = IOS_VERSION_INLINE.search(node_words(node))\n        if match:\n            return match.group(1)\n    return None\n\n\ndef read_ios_version(serial, walk):\n    \"\"\"phone/android-version on an iPhone: Settings, General, About, and the\n    iOS Version row read off the screen, checked against what the phone\n    reports over USB.\"\"\"\n    from_system = iphone_system_version(serial)\n    device = walk.screen()\n    wake_screen(device)\n    walk.check()\n    device.app_start(IOS_SETTINGS)\n    time.sleep(2)\n    walk.shot(\"Opened Settings\")\n    walk.tap(\"Open General\", text=\"General\")\n    walk.tap(\"Open About\", text=\"About\")\n    found = None\n    width, height = screen_size(device)\n    for attempt in range(3):\n        walk.check()\n        found = ios_version_beside_label(device.dump_hierarchy())\n        if found:\n            break\n        swipe_like_a_person(serial, device, width // 2, int(height * 0.7), width // 2, int(height * 0.3))\n        time.sleep(1)\n    if not found:\n        walk.shot(\"Looked for the iOS version\")\n        walk.home()\n        raise StepFailed(\n            \"Find the iOS version\",\n            \"Settings opened, but no iOS version was found on its screen. The phone itself says %s.\" % (from_system or \"nothing\"),\n        )\n    walk.shot(\"Read iOS %s\" % found)\n    walk.home()\n    return {\"fromScreen\": found, \"fromSystem\": from_system, \"match\": found == from_system, \"kind\": \"iphone\"}\n\n\ndef action_android_version(serial, args, walk):\n    \"\"\"Opens Settings at About phone and reads the Android version off the screen.\n\n    A test of the whole path: the rack reaching the phone, the phone opening an\n    app, and the screen being read. The version Android itself reports is read\n    too, so the answer can be checked against it.\n    \"\"\"\n    if is_iphone(serial):\n        return read_ios_version(serial, walk)\n    from_system = shell(serial, \"getprop ro.build.version.release\")\n    device = walk.screen()\n    device.screen_on()\n    walk.check()\n    shell(serial, \"am start -a android.settings.DEVICE_INFO_SETTINGS\")\n    time.sleep(2)\n    walk.shot(\"Opened About phone\")\n    found = None\n    # Pixels list it on About phone. Samsungs keep it one screen in, under\n    # Software information. Either may need a scroll first.\n    for attempt in range(4):\n        walk.check()\n        found = version_beside_label(device.dump_hierarchy())\n        if found:\n            break\n        if attempt == 0 and device(text=\"Software information\").exists:\n            device(text=\"Software information\").click()\n            time.sleep(1.5)\n            walk.shot(\"Opened Software information\")\n            continue\n        scroller = device(scrollable=True)\n        if scroller.exists:\n            scroller.scroll.forward()\n            time.sleep(1)\n    if not found:\n        walk.shot(\"Looked for the Android version\")\n        walk.home()\n        raise StepFailed(\n            \"Find the Android version\",\n            \"Settings opened, but no Android version was found on its screen. Android itself says %s.\" % from_system,\n        )\n    walk.shot(\"Read Android %s\" % found)\n    walk.home()\n    return {\"fromScreen\": found, \"fromSystem\": from_system, \"match\": found == from_system}\n\n\n# ---------------------------------------------------------------------------\n# The apps Promo keeps an eye on, by Play Store package. Promo keeps the same\n# list in src/lib/phones/options.ts.\n\nAPP_PACKAGES = {\n    \"reddit\": \"com.reddit.frontpage\",\n    \"instagram\": \"com.instagram.android\",\n    \"tiktok\": \"com.zhiliaoapp.musically\",\n    \"medium\": \"com.medium.reader\",\n    \"x\": \"com.twitter.android\",\n    \"linkedin\": \"com.linkedin.android\",\n    # Threads, Meta's (part 9 of the 18 Nov 2026 features task), signed in\n    # through the Instagram account on the same phone.\n    \"threads\": \"com.instagram.barcelona\",\n    # YouTube (workspace/tasks/YouTube/01-youtube-features.md): a channel's\n    # uploads, its daily reading and the comments under its videos.\n    \"youtube\": \"com.google.android.youtube\",\n}\nAPP_NAMES = {\"reddit\": \"Reddit\", \"instagram\": \"Instagram\", \"tiktok\": \"TikTok\", \"medium\": \"Medium\", \"x\": \"X\", \"linkedin\": \"LinkedIn\", \"threads\": \"Threads\", \"youtube\": \"YouTube\"}\nPLAY_STORE = \"com.android.vending\"\n\n# The same apps on an iPhone, by App Store bundle id, and Apple's own apps\n# the rack opens: Settings for the version read and Messages for a texted code.\nAPP_BUNDLES = {\n    \"reddit\": \"com.reddit.Reddit\",\n    \"instagram\": \"com.burbn.instagram\",\n    \"tiktok\": \"com.zhiliaoapp.musically\",\n    # Not yet read off a real iPhone. The Android package is Medium's own\n    # Play Store name; this one is the same until a phone says otherwise.\n    \"medium\": \"com.medium.reader\",\n    # X's iPhone app keeps Tweetie's bundle id from before Twitter bought it.\n    # Not yet read off a real iPhone either.\n    \"x\": \"com.atebits.Tweetie2\",\n    # LinkedIn's App Store bundle id. Not yet read off a real iPhone either.\n    \"linkedin\": \"com.linkedin.LinkedIn\",\n    # Threads' App Store bundle id. Its steps are not written for an iPhone\n    # yet, so `app_screens` refuses one there.\n    \"threads\": \"com.burbn.barcelona\",\n    # YouTube's App Store bundle id. Its steps are not written for an iPhone\n    # yet, so `app_screens` refuses one there.\n    \"youtube\": \"com.google.ios.youtube\",\n}\nIOS_SETTINGS = \"com.apple.Preferences\"\nIOS_MESSAGES = \"com.apple.MobileSMS\"\n\n\ndef package_for(serial, app):\n    \"\"\"The app's name to the phone it is on: a bundle id on an iPhone, a package on Android.\"\"\"\n    return APP_BUNDLES[app] if is_iphone(serial) else APP_PACKAGES[app]\n\n\ndef app_packages(app):\n    \"\"\"Both names of one app: its Android package and its iPhone bundle id. A\n    reader handed a screen and no serial filters by both, since every node\n    is stamped with one or the other.\"\"\"\n    return (APP_PACKAGES[app], APP_BUNDLES[app])\n\n\ndef own_node(node, package):\n    \"\"\"True when a node is the app's own: nothing stamped on it, the package\n    given, or either name of the app when `package` is app_packages' pair.\"\"\"\n    stamped = node.get(\"package\")\n    if not stamped or not package:\n        return True\n    if isinstance(package, tuple):\n        return stamped in package\n    return stamped == package\n\n\ndef ios_kind(node):\n    \"\"\"An iPhone node's element type, XCUIElementTypeCell and the like; an Android node's class.\"\"\"\n    return node.get(\"type\") or node.get(\"class\") or \"\"\n\n\nIOS_TEXT_BOX = re.compile(r\"^XCUIElementType(TextField|TextView|SecureTextField|SearchField)$\")\n\n\ndef is_text_box(node):\n    \"\"\"True for a box someone types into: Android's EditText or an iPhone's text field.\"\"\"\n    kind = node.get(\"class\") or node.get(\"type\") or \"\"\n    return kind == \"android.widget.EditText\" or bool(IOS_TEXT_BOX.match(kind))\n\n\ndef is_row(node):\n    \"\"\"True for something a thumb can open: a clickable Android view, or an iPhone list cell.\"\"\"\n    return node.get(\"clickable\") == \"true\" or ios_kind(node).endswith(\"Cell\")\n\n\ndef not_a_line(node, height):\n    \"\"\"True for an iPhone node that is no line anyone wrote: a button, or the\n    app's own root, whose label is the app's name and whose bounds are the\n    whole screen. Android's buttons carry a description, not text, and a\n    long Android message can be taller than half the screen, so the height\n    rule is only for iPhone nodes.\"\"\"\n    kind = ios_kind(node)\n    if not kind.startswith(\"XCUIElementType\"):\n        return False\n    if kind == \"XCUIElementTypeButton\":\n        return True\n    bounds = parse_bounds(node.get(\"bounds\"))\n    return bool(bounds) and bounds[3] - bounds[1] > height * 0.5\n\nAPPS_COMMAND = \"for p in %s; do echo \\\"$p $(dumpsys package $p | grep -m1 versionName=)\\\"; done\" % \" \".join(\n    APP_PACKAGES[app] for app in sorted(APP_PACKAGES)\n)\n\n\ndef parse_app_versions(output):\n    \"\"\"Each tracked app's version from APPS_COMMAND's lines; an app not installed is left out.\"\"\"\n    by_package = dict((package, app) for app, package in APP_PACKAGES.items())\n    versions = {}\n    for line in output.splitlines():\n        parts = line.strip().split(None, 1)\n        if len(parts) < 2 or parts[0] not in by_package:\n            continue\n        found = re.search(r\"versionName=(\\S+)\", parts[1])\n        if found:\n            versions[by_package[parts[0]]] = found.group(1)\n    return versions\n\n\ndef app_version(serial, package):\n    found = re.search(r\"versionName=(\\S+)\", shell(serial, \"dumpsys package %s | grep -m1 versionName=\" % package, timeout=20))\n    return found.group(1) if found else \"\"\n\n\ndef open_store_page(serial, package):\n    shell(serial, \"am start -a android.intent.action.VIEW -d 'market://details?id=%s' -p %s\" % (package, PLAY_STORE))\n    time.sleep(4)\n\n\nUPDATE_BUTTON = {\"textMatches\": \"(?i)^update$\", \"packageName\": PLAY_STORE}\n\n# The same apps in the App Store (phone farm part 53): each app's page by\n# Apple's own number, opened through the itms-apps address the store owns.\nAPP_STORE = \"com.apple.AppStore\"\nAPP_STORE_IDS = {\"reddit\": \"1064216828\", \"instagram\": \"389801252\", \"tiktok\": \"835599320\", \"medium\": \"828256236\", \"x\": \"333903271\", \"linkedin\": \"288429040\", \"threads\": \"6446901002\", \"youtube\": \"544007664\"}\nIOS_UPDATE_BUTTON = {\"textMatches\": \"(?i)^update$\", \"packageName\": APP_STORE}\nIOS_OPEN_BUTTON = {\"textMatches\": \"(?i)^open$\", \"packageName\": APP_STORE}\n# The page's What's New says \"Version 2025.40.0\" under the newest notes.\nSTORE_VERSION_LINE = re.compile(r\"(?i)^version\\s+(\\d+(?:\\.\\d+)*)$\")\n\n\ndef open_ios_store_page(device, app):\n    device.open_url(\"itms-apps://apps.apple.com/app/id%s\" % APP_STORE_IDS[app])\n    time.sleep(4)\n\n\ndef store_version_from_screen(hierarchy_xml):\n    \"\"\"The version the App Store page shows, \"Version 2025.40.0\", or empty.\"\"\"\n    for line in screen_lines(hierarchy_xml):\n        found = STORE_VERSION_LINE.match(line)\n        if found:\n            return found.group(1)\n    for words in ios_cells(hierarchy_xml):\n        if len(words) > 1 and plain(words[0]) == \"version\" and VERSION_TEXT.match(words[1]):\n            return words[1]\n    return \"\"\n\n\ndef ios_check_updates(serial, walk):\n    \"\"\"Each tracked app's App Store page on an iPhone: is Update showing?\n    Nothing is pressed. The versions come from the driver when it offers\n    them, else off each page; a page offering Get is an app not on the phone.\"\"\"\n    device = walk.screen()\n    versions = iphone_app_versions(serial)\n    apps = {}\n    for app in sorted(APP_BUNDLES):\n        if versions is not None and app not in versions:\n            continue\n        walk.check()\n        open_ios_store_page(device, app)\n        walk.shot(\"%s in the App Store\" % APP_NAMES[app])\n        hierarchy = device.dump_hierarchy()\n        update = bool(device(**IOS_UPDATE_BUTTON).exists)\n        if versions is None and not update and not device(**IOS_OPEN_BUTTON).exists:\n            continue\n        version = versions.get(app, \"\") if versions is not None else store_version_from_screen(hierarchy)\n        apps[app] = {\"version\": version, \"update\": update}\n    walk.home()\n    return {\"apps\": apps}\n\n\ndef ios_update_app(serial, walk, app):\n    \"\"\"Presses Update on one app's App Store page and waits for the new\n    version. With the driver's app_versions the version itself is watched;\n    without it the page is the only word, and the update is done when Update\n    has gone and Open is back, the version being the page's own line.\"\"\"\n    device = walk.screen()\n    name = APP_NAMES[app]\n    walk.check()\n    open_ios_store_page(device, app)\n    walk.shot(\"Opened %s in the App Store\" % name)\n    versions = iphone_app_versions(serial)\n    before = versions.get(app, \"\") if versions is not None else \"\"\n    if versions is not None and not before:\n        raise StepFailed(\"Find %s on the phone\" % name, \"%s is not on this phone.\" % name)\n    target = store_version_from_screen(device.dump_hierarchy())\n    walk.tap(\"Press Update\", **IOS_UPDATE_BUTTON)\n    deadline = time.time() + UPDATE_WAIT_SECONDS\n    while time.time() < deadline:\n        time.sleep(10)\n        walk.check()\n        if versions is not None:\n            after = (iphone_app_versions(serial) or {}).get(app, \"\")\n            done = bool(after) and after != before\n        else:\n            after = target\n            done = not device(**IOS_UPDATE_BUTTON).exists and bool(device(**IOS_OPEN_BUTTON).exists)\n        if done:\n            walk.shot(\"Updated to %s\" % (after or \"the new version\"))\n            walk.home()\n            return {\"app\": app, \"from\": before, \"to\": after}\n    walk.shot(\"Still updating\")\n    raise RuntimeError(\"%s did not finish updating within eight minutes. It may still finish by itself.\" % name)\n\n\ndef action_check_updates(serial, args, walk):\n    \"\"\"The Play Store page of each tracked app on the phone: is Update showing?\n    Nothing is pressed. On an iPhone it is each app's App Store page.\"\"\"\n    if is_iphone(serial):\n        return ios_check_updates(serial, walk)\n    versions = parse_app_versions(shell(serial, APPS_COMMAND, timeout=30))\n    apps = {}\n    for app in sorted(versions):\n        walk.check()\n        open_store_page(serial, APP_PACKAGES[app])\n        walk.shot(\"%s in the Play Store\" % APP_NAMES[app])\n        apps[app] = {\"version\": versions[app], \"update\": bool(walk.screen()(**UPDATE_BUTTON).exists)}\n    walk.home()\n    return {\"apps\": apps}\n\n\nUPDATE_WAIT_SECONDS = 480\n\n\ndef action_update_app(serial, args, walk):\n    \"\"\"Presses Update on one app's Play Store page and waits for the new version.\"\"\"\n    app = str(args.get(\"app\", \"\"))\n    if app not in APP_PACKAGES:\n        raise RuntimeError(\"%s is not an app the rack updates.\" % app)\n    if is_iphone(serial):\n        return ios_update_app(serial, walk, app)\n    package, name = APP_PACKAGES[app], APP_NAMES[app]\n    before = app_version(serial, package)\n    if not before:\n        raise StepFailed(\"Find %s on the phone\" % name, \"%s is not on this phone.\" % name)\n    walk.check()\n    open_store_page(serial, package)\n    walk.shot(\"Opened %s in the Play Store\" % name)\n    walk.tap(\"Press Update\", **UPDATE_BUTTON)\n    deadline = time.time() + UPDATE_WAIT_SECONDS\n    while time.time() < deadline:\n        time.sleep(10)\n        walk.check()\n        after = app_version(serial, package)\n        if after and after != before:\n            walk.shot(\"Updated to %s\" % after)\n            walk.home()\n            return {\"app\": app, \"from\": before, \"to\": after}\n    walk.shot(\"Still updating\")\n    raise RuntimeError(\"%s did not finish updating within eight minutes. It may still finish by itself.\" % name)\n\n\n# ---------------------------------------------------------------------------\n# The setup check (phone farm part 23). What a platform could notice about a\n# phone before any account is used on it: Wi-Fi left on beside a SIM, apps\n# allowed the phone's location, a clock or language from another country,\n# apps that update themselves, and the address the internet sees. Each part\n# is read on its own, so one that cannot be read leaves a blank and a reason\n# rather than failing the rest. Promo judges each line; the rack only reads.\n\n# The rack computer's own table of which country each time zone is in.\nZONE_TABLES = (\"/usr/share/zoneinfo/zone.tab\", \"/usr/share/zoneinfo/zone1970.tab\")\n\n# What the internet sees, asked over plain http so a phone with no\n# certificate quirks still loads it. The same service Promo's own proxy test uses.\nIPINFO_URL = \"http://ipinfo.io/json\"\nHOME_IPINFO_URL = \"https://ipinfo.io/json\"\n\n# A freshly wiped phone's browser asks these first. Pressing them only gets\n# past the browser's welcome screen.\nBROWSER_FIRST_RUN = (\"Accept & continue\", \"Use without an account\", \"No thanks\", \"No, thanks\", \"Got it\")\n\nPLAY_ACCOUNT_BUTTON = [\n    {\"descriptionMatches\": \"(?is)^(signed in as|account and settings|google account).*\", \"packageName\": PLAY_STORE},\n    {\"descriptionMatches\": \"(?is).*account.*\", \"packageName\": PLAY_STORE},\n]\nPLAY_SETTINGS = [{\"textMatches\": \"(?i)^settings$\", \"packageName\": PLAY_STORE}]\nPLAY_NETWORK = [{\"textMatches\": \"(?i)^network preferences$\", \"packageName\": PLAY_STORE}]\nPLAY_AUTO_UPDATE = [{\"textMatches\": \"(?i)^auto-update apps$\", \"packageName\": PLAY_STORE}]\n\nLOCATION_GRANTED = re.compile(r\"android\\.permission\\.ACCESS_(?:FINE|COARSE)_LOCATION: granted=true\")\n\n\ndef location_granted(dumpsys_package):\n    \"\"\"True when `dumpsys package` shows the app allowed the phone's location, fine or rough.\"\"\"\n    return bool(LOCATION_GRANTED.search(dumpsys_package or \"\"))\n\n\ndef zone_country(timezone, tables=ZONE_TABLES):\n    \"\"\"The two-letter country a time zone is in, from the computer's zone\n    table, or empty for a zone in no country (UTC) or no table.\"\"\"\n    zone = (timezone or \"\").strip()\n    if not zone:\n        return \"\"\n    for path in tables:\n        try:\n            with open(path, \"r\", encoding=\"utf-8\") as handle:\n                for line in handle:\n                    if line.startswith(\"#\"):\n                        continue\n                    parts = line.rstrip(\"\\n\").split(\"\\t\")\n                    if len(parts) >= 3 and parts[2].strip() == zone:\n                        return parts[0].split(\",\")[0].strip().upper()\n        except OSError:\n            continue\n    return \"\"\n\n\ndef first_listed(value):\n    \"\"\"The first non-empty item of Android's comma lists, such as one per SIM slot.\"\"\"\n    for part in (value or \"\").split(\",\"):\n        if part.strip() and part.strip() != \"null\":\n            return part.strip()\n    return \"\"\n\n\ndef pick_locale(persisted, system_locales, product):\n    \"\"\"The phone's language as en-CA: the one chosen, else the first of the\n    list, else the one it was sold with.\"\"\"\n    for value in (persisted, first_listed(system_locales), product):\n        value = (value or \"\").strip().replace(\"_\", \"-\")\n        if value and value != \"null\":\n            return value\n    return \"\"\n\n\ndef wifi_on(value):\n    \"\"\"`settings get global wifi_on`: 0 off, 1 on, 2 on in airplane mode, 3 off in airplane mode.\"\"\"\n    return {\"0\": False, \"1\": True, \"2\": True, \"3\": False}.get((value or \"\").strip())\n\n\ndef ipinfo_from_text(text):\n    \"\"\"ipinfo.io's answer read out of whatever text holds it: a JSON page as\n    a browser shows it, split over any number of lines.\"\"\"\n    found = {}\n    for key in (\"ip\", \"country\", \"timezone\", \"org\"):\n        match = re.search(r'\"%s\"\\s*:\\s*\"([^\"]*)\"' % key, text or \"\")\n        found[key] = match.group(1).strip() if match else \"\"\n    return found\n\n\ndef outside_from_screen(hierarchy_xml):\n    return ipinfo_from_text(\" \".join(screen_lines(hierarchy_xml)))\n\n\ndef checked_radio(hierarchy_xml):\n    \"\"\"The words of the ticked choice in a dialog of choices, or empty.\n    A radio button often has no words of its own; its row's do.\"\"\"\n    root = ElementTree.fromstring(hierarchy_xml)\n    parents = {child: parent for parent in root.iter() for child in parent}\n    for node in root.iter(\"node\"):\n        if node.get(\"checked\") != \"true\":\n            continue\n        if node.get(\"checkable\") != \"true\" and \"Radio\" not in (node.get(\"class\") or \"\"):\n            continue\n        words = node_words(node)\n        holder = parents.get(node)\n        while not words and holder is not None:\n            words = next((node_words(other) for other in holder.iter(\"node\") if other is not node and node_words(other)), \"\")\n            holder = parents.get(holder)\n        if words:\n            return words\n    return \"\"\n\n\ndef auto_update_word(label):\n    \"\"\"The Play Store's auto-update choice as off, wifi or any.\"\"\"\n    words = plain(label)\n    if \"don't\" in words or \"do not\" in words or \"never\" in words:\n        return \"off\"\n    if \"wi-fi\" in words or \"wifi\" in words:\n        return \"wifi\"\n    if \"any network\" in words:\n        return \"any\"\n    return \"\"\n\n\ndef battery_now(dumpsys_battery):\n    level = re.search(r\"^\\s*level:\\s*(\\d+)\", dumpsys_battery or \"\", re.M)\n    status = re.search(r\"^\\s*status:\\s*(\\d+)\", dumpsys_battery or \"\", re.M)\n    # 2 is charging and 5 is full, in Android's BatteryManager.\n    return {\"percent\": int(level.group(1)) if level else None, \"charging\": bool(status and status.group(1) in (\"2\", \"5\"))}\n\n\ndef blank_address():\n    return {\"ip\": \"\", \"country\": \"\", \"timezone\": \"\", \"org\": \"\", \"error\": \"\"}\n\n\ndef quietly(serial, command, timeout=15):\n    \"\"\"A shell command whose failure is an empty answer, for readings that may each fail alone.\"\"\"\n    try:\n        return shell(serial, command, timeout=timeout)\n    except (RuntimeError, subprocess.TimeoutExpired):\n        return \"\"\n\n\ndef read_home_address(fetch=None):\n    \"\"\"This computer's own outside address, which is the house's: the one a\n    phone on Wi-Fi must never show.\"\"\"\n    found = blank_address()\n    try:\n        if fetch is None:\n            request = urllib.request.Request(HOME_IPINFO_URL, headers={\"accept\": \"application/json\"})\n            with urllib.request.urlopen(request, timeout=15) as response:\n                text = response.read().decode(\"utf-8\")\n        else:\n            text = fetch(HOME_IPINFO_URL)\n        data = json.loads(text)\n        for key in (\"ip\", \"country\", \"timezone\", \"org\"):\n            found[key] = str(data.get(key) or \"\")\n    except (urllib.error.URLError, OSError, ValueError, AttributeError) as failure:\n        found[\"error\"] = \"This computer's own address could not be read: %s\" % failure\n    return found\n\n\ndef read_outside_on_phone(serial, walk):\n    \"\"\"The address, country and clock the internet sees from the phone, read\n    in the phone's own browser, the way any app's traffic leaves it.\"\"\"\n    found = blank_address()\n    try:\n        device = walk.screen()\n        walk.check()\n        if is_iphone(serial):\n            device.open_url(IPINFO_URL)\n        else:\n            shell(serial, \"am start -a android.intent.action.VIEW -d '%s'\" % IPINFO_URL)\n        for _ in range(6):\n            time.sleep(2.5)\n            walk.check()\n            seen = outside_from_screen(device.dump_hierarchy())\n            if seen[\"ip\"]:\n                found.update(seen)\n                break\n            for label in BROWSER_FIRST_RUN:\n                button = device(text=label)\n                if button.exists:\n                    walk.press(button)\n                    walk.shot(\"Pressed %s in the browser\" % label)\n                    break\n        walk.shot(\"Read the outside address in the browser\")\n        if not found[\"ip\"]:\n            found[\"error\"] = \"The phone's browser did not show ipinfo.io's answer within 15 seconds.\"\n    except Cancelled:\n        raise\n    except Exception as failure:  # One reading failing leaves the rest of the check.\n        found[\"error\"] = \"The phone's outside address could not be read: %s\" % (str(failure) or failure.__class__.__name__)\n    finally:\n        walk.home()\n    return found\n\n\ndef read_auto_update(serial, walk):\n    \"\"\"The Play Store's auto-update choice, read off its own settings: (off,\n    wifi, any or empty; why when empty). Nothing is changed: the choices\n    are only looked at, and the box is closed with Back.\"\"\"\n    try:\n        walk.check()\n        shell(serial, \"monkey -p %s -c android.intent.category.LAUNCHER 1\" % PLAY_STORE)\n        time.sleep(4)\n        walk.shot(\"Opened the Play Store\")\n        walk.tap_first(\"Open the account menu\", selectors=PLAY_ACCOUNT_BUTTON)\n        walk.tap_first(\"Open Settings\", selectors=PLAY_SETTINGS)\n        walk.tap_first(\"Open Network preferences\", selectors=PLAY_NETWORK)\n        walk.tap_first(\"Open Auto-update apps\", selectors=PLAY_AUTO_UPDATE)\n        label = checked_radio(walk.screen().dump_hierarchy())\n        walk.shot(\"Read auto-update: %s\" % (label or \"nothing ticked\"))\n        go_back(serial)\n        word = auto_update_word(label)\n        return word, \"\" if word else \"No auto-update choice was ticked on the Play Store's screen.\"\n    except Cancelled:\n        raise\n    except Exception as failure:  # One reading failing leaves the rest of the check.\n        return \"\", \"The Play Store's auto-update choice could not be read: %s\" % (str(failure) or failure.__class__.__name__)\n    finally:\n        walk.home()\n\n\n# The same check on an iPhone (phone farm part 53), read off iOS's own\n# Settings, each row by its label. iOS writes \"Wi-Fi\" with a non-breaking\n# hyphen, so the row is matched with any one character there.\nIOS_WIFI_ROW = [{\"textMatches\": \"(?i)^wi.fi$\", \"packageName\": IOS_SETTINGS}]\nIOS_PRIVACY_ROW = [{\"textMatches\": \"(?i)^privacy( & security)?$\", \"packageName\": IOS_SETTINGS}]\nIOS_LOCATION_ROW = [{\"textMatches\": \"(?i)^location services$\", \"packageName\": IOS_SETTINGS}]\nIOS_GENERAL_ROW = [{\"textMatches\": \"(?i)^general$\", \"packageName\": IOS_SETTINGS}]\nIOS_LANGUAGE_ROW = [{\"textMatches\": \"(?i)^language & region$\", \"packageName\": IOS_SETTINGS}]\nIOS_ABOUT_ROW = [{\"textMatches\": \"(?i)^about$\", \"packageName\": IOS_SETTINGS}]\nIOS_APP_STORE_ROW = [{\"textMatches\": \"(?i)^app store$\", \"packageName\": IOS_SETTINGS}]\nIOS_WIFI_SWITCH = \"wi-fi\"\nIOS_LOCATION_SWITCH = \"location services\"\nIOS_APP_UPDATES_SWITCH = \"app updates\"\n\n# Language & Region names the language and the region in words. The locale\n# fact is en-CA, as Android gives it, so the words are turned into codes\n# through these two tables; a word in neither leaves the locale blank\n# rather than guessed.\nIOS_LANGUAGE_CODES = {\n    \"english\": \"en\", \"french\": \"fr\", \"spanish\": \"es\", \"german\": \"de\", \"portuguese\": \"pt\",\n    \"italian\": \"it\", \"dutch\": \"nl\", \"chinese\": \"zh\", \"japanese\": \"ja\", \"korean\": \"ko\",\n    \"arabic\": \"ar\", \"hindi\": \"hi\", \"russian\": \"ru\", \"swedish\": \"sv\", \"polish\": \"pl\",\n    \"turkish\": \"tr\", \"vietnamese\": \"vi\", \"thai\": \"th\", \"indonesian\": \"id\", \"tagalog\": \"tl\",\n}\nIOS_REGION_CODES = {\n    \"united states\": \"US\", \"us\": \"US\", \"u.s.\": \"US\", \"canada\": \"CA\", \"united kingdom\": \"GB\", \"uk\": \"GB\",\n    \"u.k.\": \"GB\", \"australia\": \"AU\", \"new zealand\": \"NZ\", \"ireland\": \"IE\", \"germany\": \"DE\", \"france\": \"FR\",\n    \"spain\": \"ES\", \"mexico\": \"MX\", \"brazil\": \"BR\", \"portugal\": \"PT\", \"italy\": \"IT\", \"netherlands\": \"NL\",\n    \"india\": \"IN\", \"japan\": \"JP\", \"south korea\": \"KR\", \"philippines\": \"PH\", \"singapore\": \"SG\",\n    \"south africa\": \"ZA\", \"sweden\": \"SE\", \"poland\": \"PL\", \"turkey\": \"TR\", \"vietnam\": \"VN\", \"thailand\": \"TH\",\n    \"indonesia\": \"ID\", \"argentina\": \"AR\", \"colombia\": \"CO\", \"chile\": \"CL\", \"belgium\": \"BE\", \"switzerland\": \"CH\",\n    \"austria\": \"AT\", \"norway\": \"NO\", \"denmark\": \"DK\", \"finland\": \"FI\",\n}\n\n\ndef open_ios_settings(serial):\n    \"\"\"Settings on its first screen. iOS reopens an app where it was left, so\n    Settings is closed first.\"\"\"\n    reopen_app(serial, IOS_SETTINGS)\n    time.sleep(2)\n\n\ndef ios_switch_on(hierarchy_xml, label):\n    \"\"\"Whether the switch labelled `label` is on: True, False, or None when no\n    such switch is on screen. The switch carries the label itself, or sits in\n    a cell with a line that does.\"\"\"\n    wanted = plain(label)\n    root = ElementTree.fromstring(hierarchy_xml)\n    for node in root.iter(\"node\"):\n        if ios_kind(node).endswith(\"Switch\") and plain(node.get(\"label\") or node.get(\"name\") or \"\") == wanted:\n            return node.get(\"checked\") == \"true\"\n    for cell in root.iter(\"node\"):\n        if not ios_kind(cell).endswith(\"Cell\"):\n            continue\n        children = [child for child in cell.iter(\"node\") if child is not cell]\n        if not any(plain(node_words(child)) == wanted for child in children):\n            continue\n        switch = next((child for child in children if ios_kind(child).endswith(\"Switch\")), None)\n        if switch is not None:\n            return switch.get(\"checked\") == \"true\"\n    return None\n\n\ndef ios_cell_value(hierarchy_xml, label):\n    \"\"\"The value beside `label` in an iPhone list, \"Canada\" beside \"Region\",\n    or None when no row on screen starts with the label.\"\"\"\n    wanted = plain(label)\n    for words in ios_cells(hierarchy_xml):\n        if plain(words[0]) == wanted:\n            return \" \".join(words[1:])\n    return None\n\n\ndef ios_location_allowed(hierarchy_xml, app_name):\n    \"\"\"Whether Location Services lists the app as allowed: Never and Ask Next\n    Time are not; While Using and Always are; a row not on screen is None.\"\"\"\n    value = ios_cell_value(hierarchy_xml, app_name)\n    if value is None:\n        return None\n    words = plain(value)\n    return not (words.startswith(\"never\") or words.startswith(\"ask\"))\n\n\ndef ios_locale(language, region):\n    \"\"\"en-CA from \"English\" and \"Canada\", or from \"English (Canada)\" alone,\n    through the two tables. Empty when either word is in neither table.\"\"\"\n    language = language or \"\"\n    code = IOS_LANGUAGE_CODES.get(plain(language.split(\"(\")[0]).strip(), \"\")\n    region_code = IOS_REGION_CODES.get(plain(region or \"\").strip(), \"\")\n    inner = re.search(r\"\\(([^)]+)\\)\", language)\n    if not region_code and inner:\n        region_code = IOS_REGION_CODES.get(plain(inner.group(1)).strip(), \"\")\n    return \"%s-%s\" % (code, region_code) if code and region_code else \"\"\n\n\ndef carrier_name(value):\n    \"\"\"\"Rogers\" from the About screen's \"Rogers 59.0.1\", which adds the carrier settings' version.\"\"\"\n    return re.sub(r\"\\s+\\d+(?:\\.\\d+)*$\", \"\", (value or \"\").strip())\n\n\ndef ios_setup_check(serial, args, walk):\n    \"\"\"The setup check on an iPhone, the same facts as Android's, read off\n    Settings, the driver and Safari. Each part runs in its own try: one that\n    cannot be read leaves its fact blank, never guessed, and the rest go on.\"\"\"\n    device = walk.screen()\n    wake_screen(device)\n    timezone = _PROPS.get(serial, {}).get(\"timezone\", \"\")  # Lockdown's TimeZone, cached by the list.\n    facts = {\n        \"wifiOn\": None,\n        \"locationApps\": {},\n        \"timezone\": timezone,\n        \"timezoneCountry\": zone_country(timezone),\n        \"locale\": \"\",\n        \"sim\": {\"country\": \"\", \"carrier\": \"\"},\n        \"network\": {\"carrier\": \"\"},\n        \"autoUpdate\": \"\",\n        \"autoUpdateError\": \"\",\n        \"battery\": {\"percent\": None, \"charging\": None},\n        \"outside\": blank_address(),\n        \"home\": blank_address(),\n    }\n\n    def part(name, read):\n        try:\n            walk.check()\n            read()\n        except Cancelled:\n            raise\n        except Exception as failure:  # This part stays blank; the next is still read.\n            log(\"Could not read %s on %s: %s\" % (name, serial, short_words(failure)))\n            walk.shot(\"Could not read %s\" % name)\n        finally:\n            walk.home()\n\n    def wifi():\n        open_ios_settings(serial)\n        walk.tap_first(\"Open Wi-Fi\", selectors=IOS_WIFI_ROW)\n        time.sleep(1.5)\n        facts[\"wifiOn\"] = ios_switch_on(device.dump_hierarchy(), IOS_WIFI_SWITCH)\n        walk.shot(\"Read Wi-Fi: %s\" % {True: \"on\", False: \"off\"}.get(facts[\"wifiOn\"], \"no switch found\"))\n\n    def location():\n        open_ios_settings(serial)\n        scroll_to_first(walk, \"Find Privacy & Security\", IOS_PRIVACY_ROW)\n        walk.tap_first(\"Open Privacy & Security\", selectors=IOS_PRIVACY_ROW)\n        walk.tap_first(\"Open Location Services\", selectors=IOS_LOCATION_ROW)\n        time.sleep(1.5)\n        hierarchy = device.dump_hierarchy()\n        if ios_switch_on(hierarchy, IOS_LOCATION_SWITCH) is False:\n            # Off for every app at once; the list below it is empty then.\n            versions = iphone_app_versions(serial)\n            for app in (sorted(versions) if versions else sorted(APP_NAMES)):\n                facts[\"locationApps\"][app] = False\n            walk.shot(\"Read Location Services: off\")\n            return\n        for app in sorted(APP_NAMES):\n            scroll_to_first(walk, \"Find %s\" % APP_NAMES[app], [{\"text\": APP_NAMES[app], \"packageName\": IOS_SETTINGS}], scrolls=3)\n            allowed = ios_location_allowed(device.dump_hierarchy(), APP_NAMES[app])\n            if allowed is not None:\n                facts[\"locationApps\"][app] = allowed\n        walk.shot(\"Read Location Services\")\n\n    def language():\n        open_ios_settings(serial)\n        walk.tap_first(\"Open General\", selectors=IOS_GENERAL_ROW)\n        scroll_to_first(walk, \"Find Language & Region\", IOS_LANGUAGE_ROW)\n        walk.tap_first(\"Open Language & Region\", selectors=IOS_LANGUAGE_ROW)\n        time.sleep(1.5)\n        hierarchy = device.dump_hierarchy()\n        spoken = ios_cell_value(hierarchy, \"iPhone Language\")\n        region = ios_cell_value(hierarchy, \"Region\")\n        facts[\"locale\"] = ios_locale(spoken, region)\n        walk.shot(\"Read the language: %s, %s\" % (spoken or \"not shown\", region or \"no region\"))\n\n    def carrier():\n        open_ios_settings(serial)\n        walk.tap_first(\"Open General\", selectors=IOS_GENERAL_ROW)\n        walk.tap_first(\"Open About\", selectors=IOS_ABOUT_ROW)\n        scroll_to_first(walk, \"Find the carrier\", [{\"textMatches\": \"(?i)^carrier$\", \"packageName\": IOS_SETTINGS}], scrolls=3)\n        hierarchy = device.dump_hierarchy()\n        facts[\"sim\"][\"carrier\"] = carrier_name(ios_cell_value(hierarchy, \"Carrier\"))\n        facts[\"network\"][\"carrier\"] = carrier_name(ios_cell_value(hierarchy, \"Network\"))\n        walk.shot(\"Read the carrier: %s\" % (facts[\"sim\"][\"carrier\"] or \"not shown\"))\n\n    def updates():\n        open_ios_settings(serial)\n        scroll_to_first(walk, \"Find App Store\", IOS_APP_STORE_ROW)\n        walk.tap_first(\"Open App Store\", selectors=IOS_APP_STORE_ROW)\n        time.sleep(1.5)\n        state = ios_switch_on(device.dump_hierarchy(), IOS_APP_UPDATES_SWITCH)\n        # On, the App Store fetches updates on Wi-Fi and on cellular alike.\n        facts[\"autoUpdate\"] = {True: \"any\", False: \"off\"}.get(state, \"\")\n        if state is None:\n            facts[\"autoUpdateError\"] = \"No App Updates switch was found on the App Store settings screen.\"\n        walk.shot(\"Read App Updates: %s\" % (facts[\"autoUpdate\"] or \"no switch found\"))\n\n    def battery():\n        facts[\"battery\"][\"percent\"] = iphone_vitals(serial)[\"batteryPercent\"]\n\n    part(\"Wi-Fi\", wifi)\n    part(\"Location Services\", location)\n    part(\"Language & Region\", language)\n    part(\"the carrier\", carrier)\n    part(\"App Updates\", updates)\n    part(\"the battery\", battery)\n    facts[\"outside\"] = read_outside_on_phone(serial, walk)\n    facts[\"home\"] = read_home_address()\n    return facts\n\n\ndef action_setup_check(serial, args, walk):\n    \"\"\"Everything the setup check reads off one phone (part 23).\"\"\"\n    if is_iphone(serial):\n        return ios_setup_check(serial, args, walk)\n    versions = parse_app_versions(quietly(serial, APPS_COMMAND, timeout=30))\n    location = {}\n    for app in sorted(versions):\n        location[app] = location_granted(quietly(serial, \"dumpsys package %s\" % APP_PACKAGES[app], timeout=30))\n    timezone = quietly(serial, \"getprop persist.sys.timezone\")\n    auto_update, auto_update_error = read_auto_update(serial, walk)\n    return {\n        \"wifiOn\": wifi_on(quietly(serial, \"settings get global wifi_on\")),\n        \"locationApps\": location,\n        \"timezone\": timezone,\n        \"timezoneCountry\": zone_country(timezone),\n        \"locale\": pick_locale(\n            quietly(serial, \"getprop persist.sys.locale\"),\n            quietly(serial, \"settings get system system_locales\"),\n            quietly(serial, \"getprop ro.product.locale\"),\n        ),\n        \"sim\": {\n            \"country\": first_listed(quietly(serial, \"getprop gsm.sim.operator.iso-country\")).upper(),\n            \"carrier\": first_listed(quietly(serial, \"getprop gsm.sim.operator.alpha\")),\n        },\n        \"network\": {\"carrier\": first_listed(quietly(serial, \"getprop gsm.operator.alpha\"))},\n        \"autoUpdate\": auto_update,\n        \"autoUpdateError\": auto_update_error,\n        \"battery\": battery_now(quietly(serial, \"dumpsys battery\")),\n        \"outside\": read_outside_on_phone(serial, walk),\n        \"home\": read_home_address(),\n    }\n\n\ndef action_outside_address(serial, args, walk):\n    \"\"\"The phone's outside address beside the house's, read before a job on a\n    phone that goes out through a proxy over Wi-Fi (part 28).\"\"\"\n    return {\"phone\": read_outside_on_phone(serial, walk), \"home\": read_home_address()}\n\n\n# ---------------------------------------------------------------------------\n# The wipe (part 26). A factory reset through the phone's own Settings, so a\n# new account never inherits an old one's device history. The press that\n# erases goes through Walk.final, so a rehearsal can never wipe a phone, and\n# the wipe is not rehearsed at all. USB debugging goes with the wipe, so the\n# phone is set up again by hand afterwards.\n\nSETTINGS = \"com.android.settings\"\nFACTORY_RESET_ACTIVITY = \"com.android.settings/.Settings$FactoryResetActivity\"\n\nWIPE_SYSTEM = [\n    {\"textMatches\": \"(?i)^system$\", \"packageName\": SETTINGS},\n    {\"textMatches\": \"(?i)^general management$\"},\n]\nWIPE_RESET_MENU = [\n    {\"textMatches\": \"(?i)^reset options$\", \"packageName\": SETTINGS},\n    {\"textMatches\": \"(?i)^reset$\"},\n]\nWIPE_ENTRY = [\n    {\"textMatches\": \"(?i)^erase all data \\\\(factory reset\\\\)$\"},\n    {\"textMatches\": \"(?i)^factory data reset$\"},\n]\nWIPE_ERASE = [{\"textMatches\": \"(?i)^(erase all data|reset|reset device)$\"}]\nWIPE_CONFIRM = [{\"textMatches\": \"(?i)^(erase all data|delete all|reset)$\"}]\n\n\ndef scroll_to_first(walk, step, selectors, scrolls=5):\n    \"\"\"Finds one of the shapes, scrolling the screen down between looks.\"\"\"\n    device = walk.screen()\n    for _ in range(scrolls):\n        walk.check()\n        for selector in selectors:\n            if device(**selector).exists:\n                return\n        scroller = device(scrollable=True)\n        if not scroller.exists:\n            return\n        scroller.scroll.forward()\n        time.sleep(1)\n\n\n# An iPhone's wipe (phone farm part 54). Erased while still signed in to an\n# Apple ID, the phone locks to that Apple ID and is useless to the rack, so\n# the wipe runs only when Promo says the sign-out is done (a person did it in\n# the screen window and phone/icloud-state read the phone as signed out).\nIOS_WIPE_RESET_MENU = [{\"textMatches\": \"(?i)^(transfer or reset iphone|reset)$\", \"packageName\": IOS_SETTINGS}]\nIOS_WIPE_ENTRY = [{\"textMatches\": \"(?i)^erase all content and settings$\", \"packageName\": IOS_SETTINGS}]\nIOS_WIPE_CONTINUE = [{\"textMatches\": \"(?i)^continue$\", \"packageName\": IOS_SETTINGS}]\nIOS_WIPE_ERASE = [{\"textMatches\": \"(?i)^(erase iphone|erase this iphone|erase now|erase)$\", \"packageName\": IOS_SETTINGS}]\nIOS_PASSCODE_WORDS = (\"enter passcode\", \"enter your passcode\", \"enter iphone passcode\")\nIOS_SIGNED_OUT_WORDS = (\"sign in to your iphone\", \"sign in to iphone\")\nIOS_APPLE_ID_WORDS = (\"apple id\", \"apple account\", \"icloud\", \"media & purchases\")\nWIPE_NOT_SIGNED_OUT = (\n    \"The iPhone was not wiped: Promo did not say its Apple ID is signed out. \"\n    \"Sign out of iCloud in the screen window, let Promo read the phone as signed out, then wipe it.\"\n)\n\n\ndef ios_asks_passcode(hierarchy_xml):\n    \"\"\"True when iOS is asking for the phone's passcode: its words, or a secure field.\"\"\"\n    lines = [plain(line) for line in screen_lines(hierarchy_xml)]\n    if any(any(words in line for words in IOS_PASSCODE_WORDS) for line in lines):\n        return True\n    return any(ios_kind(node) == \"XCUIElementTypeSecureTextField\" for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"))\n\n\ndef icloud_from_screen(hierarchy_xml):\n    \"\"\"What Settings' top row says: the person's name beside Apple ID, or\n    \"Sign in to your iPhone\". None when neither row is on screen.\"\"\"\n    for words in ios_cells(hierarchy_xml):\n        joined = plain(\" \".join(words))\n        if any(phrase in joined for phrase in IOS_SIGNED_OUT_WORDS):\n            return {\"signedOut\": True, \"appleId\": \"\"}\n        if any(phrase in joined for phrase in IOS_APPLE_ID_WORDS):\n            return {\"signedOut\": False, \"appleId\": words[0][:200]}\n    return None\n\n\ndef action_icloud_state(serial, args, walk):\n    \"\"\"Whether an Apple ID is signed in, read off Settings' top row. Nothing is pressed.\"\"\"\n    if not is_iphone(serial):\n        raise RuntimeError(\"phone/icloud-state is only for an iPhone.\")\n    device = walk.screen()\n    wake_screen(device)\n    walk.check()\n    open_ios_settings(serial)\n    walk.shot(\"Opened Settings\")\n    state = icloud_from_screen(device.dump_hierarchy())\n    if state is None:\n        walk.shot(\"Looked for the Apple ID row\")\n        walk.home()\n        raise StepFailed(\"Find the Apple ID row\", \"Settings opened, but its top row named neither an Apple ID nor Sign in to your iPhone.\")\n    walk.shot(\"Read: %s\" % (\"signed out\" if state[\"signedOut\"] else \"signed in as %s\" % state[\"appleId\"]))\n    walk.home()\n    return state\n\n\ndef ios_wipe(serial, args, walk):\n    \"\"\"Erase All Content and Settings through Settings, only once Promo says\n    the Apple ID is signed out. The erase itself goes through final_first;\n    a passcode prompt stops the walk with a picture.\"\"\"\n    if args.get(\"icloudSignedOut\") is not True:\n        raise RuntimeError(WIPE_NOT_SIGNED_OUT)\n    device = walk.screen()\n    wake_screen(device)\n    walk.check()\n    open_ios_settings(serial)\n    walk.shot(\"Opened Settings\")\n    walk.tap_first(\"Open General\", selectors=IOS_GENERAL_ROW)\n    scroll_to_first(walk, \"Find Transfer or Reset iPhone\", IOS_WIPE_RESET_MENU)\n    walk.tap_first(\"Open Transfer or Reset iPhone\", selectors=IOS_WIPE_RESET_MENU)\n    walk.tap_first(\"Open Erase All Content and Settings\", selectors=IOS_WIPE_ENTRY)\n    time.sleep(1.5)\n    walk.tap_first(\"Press Continue\", selectors=IOS_WIPE_CONTINUE)\n    time.sleep(1.5)\n    if ios_asks_passcode(device.dump_hierarchy()):\n        walk.shot(\"The phone asks for its passcode\")\n        raise StepFailed(\"Enter the passcode\", \"The phone asks for its passcode; wipe it by hand.\")\n    pressed = walk.final_first(\"Press Erase iPhone\", selectors=IOS_WIPE_ERASE)\n    if pressed:\n        # iOS asks once more on a sheet of its own.\n        time.sleep(1.5)\n        if any(device(**selector).exists for selector in IOS_WIPE_ERASE):\n            walk.final_first(\"Confirm the erase\", selectors=IOS_WIPE_ERASE)\n    return {\"wiped\": bool(pressed)}\n\n\ndef action_wipe(serial, args, walk):\n    \"\"\"Erases everything on the phone. Returns as soon as the erase is pressed;\n    the phone restarts into its setup screens.\"\"\"\n    if is_iphone(serial):\n        return ios_wipe(serial, args, walk)\n    device = walk.screen()\n    device.screen_on()\n    walk.check()\n    opened = quietly(serial, \"am start -n '%s'\" % FACTORY_RESET_ACTIVITY)\n    time.sleep(2)\n    if not opened or \"Error\" in opened or \"Exception\" in opened:\n        shell(serial, \"am start -a android.settings.SETTINGS\")\n        time.sleep(2)\n        walk.shot(\"Opened Settings\")\n        scroll_to_first(walk, \"Find System\", WIPE_SYSTEM)\n        walk.tap_first(\"Open System\", selectors=WIPE_SYSTEM)\n        scroll_to_first(walk, \"Find Reset options\", WIPE_RESET_MENU)\n        walk.tap_first(\"Open Reset options\", selectors=WIPE_RESET_MENU)\n        walk.tap_first(\"Open Erase all data\", selectors=WIPE_ENTRY)\n    else:\n        walk.shot(\"Opened Erase all data\")\n    scroll_to_first(walk, \"Find the erase button\", WIPE_ERASE)\n    walk.tap_first(\"Press Erase all data\", selectors=WIPE_ERASE)\n    time.sleep(1.5)\n    pressed = walk.final_first(\"Confirm the erase\", selectors=WIPE_CONFIRM)\n    return {\"wiped\": bool(pressed)}\n\n\n# ---------------------------------------------------------------------------\n# Reddit through the Reddit app (phone farm part 29). The same names and the\n# same answers as the browser's routines, so nothing above the rack knows\n# whether a phone or a browser did the work. Searches and thread reads stay\n# with the signed-out reader browser (Tyler, 14 Oct 2026); a phone signs in,\n# reads its own account and comments.\n#\n# Who is signed in is read off the app's account menu: \"u/name\", the karma\n# and the \"Reddit age\". The app shows the age rounded (\"2y\", \"5d\"), so the\n# day the account was made is worked out counting the age down, and an\n# approximate age never makes an account look older than it is.\n\nREDDIT = APP_PACKAGES[\"reddit\"]\n\nREDDIT_AVATAR = [\n    {\n        \"descriptionMatches\": \"(?i)^(open profile|profile|account|user account|user profile|your profile|navigate to profile|open account menu|.*avatar.*)$\",\n        \"packageName\": REDDIT,\n    },\n    {\"resourceIdMatches\": \"(?i).*(avatar|user_icon|nav_icon_profile).*\", \"packageName\": REDDIT},\n]\nREDDIT_PROFILE_ENTRY = [{\"textMatches\": \"(?i)^(profile|my profile|view profile)$\", \"packageName\": REDDIT}]\nREDDIT_COMMENT_BOX = [\n    {\"textMatches\": \"(?i)^(add a comment|join the conversation|add a reply)( ?(…|\\\\.\\\\.\\\\.))?$\", \"packageName\": REDDIT},\n    {\"descriptionMatches\": \"(?i)^(add a comment|join the conversation|add a reply)( ?(…|\\\\.\\\\.\\\\.))?$\", \"packageName\": REDDIT},\n]\nREDDIT_POST_BUTTON = [\n    {\"textMatches\": \"(?i)^(post|reply|comment)$\", \"packageName\": REDDIT},\n    {\"descriptionMatches\": \"(?i)^(post|reply|comment)$\", \"packageName\": REDDIT},\n]\nREDDIT_DISCARD = [{\"textMatches\": \"(?i)^(discard|discard comment|leave)$\"}]\n\nHANDLE_LINE = re.compile(r\"^u/([A-Za-z0-9_-]{3,20})$\")\nKARMA_TEXT = re.compile(r\"^\\d[\\d,]*(\\.\\d+)?\\s*[kKmM]?$\")\nAGE_TEXT = re.compile(r\"^(\\d+\\s*(y|yr|yrs|year|years|mo|mos|month|months|w|wk|wks|week|weeks|d|day|days|h|hr|hrs|m|min|mins|s)\\s*)+$\", re.I)\nKARMA_LINE = re.compile(r\"^(\\d[\\d,]*(?:\\.\\d+)?\\s*[kKmM]?)\\s+karma$\", re.I)\nAGE_LINE = re.compile(r\"^(.+?)\\s+reddit age$\", re.I)\nPROFILE_SUSPENDED = (\"this account has been suspended\", \"account suspended\", \"has been suspended\")\nPOSTED_WORDS = (\"comment posted\", \"your comment was posted\", \"reply posted\", \"comment sent\")\n\nAGE_UNIT_DAYS = {\n    \"y\": 365, \"yr\": 365, \"yrs\": 365, \"year\": 365, \"years\": 365,\n    \"mo\": 30, \"mos\": 30, \"month\": 30, \"months\": 30,\n    \"w\": 7, \"wk\": 7, \"wks\": 7, \"week\": 7, \"weeks\": 7,\n    \"d\": 1, \"day\": 1, \"days\": 1,\n    # Under a day, and \"m\" read as minutes rather than months: counted down.\n    \"h\": 0, \"hr\": 0, \"hrs\": 0, \"m\": 0, \"min\": 0, \"mins\": 0, \"s\": 0,\n}\n\n# The comment's visit, as the browser's: feed before, the post, the comment, feed after.\nFEED_BEFORE_SECONDS = (60, 150)\nPOSTS_BEFORE = (0, 2)\nFEED_AFTER_SECONDS = (20, 60)\nFEED_POST_SECONDS = (4, 12)\nPOST_LANDED_SECONDS = 20\n# The visit plans to finish well inside Promo's 930 seconds (less the\n# rack's own minute), keeping room to type the comment.\nVISIT_BUDGET_SECONDS = 780\nCOMMENT_RESERVE_SECONDS = 120\nTYPING_SECONDS_PER_CHARACTER = 0.25\n\n\ndef parse_karma(text):\n    \"\"\"1,234 or 1.2k as a number, or None.\"\"\"\n    found = re.match(r\"^(\\d+(?:\\.\\d+)?)\\s*([km]?)$\", (text or \"\").strip().lower().replace(\",\", \"\"))\n    if not found:\n        return None\n    return int(round(float(found.group(1)) * {\"\": 1, \"k\": 1000, \"m\": 1000000}[found.group(2)]))\n\n\ndef parse_age_days(text):\n    \"\"\"\"2y\" as 730 days, \"3mo\" as 90, \"1y 2mo\" as 425, counted down; None when unreadable.\"\"\"\n    parts = re.findall(r\"(\\d+)\\s*([a-z]+)\", (text or \"\").strip().lower())\n    if not parts or any(unit not in AGE_UNIT_DAYS for _, unit in parts):\n        return None\n    return sum(int(number) * AGE_UNIT_DAYS[unit] for number, unit in parts)\n\n\ndef account_from_screen(hierarchy_xml, now=None):\n    \"\"\"Who the app's account menu says is signed in: handle, karma and the\n    day it was made. A menu with no u/ line is signed out.\"\"\"\n    now = now if now is not None else time.time()\n    lines = screen_lines(hierarchy_xml, app_packages(\"reddit\"))\n    handle = next((HANDLE_LINE.match(line).group(1) for line in lines if HANDLE_LINE.match(line)), None)\n    if not handle:\n        return {\"handle\": None, \"karma\": None, \"createdSeconds\": None}\n    karma_text = value_beside_label(hierarchy_xml, \"Karma\", KARMA_TEXT)\n    age_text = value_beside_label(hierarchy_xml, \"Reddit age\", AGE_TEXT)\n    for line in lines:\n        if karma_text is None and KARMA_LINE.match(line):\n            karma_text = KARMA_LINE.match(line).group(1)\n        if age_text is None and AGE_LINE.match(line):\n            age_text = AGE_LINE.match(line).group(1)\n    days = parse_age_days(age_text) if age_text else None\n    return {\n        \"handle\": handle,\n        \"karma\": parse_karma(karma_text) if karma_text else None,\n        \"createdSeconds\": float(now - days * 86400) if days is not None else None,\n    }\n\n\ndef profile_from_screen(hierarchy_xml, handle):\n    \"\"\"The account's own profile as the app shows it: loaded, found, suspended.\"\"\"\n    names = [plain(line) for line in screen_lines(hierarchy_xml, app_packages(\"reddit\"))]\n    found = (\"u/%s\" % handle).lower() in names or handle.lower() in names\n    suspended = any(any(words in name for words in PROFILE_SUSPENDED) for name in names)\n    return {\"status\": 200 if (found or suspended) else 0, \"found\": found, \"suspended\": suspended}\n\n\ndef handle_count(hierarchy_xml, handle):\n    \"\"\"How many lines on screen name the account: its comments in a thread.\"\"\"\n    if not handle:\n        return 0\n    wanted = (handle.lower(), \"u/%s\" % handle.lower())\n    return sum(1 for line in screen_lines(hierarchy_xml, app_packages(\"reddit\")) if plain(line).split(\" \")[0] in wanted)\n\n\ndef comment_landed(hierarchy_xml, handle, before):\n    names = [plain(line) for line in screen_lines(hierarchy_xml, app_packages(\"reddit\"))]\n    if any(any(words in name for words in POSTED_WORDS) for name in names):\n        return True\n    return handle_count(hierarchy_xml, handle) > before\n\n\ndef parse_bounds(text):\n    found = re.match(r\"^\\[(-?\\d+),(-?\\d+)\\]\\[(-?\\d+),(-?\\d+)\\]$\", text or \"\")\n    return tuple(int(part) for part in found.groups()) if found else None\n\n\ndef feed_post_titles(hierarchy_xml, height, app=\"reddit\"):\n    \"\"\"Post titles a thumb could open in the feed: long lines of the app's own\n    text in the middle of the screen, never a promoted post's. Reddit's\n    feed by default; X's feed reads the same way.\"\"\"\n    root = ElementTree.fromstring(hierarchy_xml)\n    parents = {child: parent for parent in root.iter() for child in parent}\n    titles = []\n    for node in root.iter(\"node\"):\n        if not own_node(node, app_packages(app)):\n            continue\n        words = (node.get(\"text\") or \"\").strip()\n        bounds = parse_bounds(node.get(\"bounds\"))\n        if len(words) < 25 or not bounds:\n            continue\n        middle = (bounds[1] + bounds[3]) / 2\n        if not (height * 0.2 <= middle <= height * 0.8):\n            continue\n        card = parents.get(parents.get(node)) if parents.get(node) is not None else None\n        nearby = [plain(node_words(other)) for other in (card.iter(\"node\") if card is not None else [])]\n        if any(word in (\"promoted\", \"sponsored\", \"ad\") for word in nearby):\n            continue\n        titles.append(bounds)\n    return titles\n\n\ndef new_visit():\n    return {\"beforeSeconds\": 0, \"afterSeconds\": 0, \"postsOpened\": 0, \"reachedBy\": \"address\", \"scrolls\": 0, \"problems\": []}\n\n\ndef short_words(failure):\n    return (str(failure) or failure.__class__.__name__).splitlines()[0][:200]\n\n\ndef open_reddit(serial):\n    open_app(serial, \"reddit\")\n\n\nPOST_LINK = re.compile(r\"^/r/[A-Za-z0-9_]+/comments/[A-Za-z0-9]+(/[A-Za-z0-9_%\\-]*)*/?$\")\n\n\ndef open_post_link(serial, permalink):\n    open_link(serial, \"reddit\", \"https://www.reddit.com%s\" % permalink)\n\n\ndef open_feed_post(serial, walk, app=\"reddit\"):\n    \"\"\"Opens one post from the feed by its title. False when none was on screen.\"\"\"\n    device = walk.screen()\n    _, height = screen_size(device)\n    titles = feed_post_titles(device.dump_hierarchy(), height, app)\n    if not titles:\n        return False\n    walk.check()\n    x, y = tap_point(random.choice(titles))\n    tap_at(serial, device, x, y)\n    time.sleep(2)\n    walk.shot(\"Opened a post in the feed\")\n    return True\n\n\ndef browse_feed(serial, walk, seconds, posts, visit, deadline):\n    \"\"\"Scrolls the home feed for about `seconds`, opening up to `posts` posts on the way.\"\"\"\n    device = walk.screen()\n    until = min(time.monotonic() + seconds, deadline)\n    opened = 0\n    while time.monotonic() < until:\n        walk.check()\n        up = visit[\"scrolls\"] and random.random() < SCROLL_BACK_CHANCE\n        scroll_once(serial, device, -1 if up else 1)\n        visit[\"scrolls\"] += 1\n        if opened < posts and random.random() < 0.3 and open_feed_post(serial, walk):\n            opened += 1\n            visit[\"postsOpened\"] += 1\n            time.sleep(random.uniform(*FEED_POST_SECONDS))\n            if random.random() < 0.5:\n                scroll_once(serial, device, 1)\n                visit[\"scrolls\"] += 1\n            go_back(serial)\n            time.sleep(1.5)\n        scroll_pause(until)\n\n\ndef read_post(serial, walk, length, visit):\n    \"\"\"Reads the post for longer the longer it is, a few scrolls down and the same back up.\"\"\"\n    device = walk.screen()\n    seconds = min(max(length * READ_SECONDS_PER_CHARACTER, READ_SECONDS[0]), READ_SECONDS[1])\n    until = time.monotonic() + seconds * random.uniform(0.8, 1.2)\n    down = 0\n    while time.monotonic() < until:\n        walk.check()\n        if down < 4 and random.random() < 0.6:\n            scroll_once(serial, device, 1)\n            down += 1\n            visit[\"scrolls\"] += 1\n        time.sleep(random.uniform(0.7, 2.2))\n    for _ in range(down):\n        walk.check()\n        scroll_once(serial, device, -1)\n        visit[\"scrolls\"] += 1\n        time.sleep(random.uniform(0.15, 0.6))\n\n\ndef read_account(serial, walk):\n    \"\"\"Opens the app's account menu and reads it. Leaves the menu open.\"\"\"\n    open_reddit(serial)\n    walk.shot(\"Opened Reddit\")\n    walk.tap_first(\"Open the account menu\", selectors=app_screens(serial, \"reddit\")[\"avatar\"])\n    time.sleep(1)\n    reading = account_from_screen(walk.screen().dump_hierarchy())\n    walk.shot(\"Read the account menu\")\n    return reading\n\n\ndef action_reddit_state(serial, args, walk):\n    \"\"\"Who the app is signed in as, with the karma and the age.\"\"\"\n    walk.screen().screen_on()\n    reading = read_account(serial, walk)\n    go_back(serial)\n    walk.home()\n    return dict(reading, blocked=False, reason=\"\", url=\"\")\n\n\ndef action_reddit_quick_state(serial, args, walk):\n    \"\"\"The same look, asked after every job. An app that cannot be read says\n    \"not checked\", so a failed look is never written down as signed out.\"\"\"\n    try:\n        reading = action_reddit_state(serial, args, walk)\n    except Cancelled:\n        raise\n    except Exception as failure:  # Not checked rather than signed out.\n        log(\"Could not read who is signed in on %s: %s\" % (serial, failure))\n        return {\"checked\": False, \"handle\": None, \"karma\": None, \"createdSeconds\": None, \"blocked\": False, \"reason\": \"\"}\n    return {\n        \"checked\": True,\n        \"handle\": reading[\"handle\"],\n        \"karma\": reading[\"karma\"],\n        \"createdSeconds\": reading[\"createdSeconds\"],\n        \"blocked\": False,\n        \"reason\": \"\",\n    }\n\n\ndef action_reddit_health(serial, args, walk):\n    \"\"\"The account's half of a health reading: who it is, its karma and age,\n    and its own profile as the app shows it. The stranger's half is the\n    reader browser's, never a phone's.\"\"\"\n    walk.screen().screen_on()\n    reading = read_account(serial, walk)\n    profile = None\n    if reading[\"handle\"]:\n        signed_in = {\"status\": 0, \"found\": False, \"suspended\": False}\n        try:\n            walk.tap_first(\"Open your profile\", selectors=app_screens(serial, \"reddit\")[\"profile_entry\"])\n            time.sleep(2)\n            signed_in = profile_from_screen(walk.screen().dump_hierarchy(), reading[\"handle\"])\n            walk.shot(\"Read your profile\")\n        except StepFailed:\n            # A rehearsal that cannot reach the profile is broken; a real\n            # reading says the profile did not load, which is status 0.\n            if walk.rehearse:\n                raise\n        profile = {\"signedIn\": signed_in}\n    walk.home()\n    return dict(reading, blocked=False, reason=\"\", profile=profile)\n\n\ndef leave_composer(serial, walk):\n    \"\"\"Out of the comment box without sending anything: Back, and Discard if asked.\"\"\"\n    go_back(serial)\n    time.sleep(1)\n    device = walk.screen()\n    for selector in app_screens(serial, \"reddit\")[\"discard\"]:\n        button = device(**selector)\n        if button.exists:\n            walk.press(button)\n            walk.shot(\"Left the comment box without sending\")\n            break\n\n\ndef action_reddit_comment(serial, args, walk):\n    \"\"\"Writes one comment under a post, inside an ordinary visit to the app.\n\n    Before: the home feed for a minute or two, sometimes opening a post.\n    Then who is signed in, the post by its link, the post read, the words\n    typed with a person's rhythm, a pause, and Post pressed once. After: a\n    little more feed. Nothing before the comment stops it except not being\n    signed in, and nothing after the press can fail it: it is on Reddit by\n    then and never sent twice. The comment's link is \"\" here; Promo reads it\n    afterwards from the signed-out reader browser.\n\n    In a rehearsal there is no feed and nothing is typed: the post opens,\n    the comment box opens, Post is found and not pressed, and the box is left.\n    \"\"\"\n    permalink = str(args.get(\"permalink\") or \"\").strip()\n    text = str(args.get(\"text\") or \"\").strip()\n    # Only a post's own address is opened, in a real run or a rehearsal.\n    if permalink and not POST_LINK.match(permalink):\n        raise RuntimeError(\"comment: permalink is not a Reddit post's address\")\n    if not walk.rehearse:\n        if not permalink.startswith(\"/\"):\n            raise RuntimeError(\"comment: permalink must start with /\")\n        if not text:\n            raise RuntimeError(\"comment: no words to post\")\n    device = walk.screen()\n    device.screen_on()\n    started = time.monotonic()\n    deadline = started + VISIT_BUDGET_SECONDS\n    reserve = COMMENT_RESERVE_SECONDS + len(text) * TYPING_SECONDS_PER_CHARACTER\n    visit = new_visit()\n    handle = None\n\n    if not walk.rehearse:\n        try:\n            open_reddit(serial)\n            walk.shot(\"Opened Reddit\")\n            browse_feed(serial, walk, random.uniform(*FEED_BEFORE_SECONDS), random.randint(*POSTS_BEFORE), visit, deadline - reserve)\n        except Cancelled:\n            raise\n        except Exception as failure:  # The comment still goes.\n            visit[\"problems\"].append(\"the feed before: %s\" % short_words(failure))\n        visit[\"beforeSeconds\"] = int(time.monotonic() - started)\n        handle = read_account(serial, walk)[\"handle\"]\n        go_back(serial)\n        if not handle:\n            raise RuntimeError(\"comment: the app is not signed in to Reddit\")\n\n    if permalink:\n        walk.check()\n        open_post_link(serial, permalink)\n        walk.shot(\"Opened the post\")\n    else:\n        open_reddit(serial)\n        if not open_feed_post(serial, walk):\n            raise StepFailed(\"Open a post\", \"No post was on the app's home feed to open.\")\n\n    thread = device.dump_hierarchy()\n    if not walk.rehearse:\n        read_post(serial, walk, len(\" \".join(screen_lines(thread, app_packages(\"reddit\")))), visit)\n        thread = device.dump_hierarchy()\n    before = handle_count(thread, handle)\n\n    walk.tap_first(\"Open the comment box\", selectors=app_screens(serial, \"reddit\")[\"comment_box\"])\n    if not walk.rehearse:\n        gaps = type_like_a_person(serial, device, text, walk.check)\n        walk.shot(\"Typed the comment\")\n        log(\"comment typed: %d characters, gaps %.2f to %.2f seconds\" % (len(text), min(gaps or [0]), max(gaps or [0])))\n        time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n\n    pressed = walk.final_first(\"Press Post\", selectors=app_screens(serial, \"reddit\")[\"post_button\"])\n    if not pressed:\n        leave_composer(serial, walk)\n        walk.home()\n        return {\"commentUrl\": \"\", \"visit\": visit}\n\n    landed = False\n    waiting_until = time.time() + POST_LANDED_SECONDS\n    while time.time() < waiting_until:\n        time.sleep(1)\n        try:\n            if comment_landed(device.dump_hierarchy(), handle, before):\n                landed = True\n                break\n        except Exception:  # A screen caught mid-change; look again.\n            continue\n    walk.shot(\"Looked for the comment\")\n    if not landed:\n        raise RuntimeError(\"comment: pressed Post but no new comment by u/%s appeared within %d seconds\" % (handle, POST_LANDED_SECONDS))\n\n    # After: nothing here may fail the comment, which is already on Reddit.\n    after_started = time.monotonic()\n    try:\n        seconds = min(random.uniform(*FEED_AFTER_SECONDS), deadline - after_started)\n        if seconds > 5:\n            go_back(serial)\n            time.sleep(1.5)\n            browse_feed(serial, walk, seconds, 0, visit, deadline)\n    except Exception as failure:  # Includes a cancel: the comment is out either way.\n        visit[\"problems\"].append(\"the feed after: %s\" % short_words(failure))\n    visit[\"afterSeconds\"] = int(time.monotonic() - after_started)\n    walk.home()\n    log(\"comment visit: %d seconds before, %d after, %d posts opened, %d scrolls; %s\" % (\n        visit[\"beforeSeconds\"], visit[\"afterSeconds\"], visit[\"postsOpened\"], visit[\"scrolls\"],\n        \"; \".join(visit[\"problems\"]) or \"no problems\",\n    ))\n    return {\"commentUrl\": \"\", \"visit\": visit}\n\n\n# ---------------------------------------------------------------------------\n# Instagram and TikTok (phone farm file 06), and the direct messages every\n# phone account reads, Reddit's included. The same steps in two apps, so one\n# set of actions reads each app's own buttons from APP_SCREENS.\n#\n# Nothing here posts, answers or changes a profile unless Promo sent the\n# action because a person pressed the button, and the last button (Share,\n# Post, Send, Save) is pressed once, through final_first, so a rehearsal\n# never presses it. Like Reddit's, every screen here was written from how\n# the apps are known to look, not dumped from a real phone (16 Oct 2026); the\n# self-test walks them first, and a step that does not find its button stops\n# with a picture of the screen.\n\nINSTAGRAM = APP_PACKAGES[\"instagram\"]\nTIKTOK = APP_PACKAGES[\"tiktok\"]\nTHREADS = APP_PACKAGES[\"threads\"]\nYOUTUBE = APP_PACKAGES[\"youtube\"]\n\n\ndef shapes(package, *patterns):\n    \"\"\"A button looked for by its words or its description, in each pattern given.\"\"\"\n    found = []\n    for pattern in patterns:\n        found.append({\"textMatches\": pattern, \"packageName\": package})\n        found.append({\"descriptionMatches\": pattern, \"packageName\": package})\n    return found\n\n\ndef field_in(package):\n    return [{\"className\": \"android.widget.EditText\", \"packageName\": package}]\n\n\nIOS_REDDIT, IOS_INSTAGRAM, IOS_TIKTOK = APP_BUNDLES[\"reddit\"], APP_BUNDLES[\"instagram\"], APP_BUNDLES[\"tiktok\"]\n\n\ndef ios_field_in(bundle):\n    \"\"\"A text box on an iPhone: a text field, a text view or a search field in the app's own tree.\"\"\"\n    return [{\"classNameMatches\": \"XCUIElementType(TextField|TextView|SearchField)\", \"packageName\": bundle}]\n\n\ndef ios_first_cell(bundle):\n    \"\"\"The first cell of a picker, which is the newest item in the library.\"\"\"\n    return [{\"className\": \"XCUIElementTypeCell\", \"packageName\": bundle}]\n\n\nAPP_SCREENS = {\n    \"instagram\": {\n        \"package\": INSTAGRAM,\n        \"profile_tab\": shapes(INSTAGRAM, \"(?i)^(profile|your profile)$\") + [{\"resourceIdMatches\": \"(?i).*profile_tab.*\", \"packageName\": INSTAGRAM}],\n        \"settings\": shapes(INSTAGRAM, \"(?i)^(options|menu|settings and activity|settings)$\"),\n        \"account_status\": shapes(INSTAGRAM, \"(?i)^account status$\"),\n        \"status_detail\": shapes(INSTAGRAM, \"(?i)^what can.?t be recommended$\"),\n        \"edit_profile\": shapes(INSTAGRAM, \"(?i)^edit profile$\"),\n        \"rows\": {\n            \"displayName\": shapes(INSTAGRAM, \"(?i)^name$\"),\n            \"bio\": shapes(INSTAGRAM, \"(?i)^bio$\"),\n            \"link\": shapes(INSTAGRAM, \"(?i)^(links|add link|add links|website)$\"),\n        },\n        \"link_add\": shapes(INSTAGRAM, \"(?i)^add external link$\"),\n        \"picture_row\": shapes(INSTAGRAM, \"(?i)^(edit picture or avatar|change profile photo|edit picture)$\"),\n        \"picture_library\": shapes(INSTAGRAM, \"(?i)^(choose from library|new profile picture|choose from gallery)$\"),\n        \"gallery_first\": [{\"resourceIdMatches\": \"(?i).*(gallery_grid_item|media_picker_item|thumbnail).*\", \"packageName\": INSTAGRAM}],\n        \"save\": shapes(INSTAGRAM, \"(?i)^(done|save)$\"),\n        \"next\": shapes(INSTAGRAM, \"(?i)^next$\"),\n        \"share_to\": shapes(INSTAGRAM, \"(?i)^(feed|reel|reels)$\"),\n        # A Story (part 8 of the 18 Nov 2026 features task): Story on the share\n        # screen, then Your story in the editor. Words from Instagram's share\n        # sheet and story editor as they are known, unproven on a phone.\n        \"story_to\": shapes(INSTAGRAM, \"(?i)^(story|stories|your story)$\"),\n        \"story_share\": shapes(INSTAGRAM, \"(?i)^(your story|share to your story|your stories)$\"),\n        \"story_posted\": (\"added to your story\", \"shared to your story\", \"your story is shared\", \"story shared\"),\n        \"caption\": shapes(INSTAGRAM, \"(?i)^(write a caption|add a caption)( ?(…|\\\\.\\\\.\\\\.))?$\"),\n        \"share\": shapes(INSTAGRAM, \"(?i)^share$\"),\n        \"posted\": (\"your post has been shared\", \"your reel has been shared\", \"post shared\", \"reel shared\", \"your post is live\"),\n        \"post_failed\": (\"couldn't post\", \"couldn't share\", \"upload failed\", \"couldn't upload\", \"post failed\"),\n        \"grid_first\": [\n            {\"descriptionMatches\": \"(?i).*row 1, column 1.*\", \"packageName\": INSTAGRAM},\n            {\"resourceIdMatches\": \"(?i).*(image_button|grid_card_layout_container).*\", \"packageName\": INSTAGRAM},\n        ],\n        \"more\": shapes(INSTAGRAM, \"(?i)^(more|more options|options)$\"),\n        \"copy_link\": shapes(INSTAGRAM, \"(?i)^(copy link|link)$\"),\n        \"inbox\": shapes(INSTAGRAM, \"(?i)^(direct|messenger|messages|message|direct messages)$\") + [{\"resourceIdMatches\": \"(?i).*(direct_tab|action_bar_inbox_button).*\", \"packageName\": INSTAGRAM}],\n        \"activity\": shapes(INSTAGRAM, \"(?i)^(notifications|activity)$\"),\n        \"message_box\": shapes(INSTAGRAM, \"(?i)^message( ?(…|\\\\.\\\\.\\\\.))?$\") + field_in(INSTAGRAM),\n        \"send\": shapes(INSTAGRAM, \"(?i)^send$\"),\n        \"reply\": shapes(INSTAGRAM, \"(?i)^reply$\"),\n        \"comment_box\": field_in(INSTAGRAM),\n        \"comment_send\": shapes(INSTAGRAM, \"(?i)^(post|send)$\"),\n        \"field\": field_in(INSTAGRAM),\n        \"handle_id\": \"(?i).*(action_bar_title|action_bar_large_title|profile_header_username|username).*\",\n        \"figures\": {\"posts\": \"posts\", \"followers\": \"followers\", \"following\": \"following\"},\n        \"hidden\": (\n            \"your account can't be recommended\",\n            \"can't be recommended to people who don't follow you\",\n            \"isn't eligible to be recommended\",\n            \"not eligible to be recommended\",\n            \"some of your content isn't eligible\",\n            \"your content may not be recommended\",\n        ),\n        \"clear\": (\n            \"your account can be recommended\",\n            \"you haven't posted anything that\",\n            \"no content is affected\",\n            \"nothing is affecting\",\n            \"eligible to be recommended\",\n        ),\n        \"link_shape\": re.compile(r\"^https://(www\\.)?instagram\\.com/(p|reel|tv)/[A-Za-z0-9_-]+/?(\\?\\S*)?$\"),\n    },\n    \"tiktok\": {\n        \"package\": TIKTOK,\n        \"profile_tab\": shapes(TIKTOK, \"(?i)^(profile|me)$\"),\n        \"settings\": shapes(TIKTOK, \"(?i)^(menu|settings and privacy|profile menu)$\"),\n        \"account_status\": shapes(TIKTOK, \"(?i)^account status$\"),\n        \"status_detail\": shapes(TIKTOK, \"(?i)^(for you feed eligibility|recommendation eligibility)$\"),\n        \"edit_profile\": shapes(TIKTOK, \"(?i)^edit profile$\"),\n        \"rows\": {\n            \"displayName\": shapes(TIKTOK, \"(?i)^name$\"),\n            \"bio\": shapes(TIKTOK, \"(?i)^bio$\"),\n            \"link\": shapes(TIKTOK, \"(?i)^(links|website|add link)$\"),\n        },\n        \"link_add\": shapes(TIKTOK, \"(?i)^(add link|website)$\"),\n        \"picture_row\": shapes(TIKTOK, \"(?i)^(change photo|edit photo|photo)$\"),\n        \"picture_library\": shapes(TIKTOK, \"(?i)^(select from gallery|upload photo|choose from gallery)$\"),\n        \"gallery_first\": [{\"resourceIdMatches\": \"(?i).*(media_item|gallery_item|thumbnail|cover).*\", \"packageName\": TIKTOK}],\n        \"save\": shapes(TIKTOK, \"(?i)^(save|confirm|done)$\"),\n        \"next\": shapes(TIKTOK, \"(?i)^next$\"),\n        \"share_to\": [],\n        \"caption\": shapes(TIKTOK, \"(?i)^(add description|describe your post|add a description).*$\") + field_in(TIKTOK),\n        \"share\": shapes(TIKTOK, \"(?i)^post$\"),\n        \"posted\": (\"your video is now posted\", \"posted\", \"your post is live\", \"upload complete\"),\n        \"post_failed\": (\"couldn't post\", \"upload failed\", \"couldn't upload\", \"post failed\"),\n        \"grid_first\": [{\"resourceIdMatches\": \"(?i).*(cover|video_cover|aweme_cover).*\", \"packageName\": TIKTOK}],\n        \"more\": shapes(TIKTOK, \"(?i)^(share|more)$\"),\n        \"copy_link\": shapes(TIKTOK, \"(?i)^copy link$\"),\n        \"inbox\": shapes(TIKTOK, \"(?i)^(inbox)$\"),\n        \"activity\": shapes(TIKTOK, \"(?i)^(activities|activity|comments)$\"),\n        \"message_box\": shapes(TIKTOK, \"(?i)^send a message( ?(…|\\\\.\\\\.\\\\.))?$\") + field_in(TIKTOK),\n        \"send\": shapes(TIKTOK, \"(?i)^send$\"),\n        \"reply\": shapes(TIKTOK, \"(?i)^reply$\"),\n        \"comment_box\": field_in(TIKTOK),\n        \"comment_send\": shapes(TIKTOK, \"(?i)^(post|send)$\"),\n        \"field\": field_in(TIKTOK),\n        \"handle_id\": \"\",\n        \"figures\": {\"posts\": \"\", \"followers\": \"followers\", \"following\": \"following\"},\n        \"hidden\": (\n            \"not eligible for the for you feed\",\n            \"ineligible for the for you feed\",\n            \"not eligible for recommendation\",\n            \"your account isn't eligible\",\n            \"may not be recommended\",\n        ),\n        \"clear\": (\"eligible for the for you feed\", \"good standing\", \"no violations\", \"your account is in good standing\"),\n        \"link_shape\": re.compile(r\"^https://((www|vm|vt)\\.)?tiktok\\.com/\\S+$\"),\n    },\n    # Threads (part 9 of the 18 Nov 2026 features task): TikTok's keys, with\n    # Threads' own words as they are known, unproven on a phone until the\n    # first self-test. A post is handed to Threads' share screen, which opens\n    # its composer with the file in; there is no Next. The name comes from\n    # Instagram, so only the bio, the link and the picture are its own.\n    # Threads has no Account status page, so no shadowban reading.\n    \"threads\": {\n        \"package\": THREADS,\n        \"profile_tab\": shapes(THREADS, \"(?i)^(profile)$\") + [{\"resourceIdMatches\": \"(?i).*profile.?tab.*\", \"packageName\": THREADS}],\n        \"settings\": shapes(THREADS, \"(?i)^(menu|settings|more options)$\"),\n        \"account_status\": [],\n        \"status_detail\": [],\n        \"edit_profile\": shapes(THREADS, \"(?i)^edit profile$\"),\n        \"rows\": {\n            \"displayName\": [],\n            \"bio\": shapes(THREADS, \"(?i)^bio$\"),\n            \"link\": shapes(THREADS, \"(?i)^(link|links|add link)$\"),\n        },\n        \"link_add\": [],\n        \"picture_row\": shapes(THREADS, \"(?i)^(edit picture|change profile picture|edit profile picture)$\"),\n        \"picture_library\": shapes(THREADS, \"(?i)^(choose from library|new profile picture|choose from gallery)$\"),\n        \"gallery_first\": [{\"resourceIdMatches\": \"(?i).*(gallery_grid_item|media_picker_item|thumbnail).*\", \"packageName\": THREADS}],\n        \"save\": shapes(THREADS, \"(?i)^(done|save)$\"),\n        \"next\": [],\n        \"share_to\": [],\n        \"caption\": shapes(THREADS, \"(?i)^(start a thread|what's new|what.s new\\\\?|say more)( ?(…|\\\\.\\\\.\\\\.))?$\") + field_in(THREADS),\n        \"share\": shapes(THREADS, \"(?i)^post$\"),\n        \"posted\": (\"posted\", \"your thread was posted\", \"thread posted\", \"post shared\"),\n        \"post_failed\": (\"couldn't post\", \"post failed\", \"upload failed\", \"couldn't upload\"),\n        \"grid_first\": [{\"resourceIdMatches\": \"(?i).*(thread_item|feed_item|post_container).*\", \"packageName\": THREADS}],\n        \"more\": shapes(THREADS, \"(?i)^(more|more options|share)$\"),\n        \"copy_link\": shapes(THREADS, \"(?i)^copy link$\"),\n        \"inbox\": shapes(THREADS, \"(?i)^(messages|inbox)$\"),\n        \"activity\": shapes(THREADS, \"(?i)^(activity|notifications)$\"),\n        \"message_box\": shapes(THREADS, \"(?i)^message( ?(…|\\\\.\\\\.\\\\.))?$\") + field_in(THREADS),\n        \"send\": shapes(THREADS, \"(?i)^send$\"),\n        \"reply\": shapes(THREADS, \"(?i)^reply$\"),\n        \"comment_box\": field_in(THREADS),\n        \"comment_send\": shapes(THREADS, \"(?i)^(post|reply)$\"),\n        \"field\": field_in(THREADS),\n        \"handle_id\": \"(?i).*(username|profile_header).*\",\n        \"figures\": {\"posts\": \"\", \"followers\": \"followers\", \"following\": \"\"},\n        \"hidden\": (),\n        \"clear\": (),\n        \"link_shape\": re.compile(r\"^https://(www\\.)?threads\\.(net|com)/@[A-Za-z0-9._]+/post/[A-Za-z0-9_-]+/?(\\?\\S*)?$\"),\n    },\n}\n\n# The same two apps on an iPhone (phone farm part 51), keyed by bundle id.\n# A button is found by its accessibility label (text or description here)\n# or its accessibility id (resourceId). The words the apps say, and the link\n# shapes, are the Android entries' own, since they are the same apps. The\n# post flow differs: no share screen is handed a file, so the app's own\n# create button and library picker are walked, \"create\", \"upload\" and\n# \"picker_first\". Written from how the apps are known to look (18 Oct 2026);\n# the first self-test on a real iPhone is the proof.\nAPP_SCREENS[IOS_INSTAGRAM] = {\n    \"package\": IOS_INSTAGRAM,\n    \"profile_tab\": shapes(IOS_INSTAGRAM, \"(?i)^(profile|your profile)$\") + [{\"resourceIdMatches\": \"(?i).*profile.?tab.*\", \"packageName\": IOS_INSTAGRAM}],\n    \"settings\": shapes(IOS_INSTAGRAM, \"(?i)^(options|menu|settings and activity|settings)$\") + [{\"resourceIdMatches\": \"(?i).*(settings|options).?button.*\", \"packageName\": IOS_INSTAGRAM}],\n    \"account_status\": shapes(IOS_INSTAGRAM, \"(?i)^account status$\"),\n    \"status_detail\": shapes(IOS_INSTAGRAM, \"(?i)^what can.?t be recommended$\"),\n    \"edit_profile\": shapes(IOS_INSTAGRAM, \"(?i)^edit profile$\"),\n    \"rows\": {\n        \"displayName\": shapes(IOS_INSTAGRAM, \"(?i)^name$\"),\n        \"bio\": shapes(IOS_INSTAGRAM, \"(?i)^bio$\"),\n        \"link\": shapes(IOS_INSTAGRAM, \"(?i)^(links|add link|add links|website)$\"),\n    },\n    \"link_add\": shapes(IOS_INSTAGRAM, \"(?i)^add external link$\"),\n    \"picture_row\": shapes(IOS_INSTAGRAM, \"(?i)^(edit picture or avatar|change profile photo|edit picture)$\"),\n    \"picture_library\": shapes(IOS_INSTAGRAM, \"(?i)^(choose from library|new profile picture|choose from gallery)$\"),\n    \"gallery_first\": ios_first_cell(IOS_INSTAGRAM),\n    \"create\": shapes(IOS_INSTAGRAM, \"(?i)^(create|new post|new|add|camera)$\") + [{\"resourceIdMatches\": \"(?i).*(create|camera).?tab.*\", \"packageName\": IOS_INSTAGRAM}],\n    \"upload\": [],\n    \"picker_first\": ios_first_cell(IOS_INSTAGRAM),\n    \"save\": shapes(IOS_INSTAGRAM, \"(?i)^(done|save)$\"),\n    \"next\": shapes(IOS_INSTAGRAM, \"(?i)^next$\"),\n    \"share_to\": shapes(IOS_INSTAGRAM, \"(?i)^(feed|reel|reels)$\"),\n    \"caption\": shapes(IOS_INSTAGRAM, \"(?i)^(write a caption|add a caption)( ?(…|\\\\.\\\\.\\\\.))?$\") + ios_field_in(IOS_INSTAGRAM),\n    \"keyboard_done\": [{\"textMatches\": \"(?i)^(ok|done)$\", \"packageName\": IOS_INSTAGRAM}],\n    \"share\": shapes(IOS_INSTAGRAM, \"(?i)^share$\"),\n    \"posted\": APP_SCREENS[\"instagram\"][\"posted\"],\n    \"post_failed\": APP_SCREENS[\"instagram\"][\"post_failed\"],\n    \"grid_first\": ios_first_cell(IOS_INSTAGRAM) + [{\"classNameMatches\": \"XCUIElementType(Image|Button)\", \"packageName\": IOS_INSTAGRAM, \"descriptionMatches\": \"(?i)^(photo|video|reel)( by .*)?$\"}],\n    \"more\": shapes(IOS_INSTAGRAM, \"(?i)^(more|more options|options)$\"),\n    \"copy_link\": shapes(IOS_INSTAGRAM, \"(?i)^(copy link|link)$\"),\n    \"inbox\": shapes(IOS_INSTAGRAM, \"(?i)^(direct|messenger|messages|message|direct messages)$\") + [{\"resourceIdMatches\": \"(?i).*(direct|inbox).?(tab|button).*\", \"packageName\": IOS_INSTAGRAM}],\n    \"activity\": shapes(IOS_INSTAGRAM, \"(?i)^(notifications|activity)$\"),\n    \"message_box\": shapes(IOS_INSTAGRAM, \"(?i)^message( ?(…|\\\\.\\\\.\\\\.))?$\") + ios_field_in(IOS_INSTAGRAM),\n    \"send\": shapes(IOS_INSTAGRAM, \"(?i)^send$\"),\n    \"reply\": shapes(IOS_INSTAGRAM, \"(?i)^reply$\"),\n    \"comment_box\": ios_field_in(IOS_INSTAGRAM),\n    \"comment_send\": shapes(IOS_INSTAGRAM, \"(?i)^(post|send)$\"),\n    \"field\": ios_field_in(IOS_INSTAGRAM),\n    # The username is the profile's own title bar on iOS; there is no id to match.\n    \"handle_in_title\": True,\n    \"figures\": APP_SCREENS[\"instagram\"][\"figures\"],\n    \"hidden\": APP_SCREENS[\"instagram\"][\"hidden\"],\n    \"clear\": APP_SCREENS[\"instagram\"][\"clear\"],\n    \"link_shape\": APP_SCREENS[\"instagram\"][\"link_shape\"],\n}\nAPP_SCREENS[IOS_TIKTOK] = {\n    \"package\": IOS_TIKTOK,\n    \"profile_tab\": shapes(IOS_TIKTOK, \"(?i)^(profile|me)$\"),\n    \"settings\": shapes(IOS_TIKTOK, \"(?i)^(menu|settings and privacy|profile menu)$\"),\n    \"account_status\": shapes(IOS_TIKTOK, \"(?i)^account status$\"),\n    \"status_detail\": shapes(IOS_TIKTOK, \"(?i)^(for you feed eligibility|recommendation eligibility)$\"),\n    \"edit_profile\": shapes(IOS_TIKTOK, \"(?i)^edit profile$\"),\n    \"rows\": {\n        \"displayName\": shapes(IOS_TIKTOK, \"(?i)^name$\"),\n        \"bio\": shapes(IOS_TIKTOK, \"(?i)^bio$\"),\n        \"link\": shapes(IOS_TIKTOK, \"(?i)^(links|website|add link)$\"),\n    },\n    \"link_add\": shapes(IOS_TIKTOK, \"(?i)^(add link|website)$\"),\n    \"picture_row\": shapes(IOS_TIKTOK, \"(?i)^(change photo|edit photo|photo)$\"),\n    \"picture_library\": shapes(IOS_TIKTOK, \"(?i)^(select from gallery|upload photo|choose from gallery|choose from library)$\"),\n    \"gallery_first\": ios_first_cell(IOS_TIKTOK),\n    \"create\": shapes(IOS_TIKTOK, \"(?i)^(create|record|new|add)$\") + [{\"resourceIdMatches\": \"(?i).*(create|record|camera).?(tab|button).*\", \"packageName\": IOS_TIKTOK}],\n    \"upload\": shapes(IOS_TIKTOK, \"(?i)^(upload|album|gallery)$\"),\n    \"picker_first\": ios_first_cell(IOS_TIKTOK),\n    \"save\": shapes(IOS_TIKTOK, \"(?i)^(save|confirm|done)$\"),\n    \"next\": shapes(IOS_TIKTOK, \"(?i)^next$\"),\n    \"share_to\": [],\n    \"caption\": shapes(IOS_TIKTOK, \"(?i)^(add description|describe your post|add a description).*$\") + ios_field_in(IOS_TIKTOK),\n    \"keyboard_done\": [{\"textMatches\": \"(?i)^(ok|done)$\", \"packageName\": IOS_TIKTOK}],\n    \"share\": shapes(IOS_TIKTOK, \"(?i)^post$\"),\n    \"posted\": APP_SCREENS[\"tiktok\"][\"posted\"],\n    \"post_failed\": APP_SCREENS[\"tiktok\"][\"post_failed\"],\n    \"grid_first\": ios_first_cell(IOS_TIKTOK),\n    \"more\": shapes(IOS_TIKTOK, \"(?i)^(share|more)$\"),\n    \"copy_link\": shapes(IOS_TIKTOK, \"(?i)^copy link$\"),\n    \"inbox\": shapes(IOS_TIKTOK, \"(?i)^(inbox)$\"),\n    \"activity\": shapes(IOS_TIKTOK, \"(?i)^(activities|activity|comments)$\"),\n    \"message_box\": shapes(IOS_TIKTOK, \"(?i)^send a message( ?(…|\\\\.\\\\.\\\\.))?$\") + ios_field_in(IOS_TIKTOK),\n    \"send\": shapes(IOS_TIKTOK, \"(?i)^send$\"),\n    \"reply\": shapes(IOS_TIKTOK, \"(?i)^reply$\"),\n    \"comment_box\": ios_field_in(IOS_TIKTOK),\n    \"comment_send\": shapes(IOS_TIKTOK, \"(?i)^(post|send)$\"),\n    \"field\": ios_field_in(IOS_TIKTOK),\n    \"handle_in_title\": False,\n    \"figures\": APP_SCREENS[\"tiktok\"][\"figures\"],\n    \"hidden\": APP_SCREENS[\"tiktok\"][\"hidden\"],\n    \"clear\": APP_SCREENS[\"tiktok\"][\"clear\"],\n    \"link_shape\": APP_SCREENS[\"tiktok\"][\"link_shape\"],\n}\n\n# A carousel of pictures in one post (Video's task promo/01, part 40): an\n# Instagram carousel, a TikTok photo post. The share screen takes one file,\n# so the app is opened and walked like a person would: its create button,\n# its library, the \"select multiple\" control, then the newest pictures\n# tapped in order. \"picker_cells\" are the library's picture cells, newest\n# first, each one tapped by its place (uiautomator2's and iphone.py's\n# `instance`). Instagram counts the picture its preview already shows as the\n# first pick once \"select multiple\" is on, so its taps start at the second\n# cell (\"multiple_keeps_first\"); TikTok picks nothing by itself. Written from\n# how the apps are known to look and unproven on a real phone (4 Nov 2026);\n# the self-test walks them first, and a step that does not find its button\n# stops with a picture of the screen. None of these words may be a last\n# button's (LAST_BUTTONS), or a rehearsal would refuse to tap them.\nAPP_SCREENS[\"instagram\"].update({\n    \"create\": shapes(INSTAGRAM, \"(?i)^(create|new post|camera)$\") + [{\"resourceIdMatches\": \"(?i).*(creation_tab|tab_create|camera_tab).*\", \"packageName\": INSTAGRAM}],\n    \"upload\": [],\n    # Instagram may open on Story or Reel; the feed post's tab, found by its id only.\n    \"post_mode\": [{\"resourceIdMatches\": \"(?i).*(cam_dest_feed|feed_post_tab|post_destination).*\", \"packageName\": INSTAGRAM}],\n    \"photos_tab\": [],\n    \"picker_multiple\": shapes(INSTAGRAM, \"(?i)^(select multiple|multi.?select)$\") + [{\"resourceIdMatches\": \"(?i).*(multi_select|multiple_select|select_multiple).*\", \"packageName\": INSTAGRAM}],\n    \"picker_cells\": [{\"resourceIdMatches\": \"(?i).*(gallery_grid_item|media_picker_item|gallery_item_thumbnail).*\", \"packageName\": INSTAGRAM}],\n    \"multiple_keeps_first\": True,\n})\nAPP_SCREENS[\"tiktok\"].update({\n    \"create\": shapes(TIKTOK, \"(?i)^(create|record|add)$\") + [{\"resourceIdMatches\": \"(?i).*(main_bottom_button_add|tab_create|record_tab).*\", \"packageName\": TIKTOK}],\n    \"upload\": shapes(TIKTOK, \"(?i)^(upload|album|gallery)$\"),\n    \"post_mode\": [],\n    # The library opens on All; Photos keeps videos out of the cells.\n    \"photos_tab\": shapes(TIKTOK, \"(?i)^(photos|photo)$\"),\n    \"picker_multiple\": shapes(TIKTOK, \"(?i)^(select multiple|multiple)$\") + [{\"resourceIdMatches\": \"(?i).*(multi_select|select_multiple).*\", \"packageName\": TIKTOK}],\n    \"picker_cells\": [{\"resourceIdMatches\": \"(?i).*(media_item|gallery_item|thumbnail|cover).*\", \"packageName\": TIKTOK}],\n    \"multiple_keeps_first\": False,\n})\nAPP_SCREENS[IOS_INSTAGRAM].update({\n    \"post_mode\": [{\"resourceIdMatches\": \"(?i).*(post|feed).?(mode|destination).*\", \"packageName\": IOS_INSTAGRAM}],\n    \"photos_tab\": [],\n    \"picker_multiple\": shapes(IOS_INSTAGRAM, \"(?i)^(select multiple|multi.?select)$\") + [{\"resourceIdMatches\": \"(?i).*(multi.?select|select.?multiple).*\", \"packageName\": IOS_INSTAGRAM}],\n    \"picker_cells\": ios_first_cell(IOS_INSTAGRAM),\n    \"multiple_keeps_first\": True,\n})\nAPP_SCREENS[IOS_TIKTOK].update({\n    \"post_mode\": [],\n    \"photos_tab\": shapes(IOS_TIKTOK, \"(?i)^(photos|photo)$\"),\n    \"picker_multiple\": shapes(IOS_TIKTOK, \"(?i)^(select multiple|multiple)$\") + [{\"resourceIdMatches\": \"(?i).*(multi.?select|select.?multiple).*\", \"packageName\": IOS_TIKTOK}],\n    \"picker_cells\": ios_first_cell(IOS_TIKTOK),\n    \"multiple_keeps_first\": False,\n})\n\n\n# Medium's app (Medium task, part 42). Written from how the app is put\n# together, like Instagram's and TikTok's were (phone farm file 06), and not\n# yet walked on a real phone. The daily self-test walks it first, on a story\n# Promo found in the last week; with none found, it only opens the app. A response\n# is answered in the app with the same three steps a browser takes: the\n# responses button under the story, the box, and Respond.\nMEDIUM = APP_PACKAGES[\"medium\"]\nAPP_SCREENS[\"medium\"] = {\n    \"package\": MEDIUM,\n    \"profile_tab\": shapes(MEDIUM, \"(?i)^(you|profile|your profile|me)$\") + [{\"resourceIdMatches\": \"(?i).*(profile|avatar).*tab.*\", \"packageName\": MEDIUM}],\n    \"responses\": shapes(MEDIUM, \"(?i)^(responses?|\\\\d+ responses?|view responses)$\") + [{\"resourceIdMatches\": \"(?i).*responses.*\", \"packageName\": MEDIUM}],\n    \"response_box\": shapes(MEDIUM, \"(?i)^what are your thoughts\\\\??$\") + field_in(MEDIUM),\n    \"respond\": shapes(MEDIUM, \"(?i)^(respond|publish|post)$\"),\n    \"handle_id\": \"(?i).*(username|user_name|handle).*\",\n    \"figures\": {\"posts\": \"\", \"followers\": \"followers\", \"following\": \"following\"},\n}\nAPP_SCREENS[APP_BUNDLES[\"medium\"]] = dict(\n    APP_SCREENS[\"medium\"],\n    package=APP_BUNDLES[\"medium\"],\n    response_box=shapes(APP_BUNDLES[\"medium\"], \"(?i)^what are your thoughts\\\\??$\") + ios_field_in(APP_BUNDLES[\"medium\"]),\n    handle_in_title=False,\n)\n\n\n# X's app (X task, part 2). Written from how the X app is put together: its\n# Android view ids (com.twitter.android:id/tweet_text, button_tweet,\n# composer_write, inline_reply, inline_retweet) and the words its buttons\n# say (\"New post\", \"Post your reply\", \"Reply\", \"Post\", \"Repost\", \"Quote\",\n# \"Messages\"). None of it has run on a real phone yet; the daily self-test\n# walks it first. A view id is tried before the words where both are\n# listed, since X's own Reply icon on a post says \"Reply\" too. The iPhone\n# app has no view ids to match, so its buttons are found by their words.\nX_APP = APP_PACKAGES[\"x\"]\nIOS_X = APP_BUNDLES[\"x\"]\n# The Follow button on a profile, by its view id. Its words alone could be\n# the \"Following\" count beside it.\nX_FOLLOW_BUTTON_ID = \"(?i).*(follow_button|button_bar_follow|followbutton).*\"\n\n\ndef x_screens(package, field, first_item, ios):\n    ids = (lambda pattern: []) if ios else (lambda pattern: [{\"resourceIdMatches\": pattern, \"packageName\": package}])\n    composer_box = ids(\"(?i).*tweet_text.*\") + field + shapes(\n        package, \"(?i)^(post your reply|what's happening\\\\??|what is happening\\\\?!?|add a comment|add another post)( ?(…|\\\\.\\\\.\\\\.))?$\")\n    post_button = ids(\"(?i).*button_tweet.*\") + shapes(package, \"(?i)^(post|reply|post all|reply all|tweet)$\")\n    return {\n        \"package\": package,\n        \"drawer\": shapes(package, \"(?i)^(show navigation drawer|open navigation drawer|navigation drawer|account menu|profile menu|open menu|menu)$\")\n        + ids(\"(?i).*(drawer|toolbar_avatar|nav_avatar).*\"),\n        \"profile_entry\": shapes(package, \"(?i)^profile$\"),\n        \"reply_open\": ids(\"(?i).*(inline_reply|tweet_reply|reply_compose).*\") + shapes(package, \"(?i)^(post your reply|tweet your reply|add a reply)( ?(…|\\\\.\\\\.\\\\.))?$\"),\n        \"composer_box\": composer_box,\n        \"post_button\": post_button,\n        \"repost\": ids(\"(?i).*(inline_retweet|tweet_retweet|retweet_button).*\") + shapes(package, \"(?i)^(repost|retweet)(\\\\W.*)?$\"),\n        \"quote\": shapes(package, \"(?i)^(quote|quote post|quote tweet)$\"),\n        \"new_post\": ids(\"(?i).*(composer_write|compose_fab|fab_compose).*\") + shapes(package, \"(?i)^(new post|compose|compose a post|compose a tweet|write a post|create post)$\"),\n        \"media\": ids(\"(?i).*(gallery|photo|media).*(button|icon|picker|toolbar).*\") + shapes(package, \"(?i)^(add photos or video|add photos|photos|photo|gallery|add media|media)$\"),\n        \"media_first\": first_item,\n        \"media_done\": shapes(package, \"(?i)^(add|done|ok|select)$\"),\n        \"follow_button_id\": \"\" if ios else X_FOLLOW_BUTTON_ID,\n        \"inbox\": ids(\"(?i).*(dm_tab|messages_tab|tab_messages).*\") + shapes(package, \"(?i)^(messages|direct messages|chat|chats)$\"),\n        \"activity\": shapes(package, \"(?i)^notifications$\"),\n        \"message_box\": ids(\"(?i).*(dm_compose|dm_text|message_text).*\") + shapes(package, \"(?i)^(start a (new )?message|message|new message)( ?(…|\\\\.\\\\.\\\\.))?$\") + field,\n        \"send\": ids(\"(?i).*(dm_send|send_dm|send_button).*\") + shapes(package, \"(?i)^send$\"),\n        \"reply\": shapes(package, \"(?i)^reply$\"),\n        \"comment_box\": composer_box,\n        \"comment_send\": post_button,\n        \"field\": field,\n        \"handle_id\": \"(?i).*(user_name|screen_name|username).*\",\n        \"handle_in_title\": False,\n        \"figures\": {\"posts\": \"\", \"followers\": \"followers\", \"following\": \"following\"},\n    }\n\n\nAPP_SCREENS[\"x\"] = x_screens(X_APP, field_in(X_APP), [{\"resourceIdMatches\": \"(?i).*(gallery_image|media_item|gallery_grid|thumbnail).*\", \"packageName\": X_APP}], ios=False)\nAPP_SCREENS[IOS_X] = x_screens(IOS_X, ios_field_in(IOS_X), ios_first_cell(IOS_X), ios=True)\n\n\n# LinkedIn's app (LinkedIn task, part 2). Written from how the LinkedIn app is\n# put together: its Android view ids (feed_social_actions_like, me_launcher,\n# share_compose_post_button, messaging_keyboard_send) and the words its\n# buttons say (\"Start a post\", \"Add a comment…\", \"Like\", \"Post\", \"Connect\",\n# \"Send without a note\", \"Accept\", \"Messaging\"). None of it has run on a real\n# phone yet; the daily self-test walks it first. A view id is tried before\n# the words where both are listed. The iPhone app has no view ids to match,\n# so its buttons are found by their words. The box under a post is opened by\n# its own words, never by the post's \"Comment\" button, whose word is also a\n# last button's.\nLINKEDIN = APP_PACKAGES[\"linkedin\"]\nIOS_LINKEDIN = APP_BUNDLES[\"linkedin\"]\n# The system's share sheet, outside the app: its Copy row puts the profile's\n# address on the clipboard when the app's own menu has no Copy link.\nLINKEDIN_SYSTEM_COPY = [{\"textMatches\": \"(?i)^(copy|copy link|copy to clipboard)$\"}]\n\n\ndef linkedin_screens(package, field, first_item, ios):\n    ids = (lambda pattern: []) if ios else (lambda pattern: [{\"resourceIdMatches\": pattern, \"packageName\": package}])\n    comment_box = ids(\"(?i).*(comment_bar_text|comment_compose|comments_compose_text).*\") + shapes(\n        package, \"(?i)^(add a comment|leave your thoughts here|add a reply|reply to .+)( ?(…|\\\\.\\\\.\\\\.))?$\") + field\n    # Never \"Reply\": every comment under the post has one. Only a button\n    # beside the box counts (linkedin_composer_send).\n    comment_send = ids(\"(?i).*(comment_bar_post|comment_compose_post|comment_post_button).*\") + shapes(package, \"(?i)^(post|send)$\")\n    return {\n        \"package\": package,\n        \"drawer\": ids(\"(?i).*(me_launcher|feed_toolbar_me|toolbar_profile_image|nav_me).*\")\n        + shapes(package, \"(?i)^(open (navigation )?(drawer|menu)|show navigation drawer|open profile menu|me|my profile)$\"),\n        \"profile_entry\": shapes(package, \"(?i)^(view profile|view your profile|profile)$\"),\n        \"profile_more\": ids(\"(?i).*(profile_overflow|top_card_overflow|profile_more).*\") + shapes(package, \"(?i)^(more|more actions|more options)$\"),\n        \"copy_link\": shapes(package, \"(?i)^(copy link to profile|copy profile link|copy link to your profile|copy link)$\"),\n        \"share_profile\": shapes(package, \"(?i)^(share profile( via)?( ?(…|\\\\.\\\\.\\\\.))?|share via( ?(…|\\\\.\\\\.\\\\.))?)$\"),\n        \"name_id\": \"\" if ios else \"(?i).*(profile_name|top_card_name|profile_top_card_name|identity_name).*\",\n        \"like\": ids(\"(?i).*(feed_social_actions_like|social_actions_like|reaction_button).*\") + shapes(package, \"(?i)^(like|react like)$\"),\n        \"liked\": shapes(package, \"(?i)^(unlike|liked|reaction button state: (liked|reacted).*|remove (your )?reaction.*)$\"),\n        \"comment_box\": comment_box,\n        \"comment_send\": comment_send,\n        \"comment_reply\": shapes(package, \"(?i)^reply$\"),\n        \"new_post\": ids(\"(?i).*(share_box|feed_share_box|bottom_nav_post|post_tab|create_post).*\")\n        + shapes(package, \"(?i)^(start a post|create a post|share a post)( ?(…|\\\\.\\\\.\\\\.))?$\"),\n        \"composer_box\": ids(\"(?i).*(share_compose_text|compose_text_input|sharing_compose_text).*\")\n        + shapes(package, \"(?i)^(what do you want to talk about\\\\??|share your thoughts\\\\.?|start writing)( ?(…|\\\\.\\\\.\\\\.))?$\") + field,\n        \"post_button\": ids(\"(?i).*(share_compose_post_button|sharing_compose_post|toolbar_post).*\") + shapes(package, \"(?i)^post$\"),\n        \"media\": ids(\"(?i).*(share_compose_photo|compose_add_photo|media_picker).*\") + shapes(package, \"(?i)^(add a photo|add photos|photo|add media|media|gallery)$\"),\n        \"media_first\": first_item,\n        \"media_done\": shapes(package, \"(?i)^(done|next|add|ok|select)$\"),\n        # By its words only: the profile's main button is Follow on a\n        # creator's page and Message on a contact's, under the same view id.\n        \"connect\": shapes(package, \"(?i)^(connect|invite .+ to connect)$\"),\n        \"add_note\": shapes(package, \"(?i)^(add a note|personalize invite|personalise invite)$\"),\n        # The box's hint, never the Add a note button that opened it.\n        \"note_box\": shapes(package, \"(?i)^(ex: we know each other from .*|add a note ?(…|\\\\.\\\\.\\\\.)|your message.*)$\") + field,\n        \"send_invite\": shapes(package, \"(?i)^(send|send now|send without a note|send invitation)$\"),\n        \"accept\": shapes(package, \"(?i)^(accept|accept .+ invitation)$\"),\n        \"network\": ids(\"(?i).*(bottom_nav_mynetwork|tab_mynetwork|my_network_tab).*\") + shapes(package, \"(?i)^(my network|network)$\"),\n        \"invitations\": shapes(package, \"(?i)^(invitations?( \\\\(\\\\d+\\\\))?|manage invitations|show all invitations|see all( invitations)?)$\"),\n        \"inbox\": ids(\"(?i).*(messaging_icon|toolbar_messaging|home_messaging|nav_messaging).*\") + shapes(package, \"(?i)^(messaging|messages|open messaging|messaging, .*)$\"),\n        \"activity\": ids(\"(?i).*(bottom_nav_notifications|tab_notifications).*\") + shapes(package, \"(?i)^notifications$\"),\n        \"message_box\": ids(\"(?i).*(messaging_keyboard_text|compose_message|message_text).*\") + shapes(package, \"(?i)^(write a message|message)( ?(…|\\\\.\\\\.\\\\.))?$\") + field,\n        \"send\": ids(\"(?i).*(messaging_keyboard_send|send_button).*\") + shapes(package, \"(?i)^send$\"),\n        \"field\": field,\n    }\n\n\nAPP_SCREENS[\"linkedin\"] = linkedin_screens(\n    LINKEDIN, field_in(LINKEDIN), [{\"resourceIdMatches\": \"(?i).*(media_picker_item|gallery_item|thumbnail|media_grid).*\", \"packageName\": LINKEDIN}], ios=False)\nAPP_SCREENS[IOS_LINKEDIN] = linkedin_screens(IOS_LINKEDIN, ios_field_in(IOS_LINKEDIN), ios_first_cell(IOS_LINKEDIN), ios=True)\n\n\n# YouTube (workspace/tasks/YouTube/01-youtube-features.md), Android only:\n# the You tab for the channel's @handle, its channel page for subscribers and\n# videos, the upload screen a shared video opens, and the comments through\n# the shared inbox steps. Words from the YouTube app as it is known, unproven\n# on a phone until the first self-test.\nAPP_SCREENS[\"youtube\"] = {\n    \"package\": YOUTUBE,\n    \"profile_tab\": shapes(YOUTUBE, \"(?i)^(you|library)$\") + [{\"resourceIdMatches\": \"(?i).*pivot_(you|library).*\", \"packageName\": YOUTUBE}],\n    \"view_channel\": shapes(YOUTUBE, \"(?i)^(view channel|go to channel|your channel)$\"),\n    \"your_videos\": shapes(YOUTUBE, \"(?i)^(your videos)$\"),\n    \"create\": shapes(YOUTUBE, \"(?i)^(create|upload)$\") + [{\"resourceIdMatches\": \"(?i).*(pivot_create|create_button).*\", \"packageName\": YOUTUBE}],\n    \"upload_video\": shapes(YOUTUBE, \"(?i)^(upload a video|upload video|upload)$\"),\n    \"next\": shapes(YOUTUBE, \"(?i)^next$\"),\n    \"title\": shapes(YOUTUBE, \"(?i)^(create a title|add a title|title|caption your short|add a caption)$\") + field_in(YOUTUBE),\n    \"description\": shapes(YOUTUBE, \"(?i)^(add description|description)$\"),\n    \"visibility\": shapes(YOUTUBE, \"(?i)^visibility$\"),\n    \"public\": shapes(YOUTUBE, \"(?i)^public$\"),\n    \"audience\": shapes(YOUTUBE, \"(?i)^(select audience|audience)$\"),\n    \"not_for_kids\": shapes(YOUTUBE, \"(?i)^no,? it'?s not made for kids$\"),\n    \"show_more\": shapes(YOUTUBE, \"(?i)^show more$\"),\n    \"altered\": shapes(YOUTUBE, \"(?i)^altered (or synthetic )?content$\"),\n    \"altered_yes\": shapes(YOUTUBE, \"(?i)^yes$\"),\n    \"altered_no\": shapes(YOUTUBE, \"(?i)^no$\"),\n    \"share\": shapes(YOUTUBE, \"(?i)^(upload|upload video|upload short)$\"),\n    \"posted\": (\"upload complete\", \"your video is uploaded\", \"your short is uploaded\", \"video uploaded\", \"processing\"),\n    \"post_failed\": (\"upload failed\", \"couldn't upload\", \"can't upload\", \"upload unsuccessful\"),\n    \"first_video_menu\": [{\"descriptionMatches\": \"(?i)^(action menu|more options)$\", \"packageName\": YOUTUBE}],\n    \"share_menu\": shapes(YOUTUBE, \"(?i)^share$\"),\n    \"copy_link\": shapes(YOUTUBE, \"(?i)^copy link$\"),\n    \"activity\": [{\"descriptionMatches\": \"(?i)^notifications?$\", \"packageName\": YOUTUBE}] + shapes(YOUTUBE, \"(?i)^notifications?$\"),\n    \"reply\": shapes(YOUTUBE, \"(?i)^reply$\"),\n    \"comment_box\": shapes(YOUTUBE, \"(?i)^(add a reply.*|reply.*)$\") + field_in(YOUTUBE),\n    \"comment_send\": [{\"descriptionMatches\": \"(?i)^(send|reply|post)$\", \"packageName\": YOUTUBE}] + shapes(YOUTUBE, \"(?i)^(send|reply)$\"),\n    \"field\": field_in(YOUTUBE),\n    \"handle_id\": \"(?i).*(channel_handle|handle).*\",\n    \"figures\": {\"posts\": \"videos\", \"followers\": \"subscribers\", \"following\": \"\"},\n    \"link_shape\": re.compile(r\"^https://(www\\.|m\\.)?(youtube\\.com/(watch\\?v=|shorts/)|youtu\\.be/)[A-Za-z0-9_-]{6,20}\\S*$\"),\n}\n\n# The whole phone upload, from the download to YouTube saying the video is\n# in: the app waits 42 minutes for the answer and the `youtube_upload` job's\n# claim lasts 60 (jobs.ts), so the phone stops well inside both.\nYOUTUBE_PHONE_BUDGET_SECONDS = 36 * 60\n# A YouTube file is streamed to the rack's disk, never held in memory: up to\n# 5 GB, the most the Archive keeps, in up to 15 minutes. With the 18 minutes\n# to upload and the screens between, an upload ends inside the app's 42.\nYOUTUBE_DOWNLOAD_LIMIT = 5 * 1024 ** 3\nYOUTUBE_DOWNLOAD_SECONDS = 15 * 60\nYOUTUBE_HANDLE = re.compile(r\"@([A-Za-z0-9._-]{3,100})\")\n\n\ndef app_screens(serial, app):\n    \"\"\"The app's buttons on this phone: the iPhone app's, keyed by its bundle\n    id, on an iPhone; the Android app's, keyed by its name, otherwise. An app\n    whose steps are not written for this kind of phone is refused.\"\"\"\n    key = package_for(serial, app) if is_iphone(serial) else app\n    if key not in APP_SCREENS:\n        raise RuntimeError(\"%s's steps are not written for this kind of phone yet. Put the account on an Android phone.\" % APP_NAMES[app])\n    return APP_SCREENS[key]\n\n# Words a signed-out app's first screen shows.\nLOG_IN_WORDS = (\"log in\", \"log into another account\", \"sign up\", \"create new account\", \"use phone or email\")\nCOUNT_TEXT = re.compile(r\"^\\d[\\d,]*(\\.\\d+)?\\s*[kKmM]?$\")\nCOUNT_LINE = re.compile(r\"^(\\d[\\d,]*(?:\\.\\d+)?\\s*[kKmM]?)\\s+([A-Za-z]+)$\")\nAT_HANDLE = re.compile(r\"^@([A-Za-z0-9._]{2,30})$\")\nPLAIN_HANDLE = re.compile(r\"^[A-Za-z0-9._]{1,30}$\")\n# Lines a conversation shows that nobody wrote: times, days, Seen and Sent.\nNOT_A_LINE = re.compile(r\"(?i)^(today|yesterday|seen|sent|delivered|active now|active \\d+\\w* ago|\\d{1,2}:\\d{2}( ?[ap]m)?|(today|yesterday|mon|tue|wed|thu|fri|sat|sun)\\w* \\d{1,2}:\\d{2}.*|\\d+[smhdw])$\")\nPOST_LANDED_APP_SECONDS = 180\nAPP_FEED_AFTER_SECONDS = (20, 60)\nAPP_READ_FEED_SECONDS = (30, 90)\nMEDIA_DOWNLOAD_LIMIT = 300 * 1024 * 1024\nMEDIA_DOWNLOAD_SECONDS = 120\n\n\ndef open_app(serial, app):\n    if is_iphone(serial):\n        iphone_screen(serial).app_start(APP_BUNDLES[app])\n    else:\n        shell(serial, \"monkey -p %s -c android.intent.category.LAUNCHER 1\" % APP_PACKAGES[app])\n    time.sleep(4)\n\n\ndef signed_out(hierarchy_xml, app):\n    \"\"\"True on a sign-in screen: a short screen offering Log in.\"\"\"\n    lines = [plain(line) for line in screen_lines(hierarchy_xml, app_packages(app))]\n    return len(lines) < 40 and any(line in LOG_IN_WORDS for line in lines)\n\n\ndef parse_count(text):\n    \"\"\"1,234 or 12.3K as a number, or None.\"\"\"\n    return parse_karma(text)\n\n\ndef profile_handle(hierarchy_xml, app):\n    \"\"\"The account's name on its own profile: the title bar on Instagram, the\n    @name line on TikTok. Android's title bar is found by its view id\n    (handle_id); an iPhone's is the navigation bar, named after the account\n    (handle_in_title), and has no id to match.\"\"\"\n    root = ElementTree.fromstring(hierarchy_xml)\n    packages = app_packages(app)\n    pattern = APP_SCREENS[app][\"handle_id\"]\n    # An app written for Android only (Threads, YouTube) has no iPhone table to ask.\n    in_title = APP_SCREENS.get(APP_BUNDLES[app], {}).get(\"handle_in_title\", False)\n    for node in root.iter(\"node\"):\n        if not own_node(node, packages):\n            continue\n        words = node_words(node).strip().rstrip(\"⌄▾\").strip()\n        found = AT_HANDLE.match(words)\n        if found:\n            return found.group(1)\n        if pattern and re.match(pattern, node.get(\"resource-id\") or \"\") and PLAIN_HANDLE.match(words):\n            return words\n        if in_title and ios_kind(node) == \"XCUIElementTypeNavigationBar\" and PLAIN_HANDLE.match(words) and plain(words) not in NOT_A_HANDLE:\n            return words\n    return None\n\n\n# Titles a navigation bar shows that are no account's name.\nNOT_A_HANDLE = (\"profile\", \"settings\", \"instagram\", \"home\", \"search\", \"reels\", \"explore\", \"edit\", \"back\")\n\n\ndef app_profile_from_screen(hierarchy_xml, app):\n    \"\"\"The handle and the figures on the account's own profile. None where one is not shown.\"\"\"\n    handle = profile_handle(hierarchy_xml, app)\n    figures = {}\n    lines = screen_lines(hierarchy_xml, app_packages(app))\n    for key, label in APP_SCREENS[app][\"figures\"].items():\n        if not label:\n            figures[key] = None\n            continue\n        value = value_beside_label(hierarchy_xml, label, COUNT_TEXT)\n        if value is None:\n            for line in lines:\n                found = COUNT_LINE.match(line)\n                if found and plain(found.group(2)) == label:\n                    value = found.group(1)\n                    break\n        figures[key] = parse_count(value) if value else None\n    return {\"handle\": handle, \"followers\": figures[\"followers\"], \"following\": figures[\"following\"], \"posts\": figures[\"posts\"]}\n\n\ndef read_app_profile(serial, walk, app):\n    \"\"\"Opens the app on the account's own profile and reads it. Leaves it there.\"\"\"\n    open_app(serial, app)\n    walk.shot(\"Opened %s\" % APP_NAMES[app])\n    device = walk.screen()\n    if signed_out(device.dump_hierarchy(), app):\n        return {\"handle\": None, \"followers\": None, \"following\": None, \"posts\": None}\n    walk.tap_first(\"Open the profile\", selectors=app_screens(serial, app)[\"profile_tab\"])\n    time.sleep(2)\n    reading = app_profile_from_screen(device.dump_hierarchy(), app)\n    walk.shot(\"Read the profile\")\n    return reading\n\n\ndef action_app_quick_state(app):\n    def action(serial, args, walk):\n        \"\"\"Who the app is signed in as, read after every job. An app that cannot\n        be read says \"not checked\", so a failed look is never written down as\n        signed out.\"\"\"\n        try:\n            walk.screen().screen_on()\n            reading = read_app_profile(serial, walk, app)\n            walk.home()\n        except Cancelled:\n            raise\n        except Exception as failure:  # Not checked rather than signed out.\n            log(\"Could not read who is signed in to %s on %s: %s\" % (APP_NAMES[app], serial, failure))\n            return {\"checked\": False, \"handle\": None}\n        return {\"checked\": True, \"handle\": reading[\"handle\"]}\n    return action\n\n\ndef shadowban_from_screen(hierarchy_xml, app):\n    \"\"\"What the Account status page says about being shown to people who do not\n    follow the account: hidden, clear, or not read when neither is said.\n    Hidden is looked for first, since \"can't be recommended\" also holds\n    \"be recommended\".\"\"\"\n    screens = APP_SCREENS[app]\n    labels = [selector[\"textMatches\"] for selector in screens[\"status_detail\"] if \"textMatches\" in selector]\n    # The menu's own label (\"What can't be recommended\") is not an answer.\n    lines = [line for line in screen_lines(hierarchy_xml, app_packages(app)) if not any(re.match(label, line) for label in labels)]\n    words = [plain(line) for line in lines]\n    for line in words:\n        if any(phrase in line for phrase in screens[\"hidden\"]):\n            return {\"read\": True, \"hidden\": True, \"words\": next(text for text in lines if plain(text) == line)[:300]}\n    for line in words:\n        if any(phrase in line for phrase in screens[\"clear\"]):\n            return {\"read\": True, \"hidden\": False, \"words\": next(text for text in lines if plain(text) == line)[:300]}\n    return {\"read\": False, \"hidden\": False, \"words\": \"\"}\n\n\ndef read_account_status(serial, walk, app):\n    \"\"\"Settings, then Account status, then the part about recommendations,\n    read without pressing anything else. A step that is not found leaves it\n    unread rather than failing the reading.\"\"\"\n    screens = app_screens(serial, app)\n    # An app with no Account status page, such as Threads, has nothing to read.\n    if not screens[\"account_status\"]:\n        return {\"read\": False, \"hidden\": False, \"words\": \"\"}\n    try:\n        walk.tap_first(\"Open the menu\", selectors=screens[\"settings\"])\n        time.sleep(1.5)\n        scroll_to_first(walk, \"Find Account status\", screens[\"account_status\"])\n        walk.tap_first(\"Open Account status\", selectors=screens[\"account_status\"])\n        time.sleep(2)\n        reading = shadowban_from_screen(walk.screen().dump_hierarchy(), app)\n        if not reading[\"read\"]:\n            try:\n                walk.tap_first(\"Open what can't be recommended\", timeout=3, selectors=screens[\"status_detail\"])\n                time.sleep(2)\n                reading = shadowban_from_screen(walk.screen().dump_hierarchy(), app)\n            except StepFailed:\n                pass\n        walk.shot(\"Read Account status\")\n        return reading\n    except StepFailed:\n        if walk.rehearse:\n            raise\n        return {\"read\": False, \"hidden\": False, \"words\": \"\"}\n\n\ndef post_numbers_from_screen(hierarchy_xml, app):\n    \"\"\"Views, likes and comments as one post's own screen shows them, each None when not shown.\"\"\"\n    lines = screen_lines(hierarchy_xml, app_packages(app))\n    found = {\"views\": None, \"likes\": None, \"comments\": None}\n    words = {\"views\": (\"views\", \"plays\", \"view\", \"play\"), \"likes\": (\"likes\", \"like\"), \"comments\": (\"comments\", \"comment\")}\n    for line in lines:\n        text = line.replace(\",\", \"\")\n        for key, names in words.items():\n            if found[key] is not None:\n                continue\n            match = re.match(r\"(?i)^([\\d.]+\\s*[km]?)\\s+(%s)$\" % \"|\".join(names), text.strip())\n            if match:\n                found[key] = parse_count(match.group(1))\n    # TikTok writes the counts under their icons, described by the button: \"Like, 1.2K\".\n    for line in lines:\n        match = re.match(r\"(?i)^(like|likes|comment|comments|views?|plays?)\\W+([\\d.,]+\\s*[km]?)\\b\", line.strip())\n        if match:\n            key = \"likes\" if match.group(1).lower().startswith(\"like\") else \"comments\" if match.group(1).lower().startswith(\"comment\") else \"views\"\n            if found[key] is None:\n                found[key] = parse_count(match.group(2).replace(\",\", \"\"))\n    return found\n\n\ndef open_link(serial, app, url):\n    \"\"\"Opens an address in the app that owns it: handed to the app on Android,\n    through the iPhone's own link handling (the app, or Safari) on an iPhone.\"\"\"\n    if is_iphone(serial):\n        iphone_screen(serial).open_url(url)\n    else:\n        shell(serial, \"am start -a android.intent.action.VIEW -d '%s' -p %s\" % (url.replace(\"'\", \"\"), APP_PACKAGES[app]))\n    time.sleep(4)\n\n\ndef unread_in_inbox(hierarchy_xml, app):\n    \"\"\"True when the inbox button says something is unread: \"Messenger, 2 unread\", \"Inbox, 3\".\"\"\"\n    for line in screen_lines(hierarchy_xml, app_packages(app)):\n        text = plain(line)\n        if re.match(r\"^(direct|messenger|messages|inbox)\\W+\\d+\", text) or re.search(r\"\\b\\d+ (unread|new)\\b\", text):\n            return True\n    return False\n\n\ndef action_app_health(app):\n    def action(serial, args, walk):\n        \"\"\"The daily reading: the profile, the Account status page, and the\n        numbers of each post named, opened by its link. A post that will not\n        open is left out, and its numbers stay as they were.\"\"\"\n        walk.screen().screen_on()\n        reading = read_app_profile(serial, walk, app)\n        result = dict(reading, shadowban={\"read\": False, \"hidden\": False, \"words\": \"\"}, numbers=[], inboxWaiting=False)\n        if not reading[\"handle\"]:\n            walk.home()\n            return result\n        result[\"shadowban\"] = read_account_status(serial, walk, app)\n        go_back(serial)\n        go_back(serial)\n        urls = [str(url) for url in (args.get(\"postUrls\") or []) if app_screens(serial, app)[\"link_shape\"].match(str(url))]\n        for url in urls[:12]:\n            walk.check()\n            try:\n                open_link(serial, app, url)\n                numbers = post_numbers_from_screen(walk.screen().dump_hierarchy(), app)\n                walk.shot(\"Read a post's numbers\")\n                result[\"numbers\"].append(dict(numbers, url=url))\n            except StepFailed:\n                continue\n        try:\n            open_app(serial, app)\n            result[\"inboxWaiting\"] = unread_in_inbox(walk.screen().dump_hierarchy(), app)\n        except Exception as failure:  # A glance that fails is only a glance.\n            log(\"Could not glance at the %s inbox on %s: %s\" % (APP_NAMES[app], serial, failure))\n        walk.home()\n        return result\n    return action\n\n\n# ---------------------------------------------------------------------------\n# Files for a post or a profile picture: downloaded from Promo's own media\n# address, put in the phone's camera folder under a camera-like name, and\n# scanned so the gallery shows it.\n\nMEDIA_TYPES = {\n    \".jpg\": \"image/jpeg\", \".jpeg\": \"image/jpeg\", \".png\": \"image/png\", \".webp\": \"image/webp\",\n    \".mp4\": \"video/mp4\", \".mov\": \"video/quicktime\", \".webm\": \"video/webm\",\n}\n\n\ndef media_extension(url):\n    path = url.split(\"?\", 1)[0].lower()\n    for extension in MEDIA_TYPES:\n        if path.endswith(extension):\n            return extension\n    return \"\"\n\n\ndef download_media(url, fetch=None):\n    \"\"\"The file's bytes and its extension, or a failure saying why. Only an https address is fetched.\"\"\"\n    if not url.startswith(\"https://\"):\n        raise RuntimeError(\"post: the file's address is not an https address\")\n    extension = media_extension(url)\n    if not extension:\n        raise RuntimeError(\"post: the file is not a photo or video the apps take\")\n    if fetch is None:\n        def fetch(address):\n            with urllib.request.urlopen(address, timeout=MEDIA_DOWNLOAD_SECONDS) as response:\n                data = response.read(MEDIA_DOWNLOAD_LIMIT + 1)\n            return data\n    data = fetch(url)\n    if len(data) > MEDIA_DOWNLOAD_LIMIT:\n        raise RuntimeError(\"post: the file is larger than 300 MB\")\n    if not data:\n        raise RuntimeError(\"post: the file came back empty\")\n    return data, extension\n\n\ndef camera_name(extension, now=None):\n    \"\"\"IMG_20261016_142233.jpg or VID_..., the way the phone's own camera names a file.\"\"\"\n    stamp = time.strftime(\"%Y%m%d_%H%M%S\", time.localtime(now or time.time()))\n    return \"%s_%s%s\" % (\"VID\" if MEDIA_TYPES[extension].startswith(\"video/\") else \"IMG\", stamp, extension)\n\n\ndef put_in_gallery(serial, data, extension, now=None):\n    \"\"\"Puts the file in the camera folder and has the gallery read it. Returns its path on the phone.\n    `now` names it for that moment, so files put in one after another never share a name.\"\"\"\n    name = camera_name(extension, now)\n    folder = os.path.join(HOME, \"media\")\n    os.makedirs(folder, exist_ok=True)\n    local = os.path.join(folder, name)\n    with open(local, \"wb\") as handle:\n        handle.write(data)\n    remote = \"/sdcard/DCIM/Camera/%s\" % name\n    try:\n        adb([\"push\", local, remote], serial=serial, timeout=MEDIA_DOWNLOAD_SECONDS)\n    finally:\n        try:\n            os.remove(local)\n        except OSError:\n            pass\n    shell(serial, \"am broadcast -a android.intent.action.MEDIA_SCANNER_SCAN_FILE -d 'file://%s'\" % remote, timeout=15)\n    time.sleep(2)\n    return remote\n\n\ndef media_uri(serial, remote, extension):\n    \"\"\"The gallery's own address for a file, which the share screen is handed.\"\"\"\n    kind = \"video\" if MEDIA_TYPES[extension].startswith(\"video/\") else \"images\"\n    output = shell(serial, \"content query --uri content://media/external/%s/media --projection _id --where \\\"_data='%s'\\\"\" % (kind, remote), timeout=15)\n    found = re.search(r\"_id=(\\d+)\", output)\n    if not found:\n        raise RuntimeError(\"post: the gallery did not list the file after it was copied in\")\n    return \"content://media/external/%s/media/%s\" % (kind, found.group(1))\n\n\ndef rehearsal_picture():\n    \"\"\"A plain picture for the self-test to walk the post screens with. Never posted.\"\"\"\n    from PIL import Image  # uiautomator2 brings Pillow.\n    buffer = io.BytesIO()\n    Image.new(\"RGB\", (1080, 1080), (232, 228, 220)).save(buffer, format=\"JPEG\", quality=80)\n    return buffer.getvalue(), \".jpg\"\n\n\ndef share_into(serial, app, uri, extension):\n    \"\"\"Hands the file to the app's own share screen, as sharing from the gallery does.\"\"\"\n    shell(serial, \"am start -a android.intent.action.SEND -t %s --eu android.intent.extra.STREAM %s --grant-read-uri-permission -p %s\" % (\n        MEDIA_TYPES[extension], uri, APP_PACKAGES[app]))\n    time.sleep(5)\n\n\ndef leave_app_screen(serial, walk, app, times=4):\n    \"\"\"Backs out of a screen without sending anything, discarding a draft if\n    asked. On an iPhone the app is closed as well, since its create screens\n    do not all answer the swipe back, and a closed app holds no draft. It is\n    the app given that is closed, never whatever is in front, which could be\n    the home screen or Safari.\"\"\"\n    for _ in range(times):\n        go_back(serial)\n        time.sleep(1)\n        device = walk.screen()\n        for label in (\"Discard\", \"Discard post\", \"Discard edits\", \"Delete draft\", \"Leave\"):\n            try:\n                if device(text=label).exists:\n                    walk.press(device(text=label))\n                    break\n            except Exception:  # A screen caught mid-change.\n                break\n    if is_iphone(serial):\n        try:\n            walk.screen().app_stop(package_for(serial, app))\n        except Exception:  # The app is gone already, or the phone is.\n            pass\n\n\ndef screen_says(hierarchy_xml, app, phrases):\n    lines = [plain(line) for line in screen_lines(hierarchy_xml, app_packages(app))]\n    return next((line for line in lines if any(phrase in line for phrase in phrases)), None)\n\n\ndef tap_next_until(walk, step, selectors, until, most=3):\n    \"\"\"Presses Next until the screen with `until` shows, at most `most` times.\"\"\"\n    device = walk.screen()\n    for index in range(most):\n        for selector in until:\n            if device(**selector).exists:\n                return\n        walk.tap_first(\"%s (%d)\" % (step, index + 1), selectors=selectors)\n        time.sleep(2)\n    walk.find_first(step, selectors=until)\n\n\ndef read_post_link(serial, walk, app):\n    \"\"\"The newest post's link: the profile, its first post, More, Copy link,\n    and the clipboard read. \"\" when the app would not give it.\"\"\"\n    screens = app_screens(serial, app)\n    try:\n        open_app(serial, app)\n        walk.tap_first(\"Open the profile\", selectors=screens[\"profile_tab\"])\n        time.sleep(2)\n        walk.tap_first(\"Open the newest post\", selectors=screens[\"grid_first\"])\n        time.sleep(2)\n        walk.tap_first(\"Open its menu\", selectors=screens[\"more\"])\n        time.sleep(1)\n        walk.tap_first(\"Copy its link\", selectors=screens[\"copy_link\"])\n        time.sleep(1)\n        link = str(walk.screen().clipboard or \"\").strip()\n    except (StepFailed, AttributeError) as failure:\n        log(\"Could not read the new post's link on %s: %s\" % (walk.serial, short_words(failure)))\n        return \"\"\n    return link if screens[\"link_shape\"].match(link) else \"\"\n\n\ndef browse_app_feed(serial, walk, seconds):\n    \"\"\"A little of the app's own feed, which can never fail what came before it.\"\"\"\n    device = walk.screen()\n    until = time.monotonic() + seconds\n    while time.monotonic() < until:\n        walk.check()\n        scroll_once(serial, device, 1)\n        scroll_pause(until)\n\n\n# A post's file on an iPhone (phone farm part 55). A computer cannot drop a\n# file into an iPhone's Photos, so Promo makes a one-time link to the file,\n# good for ten minutes and one download, and the rack opens it in Safari on\n# the phone, holds a thumb on the picture or video and saves it to Photos.\n# The app's own picker then shows it first, as the newest item.\nSAFARI = \"com.apple.mobilesafari\"\nMEDIA_SHOW_SECONDS = 30\nLONG_PRESS_SECONDS = 1.0\nSAVE_TO_PHOTOS = [{\"textMatches\": \"(?i)^(save to photos|add to photos|save image|save video)$\"}]\n# Safari's own share button, by its accessibility id; the words only as a fallback.\nSAFARI_SHARE = [{\"resourceIdMatches\": \"(?i)^(sharebutton|share)$\"}, {\"textMatches\": \"(?i)^share$\"}]\n# The first save asks whether Safari may add to Photos.\nIOS_ALLOW = [{\"textMatches\": \"(?i)^(allow|allow full access|allow access to all photos|add photos only|ok)$\"}]\n\n\ndef media_on_screen(hierarchy_xml, height):\n    \"\"\"Where Safari shows the picture or video: the largest image or video\n    element below the address bar, else the web view itself, which the file\n    fills when it is the whole page. None when there is neither.\"\"\"\n    largest, page = None, None\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        kind = ios_kind(node)\n        bounds = parse_bounds(node.get(\"bounds\"))\n        if not bounds or bounds[3] <= height * 0.1:\n            continue\n        area = max(0, bounds[2] - bounds[0]) * max(0, bounds[3] - bounds[1])\n        if kind.endswith(\"Image\") or kind.endswith(\"Video\") or plain(node.get(\"label\") or \"\") in (\"video\", \"image\"):\n            if area and (largest is None or area > largest[0]):\n                largest = (area, bounds)\n        elif kind.endswith(\"WebView\") and area and (page is None or area > page[0]):\n            page = (area, bounds)\n    found = largest or page\n    return found[1] if found else None\n\n\ndef long_press(device, x, y):\n    \"\"\"A thumb held on one spot for a second: the iPhone driver's swipe with\n    no distance, held for LONG_PRESS_SECONDS.\"\"\"\n    device.swipe(x, y, x, y, duration=LONG_PRESS_SECONDS)\n\n\ndef save_from_safari(serial, walk, url):\n    \"\"\"Opens the one-time link in Safari, waits for the picture or video,\n    holds a thumb on it and saves it to Photos. A video has no long-press\n    menu, so Safari's share sheet saves that. Runs once: the link dies after\n    one download.\"\"\"\n    if not url.startswith(\"https://\"):\n        raise RuntimeError(\"post: the file's address is not an https address\")\n    device = walk.screen()\n    walk.check()\n    device.open_url(url)\n    _, height = screen_size(device)\n    bounds = None\n    deadline = time.time() + MEDIA_SHOW_SECONDS\n    while time.time() < deadline:\n        time.sleep(2)\n        walk.check()\n        bounds = media_on_screen(device.dump_hierarchy(), height)\n        if bounds:\n            break\n    if not bounds:\n        walk.shot(\"Looked for the file in Safari\")\n        raise StepFailed(\"Open the file in Safari\", \"Safari did not show the picture or video within %d seconds.\" % MEDIA_SHOW_SECONDS)\n    walk.shot(\"Opened the file in Safari\")\n    x, y = tap_point(bounds)\n    walk.check()\n    long_press(device, x, y)\n    time.sleep(1.5)\n    try:\n        walk.tap_first(\"Save to Photos\", timeout=5, selectors=SAVE_TO_PHOTOS)\n    except StepFailed:\n        walk.tap_first(\"Open Safari's share sheet\", selectors=SAFARI_SHARE)\n        time.sleep(1.5)\n        walk.tap_first(\"Save to Photos\", timeout=5, selectors=SAVE_TO_PHOTOS)\n    time.sleep(1.5)\n    try:\n        walk.tap_first(\"Allow Safari to add to Photos\", timeout=3, selectors=IOS_ALLOW)\n    except StepFailed:\n        pass  # Allowed on an earlier save.\n    walk.shot(\"Saved to Photos\")\n    walk.home()\n\n\ndef wait_for_post(serial, walk, app, screens):\n    \"\"\"After the last button was pressed: the post counts as up when the app\n    says so within three minutes, then its link is read and a little feed.\n    Nothing here may fail the post, which is up and never sent twice.\"\"\"\n    device = walk.screen()\n    button = \"Share\" if app == \"instagram\" else \"Post\"\n    landed = None\n    waiting_until = time.time() + POST_LANDED_APP_SECONDS\n    while time.time() < waiting_until:\n        time.sleep(3)\n        try:\n            hierarchy = device.dump_hierarchy()\n        except Exception:  # A screen caught mid-change; look again.\n            continue\n        if screen_says(hierarchy, app, screens[\"post_failed\"]):\n            walk.shot(\"The app said it failed\")\n            raise RuntimeError(\"post: the app said it could not post: %s\" % screen_says(hierarchy, app, screens[\"post_failed\"]))\n        if screen_says(hierarchy, app, screens[\"posted\"]):\n            landed = True\n            break\n    walk.shot(\"Looked for the post\")\n    if not landed:\n        raise RuntimeError(\"post: pressed %s but the app did not say it was posted within %d seconds. It may still be uploading; check the app before posting again.\" % (\n            button, POST_LANDED_APP_SECONDS))\n    link = \"\"\n    try:\n        link = read_post_link(serial, walk, app)\n        browse_app_feed(serial, walk, random.uniform(*APP_FEED_AFTER_SECONDS))\n    except Exception as failure:  # Includes a cancel: the post is up either way.\n        log(\"After the post on %s: %s\" % (serial, short_words(failure)))\n    walk.home()\n    return {\"postUrl\": link}\n\n\ndef ios_app_post(serial, args, walk, app):\n    \"\"\"A post from an iPhone: the file saved to Photos through Safari, then\n    the app's own create screen, its picker's newest item, Next until the\n    caption box, the caption typed, and Share or Post pressed once. A\n    rehearsal downloads nothing and saves nothing: it walks the create\n    screen with whatever the test phone's Photos holds, finds the last\n    button and backs out.\"\"\"\n    screens = app_screens(serial, app)\n    caption = str(args.get(\"caption\") or \"\")\n    device = walk.screen()\n    wake_screen(device)\n    if not walk.rehearse:\n        if args.get(\"mediaFromSafari\") is not True:\n            raise RuntimeError(\"post: an iPhone takes its file through a one-time Safari link (mediaFromSafari), and Promo sent none\")\n        save_from_safari(serial, walk, str(args.get(\"mediaUrl\") or \"\"))\n    try:\n        open_app(serial, app)\n        walk.shot(\"Opened %s\" % APP_NAMES[app])\n        if signed_out(device.dump_hierarchy(), app):\n            raise RuntimeError(\"post: the app is not signed in to %s\" % APP_NAMES[app])\n        walk.tap_first(\"Open the create screen\", selectors=screens[\"create\"])\n        time.sleep(2)\n        if screens[\"upload\"]:\n            try:\n                walk.tap_first(\"Open the library\", timeout=4, selectors=screens[\"upload\"])\n                time.sleep(2)\n            except StepFailed:\n                pass  # The library is already open on this version.\n        walk.tap_first(\"Pick the newest item\", selectors=screens[\"picker_first\"])\n        time.sleep(1.5)\n        if screens[\"share_to\"]:\n            try:\n                walk.tap_first(\"Pick the feed\", timeout=4, selectors=screens[\"share_to\"])\n            except StepFailed:\n                pass  # Straight to the editor on this version.\n        tap_next_until(walk, \"Press Next\", screens[\"next\"], screens[\"caption\"])\n        walk.tap_first(\"Open the caption box\", selectors=screens[\"caption\"])\n        if not walk.rehearse and caption:\n            gaps = type_like_a_person(serial, device, caption, walk.check)\n            walk.shot(\"Typed the caption\")\n            log(\"caption typed: %d characters, gaps %.2f to %.2f seconds\" % (len(caption), min(gaps or [0]), max(gaps or [0])))\n            # The keyboard down, so the last button is on screen. iOS has no\n            # Back key for that; the app's own OK or Done above the keyboard does it.\n            try:\n                walk.tap_first(\"Close the keyboard\", timeout=3, selectors=screens[\"keyboard_done\"])\n            except StepFailed:\n                pass\n            time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n        pressed = walk.final_first(\"Press %s\" % (\"Share\" if app == \"instagram\" else \"Post\"), selectors=screens[\"share\"])\n    except Cancelled:\n        raise\n    except Exception:\n        if not walk.rehearse:\n            leave_app_screen(serial, walk, app)\n        raise\n    finally:\n        if walk.rehearse:\n            leave_app_screen(serial, walk, app)\n    if not pressed:\n        walk.home()\n        return {\"postUrl\": \"\"}\n    return wait_for_post(serial, walk, app, screens)\n\n\n# A carousel (Video's task promo/01, part 40): at most this many pictures,\n# and the gap between two pushes into the gallery, so each has its own\n# second and the gallery sorts them the way they were put in.\nCAROUSEL_MOST = 20\nCAROUSEL_PUSH_GAP_SECONDS = 1.1\n\n\ndef carousel_urls(args):\n    \"\"\"The carousel's addresses in order, or a failure saying why: 2 to 20, each https.\"\"\"\n    urls = args.get(\"mediaUrls\")\n    if not isinstance(urls, list) or not all(isinstance(url, str) for url in urls):\n        raise RuntimeError(\"post: a carousel needs its pictures' addresses (mediaUrls), and Promo sent none\")\n    urls = [url.strip() for url in urls]\n    if len(urls) < 2 or len(urls) > CAROUSEL_MOST:\n        raise RuntimeError(\"post: a carousel holds 2 to %d pictures, and Promo sent %d\" % (CAROUSEL_MOST, len(urls)))\n    for url in urls:\n        if not url.startswith(\"https://\"):\n            raise RuntimeError(\"post: a carousel picture's address is not an https address\")\n    return urls\n\n\ndef put_slides_in_gallery(serial, files):\n    \"\"\"Puts the pictures in the camera folder last one first, a second apart,\n    so the first picture is the newest and the library lists them in order.\n    Returns their paths on the phone, in the carousel's order.\"\"\"\n    remotes = [None] * len(files)\n    start = time.time()\n    for step, index in enumerate(reversed(range(len(files)))):\n        if step:\n            time.sleep(CAROUSEL_PUSH_GAP_SECONDS)\n        data, extension = files[index]\n        remotes[index] = put_in_gallery(serial, data, extension, now=start + step)\n    return remotes\n\n\ndef pick_carousel_pictures(walk, screens, count):\n    \"\"\"In the app's library: \"select multiple\", then the newest `count`\n    pictures tapped in order, each by its place among the picture cells. One\n    the library does not show is a failure that names it; a carousel longer\n    than one screen of the library is unproven.\"\"\"\n    walk.tap_first(\"Choose several pictures\", selectors=screens[\"picker_multiple\"])\n    time.sleep(1)\n    first = 1 if screens.get(\"multiple_keeps_first\") else 0\n    for index in range(first, count):\n        walk.tap_first(\"Pick picture %d of %d\" % (index + 1, count), selectors=[dict(cell, instance=index) for cell in screens[\"picker_cells\"]])\n        time.sleep(random.uniform(0.4, 1.0))\n    walk.shot(\"Picked %d pictures\" % count)\n\n\ndef open_create_library(serial, walk, app, screens):\n    \"\"\"The app opened, then its create button, its library and its photos,\n    each optional step tried briefly in case this version opens straight on it.\"\"\"\n    open_app(serial, app)\n    walk.shot(\"Opened %s\" % APP_NAMES[app])\n    if signed_out(walk.screen().dump_hierarchy(), app):\n        raise RuntimeError(\"post: the app is not signed in to %s\" % APP_NAMES[app])\n    walk.tap_first(\"Open the create screen\", selectors=screens[\"create\"])\n    time.sleep(2)\n    for key, step in ((\"post_mode\", \"Pick a feed post\"), (\"upload\", \"Open the library\"), (\"photos_tab\", \"Show photos only\")):\n        if screens.get(key):\n            try:\n                walk.tap_first(step, timeout=4, selectors=screens[key])\n                time.sleep(1.5)\n            except StepFailed:\n                pass  # Already there on this version.\n\n\ndef caption_and_last_button(serial, walk, app, screens, caption):\n    \"\"\"Next until the caption box, the caption typed at a person's pace, the\n    keyboard closed, and Share or Post pressed once (found only, in a\n    rehearsal). True when it was pressed.\"\"\"\n    device = walk.screen()\n    if screens[\"share_to\"]:\n        try:\n            walk.tap_first(\"Pick the feed\", timeout=4, selectors=screens[\"share_to\"])\n        except StepFailed:\n            pass  # Straight to the editor on this version.\n    tap_next_until(walk, \"Press Next\", screens[\"next\"], screens[\"caption\"])\n    walk.tap_first(\"Open the caption box\", selectors=screens[\"caption\"])\n    if not walk.rehearse and caption:\n        gaps = type_like_a_person(serial, device, caption, walk.check)\n        walk.shot(\"Typed the caption\")\n        log(\"caption typed: %d characters, gaps %.2f to %.2f seconds\" % (len(caption), min(gaps or [0]), max(gaps or [0])))\n        if is_iphone(serial):\n            try:\n                walk.tap_first(\"Close the keyboard\", timeout=3, selectors=screens[\"keyboard_done\"])\n            except StepFailed:\n                pass\n        else:\n            go_back(serial)  # The keyboard down, so Share is on screen.\n        time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n    return walk.final_first(\"Press %s\" % (\"Share\" if app == \"instagram\" else \"Post\"), selectors=screens[\"share\"])\n\n\ndef action_app_carousel(app):\n    def action(serial, args, walk):\n        \"\"\"Posts 2 to 20 pictures as one post with its caption, once: an\n        Instagram carousel or a TikTok photo post.\n\n        On an Android every picture is downloaded from Promo's own address\n        and put in the camera folder last one first, so the first is the\n        newest. On an iPhone each comes through its own one-time Safari link,\n        saved last one first for the same reason. Then the app's create\n        screen, its library, \"select multiple\", the pictures tapped in order,\n        Next until the caption box, the caption typed, and Share or Post\n        pressed once. It counts as posted when the app says so.\n\n        A rehearsal puts two plain pictures in an Android's gallery and\n        deletes them afterwards; on an iPhone it saves nothing and walks\n        with the newest two in Photos. Either way the last button is found\n        and never pressed.\n        \"\"\"\n        screens = app_screens(serial, app)\n        caption = str(args.get(\"caption\") or \"\")\n        device = walk.screen()\n        wake_screen(device)\n        iphone_run = is_iphone(serial)\n        if walk.rehearse:\n            count = 2\n            urls = []\n        else:\n            urls = carousel_urls(args)\n            count = len(urls)\n        remotes = []\n        if iphone_run:\n            if not walk.rehearse:\n                if args.get(\"mediaFromSafari\") is not True:\n                    raise RuntimeError(\"post: an iPhone takes its pictures through one-time Safari links (mediaFromSafari), and Promo sent none\")\n                for url in reversed(urls):\n                    save_from_safari(serial, walk, url)\n        else:\n            if walk.rehearse:\n                files = [rehearsal_picture() for _ in range(count)]\n            else:\n                files = [download_media(url) for url in urls]\n                for index, (_, extension) in enumerate(files):\n                    if MEDIA_TYPES[extension].startswith(\"video/\"):\n                        raise RuntimeError(\"post: picture %d of the carousel is a video, and a carousel here holds pictures only\" % (index + 1))\n            remotes = put_slides_in_gallery(serial, files)\n            walk.shot(\"Put %d pictures in the gallery\" % count)\n        try:\n            open_create_library(serial, walk, app, screens)\n            pick_carousel_pictures(walk, screens, count)\n            pressed = caption_and_last_button(serial, walk, app, screens, caption)\n        except Cancelled:\n            raise\n        except Exception:\n            # Stopped before the last button: the draft is discarded and nothing was posted.\n            if not walk.rehearse:\n                leave_app_screen(serial, walk, app)\n            raise\n        finally:\n            if walk.rehearse:\n                leave_app_screen(serial, walk, app)\n                for remote in remotes:\n                    quietly(serial, \"rm -f '%s'\" % remote)\n                    quietly(serial, \"am broadcast -a android.intent.action.MEDIA_SCANNER_SCAN_FILE -d 'file://%s'\" % remote)\n        if not pressed:\n            walk.home()\n            return {\"postUrl\": \"\"}\n        return wait_for_post(serial, walk, app, screens)\n    return action\n\n\ndef action_app_post(app):\n    def action(serial, args, walk):\n        \"\"\"Posts one photo or video with its caption, once.\n\n        The file is downloaded from Promo's own address, put in the phone's\n        camera folder and handed to the app's own share screen, as sharing\n        from the gallery does. Next until the caption box shows, the caption\n        typed with a person's rhythm, a pause, and Share or Post pressed once.\n        It counts as posted when the app says so within three minutes. Then\n        the link is read off the newest post, and a little feed. Nothing after\n        the press can fail the post: it is up by then and never sent twice.\n\n        In a rehearsal a plain picture walks the same screens up to the last\n        button, which is found and not pressed, then the draft is discarded\n        and the picture deleted.\n\n        On an iPhone the file comes through Safari and the app's own picker\n        (ios_app_post); on Android nothing changes.\n        \"\"\"\n        if is_iphone(serial):\n            return ios_app_post(serial, args, walk, app)\n        screens = app_screens(serial, app)\n        caption = str(args.get(\"caption\") or \"\")\n        device = walk.screen()\n        device.screen_on()\n        if walk.rehearse:\n            data, extension = rehearsal_picture()\n        else:\n            data, extension = download_media(str(args.get(\"mediaUrl\") or \"\"))\n        remote = put_in_gallery(serial, data, extension)\n        walk.shot(\"Put the file in the gallery\")\n        try:\n            share_into(serial, app, media_uri(serial, remote, extension), extension)\n            walk.shot(\"Opened %s's share screen\" % APP_NAMES[app])\n            if signed_out(device.dump_hierarchy(), app):\n                raise RuntimeError(\"post: the app is not signed in to %s\" % APP_NAMES[app])\n            if screens[\"share_to\"]:\n                try:\n                    walk.tap_first(\"Pick the feed\", timeout=4, selectors=screens[\"share_to\"])\n                except StepFailed:\n                    pass  # Straight to the editor on this version.\n            tap_next_until(walk, \"Press Next\", screens[\"next\"], screens[\"caption\"])\n            walk.tap_first(\"Open the caption box\", selectors=screens[\"caption\"])\n            if not walk.rehearse and caption:\n                gaps = type_like_a_person(serial, device, caption, walk.check)\n                walk.shot(\"Typed the caption\")\n                log(\"caption typed: %d characters, gaps %.2f to %.2f seconds\" % (len(caption), min(gaps or [0]), max(gaps or [0])))\n                go_back(serial)  # The keyboard down, so Share is on screen.\n                time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n            pressed = walk.final_first(\"Press %s\" % (\"Share\" if app == \"instagram\" else \"Post\"), selectors=screens[\"share\"])\n        except Cancelled:\n            raise\n        except Exception:\n            # Stopped before the last button: the draft is discarded so the\n            # phone is not left on it, and nothing was posted.\n            if not walk.rehearse:\n                leave_app_screen(serial, walk, app)\n            raise\n        finally:\n            if walk.rehearse:\n                leave_app_screen(serial, walk, app)\n                quietly(serial, \"rm -f '%s'\" % remote)\n                quietly(serial, \"am broadcast -a android.intent.action.MEDIA_SCANNER_SCAN_FILE -d 'file://%s'\" % remote)\n        if not pressed:\n            walk.home()\n            return {\"postUrl\": \"\"}\n        return wait_for_post(serial, walk, app, screens)\n    return action\n\n\n\ndef action_instagram_story(serial, args, walk):\n    \"\"\"Posts one picture or video from the Archive as an Instagram Story, once.\n\n    The same way in as a feed post: the file is downloaded from Promo's own\n    address, put in the camera folder and handed to Instagram's share\n    screen. Story is picked there, the story editor opens, and Your story is\n    pressed once. It counts as posted when Instagram says the story was\n    shared within three minutes. A Story has no caption and no link to read.\n\n    A rehearsal walks a plain picture up to Your story, which is found and\n    not pressed, then the draft is discarded and the picture deleted. An\n    iPhone is refused for now: its share sheet has not been walked.\n    \"\"\"\n    if is_iphone(serial):\n        raise RuntimeError(\"story: an Instagram Story is not done on an iPhone yet. Post it from an Android phone.\")\n    screens = app_screens(serial, \"instagram\")\n    device = walk.screen()\n    device.screen_on()\n    if walk.rehearse:\n        data, extension = rehearsal_picture()\n    else:\n        data, extension = download_media(str(args.get(\"mediaUrl\") or \"\"))\n    remote = put_in_gallery(serial, data, extension)\n    walk.shot(\"Put the file in the gallery\")\n    try:\n        share_into(serial, \"instagram\", media_uri(serial, remote, extension), extension)\n        walk.shot(\"Opened Instagram's share screen\")\n        if signed_out(device.dump_hierarchy(), \"instagram\"):\n            raise RuntimeError(\"story: the app is not signed in to Instagram\")\n        walk.tap_first(\"Pick Story\", selectors=screens[\"story_to\"])\n        pressed = walk.final_first(\"Press Your story\", selectors=screens[\"story_share\"])\n    except Cancelled:\n        raise\n    except Exception:\n        # Stopped before the last button: the draft is discarded and nothing was posted.\n        if not walk.rehearse:\n            leave_app_screen(serial, walk, \"instagram\")\n        raise\n    finally:\n        if walk.rehearse:\n            leave_app_screen(serial, walk, \"instagram\")\n            quietly(serial, \"rm -f '%s'\" % remote)\n            quietly(serial, \"am broadcast -a android.intent.action.MEDIA_SCANNER_SCAN_FILE -d 'file://%s'\" % remote)\n    if not pressed:\n        walk.home()\n        return {\"postUrl\": \"\"}\n    landed = False\n    waiting_until = time.time() + POST_LANDED_APP_SECONDS\n    while time.time() < waiting_until:\n        time.sleep(3)\n        try:\n            hierarchy = device.dump_hierarchy()\n        except Exception:  # A screen caught mid-change; look again.\n            continue\n        if screen_says(hierarchy, \"instagram\", screens[\"post_failed\"]):\n            walk.shot(\"The app said it failed\")\n            raise RuntimeError(\"story: the app said it could not post: %s\" % screen_says(hierarchy, \"instagram\", screens[\"post_failed\"]))\n        if screen_says(hierarchy, \"instagram\", screens[\"story_posted\"]):\n            landed = True\n            break\n    walk.shot(\"Looked for the story\")\n    walk.home()\n    if not landed:\n        raise RuntimeError(\"story: pressed Your story but Instagram did not say it was shared within %d seconds. It may still be uploading; check the app before posting again.\" % POST_LANDED_APP_SECONDS)\n    return {\"postUrl\": \"\"}\n\ndef youtube_profile_from_screen(hierarchy_xml):\n    \"\"\"The channel's @handle, subscribers and videos as the YouTube app's You tab\n    or channel page shows them. None where one is not shown.\"\"\"\n    lines = screen_lines(hierarchy_xml, app_packages(\"youtube\"))\n    handle = None\n    for line in lines:\n        found = YOUTUBE_HANDLE.search(line)\n        if found:\n            handle = found.group(1).rstrip(\".\")\n            break\n    figures = {\"subscribers\": None, \"videos\": None}\n    for line in lines:\n        text = line.replace(\",\", \"\")\n        for key, word in ((\"subscribers\", \"subscribers?\"), (\"videos\", \"videos?\")):\n            match = re.search(r\"(?i)(\\d[\\d.]*\\s*[km]?)\\s+%s\\b\" % word, text)\n            if match and figures[key] is None:\n                figures[key] = parse_count(match.group(1).replace(\" \", \"\"))\n    return {\"handle\": handle, \"subscribers\": figures[\"subscribers\"], \"videos\": figures[\"videos\"]}\n\n\ndef read_youtube_channel(serial, walk):\n    \"\"\"Opens the YouTube app on the You tab and reads the channel; its channel\n    page too when the You tab shows no figures. Leaves it there.\"\"\"\n    open_app(serial, \"youtube\")\n    walk.shot(\"Opened YouTube\")\n    device = walk.screen()\n    if signed_out(device.dump_hierarchy(), \"youtube\"):\n        return {\"handle\": None, \"subscribers\": None, \"videos\": None}\n    screens = app_screens(serial, \"youtube\")\n    walk.tap_first(\"Open the You tab\", selectors=screens[\"profile_tab\"])\n    time.sleep(2)\n    reading = youtube_profile_from_screen(device.dump_hierarchy())\n    if reading[\"handle\"] and reading[\"subscribers\"] is None:\n        try:\n            walk.tap_first(\"Open the channel\", timeout=4, selectors=screens[\"view_channel\"])\n            time.sleep(2.5)\n            page = youtube_profile_from_screen(device.dump_hierarchy())\n            reading.update({key: value for key, value in page.items() if value is not None})\n        except StepFailed:\n            pass  # The You tab's handle stands; the figures wait for tomorrow.\n    walk.shot(\"Read the channel\")\n    return reading\n\n\ndef action_youtube_quick_state(serial, args, walk):\n    \"\"\"Who the YouTube app is signed in as, read after every YouTube job. One\n    that cannot be read says \"not checked\", so a failed look is never\n    written down as signed out.\"\"\"\n    if is_iphone(serial):\n        return {\"checked\": False, \"handle\": None, \"blocked\": False, \"reason\": \"YouTube is not done on an iPhone yet\", \"banScreen\": None}\n    try:\n        walk.screen().screen_on()\n        reading = read_youtube_channel(serial, walk)\n        walk.home()\n    except Cancelled:\n        raise\n    except Exception as failure:  # Not checked rather than signed out.\n        log(\"Could not read who is signed in to YouTube on %s: %s\" % (serial, failure))\n        return {\"checked\": False, \"handle\": None, \"blocked\": False, \"reason\": \"\", \"banScreen\": None}\n    return {\"checked\": True, \"handle\": reading[\"handle\"], \"blocked\": False, \"reason\": \"\", \"banScreen\": None}\n\n\ndef action_youtube_health(serial, args, walk):\n    \"\"\"The daily reading: the channel's subscribers and videos, then the\n    numbers of each video named, opened by its link. A video that will not\n    open is left out, and its numbers stay as they were. Comments on a phone\n    come through YouTube's notifications, so none are read here.\"\"\"\n    if is_iphone(serial):\n        raise RuntimeError(\"health: YouTube is not done on an iPhone yet. Put the channel on an Android phone.\")\n    walk.screen().screen_on()\n    reading = read_youtube_channel(serial, walk)\n    result = {\"handle\": reading[\"handle\"], \"subscribers\": reading[\"subscribers\"], \"videos\": reading[\"videos\"], \"verified\": None, \"numbers\": [], \"comments\": [], \"banScreen\": None}\n    if not reading[\"handle\"]:\n        walk.home()\n        return result\n    shape = app_screens(serial, \"youtube\")[\"link_shape\"]\n    for url in [str(url) for url in (args.get(\"videoUrls\") or []) if shape.match(str(url))][:20]:\n        walk.check()\n        try:\n            open_link(serial, \"youtube\", url)\n            numbers = post_numbers_from_screen(walk.screen().dump_hierarchy(), \"youtube\")\n            walk.shot(\"Read a video's numbers\")\n            result[\"numbers\"].append(dict(numbers, url=url))\n        except Cancelled:\n            raise\n        except Exception as failure:  # One video that will not open never loses the rest.\n            log(\"A YouTube video's numbers on %s: %s\" % (serial, short_words(failure)))\n    walk.home()\n    return result\n\n\ndef download_to_rack(url, limit, seconds):\n    \"\"\"Streams one of Promo's own https files to the rack's disk, never into\n    memory, and returns its path and extension.\"\"\"\n    if not url.startswith(\"https://\"):\n        raise RuntimeError(\"upload: the file's address is not an https address\")\n    extension = media_extension(url)\n    if not extension or not MEDIA_TYPES[extension].startswith(\"video/\"):\n        raise RuntimeError(\"upload: the file is not an MP4, MOV or WebM video\")\n    folder = os.path.join(HOME, \"media\")\n    os.makedirs(folder, exist_ok=True)\n    local = os.path.join(folder, camera_name(extension))\n    deadline = time.time() + seconds\n    size = 0\n    try:\n        with urllib.request.urlopen(url, timeout=60) as response, open(local, \"wb\") as out:\n            while True:\n                if time.time() > deadline:\n                    raise RuntimeError(\"upload: the file took longer than %d minutes to download\" % (seconds // 60))\n                chunk = response.read(1024 * 1024)\n                if not chunk:\n                    break\n                size += len(chunk)\n                if size > limit:\n                    raise RuntimeError(\"upload: the file is larger than Promo sends to a phone\")\n                out.write(chunk)\n    except Exception:\n        try:\n            os.remove(local)\n        except OSError:\n            pass\n        raise\n    if not size:\n        os.remove(local)\n        raise RuntimeError(\"upload: the file came back empty\")\n    return local, extension\n\n\ndef push_to_gallery(serial, local, extension):\n    \"\"\"Puts a file already on the rack's disk in the phone's camera folder, then deletes the rack's copy.\"\"\"\n    remote = \"/sdcard/DCIM/Camera/%s\" % os.path.basename(local)\n    try:\n        adb([\"push\", local, remote], serial=serial, timeout=YOUTUBE_DOWNLOAD_SECONDS)\n    finally:\n        try:\n            os.remove(local)\n        except OSError:\n            pass\n    shell(serial, \"am broadcast -a android.intent.action.MEDIA_SCANNER_SCAN_FILE -d 'file://%s'\" % remote, timeout=15)\n    time.sleep(2)\n    return remote\n\n\ndef read_youtube_link(serial, walk):\n    \"\"\"The newest video's link: You, Your videos, its menu, Share, Copy link,\n    and the clipboard read. \"\" when the app would not give it.\"\"\"\n    screens = app_screens(serial, \"youtube\")\n    try:\n        open_app(serial, \"youtube\")\n        walk.tap_first(\"Open the You tab\", selectors=screens[\"profile_tab\"])\n        time.sleep(2)\n        walk.tap_first(\"Open Your videos\", selectors=screens[\"your_videos\"])\n        time.sleep(2.5)\n        walk.tap_first(\"Open the newest video's menu\", selectors=screens[\"first_video_menu\"])\n        time.sleep(1)\n        walk.tap_first(\"Open Share\", selectors=screens[\"share_menu\"])\n        time.sleep(1)\n        walk.tap_first(\"Copy its link\", selectors=screens[\"copy_link\"])\n        time.sleep(1)\n        link = str(walk.screen().clipboard or \"\").strip()\n    except (StepFailed, AttributeError) as failure:\n        log(\"Could not read the new video's link on %s: %s\" % (walk.serial, short_words(failure)))\n        return \"\"\n    return link if screens[\"link_shape\"].match(link) else \"\"\n\n\ndef action_youtube_upload(serial, args, walk):\n    \"\"\"Uploads one video, a long one or a Short, once.\n\n    The file is streamed from Promo's own address to the rack, put in the\n    phone's camera folder and handed to the YouTube app's share screen, which\n    opens its upload screen. Next until the title box shows, the title typed\n    with a person's rhythm, then the description, \"No, it's not made for\n    kids\", the altered content question answered (it must be found when the\n    answer is Yes), Public, and Upload pressed once. It counts as uploaded\n    when the app says so inside the upload's 36 minutes, counted from the\n    download's start; then the link is read off Your\n    videos. YouTube makes a tall video of three minutes or less a Short by\n    itself. The app sets no thumbnail and no tags at upload, so a thumbnail\n    asked for comes back as not set, with why.\n\n    A rehearsal opens the app's Create button and finds Upload a video\n    without pressing it, so nothing is uploaded or downloaded.\n    \"\"\"\n    if is_iphone(serial):\n        raise RuntimeError(\"upload: YouTube is not done on an iPhone yet. Upload from a channel on an Android phone or in a browser.\")\n    screens = app_screens(serial, \"youtube\")\n    device = walk.screen()\n    device.screen_on()\n    if walk.rehearse:\n        open_app(serial, \"youtube\")\n        try:\n            walk.tap_first(\"Open Create\", selectors=screens[\"create\"])\n            time.sleep(1.5)\n            walk.find_first(\"Find Upload a video\", selectors=screens[\"upload_video\"])\n            walk.shot(\"Found Upload a video (not pressed)\")\n        finally:\n            leave_app_screen(serial, walk, \"youtube\", times=2)\n            walk.home()\n        return {\"postUrl\": \"\", \"thumbnailSet\": None, \"thumbnailNote\": \"\"}\n    title = str(args.get(\"title\") or \"\")[:100]\n    description = str(args.get(\"description\") or \"\")[:5000]\n    if not title.strip():\n        raise RuntimeError(\"upload: the video has no title\")\n    # One deadline from the start, inside the app's 42 minutes, so the app never\n    # gives up on an upload the phone is still making.\n    deadline = time.time() + YOUTUBE_PHONE_BUDGET_SECONDS\n    local, extension = download_to_rack(str(args.get(\"mediaUrl\") or \"\"), YOUTUBE_DOWNLOAD_LIMIT, YOUTUBE_DOWNLOAD_SECONDS)\n    remote = push_to_gallery(serial, local, extension)\n    walk.shot(\"Put the video in the gallery\")\n    link = \"\"\n    try:\n        try:\n            share_into(serial, \"youtube\", media_uri(serial, remote, extension), extension)\n            walk.shot(\"Opened YouTube's upload screen\")\n            if signed_out(device.dump_hierarchy(), \"youtube\"):\n                raise RuntimeError(\"upload: the app is not signed in to YouTube\")\n            tap_next_until(walk, \"Press Next\", screens[\"next\"], screens[\"title\"])\n            box = walk.find_first(\"Find the title box\", selectors=screens[\"title\"])\n            clear_and_type(serial, walk, box, title)\n            walk.shot(\"Typed the title\")\n            go_back(serial)  # The keyboard down.\n            if description.strip():\n                try:\n                    walk.tap_first(\"Open the description\", timeout=5, selectors=screens[\"description\"])\n                    time.sleep(1)\n                    field = walk.find_first(\"Find the description box\", timeout=5, selectors=screens[\"field\"])\n                    # Up to 5,000 characters typed a key at a time would take ten\n                    # minutes, so the description is put in whole, as a paste is.\n                    put_text(serial, walk, field, description)\n                    walk.shot(\"Put in the description\")\n                    go_back(serial)\n                    go_back(serial)\n                except StepFailed:\n                    pass  # A Short's screen holds the title alone.\n            walk.tap_first(\"Open Select audience\", selectors=screens[\"audience\"])\n            time.sleep(1)\n            walk.tap_first(\"Pick not made for kids\", selectors=screens[\"not_for_kids\"])\n            go_back(serial)\n            time.sleep(1)\n            try:\n                walk.tap_first(\"Show more\", timeout=4, selectors=screens[\"show_more\"])\n                time.sleep(1)\n            except StepFailed:\n                pass\n            try:\n                walk.tap_first(\"Open altered content\", timeout=5, selectors=screens[\"altered\"])\n                time.sleep(1)\n                walk.tap_first(\"Answer altered content\", selectors=screens[\"altered_yes\" if args.get(\"aiMade\") else \"altered_no\"])\n                go_back(serial)\n            except StepFailed:\n                # YouTube's own answer is No; a Yes must be given, so a missing question stops the upload.\n                if args.get(\"aiMade\"):\n                    raise\n            try:\n                walk.tap_first(\"Open Visibility\", timeout=5, selectors=screens[\"visibility\"])\n                time.sleep(1)\n                walk.tap_first(\"Pick Public\", selectors=screens[\"public\"])\n                go_back(serial)\n            except StepFailed:\n                pass  # The app's own choice for a new channel is Public.\n            if time.time() > deadline - 5 * 60:\n                raise RuntimeError(\"upload: the screens took too long, so Upload was not pressed. Nothing was uploaded.\")\n            time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n            walk.final_first(\"Press Upload\", selectors=screens[\"share\"])\n        except Cancelled:\n            raise\n        except Exception:\n            # Stopped before the last button: the draft is discarded and nothing was uploaded.\n            leave_app_screen(serial, walk, \"youtube\")\n            raise\n        landed = False\n        while time.time() < deadline:\n            time.sleep(5)\n            walk.check()\n            try:\n                hierarchy = device.dump_hierarchy()\n            except Exception:  # A screen caught mid-change; look again.\n                continue\n            if screen_says(hierarchy, \"youtube\", screens[\"post_failed\"]):\n                walk.shot(\"The app said it failed\")\n                raise RuntimeError(\"upload: the app said it could not upload: %s\" % screen_says(hierarchy, \"youtube\", screens[\"post_failed\"]))\n            if screen_says(hierarchy, \"youtube\", screens[\"posted\"]):\n                landed = True\n                break\n        walk.shot(\"Looked for the upload\")\n        if not landed:\n            raise RuntimeError(\"upload: pressed Upload but YouTube did not say it was uploaded in time. It may still be uploading; look in the app before uploading again.\")\n        try:\n            link = read_youtube_link(serial, walk)\n        except Exception as failure:  # Includes a cancel: the video is up either way.\n            log(\"After the upload on %s: %s\" % (serial, short_words(failure)))\n        walk.home()\n    finally:\n        # Only once YouTube has the file, or the upload stopped: the app reads it while it uploads.\n        quietly(serial, \"rm -f '%s'\" % remote)\n        quietly(serial, \"am broadcast -a android.intent.action.MEDIA_SCANNER_SCAN_FILE -d 'file://%s'\" % remote)\n    asked = bool(args.get(\"thumbnailUrl\"))\n    return {\n        \"postUrl\": link,\n        \"thumbnailSet\": False if asked else None,\n        \"thumbnailNote\": \"The YouTube app on a phone sets no thumbnail at upload. Set it in YouTube Studio.\" if asked else \"\",\n    }\n\n\ndef put_text(serial, walk, element, text):\n    \"\"\"Puts a long text into a box whole, as a paste does, where typing it a key\n    at a time would take minutes. A box that will not take it is typed into.\"\"\"\n    walk.press(element)\n    time.sleep(0.6)\n    try:\n        element.set_text(text)\n    except Exception:  # A box set_text cannot reach: typed with a person's rhythm instead.\n        type_like_a_person(serial, walk.screen(), text, walk.check)\n\n\ndef clear_and_type(serial, walk, element, text):\n    \"\"\"Empties a text box and types into it with a person's rhythm.\"\"\"\n    walk.press(element)\n    time.sleep(0.6)\n    try:\n        element.clear_text()\n    except Exception:  # A fake screen, or a box that clears on its own.\n        pass\n    if text:\n        type_like_a_person(serial, walk.screen(), text, walk.check)\n\n\ndef action_app_profile(app):\n    def action(serial, args, walk):\n        \"\"\"Changes the fields given in the app's Edit profile: the name, the\n        bio, the link and the picture, each saved on its own screen with one\n        press. The bio is read back off the profile afterwards. A rehearsal\n        opens Edit profile and the bio's screen, finds its box and its Save,\n        and backs out without pressing it.\"\"\"\n        screens = app_screens(serial, app)\n        device = walk.screen()\n        device.screen_on()\n        reading = read_app_profile(serial, walk, app)\n        if not reading[\"handle\"]:\n            raise RuntimeError(\"profile: the app is not signed in to %s\" % APP_NAMES[app])\n        walk.tap_first(\"Open Edit profile\", selectors=screens[\"edit_profile\"])\n        time.sleep(2)\n        applied = []\n        fields = [(key, args.get(key)) for key in (\"displayName\", \"bio\", \"link\")]\n        if walk.rehearse:\n            fields = [(\"bio\", \"\")]\n        for key, value in fields:\n            if value is None:\n                continue\n            walk.check()\n            walk.tap_first(\"Open the %s\" % key, selectors=screens[\"rows\"][key])\n            time.sleep(1.5)\n            if key == \"link\" and not walk.rehearse:\n                try:\n                    walk.tap_first(\"Add an external link\", timeout=3, selectors=screens[\"link_add\"])\n                    time.sleep(1)\n                except StepFailed:\n                    pass\n            box = walk.find_first(\"Find the %s box\" % key, selectors=screens[\"field\"])\n            if not walk.rehearse:\n                clear_and_type(serial, walk, box, str(value))\n                walk.shot(\"Typed the %s\" % key)\n            if walk.final_first(\"Save the %s\" % key, selectors=screens[\"save\"]):\n                applied.append(key)\n                time.sleep(2)\n            else:\n                leave_app_screen(serial, walk, app, times=2)\n                walk.home()\n                return {\"applied\": [], \"bioAfter\": None}\n        picture = str(args.get(\"pictureUrl\") or \"\")\n        if picture and not walk.rehearse:\n            if is_iphone(serial):\n                # Into Photos through Safari, then back to Edit profile.\n                save_from_safari(serial, walk, picture)\n                open_app(serial, app)\n                walk.tap_first(\"Open the profile\", selectors=screens[\"profile_tab\"])\n                time.sleep(2)\n                walk.tap_first(\"Open Edit profile\", selectors=screens[\"edit_profile\"])\n                time.sleep(2)\n            else:\n                data, extension = download_media(picture)\n                put_in_gallery(serial, data, extension)\n            walk.tap_first(\"Change the picture\", selectors=screens[\"picture_row\"])\n            time.sleep(1.5)\n            walk.tap_first(\"Choose from the gallery\", selectors=screens[\"picture_library\"])\n            time.sleep(2)\n            # The newest picture in the gallery is the one just put there.\n            walk.tap_first(\"Pick the newest picture\", selectors=screens[\"gallery_first\"])\n            time.sleep(1.5)\n            # Instagram crops the picture first, behind Next; only Save or Done keeps it.\n            tap_next_until(walk, \"Crop the picture\", screens[\"next\"], screens[\"save\"])\n            if walk.final_first(\"Save the picture\", selectors=screens[\"save\"]):\n                applied.append(\"picture\")\n                time.sleep(4)\n        go_back(serial)\n        time.sleep(2)\n        bio_after = None\n        if \"bio\" in applied:\n            lines = screen_lines(device.dump_hierarchy(), screens[\"package\"])\n            wanted = \" \".join(str(args.get(\"bio\") or \"\").split())\n            bio_after = wanted if wanted in lines else None\n            walk.shot(\"Read the profile afterwards\")\n        walk.home()\n        return {\"applied\": applied, \"bioAfter\": bio_after}\n    return action\n\n\n# ---------------------------------------------------------------------------\n# Messages and comments. The rack reads each phone's notifications once a\n# minute without opening an app, and tells Promo which app had a message or\n# a comment, never its words. Promo then sends an inbox action, which taps\n# that notification the way a person answers the buzz (Tyler, 16 Oct 2026:\n# \"if it goes straight to the DM wouldnt that be suspicious?\"), reads the\n# conversation or the comments, and spends a little time in the feed.\n\nALERT_KEEP = 500\n\n\ndef parse_app_notifications(output):\n    \"\"\"The notifications of the three apps in `dumpsys notification --noredact`:\n    (app, key, channel and category, title, text).\"\"\"\n    packages = dict((package, app) for app, package in APP_PACKAGES.items())\n    found = []\n    current = None\n    for line in output.splitlines():\n        stripped = line.strip()\n        if stripped.startswith(\"NotificationRecord(\"):\n            package = re.search(r\"pkg=(\\S+)\", stripped)\n            app = packages.get(package.group(1)) if package else None\n            key = re.search(r\"key=(\\S+?):\", stripped)\n            meta = \" \".join(re.findall(r\"(?:channel|category|tag)=(\\S+)\", stripped))\n            current = {\"app\": app, \"key\": key.group(1) if key else stripped[:80], \"meta\": meta, \"title\": \"\", \"text\": \"\"} if app else None\n            if current:\n                found.append(current)\n        elif current and stripped.startswith(\"android.title=\"):\n            current[\"title\"] = re.sub(r\"^android\\.title=\\w+ \\((.*)\\)$\", r\"\\1\", stripped)\n        elif current and stripped.startswith(\"android.text=\"):\n            current[\"text\"] = re.sub(r\"^android\\.text=\\w+ \\((.*)\\)$\", r\"\\1\", stripped)\n    return found\n\n\nCOMMENT_ALERT = re.compile(r\"\\b(commented|replied to your comment|mentioned you in a comment)\\b\")\nMESSAGE_ALERT = re.compile(r\"\\b(sent you an? (new )?(direct message|message|inmail|chat|photo|video|reel|post)|messaged you|new (direct )?message|new chat|wants to send you a message)\\b\")\n\n\ndef alert_kind(item):\n    \"\"\"\"message\", \"comment\" or None for one app notification. Reddit's comment\n    replies are left to the reader browser, so Reddit only counts its chats\n    and messages. X is the same: replies and mentions are read from a\n    browser, so only its direct messages count, which X files under a \"dm\"\n    channel. LinkedIn too: its comments are read by a search account, so only\n    its messages and InMail count, which it files under a \"messaging\"\n    channel. Likes, reactions, follows and invitations are nothing.\"\"\"\n    words = plain(\"%s %s\" % (item[\"title\"], item[\"text\"]))\n    meta = plain(item[\"meta\"])\n    if item[\"app\"] in (\"instagram\", \"tiktok\", \"threads\", \"youtube\") and COMMENT_ALERT.search(words):\n        return \"comment\"\n    if MESSAGE_ALERT.search(words) or re.search(r\"(direct|messag(e|ing)|chat|\\bmsg\\b|\\bim\\b|(?<![a-z])dms?(?![a-z]))\", meta):\n        return \"message\"\n    return None\n\n\ndef new_alerts(output, seen):\n    \"\"\"The alerts not reported before: one per app and kind, each notification\n    remembered by its key and words so it is reported once.\"\"\"\n    alerts = []\n    for item in parse_app_notifications(output):\n        kind = alert_kind(item)\n        if not kind:\n            continue\n        mark = hashlib.sha256((\"%s|%s|%s\" % (item[\"key\"], item[\"title\"], item[\"text\"])).encode(\"utf-8\")).hexdigest()\n        if mark in seen:\n            continue\n        seen[mark] = True\n        alert = {\"app\": item[\"app\"], \"kind\": kind}\n        if alert not in alerts:\n            alerts.append(alert)\n    while len(seen) > ALERT_KEEP:\n        seen.popitem(last=False)  # The oldest goes first.\n    return alerts\n\n\n_ALERTS = {}\n_ALERTS_LOCK = threading.Lock()\n\n\ndef keep_alerts(serial, alerts):\n    with _ALERTS_LOCK:\n        waiting = _ALERTS.setdefault(serial, [])\n        for alert in alerts:\n            if alert not in waiting:\n                waiting.append(alert)\n\n\ndef take_alerts(serial):\n    with _ALERTS_LOCK:\n        return _ALERTS.pop(serial, [])\n\n\ndef conversation_from_screen(hierarchy_xml, app, height=2400, width=1080):\n    \"\"\"One conversation as its screen shows it: its name from the top bar, and\n    its lines, the account's own on the right.\"\"\"\n    packages = app_packages(app)\n    root = ElementTree.fromstring(hierarchy_xml)\n    thread = \"\"\n    lines = []\n    for node in root.iter(\"node\"):\n        if not own_node(node, packages):\n            continue\n        words = node_words(node)\n        bounds = parse_bounds(node.get(\"bounds\"))\n        if not words or not bounds:\n            continue\n        middle_y = (bounds[1] + bounds[3]) / 2\n        if middle_y < height * 0.12:\n            if not thread and 1 <= len(words) <= 60 and plain(words) not in (\"back\", \"call\", \"video call\", \"info\", \"audio call\"):\n                thread = words\n            continue\n        if middle_y > height * 0.9 or NOT_A_LINE.match(words) or is_text_box(node) or not_a_line(node, height):\n            continue\n        if node.get(\"text\") is None or not (node.get(\"text\") or \"\").strip():\n            continue\n        mine = (bounds[0] + bounds[2]) / 2 > width * 0.55\n        lines.append({\"from\": \"\" if mine else thread, \"text\": words, \"mine\": mine})\n    return {\"thread\": thread, \"lines\": lines}\n\n\nAUTHOR_TEXT = re.compile(r\"^([A-Za-z0-9._]{2,30})\\s+(.+)$\")\n\n\ndef comments_from_screen(hierarchy_xml, app, handle, height=2400):\n    \"\"\"The comments on a post's comments screen, by author, leaving out the\n    account's own. The first line by the account is the caption, which says\n    which post it is.\"\"\"\n    packages = app_packages(app)\n    lines = []\n    root = ElementTree.fromstring(hierarchy_xml)\n    for node in root.iter(\"node\"):\n        if not own_node(node, packages):\n            continue\n        bounds = parse_bounds(node.get(\"bounds\"))\n        words = (node.get(\"text\") or \"\").strip()\n        if not words or not bounds or not (height * 0.1 < (bounds[1] + bounds[3]) / 2 < height * 0.9):\n            continue\n        if NOT_A_LINE.match(words) or plain(words) in (\"reply\", \"see translation\", \"view replies\", \"hide replies\") or not_a_line(node, height):\n            continue\n        lines.append(\" \".join(words.split()))\n    thread = \"\"\n    comments = []\n    index = 0\n    own = (handle or \"\").lower()\n    while index < len(lines):\n        line = lines[index]\n        author, text = None, None\n        joined = AUTHOR_TEXT.match(line)\n        if PLAIN_HANDLE.match(line) and index + 1 < len(lines) and not PLAIN_HANDLE.match(lines[index + 1]):\n            author, text = line, lines[index + 1]\n            index += 2\n        elif joined:\n            author, text = joined.group(1), joined.group(2)\n            index += 1\n        else:\n            index += 1\n            continue\n        if author.lower() == own:\n            if not thread:\n                thread = text[:120]\n            continue\n        comments.append({\"author\": author, \"text\": text})\n    return [dict(comment, thread=thread) for comment in comments]\n\n\nNOT_A_MESSAGE = re.compile(r\"\\b(liked|follow|following|tagged you|went live|posted|reposted)\\b\")\n\n\ndef notification_for(hierarchy_xml, app, kind):\n    \"\"\"Where the shade shows the app's newest notification of this kind, or None.\n    Each line belongs to the app named above it. A comment needs its words; a\n    message is one that says so, or failing that the app's first line that is\n    no comment, like or follow, since a direct message shows only its words.\"\"\"\n    name = plain(APP_NAMES[app])\n    names = set(plain(other) for other in APP_NAMES.values())\n    under = None\n    fallback = None\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        words = plain(\" \".join((node.get(\"text\") or \"\").split()))\n        bounds = parse_bounds(node.get(\"bounds\"))\n        if not words or not bounds:\n            continue\n        if words in names:\n            under = words\n            continue\n        if under != name:\n            continue\n        if kind == \"comment\":\n            if COMMENT_ALERT.search(words):\n                return bounds\n        elif MESSAGE_ALERT.search(words):\n            return bounds\n        elif fallback is None and not COMMENT_ALERT.search(words) and not NOT_A_MESSAGE.search(words):\n            fallback = bounds\n    return fallback if kind == \"message\" else None\n\n\ndef open_newest_notification(walk, app, kind):\n    \"\"\"Pulls the notification shade down and taps the app's newest notification\n    of this kind. False when none is there.\"\"\"\n    device = walk.screen()\n    try:\n        device.open_notification()\n    except Exception:  # A fake screen; the inbox is opened instead.\n        return False\n    time.sleep(1.5)\n    bounds = notification_for(device.dump_hierarchy(), app, kind)\n    if not bounds:\n        go_back(walk.serial)\n        return False\n    walk.shot(\"Opened the notifications\")\n    press_bounds(walk, bounds)\n    time.sleep(3)\n    return True\n\n\ndef press_bounds(walk, bounds):\n    \"\"\"Presses a place read off the screen the way walk.press presses an element.\"\"\"\n    time.sleep(random.uniform(*LOOK_BEFORE_TAP_SECONDS))\n    walk.check()\n    x, y = tap_point(bounds)\n    tap_at(walk.serial, walk.screen(), x, y)\n\n\ndef landed_on(device, selectors):\n    \"\"\"True when one of these shapes shows now: the notification led where it should.\"\"\"\n    return any(device(**selector).exists for selector in selectors)\n\n\ndef open_inbox(serial, walk, app):\n    open_app(serial, app)\n    if app == \"reddit\":\n        walk.tap_first(\"Open the chats\", selectors=app_screens(serial, \"reddit\")[\"chat\"])\n    else:\n        walk.tap_first(\"Open the inbox\", selectors=app_screens(serial, app)[\"inbox\"])\n    time.sleep(2)\n\n\nREDDIT_CHAT = shapes(REDDIT, \"(?i)^(chat|chats|inbox|messages)$\")\nREDDIT_MESSAGE_BOX = shapes(REDDIT, \"(?i)^(message|send a message)( ?(…|\\\\.\\\\.\\\\.))?$\") + field_in(REDDIT)\nREDDIT_SEND = shapes(REDDIT, \"(?i)^send$\")\n\n# Reddit's own buttons join APP_SCREENS so app_screens picks them by the\n# phone's kind too: the Android app's by name, the iPhone app's by bundle id.\nAPP_SCREENS[\"reddit\"] = {\n    \"package\": REDDIT,\n    \"avatar\": REDDIT_AVATAR,\n    \"profile_entry\": REDDIT_PROFILE_ENTRY,\n    \"comment_box\": REDDIT_COMMENT_BOX,\n    \"post_button\": REDDIT_POST_BUTTON,\n    \"discard\": REDDIT_DISCARD,\n    \"chat\": REDDIT_CHAT,\n    \"message_box\": REDDIT_MESSAGE_BOX,\n    \"send\": REDDIT_SEND,\n    \"field\": field_in(REDDIT),\n}\nAPP_SCREENS[IOS_REDDIT] = {\n    \"package\": IOS_REDDIT,\n    \"avatar\": shapes(IOS_REDDIT, \"(?i)^(open profile menu|profile menu|profile|account|user account|your profile|avatar|.*avatar.*)$\")\n    + [{\"resourceIdMatches\": \"(?i).*(avatar|profile.?menu|user.?icon).*\", \"packageName\": IOS_REDDIT}],\n    \"profile_entry\": shapes(IOS_REDDIT, \"(?i)^(profile|my profile|view profile)$\"),\n    \"comment_box\": shapes(IOS_REDDIT, \"(?i)^(add a comment|join the conversation|add a reply)( ?(…|\\\\.\\\\.\\\\.))?$\"),\n    \"post_button\": shapes(IOS_REDDIT, \"(?i)^(post|reply|comment)$\"),\n    \"discard\": [{\"textMatches\": \"(?i)^(discard|discard comment|leave)$\"}],\n    \"chat\": shapes(IOS_REDDIT, \"(?i)^(chat|chats|inbox|messages)$\"),\n    \"message_box\": shapes(IOS_REDDIT, \"(?i)^(message|send a message)( ?(…|\\\\.\\\\.\\\\.))?$\") + ios_field_in(IOS_REDDIT),\n    \"send\": shapes(IOS_REDDIT, \"(?i)^send$\"),\n    \"field\": ios_field_in(IOS_REDDIT),\n}\n\n\ndef screens_for(app, serial=\"\"):\n    \"\"\"The buttons an app's messages use on this phone; Reddit's chats have their own.\"\"\"\n    screens = app_screens(serial, app)\n    if app == \"reddit\":\n        return {\"message_box\": screens[\"message_box\"], \"send\": screens[\"send\"], \"package\": screens[\"package\"]}\n    return screens\n\n\ndef first_conversation(walk, app):\n    \"\"\"Opens the inbox's first conversation. False when the inbox is empty.\"\"\"\n    device = walk.screen()\n    width, height = screen_size(device)\n    root = ElementTree.fromstring(device.dump_hierarchy())\n    package = package_for(walk.serial, app)\n    for node in root.iter(\"node\"):\n        bounds = parse_bounds(node.get(\"bounds\"))\n        if not own_node(node, package) or not bounds or not is_row(node):\n            continue\n        if height * 0.18 < (bounds[1] + bounds[3]) / 2 < height * 0.85 and bounds[2] - bounds[0] > width * 0.7:\n            x, y = tap_point(bounds)\n            walk.check()\n            tap_at(walk.serial, device, x, y)\n            time.sleep(2)\n            return True\n    return False\n\n\ndef action_app_inbox(app):\n    def action(serial, args, walk):\n        \"\"\"Reads what arrived. With `via` \"notification\" it taps the app's\n        newest notification first; otherwise, or when there is none, it opens\n        the app's inbox and the first conversation. Comments are read off the\n        post the notification opens. A minute or so of feed afterwards.\n        Nothing is pressed but the way in and Back.\"\"\"\n        kind = \"comment\" if args.get(\"kind\") == \"comment\" else \"message\"\n        device = walk.screen()\n        device.screen_on()\n        width, height = screen_size(device)\n        # Promo names the account, so its own lines (the caption) are told apart.\n        handle = str(args.get(\"handle\") or \"\")\n        reached = False\n        if args.get(\"via\") != \"inbox\" and not walk.rehearse:\n            reached = open_newest_notification(walk, app, kind)\n            # A notification that led somewhere else is left, and the way in\n            # is the inbox or the activity, as with no notification at all.\n            box = screens_for(app, serial)[\"message_box\"] if kind == \"message\" else app_screens(serial, app)[\"comment_box\"]\n            if reached and not landed_on(device, box):\n                go_back(serial)\n                reached = False\n        result = {\"conversations\": [], \"comments\": []}\n        if kind == \"comment\":\n            if not reached:\n                open_app(serial, app)\n                walk.tap_first(\"Open the activity\", selectors=app_screens(serial, app)[\"activity\"])\n                time.sleep(2)\n                walk.shot(\"Opened the activity\")\n                walk.home()\n                return result\n            result[\"comments\"] = comments_from_screen(device.dump_hierarchy(), app, handle, height)\n            walk.shot(\"Read the comments\")\n        else:\n            if not reached:\n                open_inbox(serial, walk, app)\n                walk.shot(\"Opened the inbox\")\n                if walk.rehearse or not first_conversation(walk, app):\n                    walk.home()\n                    return result\n            conversation = conversation_from_screen(device.dump_hierarchy(), app, height, width)\n            walk.shot(\"Read the conversation\")\n            if conversation[\"thread\"] and conversation[\"lines\"]:\n                result[\"conversations\"].append(conversation)\n        try:\n            go_back(serial)\n            time.sleep(1.5)\n            if app != \"reddit\":\n                browse_app_feed(serial, walk, random.uniform(*APP_READ_FEED_SECONDS))\n            else:\n                browse_feed(serial, walk, random.uniform(*APP_READ_FEED_SECONDS), 0, new_visit(), time.monotonic() + 120)\n        except Exception as failure:  # The reading stands either way.\n            log(\"The feed after reading %s on %s: %s\" % (APP_NAMES[app], serial, short_words(failure)))\n        walk.home()\n        return result\n    return action\n\n\ndef find_line(device, package, words):\n    \"\"\"An element on screen whose own words hold `words`, or None.\"\"\"\n    wanted = \" \".join((words or \"\").split())[:60]\n    if not wanted:\n        return None\n    element = device(textContains=wanted, packageName=package)\n    return element if element.exists else None\n\n\ndef rows_named(hierarchy_xml, package, name):\n    \"\"\"Where the screen shows exactly this name, in the app's own views. An\n    inbox row is told apart by its whole name, so \"sam\" never opens \"samantha\"\n    or a chat whose last line reads \"ask sam\".\"\"\"\n    wanted = plain(\" \".join((name or \"\").split()))\n    found = []\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        if not own_node(node, package):\n            continue\n        bounds = parse_bounds(node.get(\"bounds\"))\n        if bounds and wanted and plain(\" \".join((node.get(\"text\") or \"\").split())) == wanted:\n            found.append(bounds)\n    return found\n\n\ndef reply_under(hierarchy_xml, package, words, height):\n    \"\"\"Where the Reply of the comment holding `words` is: the first Reply below\n    the comment's own words, close under them. None when the comment or its\n    Reply is not on screen.\"\"\"\n    wanted = \" \".join((words or \"\").split())[:60]\n    comment = None\n    replies = []\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        if not own_node(node, package):\n            continue\n        bounds = parse_bounds(node.get(\"bounds\"))\n        text = \" \".join((node.get(\"text\") or \"\").split())\n        if not bounds or not text:\n            continue\n        if comment is None and wanted and wanted in text:\n            comment = bounds\n        elif plain(text) == \"reply\":\n            replies.append(bounds)\n    if comment is None:\n        return None\n    below = [bounds for bounds in replies if comment[3] - 5 <= bounds[1] <= comment[3] + height * 0.12]\n    return min(below, key=lambda bounds: bounds[1]) if below else None\n\n\ndef times_shown(hierarchy_xml, package, text):\n    \"\"\"How many of the app's views show the words, the text box left out: words\n    still sitting unsent in the box are not an answer that went out, and the\n    same words said earlier in the chat each count once.\"\"\"\n    wanted = \" \".join(text.split())[:60]\n    if not wanted:\n        return 0\n    count = 0\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        if not own_node(node, package) or is_text_box(node):\n            continue\n        if any(wanted in \" \".join((node.get(key) or \"\").split()) for key in (\"text\", \"content-desc\")):\n            count += 1\n    return count\n\n\ndef action_app_reply(app):\n    def action(serial, args, walk):\n        \"\"\"Answers one conversation or one comment, once. A conversation is\n        found by its name in the inbox; a comment through the app's activity,\n        by its author and words, then its Reply. The words are typed with a\n        person's rhythm and Send or Post pressed once; it counts as sent when\n        the words show on screen within 20 seconds. A rehearsal opens the\n        inbox and its first conversation, if any, finds the box and Send,\n        and presses neither.\"\"\"\n        kind = \"comment\" if args.get(\"kind\") == \"comment\" else \"message\"\n        text = str(args.get(\"text\") or \"\")\n        thread = str(args.get(\"thread\") or \"\")\n        author = str(args.get(\"author\") or \"\")\n        quote = str(args.get(\"quote\") or \"\")\n        screens = screens_for(app, serial)\n        package = package_for(serial, app)\n        device = walk.screen()\n        device.screen_on()\n        if not walk.rehearse and not text:\n            raise RuntimeError(\"reply: no words to send\")\n\n        if kind == \"message\":\n            open_inbox(serial, walk, app)\n            if walk.rehearse:\n                if not first_conversation(walk, app):\n                    walk.home()\n                    return {\"sent\": False}\n            else:\n                rows = rows_named(device.dump_hierarchy(), package, thread)\n                if len(rows) != 1:\n                    walk.shot(\"Looked for the conversation\")\n                    raise StepFailed(\n                        \"Find the conversation\",\n                        \"The conversation was not in the inbox.\" if not rows\n                        else \"Two conversations in the inbox have the same name, so neither was answered.\",\n                    )\n                press_bounds(walk, rows[0])\n                time.sleep(2)\n            walk.shot(\"Opened the conversation\")\n            box = walk.find_first(\"Find the message box\", selectors=screens[\"message_box\"])\n            send = screens[\"send\"]\n        else:\n            open_app(serial, app)\n            walk.tap_first(\"Open the activity\", selectors=app_screens(serial, app)[\"activity\"])\n            time.sleep(2)\n            if walk.rehearse:\n                walk.shot(\"Opened the activity\")\n                walk.home()\n                return {\"sent\": False}\n            row = find_line(device, package, author)\n            if row is None:\n                raise StepFailed(\"Find the comment\", \"No comment by %s was in the activity.\" % author)\n            walk.press(row)\n            time.sleep(3)\n            # The Reply under this comment's own words, never the first on screen.\n            _, height = screen_size(device)\n            reply = reply_under(device.dump_hierarchy(), package, quote, height)\n            if reply is None:\n                walk.shot(\"Looked for the comment\")\n                raise StepFailed(\"Find the comment\", \"The comment by %s, with its Reply, was not on the post's screen.\" % author)\n            press_bounds(walk, reply)\n            time.sleep(1.5)\n            box = walk.find_first(\"Find the reply box\", selectors=app_screens(serial, app)[\"comment_box\"])\n            send = app_screens(serial, app)[\"comment_send\"]\n\n        before = 0\n        if not walk.rehearse:\n            before = times_shown(device.dump_hierarchy(), package, text)\n            walk.press(box)\n            gaps = type_like_a_person(serial, device, text, walk.check)\n            walk.shot(\"Typed the answer\")\n            log(\"answer typed: %d characters, gaps %.2f to %.2f seconds\" % (len(text), min(gaps or [0]), max(gaps or [0])))\n            time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n        pressed = walk.final_first(\"Press Send\", selectors=send)\n        if not pressed:\n            leave_app_screen(serial, walk, app, times=2)\n            walk.home()\n            return {\"sent\": False}\n        sent = False\n        waiting_until = time.time() + POST_LANDED_SECONDS\n        while time.time() < waiting_until:\n            time.sleep(1)\n            try:\n                if times_shown(device.dump_hierarchy(), package, text) > before:\n                    sent = True\n                    break\n            except Exception:  # A screen caught mid-change; look again.\n                continue\n        walk.shot(\"Looked for the answer\")\n        if not sent:\n            raise RuntimeError(\"reply: pressed Send but the words did not show within %d seconds. Check the app before sending again.\" % POST_LANDED_SECONDS)\n        try:\n            go_back(serial)\n            time.sleep(1)\n            if app != \"reddit\":\n                browse_app_feed(serial, walk, random.uniform(*APP_FEED_AFTER_SECONDS))\n        except Exception as failure:  # The answer is out either way.\n            log(\"The feed after answering on %s: %s\" % (serial, short_words(failure)))\n        walk.home()\n        return {\"sent\": True}\n    return action\n\n\n# The actions the daily self-test walks, with the arguments a rehearsal uses.\n# The app actions join this list as they are written. The wipe never does:\n# a rehearsal cannot press its last button, but nothing about a wipe is\n# worth the risk. The comment's post is sent by Promo, a recent one found.\nREHEARSALS = {\n    \"phone/android-version\": {},\n    # Read-only on an iPhone; on an Android it says so and stops.\n    \"phone/icloud-state\": {},\n    \"reddit/state\": {},\n    \"reddit/health\": {},\n    \"reddit/comment\": {\"permalink\": \"\", \"text\": \"\", \"subreddit\": \"\"},\n    \"reddit/inbox\": {\"kind\": \"message\", \"via\": \"inbox\"},\n    \"reddit/reply_message\": {\"kind\": \"message\", \"thread\": \"\", \"author\": \"\", \"quote\": \"\", \"text\": \"\"},\n}\n# Instagram's and TikTok's steps (phone farm file 06). The post walks a plain\n# picture the rack makes, up to Share or Post; the profile walks the bio's box\n# up to Save; neither presses its last button.\nfor _app in (\"instagram\", \"tiktok\"):\n    REHEARSALS.update({\n        \"%s/health\" % _app: {\"postUrls\": []},\n        \"%s/profile\" % _app: {},\n        \"%s/post\" % _app: {\"mediaUrl\": \"\", \"mediaKind\": \"photo\", \"caption\": \"\"},\n        # Two plain pictures on an Android, the newest two in Photos on an iPhone (part 40).\n        \"%s/post_carousel\" % _app: {\"mediaUrls\": [], \"caption\": \"\"},\n        \"%s/inbox\" % _app: {\"kind\": \"message\", \"via\": \"inbox\", \"handle\": \"\"},\n        \"%s/reply\" % _app: {\"kind\": \"message\", \"thread\": \"\", \"author\": \"\", \"quote\": \"\", \"text\": \"\"},\n        # Opens the feed and stops: nothing is liked in a rehearsal.\n        \"%s/warm_up\" % _app: {\"likes\": 0},\n    })\n# A plain picture walked up to Your story, never pressed (part 8 of the 18 Nov 2026 features task).\nREHEARSALS[\"instagram/post_story\"] = {\"mediaUrl\": \"\", \"mediaKind\": \"photo\"}\n# Threads' steps (part 9), Instagram's walks without the carousel or a Story.\nREHEARSALS.update({\n    \"threads/health\": {\"postUrls\": []},\n    \"threads/profile\": {},\n    \"threads/post\": {\"mediaUrl\": \"\", \"mediaKind\": \"photo\", \"caption\": \"\"},\n    \"threads/inbox\": {\"kind\": \"comment\", \"via\": \"activity\", \"handle\": \"\"},\n    \"threads/reply\": {\"kind\": \"comment\", \"thread\": \"\", \"author\": \"\", \"quote\": \"\", \"text\": \"\"},\n    \"threads/warm_up\": {\"likes\": 0},\n})\n# YouTube's steps (YouTube task): the upload walks the Create button up to\n# Upload a video, never pressed; the comments walk the notifications.\nREHEARSALS.update({\n    \"youtube/health\": {\"videoUrls\": []},\n    \"youtube/upload\": {\"mediaUrl\": \"\", \"title\": \"\", \"description\": \"\", \"tags\": [], \"thumbnailUrl\": \"\", \"aiMade\": False, \"short\": False},\n    \"youtube/inbox\": {\"kind\": \"comment\", \"via\": \"activity\", \"handle\": \"\"},\n    \"youtube/reply\": {\"kind\": \"comment\", \"thread\": \"\", \"author\": \"\", \"quote\": \"\", \"text\": \"\"},\n})\n\n\ndef rehearsal_args(rehearsals, overrides):\n    \"\"\"Each rehearsal's arguments, with Promo's own for the ones it names.\n    An action Promo names that is not rehearsed is left out.\"\"\"\n    merged = dict((name, dict(args)) for name, args in rehearsals.items())\n    for name, args in (overrides or {}).items():\n        if name in merged and isinstance(args, dict):\n            merged[name].update(args)\n    return merged\n\n\n# Steps the self-test walks only where they can run (18 Nov 2026 features\n# task, parts 8 and 9): neither Threads nor an Instagram Story is written for\n# an iPhone yet, and Threads' steps need its app on the phone. One left out is\n# neither passed nor broken, so its jobs stay refused and no bell rings for it.\nANDROID_ONLY_REHEARSALS = (\"threads/\", \"instagram/post_story\", \"youtube/\")\n\n# Apps whose walks wait until the app is on the phone.\nNEEDS_THE_APP = (\"threads\", \"youtube\")\n\n\ndef rehearsals_not_here(serial, names):\n    \"\"\"The rehearsals this phone cannot walk, by name.\"\"\"\n    wanted = [name for name in names if name.startswith(ANDROID_ONLY_REHEARSALS)]\n    if not wanted:\n        return set()\n    if is_iphone(serial):\n        return set(wanted)\n    needing = [name for name in wanted if name.split(\"/\", 1)[0] in NEEDS_THE_APP]\n    if not needing:\n        return set()\n    try:\n        installed = parse_app_versions(shell(serial, APPS_COMMAND, timeout=30))\n    except Exception as failure:  # Not known: walk them, and a broken one says why.\n        log(\"Could not read which apps are on %s: %s\" % (serial, short_words(failure)))\n        return set()\n    return set(name for name in needing if name.split(\"/\", 1)[0] not in installed)\n\n\ndef action_self_test(serial, args, walk, rehearsals=None):\n    \"\"\"Walks every action in REHEARSALS up to just before its last button.\n\n    A rehearsal that cannot find a step is that action broken. The pictures\n    of a broken one are all kept, so the step it stopped at can be seen;\n    a passed one keeps only its last. Promo may send arguments for some, as\n    {\"rehearsals\": {name: args}}, such as a post to rehearse a comment on.\n    \"\"\"\n    rehearsals = rehearsal_args(rehearsals or REHEARSALS, (args or {}).get(\"rehearsals\"))\n    not_here = rehearsals_not_here(serial, rehearsals)\n    lines = []\n    for name in sorted(rehearsals):\n        if name in not_here:\n            continue\n        walk.check()\n        rehearsal = Walk(serial, rehearse=True, cancelled=walk.cancelled, connect=walk.connect)\n        rehearsal.device = walk.device\n        try:\n            ACTIONS[name](serial, dict(rehearsals[name]), rehearsal)\n            lines.append({\"action\": name, \"passed\": True, \"step\": \"\", \"error\": \"\"})\n            kept = rehearsal.steps[-1:]\n        except Cancelled:\n            raise\n        except StepFailed as failure:\n            lines.append({\"action\": name, \"passed\": False, \"step\": failure.step, \"error\": str(failure)})\n            kept = rehearsal.steps\n        except Exception as failure:  # Anything else is broken too, at the step it was on.\n            lines.append({\"action\": name, \"passed\": False, \"step\": rehearsal.current, \"error\": str(failure) or failure.__class__.__name__})\n            kept = rehearsal.steps\n        walk.device = rehearsal.device\n        walk.steps.extend((\"%s: %s\" % (name, step), jpeg) for step, jpeg in kept)\n        walk.home()\n    return {\"actions\": lines}\n\n\ndef medium_state(serial, args, walk):\n    \"\"\"Who the Medium app is signed in as, and its followers, off its own\n    profile. When Medium joined it is not shown in the app, so Promo reads it\n    from the account's public page in the reader browser instead.\"\"\"\n    try:\n        walk.screen().screen_on()\n        reading = read_app_profile(serial, walk, \"medium\")\n        walk.home()\n    except Cancelled:\n        raise\n    except Exception as failure:  # Not checked rather than signed out.\n        log(\"Could not read who is signed in to Medium on %s: %s\" % (serial, failure))\n        return {\"checked\": False, \"handle\": None, \"blocked\": False, \"reason\": \"\", \"joinedSeconds\": None, \"followers\": None}\n    return {\"checked\": True, \"handle\": reading[\"handle\"], \"blocked\": False, \"reason\": \"\", \"joinedSeconds\": None, \"followers\": reading[\"followers\"]}\n\n\nMEDIUM_STORY_ID = re.compile(r\"^[0-9a-f]{8,16}$\")\n\n\ndef action_medium_respond(serial, args, walk):\n    \"\"\"Writes one response under a story in the Medium app, inside a visit.\n\n    Before: a little of the app's home feed. Then the story by its link, read\n    for a while, the responses button, the box, the words typed with a\n    person's rhythm, and Respond pressed once. It counts as sent when the\n    words show on screen. Medium's id for the response is not shown in the\n    app, so it is \"\" here and Promo finds it from the reader browser, by the\n    account's name and the opening words. A highlighted line is a browser\n    step and is refused before anything opens.\n\n    In a rehearsal nothing is typed: the story opens, the box opens, Respond\n    is found and not pressed, and the screen is left. With no story sent, a\n    rehearsal only opens the app.\n    \"\"\"\n    story_id = str(args.get(\"storyId\") or \"\").strip()\n    text = str(args.get(\"text\") or \"\").strip()\n    if str(args.get(\"line\") or \"\").strip():\n        raise RuntimeError(\"respond: answering one highlighted line is done in a browser, not the Medium app\")\n    if story_id and not MEDIUM_STORY_ID.match(story_id):\n        raise RuntimeError(\"respond: that is not a Medium story id\")\n    if not walk.rehearse and (not story_id or not text):\n        raise RuntimeError(\"respond: a response needs its story and its words\")\n    device = walk.screen()\n    device.screen_on()\n    screens = app_screens(serial, \"medium\")\n    package = package_for(serial, \"medium\")\n    visit = new_visit()\n\n    if not walk.rehearse:\n        started = time.monotonic()\n        try:\n            open_app(serial, \"medium\")\n            walk.shot(\"Opened Medium\")\n            browse_app_feed(serial, walk, random.uniform(*APP_READ_FEED_SECONDS))\n        except Cancelled:\n            raise\n        except Exception as failure:  # The response still goes.\n            visit[\"problems\"].append(\"the feed before: %s\" % short_words(failure))\n        visit[\"beforeSeconds\"] = int(time.monotonic() - started)\n\n    if not story_id:\n        open_app(serial, \"medium\")\n        walk.shot(\"Opened Medium\")\n        walk.home()\n        return {\"responseId\": \"\", \"responseUrl\": \"\"}\n\n    walk.check()\n    open_link(serial, \"medium\", \"https://medium.com/p/%s\" % story_id)\n    walk.shot(\"Opened the story\")\n    if not walk.rehearse:\n        read_post(serial, walk, len(\" \".join(screen_lines(device.dump_hierarchy(), app_packages(\"medium\")))), visit)\n    walk.tap_first(\"Open the responses\", selectors=screens[\"responses\"])\n    time.sleep(2)\n    box = walk.find_first(\"Find the response box\", selectors=screens[\"response_box\"])\n    before = 0\n    if not walk.rehearse:\n        before = times_shown(device.dump_hierarchy(), package, text)\n        walk.press(box)\n        gaps = type_like_a_person(serial, device, text, walk.check)\n        walk.shot(\"Typed the response\")\n        log(\"medium response typed: %d characters, gaps %.2f to %.2f seconds\" % (len(text), min(gaps or [0]), max(gaps or [0])))\n        time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n    pressed = walk.final_first(\"Press Respond\", selectors=screens[\"respond\"])\n    if not pressed:\n        leave_app_screen(serial, walk, \"medium\", times=3)\n        walk.home()\n        return {\"responseId\": \"\", \"responseUrl\": \"\"}\n    waiting_until = time.time() + POST_LANDED_SECONDS\n    shown = False\n    while time.time() < waiting_until:\n        time.sleep(1)\n        try:\n            if times_shown(device.dump_hierarchy(), package, text) > before:\n                shown = True\n                break\n        except Exception:  # A screen caught mid-change; look again.\n            continue\n    walk.shot(\"Looked for the response\")\n    if not shown:\n        raise RuntimeError(\"respond: Respond was pressed but the words did not show within %d seconds. It may already be on Medium; look before sending again.\" % POST_LANDED_SECONDS)\n    try:\n        browse_app_feed(serial, walk, random.uniform(*APP_FEED_AFTER_SECONDS))\n    except Cancelled:\n        raise\n    except Exception as failure:  # It is on Medium already.\n        visit[\"problems\"].append(\"the feed after: %s\" % short_words(failure))\n    walk.home()\n    return {\"responseId\": \"\", \"responseUrl\": \"\", \"visit\": visit}\n\n\ndef action_medium_warm_up(serial, args, walk):\n    \"\"\"A warming account's day in the Medium app: its home feed read for a few\n    minutes. Nothing is written, clapped, highlighted or followed from a phone.\"\"\"\n    walk.screen().screen_on()\n    open_app(serial, \"medium\")\n    walk.shot(\"Opened Medium\")\n    if walk.rehearse:\n        walk.home()\n        return {\"storiesRead\": 0, \"followed\": [], \"problems\": []}\n    browse_app_feed(serial, walk, random.uniform(150, 360))\n    walk.home()\n    return {\"storiesRead\": 0, \"followed\": [], \"problems\": []}\n\n\nREHEARSALS.update({\n    \"medium/state\": {},\n    \"medium/respond\": {\"storyId\": \"\", \"text\": \"\", \"line\": \"\", \"tags\": []},\n})\n\n\n# ---------------------------------------------------------------------------\n# X's app (X task, part 2). The phone answers the same routine names as the\n# browser (src/server/social/x/calls.ts) with the same answers, so Promo does\n# not care where an X account runs. X's id for a reply or a post is not shown\n# in the app after it is sent, so it is \"\" here and Promo looks it up through\n# a search account, as Medium's reader does for a response. A community post\n# or a poll is made in a browser only, and is refused before anything opens.\n# Direct messages go through the shared inbox steps, as Instagram's and\n# TikTok's do: x/inbox reads them and x/reply_message answers one (x/reply\n# is the reply under a post). The phone's x/inbox answers in the shared\n# inbox's shape, conversations and their lines, not the browser's list of\n# messages, so Promo reads a phone account's messages through the phone\n# inbox code only. None of this has run on a real phone yet.\n\nX_POST_ID = re.compile(r\"^\\d{1,25}$\")\nX_HANDLE = re.compile(r\"^[A-Za-z0-9_]{1,15}$\")\n# \"Joined March 2021\" on the account's own profile.\nX_JOINED = re.compile(r\"(?i)^joined\\s+([a-z]+)\\s+(\\d{4})$\")\nMONTHS = (\"jan\", \"feb\", \"mar\", \"apr\", \"may\", \"jun\", \"jul\", \"aug\", \"sep\", \"oct\", \"nov\", \"dec\")\nX_POSTED = (\"your post was sent\", \"your reply was sent\", \"your post was posted\", \"post sent\", \"reply sent\")\nX_POST_FAILED = (\"couldn't be sent\", \"could not be sent\", \"couldn't send your\", \"failed to send\", \"you already said that\", \"over the daily limit\")\nX_NOT_CHECKED = {\"checked\": False, \"handle\": None, \"blocked\": False, \"reason\": \"\", \"banScreen\": None, \"joinedSeconds\": None, \"followers\": None}\nX_BAN_WORDS = {\"suspended\": \"suspended\", \"locked\": \"locked or limited\", \"confirm\": \"asking to confirm it's you\"}\n\n\ndef x_joined_seconds(hierarchy_xml):\n    \"\"\"When the account joined, as the first of the month its profile names, in seconds. None when not shown.\"\"\"\n    for line in screen_lines(hierarchy_xml, app_packages(\"x\")):\n        found = X_JOINED.match(line.strip())\n        if found and found.group(1).lower()[:3] in MONTHS:\n            month = MONTHS.index(found.group(1).lower()[:3]) + 1\n            return float(calendar.timegm((int(found.group(2)), month, 1, 0, 0, 0)))\n    return None\n\n\ndef read_x_profile(serial, walk):\n    \"\"\"Opens X on the account's own profile, through the menu behind its\n    picture, and reads the handle, the followers and when it joined. A ban\n    screen in the way is read instead. Leaves the profile open.\"\"\"\n    empty = {\"handle\": None, \"followers\": None, \"joinedSeconds\": None, \"ban\": None}\n    open_app(serial, \"x\")\n    walk.shot(\"Opened X\")\n    device = walk.screen()\n    hierarchy = device.dump_hierarchy()\n    ban = ban_screen_in(hierarchy, \"x\", package_for(serial, \"x\"))\n    # An unknown line asks a person after the action (run_action); this\n    # reading would stop the account for good without asking.\n    if ban and ban[\"kind\"] != \"unknown\":\n        return dict(empty, ban=ban)\n    if signed_out(hierarchy, \"x\"):\n        return empty\n    screens = app_screens(serial, \"x\")\n    walk.tap_first(\"Open the account menu\", selectors=screens[\"drawer\"])\n    time.sleep(1.5)\n    walk.tap_first(\"Open the profile\", selectors=screens[\"profile_entry\"])\n    time.sleep(2)\n    hierarchy = device.dump_hierarchy()\n    reading = app_profile_from_screen(hierarchy, \"x\")\n    walk.shot(\"Read the profile\")\n    return {\"handle\": reading[\"handle\"], \"followers\": reading[\"followers\"], \"joinedSeconds\": x_joined_seconds(hierarchy), \"ban\": None}\n\n\ndef action_x_state(serial, args, walk):\n    \"\"\"Who the X app is signed in as, its followers and when it joined, off\n    its own profile; asked after every X job too, as x/quick_state. A lock\n    or suspended screen is answered as blocked, with X's own words. An app\n    that cannot be read says \"not checked\", so a failed look is never written\n    down as signed out; a rehearsal that cannot read it is broken.\"\"\"\n    try:\n        walk.screen().screen_on()\n        reading = read_x_profile(serial, walk)\n        walk.home()\n    except Cancelled:\n        raise\n    except Exception as failure:  # Not checked rather than signed out.\n        if walk.rehearse:\n            raise\n        log(\"Could not read who is signed in to X on %s: %s\" % (serial, failure))\n        return dict(X_NOT_CHECKED)\n    ban = reading[\"ban\"]\n    return {\n        \"checked\": True,\n        \"handle\": reading[\"handle\"],\n        \"blocked\": bool(ban),\n        \"reason\": \"X shows the account %s\" % X_BAN_WORDS.get(ban[\"kind\"], \"stopped\") if ban else \"\",\n        \"banScreen\": ban[\"words\"] if ban else None,\n        \"joinedSeconds\": reading[\"joinedSeconds\"],\n        \"followers\": reading[\"followers\"],\n    }\n\n\n# Said by every error after Post or Reply was pressed, so nobody sends twice blind.\nX_MAY_BE_SENT = \"It may already be on X; look before sending again.\"\n\n\ndef x_lines(hierarchy_xml):\n    \"\"\"The X app's own lines on screen, kept from before a press so the\n    lines after it can be told apart.\"\"\"\n    return set(screen_lines(hierarchy_xml, app_packages(\"x\")))\n\n\ndef x_landed(hierarchy_xml, package, text, before, shown_before=()):\n    \"\"\"What the screen says after Post or Reply was pressed: (\"sent\", \"\"),\n    (\"failed\", X's words), or (\"\", \"\") while neither shows. Only lines that\n    were not on screen before the press are read, so the post being answered\n    saying \"couldn't be sent\" is not X's notice. The words showing more times\n    than before also count as sent.\"\"\"\n    fresh = [plain(line) for line in screen_lines(hierarchy_xml, app_packages(\"x\")) if line not in shown_before]\n    failed = next((line for line in fresh if any(phrase in line for phrase in X_POST_FAILED)), None)\n    if failed:\n        return \"failed\", failed\n    if any(phrase in line for line in fresh for phrase in X_POSTED) or (text and times_shown(hierarchy_xml, package, text) > before):\n        return \"sent\", \"\"\n    return \"\", \"\"\n\n\ndef x_wait_landed(walk, package, text, before, verb, shown_before=()):\n    \"\"\"Waits for X to say the post went. A failure X names fails the job; True once sent; False when nothing showed in time.\"\"\"\n    device = walk.screen()\n    waiting_until = time.time() + POST_LANDED_SECONDS\n    while time.time() < waiting_until:\n        time.sleep(1)\n        try:\n            state, words = x_landed(device.dump_hierarchy(), package, text, before, shown_before)\n        except Exception:  # A screen caught mid-change; look again.\n            continue\n        if state == \"failed\":\n            walk.shot(\"X said it failed\")\n            raise RuntimeError(\"%s: X said it did not go: %s. %s\" % (verb, words, X_MAY_BE_SENT))\n        if state == \"sent\":\n            walk.shot(\"Looked for the post\")\n            return True\n    walk.shot(\"Looked for the post\")\n    return False\n\n\ndef x_after_press(verb, look):\n    \"\"\"Runs the look after Post or Reply was pressed. Whatever fails in it\n    says the words may be on X already.\"\"\"\n    try:\n        return look()\n    except Cancelled:\n        raise\n    except Exception as failure:\n        words = str(failure) or failure.__class__.__name__\n        if \"It may already be on X\" in words:\n            raise\n        raise RuntimeError(\"%s: %s. %s\" % (verb, words.rstrip(\".\"), X_MAY_BE_SENT))\n\n\ndef x_words_under(hierarchy_xml, package, text):\n    \"\"\"True when one of the app's views shows exactly these words, the text\n    box left out: our reply is under the post already. Only the whole words\n    count, so a \"Yes\" of ours is never found inside somebody's longer post.\"\"\"\n    wanted = plain(\" \".join(text.split())).rstrip(\".\")\n    if not wanted:\n        return False\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        if not own_node(node, package) or is_text_box(node):\n            continue\n        for key in (\"text\", \"content-desc\", \"label\"):\n            if plain(\" \".join((node.get(key) or \"\").split())).rstrip(\".\") == wanted:\n                return True\n    return False\n\n\ndef x_on_profile(serial, walk, package, text):\n    \"\"\"The account's own profile looked at for the words, since a quote or a\n    post of its own does not show where it was written. False when the\n    profile could not be reached.\"\"\"\n    screens = app_screens(serial, \"x\")\n    try:\n        open_app(serial, \"x\")\n        walk.tap_first(\"Open the account menu\", timeout=5, selectors=screens[\"drawer\"])\n        time.sleep(1.5)\n        walk.tap_first(\"Open the profile\", timeout=5, selectors=screens[\"profile_entry\"])\n        time.sleep(2)\n        found = times_shown(walk.screen().dump_hierarchy(), package, text) > 0\n        walk.shot(\"Looked on the profile\")\n        return found\n    except StepFailed:\n        return False\n\n\ndef x_feed_before(serial, walk, visit):\n    \"\"\"A little of the home feed before a reply or a quote, which never stops it.\"\"\"\n    started = time.monotonic()\n    try:\n        open_app(serial, \"x\")\n        walk.shot(\"Opened X\")\n        browse_app_feed(serial, walk, random.uniform(*APP_READ_FEED_SECONDS))\n    except Cancelled:\n        raise\n    except Exception as failure:  # The reply still goes.\n        visit[\"problems\"].append(\"the feed before: %s\" % short_words(failure))\n    visit[\"beforeSeconds\"] = int(time.monotonic() - started)\n\n\ndef x_feed_after(serial, walk, visit):\n    \"\"\"A little scrolling after the press, which can never fail what is already on X.\"\"\"\n    started = time.monotonic()\n    try:\n        go_back(serial)\n        time.sleep(1.5)\n        browse_app_feed(serial, walk, random.uniform(*APP_FEED_AFTER_SECONDS))\n    except Exception as failure:  # Includes a cancel: it is on X either way.\n        visit[\"problems\"].append(\"the feed after: %s\" % short_words(failure))\n    visit[\"afterSeconds\"] = int(time.monotonic() - started)\n\n\ndef x_open_post(serial, walk, post_id):\n    \"\"\"Opens a post by its link in the app. With no post (a rehearsal when\n    Promo found none lately) the first post of the home feed is opened.\"\"\"\n    walk.check()\n    if post_id:\n        open_link(serial, \"x\", \"https://x.com/i/status/%s\" % post_id)\n        walk.shot(\"Opened the post\")\n        return\n    open_app(serial, \"x\")\n    walk.shot(\"Opened X\")\n    if not open_feed_post(serial, walk, \"x\"):\n        raise StepFailed(\"Open a post\", \"No post was on X's home feed to open.\")\n\n\ndef x_put_picture(serial, walk, url):\n    \"\"\"Puts the post's picture on the phone, as Instagram's post does: into the\n    camera folder on an Android, into Photos through a one-time Safari link\n    on an iPhone. It is then the newest item the post box's picker shows.\"\"\"\n    if is_iphone(serial):\n        save_from_safari(serial, walk, url)\n        return\n    data, extension = download_media(url)\n    put_in_gallery(serial, data, extension)\n    walk.shot(\"Put the picture in the gallery\")\n\n\ndef x_fill(serial, walk, screens, text, picture):\n    \"\"\"In an open post box: the picture first, when one was put on the phone,\n    then the words typed with a person's rhythm. A rehearsal only finds the box.\"\"\"\n    device = walk.screen()\n    box = walk.find_first(\"Find the post box\", selectors=screens[\"composer_box\"])\n    if walk.rehearse:\n        return\n    if picture:\n        walk.tap_first(\"Open the photos\", selectors=screens[\"media\"])\n        time.sleep(2)\n        walk.tap_first(\"Pick the newest picture\", selectors=screens[\"media_first\"])\n        time.sleep(1.5)\n        try:\n            walk.tap_first(\"Add the picture\", timeout=4, selectors=screens[\"media_done\"])\n            time.sleep(1.5)\n        except StepFailed:\n            pass  # Added on the pick on this version.\n        box = walk.find_first(\"Find the post box\", selectors=screens[\"composer_box\"])\n    if text:\n        walk.press(box)\n        gaps = type_like_a_person(serial, device, text, walk.check)\n        walk.shot(\"Typed the words\")\n        log(\"x words typed: %d characters, gaps %.2f to %.2f seconds\" % (len(text), min(gaps or [0]), max(gaps or [0])))\n    time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n\n\ndef x_reply_under(serial, walk, post_id, text, picture, verb):\n    \"\"\"One reply under a post, Reply pressed once. A reply of the account's\n    own (verb \"reply\") is a visit: the home feed first, the post read for a\n    while. A thread's next piece (verb \"publish\") goes straight on. Words of\n    ours already under the post (an earlier try that went out without saying\n    so) count as sent, and nothing is typed.\"\"\"\n    device = walk.screen()\n    device.screen_on()\n    screens = app_screens(serial, \"x\")\n    package = package_for(serial, \"x\")\n    visit = new_visit()\n    if verb == \"reply\" and not walk.rehearse:\n        x_feed_before(serial, walk, visit)\n    before = 0\n    shown = set()\n    try:\n        x_open_post(serial, walk, post_id)\n        hierarchy = device.dump_hierarchy()\n        if signed_out(hierarchy, \"x\"):\n            raise RuntimeError(\"%s: the app is not signed in to X\" % verb)\n        if verb == \"reply\" and not walk.rehearse:\n            read_post(serial, walk, len(\" \".join(screen_lines(hierarchy, app_packages(\"x\")))), visit)\n        if not walk.rehearse:\n            hierarchy = device.dump_hierarchy()\n            if x_words_under(hierarchy, package, text):\n                walk.shot(\"Our words are under the post already\")\n                walk.home()\n                return {\"postId\": \"\", \"url\": \"\", \"visit\": visit}\n            before = times_shown(hierarchy, package, text)\n            shown = x_lines(hierarchy)\n        walk.tap_first(\"Open the reply box\", selectors=screens[\"reply_open\"])\n        time.sleep(2)\n        x_fill(serial, walk, screens, text, picture)\n        shown |= x_lines(device.dump_hierarchy())\n        pressed = walk.final_first(\"Press Reply\", selectors=screens[\"post_button\"])\n    except Cancelled:\n        raise\n    except Exception:\n        # Stopped before the last button: the draft is thrown away and nothing was sent.\n        if not walk.rehearse:\n            leave_app_screen(serial, walk, \"x\", times=3)\n        raise\n    finally:\n        if walk.rehearse:\n            leave_app_screen(serial, walk, \"x\", times=3)\n    if not pressed:\n        walk.home()\n        return {\"postId\": \"\", \"url\": \"\"}\n    if not x_after_press(verb, lambda: x_wait_landed(walk, package, text, before, verb, shown)):\n        raise RuntimeError(\"%s: Reply was pressed but X did not say it was sent, and the words did not show within %d seconds. %s\" % (verb, POST_LANDED_SECONDS, X_MAY_BE_SENT))\n    x_feed_after(serial, walk, visit)\n    walk.home()\n    return {\"postId\": \"\", \"url\": \"\", \"visit\": visit}\n\n\ndef action_x_reply(serial, args, walk):\n    \"\"\"Writes one reply under a post in the X app, inside a visit: a little\n    home feed, the post by its link, read for a while, the reply box, the\n    words typed with a person's rhythm, and Reply pressed once. It counts as\n    sent when X says so or the words show under the post. Its id is \"\".\n\n    In a rehearsal nothing is typed: the post opens (the feed's first post\n    when none was sent), the box opens, Reply is found and not pressed, and\n    the box is left.\n    \"\"\"\n    post_id = str(args.get(\"replyToId\") or \"\").strip()\n    text = str(args.get(\"text\") or \"\").strip()\n    if post_id and not X_POST_ID.match(post_id):\n        raise RuntimeError(\"reply: that is not an X post id\")\n    if not walk.rehearse and (not post_id or not text):\n        raise RuntimeError(\"reply: a reply needs its post and its words\")\n    return x_reply_under(serial, walk, post_id, text, False, \"reply\")\n\n\ndef action_x_quote(serial, args, walk):\n    \"\"\"One quote post of somebody's post, inside a visit: a little home feed,\n    the post by its link, read, Repost, Quote, the words typed, and Post\n    pressed once. A quote does not show under the post it quotes, so it\n    counts as sent when X says so, or failing that when the words are on the\n    account's own profile. Its id is \"\".\n\n    In a rehearsal nothing is typed and Post is found, not pressed.\n    \"\"\"\n    post_id = str(args.get(\"postId\") or \"\").strip()\n    text = str(args.get(\"text\") or \"\").strip()\n    if post_id and not X_POST_ID.match(post_id):\n        raise RuntimeError(\"quote: that is not an X post id\")\n    if not walk.rehearse and (not post_id or not text):\n        raise RuntimeError(\"quote: a quote needs its post and its words\")\n    device = walk.screen()\n    device.screen_on()\n    screens = app_screens(serial, \"x\")\n    package = package_for(serial, \"x\")\n    visit = new_visit()\n    if not walk.rehearse:\n        x_feed_before(serial, walk, visit)\n    try:\n        x_open_post(serial, walk, post_id)\n        hierarchy = device.dump_hierarchy()\n        if signed_out(hierarchy, \"x\"):\n            raise RuntimeError(\"quote: the app is not signed in to X\")\n        shown = x_lines(hierarchy)\n        if not walk.rehearse:\n            read_post(serial, walk, len(\" \".join(screen_lines(hierarchy, app_packages(\"x\")))), visit)\n        walk.tap_first(\"Open Repost\", selectors=screens[\"repost\"])\n        time.sleep(1.5)\n        walk.tap_first(\"Pick Quote\", selectors=screens[\"quote\"])\n        time.sleep(2)\n        x_fill(serial, walk, screens, text, False)\n        shown |= x_lines(device.dump_hierarchy())\n        pressed = walk.final_first(\"Press Post\", selectors=screens[\"post_button\"])\n    except Cancelled:\n        raise\n    except Exception:\n        if not walk.rehearse:\n            leave_app_screen(serial, walk, \"x\", times=3)\n        raise\n    finally:\n        if walk.rehearse:\n            leave_app_screen(serial, walk, \"x\", times=3)\n    if not pressed:\n        walk.home()\n        return {\"postId\": \"\", \"url\": \"\"}\n    if not x_after_press(\"quote\", lambda: x_wait_landed(walk, package, text, 0, \"quote\", shown) or x_on_profile(serial, walk, package, text)):\n        raise RuntimeError(\"quote: Post was pressed but X did not say it was sent, and the words are not on the profile. %s\" % X_MAY_BE_SENT)\n    x_feed_after(serial, walk, visit)\n    walk.home()\n    return {\"postId\": \"\", \"url\": \"\", \"visit\": visit}\n\n\ndef action_x_publish(serial, args, walk):\n    \"\"\"One post of the account's own: the first of a thread from X's New post\n    button, or a later piece under `replyToId`, the piece before it. A picture\n    from `pictureUrl` is put on the phone first and picked in the post box.\n    Post or Reply is pressed once; it counts as sent when X says so or the\n    words show, under the piece before or on the profile. Its id is \"\".\n\n    A community post or a poll is made in a browser, and is refused here\n    before anything opens. In a rehearsal no picture is fetched, nothing is\n    typed, and Post is found, not pressed.\n    \"\"\"\n    text = str(args.get(\"text\") or \"\").strip()\n    picture = str(args.get(\"pictureUrl\") or \"\").strip()\n    reply_to = str(args.get(\"replyToId\") or \"\").strip()\n    if str(args.get(\"communityId\") or \"\").strip():\n        raise RuntimeError(\"publish: a post into a community is made in a browser, not the X app\")\n    if args.get(\"poll\"):\n        raise RuntimeError(\"publish: a poll is made in a browser, not the X app\")\n    if reply_to and not X_POST_ID.match(reply_to):\n        raise RuntimeError(\"publish: that is not an X post id\")\n    if not walk.rehearse and not text and not picture:\n        raise RuntimeError(\"publish: a post needs its words or a picture\")\n    device = walk.screen()\n    device.screen_on()\n    has_picture = bool(picture) and not walk.rehearse\n    if has_picture:\n        x_put_picture(serial, walk, picture)\n    if reply_to:\n        return x_reply_under(serial, walk, reply_to, text, has_picture, \"publish\")\n    screens = app_screens(serial, \"x\")\n    package = package_for(serial, \"x\")\n    visit = new_visit()\n    try:\n        open_app(serial, \"x\")\n        walk.shot(\"Opened X\")\n        hierarchy = device.dump_hierarchy()\n        if signed_out(hierarchy, \"x\"):\n            raise RuntimeError(\"publish: the app is not signed in to X\")\n        shown = x_lines(hierarchy)\n        walk.tap_first(\"Open a new post\", selectors=screens[\"new_post\"])\n        time.sleep(2)\n        try:\n            walk.find_first(\"Find the post box\", timeout=4, selectors=screens[\"composer_box\"])\n        except StepFailed:\n            # On some versions the button first opens a small menu, and a\n            # second press of it opens the post box.\n            walk.tap_first(\"Open a new post again\", selectors=screens[\"new_post\"])\n            time.sleep(2)\n        x_fill(serial, walk, screens, text, has_picture)\n        shown |= x_lines(device.dump_hierarchy())\n        pressed = walk.final_first(\"Press Post\", selectors=screens[\"post_button\"])\n    except Cancelled:\n        raise\n    except Exception:\n        if not walk.rehearse:\n            leave_app_screen(serial, walk, \"x\", times=3)\n        raise\n    finally:\n        if walk.rehearse:\n            leave_app_screen(serial, walk, \"x\", times=3)\n    if not pressed:\n        walk.home()\n        return {\"postId\": \"\", \"url\": \"\"}\n    if not x_after_press(\"publish\", lambda: x_wait_landed(walk, package, text, 0, \"publish\", shown) or (text and x_on_profile(serial, walk, package, text))):\n        raise RuntimeError(\"publish: Post was pressed but X did not say it was sent, and the words are not on the profile. %s\" % X_MAY_BE_SENT)\n    x_feed_after(serial, walk, visit)\n    walk.home()\n    return {\"postId\": \"\", \"url\": \"\", \"visit\": visit}\n\n\ndef x_follow_state(hierarchy_xml, handle, button_id=\"\"):\n    \"\"\"What a profile's Follow button says: \"following\", \"pending\" (a\n    protected account was asked, as the browser counts it too), \"follow\", or\n    \"\" when none shows. Only the button counts: by its description naming the\n    handle (\"Following @sam\"), or by its view id, never a bare \"Following\",\n    which is also the count beside it. A bare \"Pending\" is the button: no\n    count on a profile is called that.\"\"\"\n    wanted = (handle or \"\").lower()\n    state = \"\"\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        if not own_node(node, app_packages(\"x\")):\n            continue\n        on_button = bool(button_id) and bool(re.match(button_id, node.get(\"resource-id\") or \"\"))\n        for key in (\"text\", \"content-desc\", \"label\"):\n            words = plain(\" \".join((node.get(key) or \"\").split())).rstrip(\".\")\n            if not words:\n                continue\n            if words in (\"following @%s\" % wanted, \"unfollow @%s\" % wanted) or (on_button and words == \"following\"):\n                return \"following\"\n            if words in (\"pending\", \"pending @%s\" % wanted):\n                return \"pending\"\n            if words in (\"follow @%s\" % wanted, \"follow back @%s\" % wanted) or (on_button and words in (\"follow\", \"follow back\")):\n                state = \"follow\"\n    return state\n\n\ndef action_x_follow(serial, args, walk):\n    \"\"\"Follows one account from its profile, opened by its link: Follow\n    pressed once, then Following looked for, or Pending for a protected\n    account, which counts as done. An account already followed, or asked, is\n    done with no press. A rehearsal finds Follow and never presses it; with\n    no handle sent it only opens the app.\"\"\"\n    handle = str(args.get(\"handle\") or \"\").strip().lstrip(\"@\")\n    if handle and not X_HANDLE.match(handle):\n        raise RuntimeError(\"follow: that is not an X handle\")\n    if not walk.rehearse and not handle:\n        raise RuntimeError(\"follow: a follow needs the account's handle\")\n    device = walk.screen()\n    device.screen_on()\n    screens = app_screens(serial, \"x\")\n    package = package_for(serial, \"x\")\n    if not handle:\n        open_app(serial, \"x\")\n        walk.shot(\"Opened X\")\n        walk.home()\n        return {\"done\": False}\n    walk.check()\n    open_link(serial, \"x\", \"https://x.com/%s\" % handle)\n    walk.shot(\"Opened the profile\")\n    hierarchy = device.dump_hierarchy()\n    if signed_out(hierarchy, \"x\"):\n        raise RuntimeError(\"follow: the app is not signed in to X\")\n    if x_follow_state(hierarchy, handle, screens[\"follow_button_id\"]) in (\"following\", \"pending\"):\n        walk.home()\n        return {\"done\": True}\n    buttons = shapes(package, \"(?i)^follow @%s\\\\.?$\" % handle)\n    if screens[\"follow_button_id\"]:\n        buttons.append({\"resourceIdMatches\": screens[\"follow_button_id\"], \"textMatches\": \"(?i)^(follow|follow back)$\", \"packageName\": package})\n    buttons += shapes(package, \"(?i)^(follow|follow back)$\")\n    if not walk.final_first(\"Press Follow\", selectors=buttons):\n        walk.home()\n        return {\"done\": False}\n    followed = False\n    waiting_until = time.time() + POST_LANDED_SECONDS\n    while time.time() < waiting_until:\n        time.sleep(1)\n        try:\n            if x_follow_state(device.dump_hierarchy(), handle, screens[\"follow_button_id\"]) in (\"following\", \"pending\"):\n                followed = True\n                break\n        except Exception:  # A screen caught mid-change; look again.\n            continue\n    walk.shot(\"Looked for Following\")\n    if not followed:\n        raise RuntimeError(\"follow: Follow was pressed but X did not show Following within %d seconds. Look at the profile before following again.\" % POST_LANDED_SECONDS)\n    try:\n        browse_app_feed(serial, walk, random.uniform(*APP_FEED_AFTER_SECONDS))\n    except Exception as failure:  # The follow stands either way.\n        log(\"The feed after following on %s: %s\" % (serial, short_words(failure)))\n    walk.home()\n    return {\"done\": True}\n\n\ndef action_x_warm_up(serial, args, walk):\n    \"\"\"A warming account's day in the X app: its home feed read for a few\n    minutes. Nothing is written, liked, reposted or followed from a phone,\n    and the browser's search or two on the topic is left out.\"\"\"\n    walk.screen().screen_on()\n    open_app(serial, \"x\")\n    walk.shot(\"Opened X\")\n    if walk.rehearse:\n        walk.home()\n        return {\"postsRead\": 0, \"problems\": []}\n    browse_app_feed(serial, walk, random.uniform(150, 360))\n    walk.home()\n    return {\"postsRead\": 0, \"problems\": []}\n\n\n# X's rehearsals. The reply, the quote and the follow open what Promo sends\n# (an X post found in the last week, and its writer); without one, the reply\n# and the quote open the home feed's first post and the follow only opens\n# the app. x/quick_state is x/state's own step, so it is walked once.\nREHEARSALS.update({\n    \"x/state\": {},\n    \"x/reply\": {\"replyToId\": \"\", \"text\": \"\"},\n    \"x/quote\": {\"postId\": \"\", \"text\": \"\"},\n    \"x/publish\": {\"text\": \"\", \"pictureUrl\": \"\", \"replyToId\": \"\", \"communityId\": \"\", \"poll\": None},\n    \"x/follow\": {\"handle\": \"\"},\n    \"x/warm_up\": {\"words\": []},\n    \"x/inbox\": {\"kind\": \"message\", \"via\": \"inbox\", \"handle\": \"\"},\n    \"x/reply_message\": {\"kind\": \"message\", \"thread\": \"\", \"author\": \"\", \"quote\": \"\", \"text\": \"\"},\n})\n\n\n# ---------------------------------------------------------------------------\n# LinkedIn's app (LinkedIn task, part 2). The phone answers the same routine\n# names as the browser (src/server/social/linkedin/calls.ts) with the same\n# answers, so Promo does not care where a LinkedIn account runs. LinkedIn's id\n# for a comment or a post is not shown in the app after it is sent, so it is\n# \"\" here and Promo looks it up through a search account (linkedin/find_own).\n# A poll, a video, a repost, a group post, tags and anything as a company page\n# are made in a browser only, and are refused before anything opens. The\n# app's state reads the member's slug off the profile's own address, copied\n# from its More menu, because the app shows the name and never the address.\n# Messages go through the shared inbox steps, as X's do: linkedin/inbox reads\n# them and linkedin/reply_message answers one. None of this has run on a real\n# phone yet.\n\nLINKEDIN_POST_ID = re.compile(r\"^\\d{10,25}$\")\nLINKEDIN_COMMENT_ID = re.compile(r\"^\\d{5,40}$\")\nLINKEDIN_SLUG = re.compile(r\"^[\\w-]{3,100}$\", re.UNICODE)\nLINKEDIN_PROFILE_ADDRESS = re.compile(r\"linkedin\\.com/in/([^/?#\\s]+)\", re.IGNORECASE)\nLINKEDIN_FOLLOWERS = re.compile(r\"(?i)^([\\d,.]+\\s*[km]?)\\+?\\s+followers?$\")\nLINKEDIN_POSTED = (\"post successful\", \"your post was shared\", \"posted\", \"comment posted\", \"your comment was posted\", \"reply posted\")\nLINKEDIN_POST_FAILED = (\"couldn't be posted\", \"could not be posted\", \"couldn't post\", \"couldn't be shared\", \"something went wrong\", \"failed to post\")\nLINKEDIN_CODE_WORDS = (\"enter the code\", \"enter code\", \"we sent a code\", \"verification code\", \"enter the 6-digit code\", \"check your email\")\nLINKEDIN_PREMIUM_WORDS = (\"premium\", \"premium member\", \"linkedin premium member\")\nLINKEDIN_NOT_CHECKED = {\n    \"checked\": False, \"slug\": None, \"name\": \"\", \"blocked\": False, \"reason\": \"\", \"banScreen\": None,\n    \"codeAsked\": False, \"pages\": None, \"premium\": None, \"followers\": None,\n}\nLINKEDIN_BAN_WORDS = {\"restricted\": \"restricted\", \"confirm\": \"asking to verify it's you\"}\n# Said by every error after Post or Send was pressed, so nobody sends twice blind.\nLINKEDIN_MAY_BE_SENT = \"It may already be on LinkedIn; look before sending again.\"\n# A request shows on the profile as one of these once it is out, or the two are connected.\nLINKEDIN_ASKED = (\"pending\", \"withdraw\", \"invitation sent\")\n# \"1st\", or \"· 1st\" beside the name, is a first-degree connection already.\nLINKEDIN_CONNECTED = re.compile(r\"^(·\\s*)?1st( degree( connection)?)?$|^remove connection$\")\n# How many waiting requests one read opens, each for its profile's address.\nLINKEDIN_INVITES_MAX = 10\n\n\ndef linkedin_slug_from(text):\n    \"\"\"The member's slug out of a profile address, or None.\"\"\"\n    found = LINKEDIN_PROFILE_ADDRESS.search(text or \"\")\n    if not found:\n        return None\n    slug = found.group(1).strip(\"/\")\n    try:\n        slug = urllib.parse.unquote(slug)\n    except Exception:  # A broken escape is no slug.\n        return None\n    return slug if LINKEDIN_SLUG.match(slug) else None\n\n\ndef linkedin_name(hierarchy_xml, name_id):\n    \"\"\"The member's name on a profile, by its view id. \"\" when it has no id to match (an iPhone).\"\"\"\n    if not name_id:\n        return \"\"\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        if own_node(node, app_packages(\"linkedin\")) and re.match(name_id, node.get(\"resource-id\") or \"\"):\n            words = node_words(node)\n            if words:\n                return words[:200]\n    return \"\"\n\n\ndef linkedin_followers(hierarchy_xml):\n    \"\"\"The followers a profile shows (\"1,204 followers\"), or None.\"\"\"\n    for line in screen_lines(hierarchy_xml, app_packages(\"linkedin\")):\n        found = LINKEDIN_FOLLOWERS.match(line.strip())\n        if found:\n            return parse_count(found.group(1).replace(\" \", \"\"))\n    return None\n\n\ndef linkedin_premium(hierarchy_xml):\n    \"\"\"True when the profile shows the Premium badge. None, never False, when it does not: a badge not seen is not a badge missing.\"\"\"\n    lines = [plain(line) for line in screen_lines(hierarchy_xml, app_packages(\"linkedin\"))]\n    return True if any(line in LINKEDIN_PREMIUM_WORDS for line in lines) else None\n\n\ndef linkedin_code_asked(hierarchy_xml):\n    \"\"\"True on LinkedIn's \"enter the code we emailed\" screen.\"\"\"\n    return screen_says(hierarchy_xml, \"linkedin\", LINKEDIN_CODE_WORDS) is not None\n\n\ndef clear_clipboard(device):\n    \"\"\"Empties the phone's clipboard. False when this screen has no clipboard\n    to empty or read (an iPhone), so a copy can never be checked there.\"\"\"\n    if not hasattr(device, \"clipboard\"):\n        return False\n    try:\n        setter = getattr(device, \"set_clipboard\", None)\n        if callable(setter):\n            setter(\"\")\n        else:\n            device.clipboard = \"\"\n        return not str(device.clipboard or \"\")\n    except Exception:  # A phone that would not take it; the copy can't be trusted.\n        return False\n\n\ndef linkedin_copy_profile_link(serial, walk, screens, previous=None):\n    \"\"\"The open profile's own address, through its More menu: Copy link when\n    the menu has it, else the system's share sheet and its Copy. The slug, or\n    None when the app would not give it.\n\n    The clipboard is emptied first, so a copy that silently did nothing reads\n    as nothing rather than as the last address copied, which would file one\n    person under another's profile. A slug equal to `previous`, the one copied\n    just before, is the same mistake by another road and is dropped too.\"\"\"\n    device = walk.screen()\n    if not clear_clipboard(device):\n        log(\"Could not empty the clipboard on %s, so a copied address can't be trusted\" % serial)\n        return None\n    walk.tap_first(\"Open the profile's menu\", selectors=screens[\"profile_more\"])\n    time.sleep(1.5)\n    try:\n        walk.tap_first(\"Copy the profile's link\", timeout=3, selectors=screens[\"copy_link\"])\n    except StepFailed:\n        walk.tap_first(\"Share the profile\", selectors=screens[\"share_profile\"])\n        time.sleep(2)\n        walk.tap_first(\"Copy the address\", selectors=LINKEDIN_SYSTEM_COPY)\n    time.sleep(1)\n    try:\n        copied = str(device.clipboard or \"\")\n    except Exception:  # A screen that cannot read the clipboard.\n        return None\n    slug = linkedin_slug_from(copied)\n    if slug and previous and slug.lower() == previous.lower():\n        log(\"The address copied on %s was the one copied before, so it was dropped\" % serial)\n        return None\n    return slug\n\n\ndef read_linkedin_profile(serial, walk):\n    \"\"\"Opens LinkedIn on the member's own profile, through the menu behind its\n    picture, and reads the slug, the name, the followers and the Premium\n    badge. A ban screen or the code screen in the way is read instead.\"\"\"\n    empty = {\"slug\": None, \"name\": \"\", \"followers\": None, \"premium\": None, \"ban\": None, \"codeAsked\": False}\n    open_app(serial, \"linkedin\")\n    walk.shot(\"Opened LinkedIn\")\n    device = walk.screen()\n    hierarchy = device.dump_hierarchy()\n    # The code screen first: its \"quick verification\" heading must never be\n    # read as an identity ban, which stops the account for good.\n    if linkedin_code_asked(hierarchy):\n        return dict(empty, codeAsked=True)\n    ban = ban_screen_in(hierarchy, \"linkedin\", package_for(serial, \"linkedin\"))\n    if ban and ban[\"kind\"] != \"unknown\":\n        return dict(empty, ban=ban)\n    if signed_out(hierarchy, \"linkedin\"):\n        return empty\n    screens = app_screens(serial, \"linkedin\")\n    walk.tap_first(\"Open the menu\", selectors=screens[\"drawer\"])\n    time.sleep(1.5)\n    walk.tap_first(\"Open the profile\", selectors=screens[\"profile_entry\"])\n    time.sleep(2.5)\n    hierarchy = device.dump_hierarchy()\n    reading = {\n        \"name\": linkedin_name(hierarchy, screens[\"name_id\"]),\n        \"followers\": linkedin_followers(hierarchy),\n        \"premium\": linkedin_premium(hierarchy),\n    }\n    walk.shot(\"Read the profile\")\n    slug = linkedin_copy_profile_link(serial, walk, screens)\n    if not slug:\n        raise StepFailed(\"Copy the profile's link\", \"The profile's address was not on the clipboard.\")\n    return dict(empty, slug=slug, **reading)\n\n\ndef action_linkedin_state(serial, args, walk):\n    \"\"\"Who the LinkedIn app is signed in as, its name, followers and Premium\n    badge, off its own profile; asked after every LinkedIn job too, as\n    linkedin/quick_state. A restricted or verify screen is answered as\n    blocked, with LinkedIn's own words; the emailed-code screen as\n    codeAsked. The company pages a member runs are not shown in the app, so\n    pages is None. An app that cannot be read says \"not checked\", so a failed\n    look is never written down as signed out; a rehearsal that cannot read it\n    is broken.\"\"\"\n    try:\n        walk.screen().screen_on()\n        reading = read_linkedin_profile(serial, walk)\n        walk.home()\n    except Cancelled:\n        raise\n    except Exception as failure:  # Not checked rather than signed out.\n        if walk.rehearse:\n            raise\n        log(\"Could not read who is signed in to LinkedIn on %s: %s\" % (serial, failure))\n        return dict(LINKEDIN_NOT_CHECKED)\n    ban = reading[\"ban\"]\n    return {\n        \"checked\": True,\n        \"slug\": reading[\"slug\"],\n        \"name\": reading[\"name\"],\n        \"blocked\": bool(ban) or reading[\"codeAsked\"],\n        \"reason\": \"LinkedIn shows the account %s\" % LINKEDIN_BAN_WORDS.get(ban[\"kind\"], \"stopped\") if ban\n        else (\"LinkedIn is asking for the code it emailed\" if reading[\"codeAsked\"] else \"\"),\n        \"banScreen\": ban[\"words\"] if ban else None,\n        \"codeAsked\": reading[\"codeAsked\"],\n        \"pages\": None,\n        \"premium\": reading[\"premium\"],\n        \"followers\": reading[\"followers\"],\n    }\n\n\ndef linkedin_lines(hierarchy_xml):\n    \"\"\"The LinkedIn app's own lines on screen, kept from before a press so the lines after it can be told apart.\"\"\"\n    return set(screen_lines(hierarchy_xml, app_packages(\"linkedin\")))\n\n\ndef linkedin_landed(hierarchy_xml, package, text, before, shown_before=()):\n    \"\"\"What the screen says after Post was pressed: (\"sent\", \"\"), (\"failed\",\n    LinkedIn's words), or (\"\", \"\") while neither shows. Only lines that were\n    not on screen before the press are read, so a post that says \"couldn't be\n    posted\" is not LinkedIn's notice. The words showing more times than\n    before also count as sent.\"\"\"\n    fresh = [plain(line) for line in screen_lines(hierarchy_xml, app_packages(\"linkedin\")) if line not in shown_before]\n    failed = next((line for line in fresh if any(phrase in line for phrase in LINKEDIN_POST_FAILED)), None)\n    if failed:\n        return \"failed\", failed\n    if any(line in LINKEDIN_POSTED or line.startswith(\"post successful\") for line in fresh) or (\n        text and times_shown(hierarchy_xml, package, text) > before\n    ):\n        return \"sent\", \"\"\n    return \"\", \"\"\n\n\ndef linkedin_wait_landed(walk, package, text, before, verb, shown_before=()):\n    \"\"\"Waits for LinkedIn to say it went. A failure LinkedIn names fails the job; True once sent; False when nothing showed in time.\"\"\"\n    device = walk.screen()\n    waiting_until = time.time() + POST_LANDED_SECONDS\n    while time.time() < waiting_until:\n        time.sleep(1)\n        try:\n            state, words = linkedin_landed(device.dump_hierarchy(), package, text, before, shown_before)\n        except Exception:  # A screen caught mid-change; look again.\n            continue\n        if state == \"failed\":\n            walk.shot(\"LinkedIn said it failed\")\n            raise RuntimeError(\"%s: LinkedIn said it did not go: %s. %s\" % (verb, words, LINKEDIN_MAY_BE_SENT))\n        if state == \"sent\":\n            walk.shot(\"Looked for it\")\n            return True\n    walk.shot(\"Looked for it\")\n    return False\n\n\ndef linkedin_after_press(verb, look):\n    \"\"\"Runs the look after Post or Send was pressed. Whatever fails in it says\n    the words may be on LinkedIn already.\"\"\"\n    try:\n        return look()\n    except Cancelled:\n        raise\n    except Exception as failure:\n        words = str(failure) or failure.__class__.__name__\n        if \"It may already be on LinkedIn\" in words:\n            raise\n        raise RuntimeError(\"%s: %s. %s\" % (verb, words.rstrip(\".\"), LINKEDIN_MAY_BE_SENT))\n\n\ndef linkedin_feed_before(serial, walk, visit):\n    \"\"\"A little of the home feed before a comment, which never stops it.\"\"\"\n    started = time.monotonic()\n    try:\n        open_app(serial, \"linkedin\")\n        walk.shot(\"Opened LinkedIn\")\n        browse_app_feed(serial, walk, random.uniform(*APP_READ_FEED_SECONDS))\n    except Cancelled:\n        raise\n    except Exception as failure:  # The comment still goes.\n        visit[\"problems\"].append(\"the feed before: %s\" % short_words(failure))\n    visit[\"beforeSeconds\"] = int(time.monotonic() - started)\n\n\ndef linkedin_feed_after(serial, walk, visit):\n    \"\"\"A little scrolling after the press, which can never fail what is already on LinkedIn.\"\"\"\n    started = time.monotonic()\n    try:\n        go_back(serial)\n        time.sleep(1.5)\n        browse_app_feed(serial, walk, random.uniform(*APP_FEED_AFTER_SECONDS))\n    except Exception as failure:  # Includes a cancel: it is on LinkedIn either way.\n        visit[\"problems\"].append(\"the feed after: %s\" % short_words(failure))\n    visit[\"afterSeconds\"] = int(time.monotonic() - started)\n\n\ndef linkedin_post_url(post_id, comment_id=\"\"):\n    \"\"\"A post's address, or one comment under it, which the app opens with that comment first.\"\"\"\n    url = \"https://www.linkedin.com/feed/update/urn:li:activity:%s/\" % post_id\n    if comment_id:\n        url += \"?commentUrn=\" + urllib.parse.quote(\"urn:li:comment:(activity:%s,%s)\" % (post_id, comment_id), safe=\"\")\n    return url\n\n\ndef linkedin_open_post(serial, walk, post_id, comment_id=\"\"):\n    \"\"\"Opens a post by its link in the app, with one comment first when named.\n    With no post (a rehearsal when Promo found none lately) the first post of\n    the home feed is opened.\"\"\"\n    walk.check()\n    if post_id:\n        open_link(serial, \"linkedin\", linkedin_post_url(post_id, comment_id))\n        walk.shot(\"Opened the post\")\n        return\n    open_app(serial, \"linkedin\")\n    walk.shot(\"Opened LinkedIn\")\n    if not open_feed_post(serial, walk, \"linkedin\"):\n        raise StepFailed(\"Open a post\", \"No post was on LinkedIn's home feed to open.\")\n\n\ndef selector_hits(hierarchy_xml, selector):\n    \"\"\"The bounds of every node on screen one uiautomator2-style selector\n    finds, read off the dump, in screen order. Only the words the LinkedIn\n    screens use: text, description, view id, class and package.\"\"\"\n    found = []\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        bounds = parse_bounds(node.get(\"bounds\"))\n        if not bounds:\n            continue\n        text = node.get(\"text\") or \"\"\n        description = node.get(\"content-desc\") or node.get(\"label\") or \"\"\n        kind = node.get(\"class\") or node.get(\"type\") or \"\"\n        tests = {\n            \"textMatches\": lambda wanted: re.fullmatch(wanted, text) is not None,\n            \"descriptionMatches\": lambda wanted: re.fullmatch(wanted, description) is not None,\n            \"resourceIdMatches\": lambda wanted: re.fullmatch(wanted, node.get(\"resource-id\") or \"\") is not None,\n            \"className\": lambda wanted: kind == wanted,\n            \"classNameMatches\": lambda wanted: re.fullmatch(wanted, kind) is not None,\n            \"packageName\": lambda wanted: own_node(node, wanted),\n        }\n        if all(key in tests and tests[key](wanted) for key, wanted in selector.items()):\n            found.append(bounds)\n    return found\n\n\ndef same_row(a, b, slack=40):\n    \"\"\"True when two places on screen sit on one line: their middles within `slack` pixels.\"\"\"\n    return abs((a[1] + a[3]) / 2 - (b[1] + b[3]) / 2) <= slack\n\n\ndef linkedin_post_like(hierarchy_xml, package, screens):\n    \"\"\"The post's own Like on screen: (\"like\", bounds) to press, (\"liked\",\n    None) when the account reacted already, or (None, None) when it is not on\n    screen. Only a Like on the same row as a Repost counts, since that row is\n    the post's own action bar; a comment's Like sits beside its Reply, never\n    beside a Repost. The topmost such row is the post's.\"\"\"\n    reposts = [bounds for selector in shapes(package, \"(?i)^repost( .*)?$\") for bounds in selector_hits(hierarchy_xml, selector)]\n    if not reposts:\n        return None, None\n    rows = []\n    for state, key in ((\"liked\", \"liked\"), (\"like\", \"like\")):\n        for selector in screens[key]:\n            for bounds in selector_hits(hierarchy_xml, selector):\n                if any(same_row(bounds, repost) for repost in reposts):\n                    rows.append((bounds[1], state, bounds))\n    if not rows:\n        return None, None\n    top = min(row[0] for row in rows)\n    states = set(row[1] for row in rows if row[0] == top)\n    if \"liked\" in states:\n        return \"liked\", None\n    return \"like\", next(row[2] for row in rows if row[0] == top)\n\n\ndef linkedin_react_first(serial, walk, screens, visit):\n    \"\"\"Likes the post a few seconds before the comment is typed (part 26),\n    unless the account already reacted to it. Never in a rehearsal, and never\n    stops the comment. Only the post's own Like is pressed (linkedin_post_like);\n    when it can't be told apart on screen nothing is liked and that is noted,\n    rather than guessing and liking somebody's comment.\"\"\"\n    if walk.rehearse:\n        return\n    try:\n        state, bounds = linkedin_post_like(walk.screen().dump_hierarchy(), package_for(serial, \"linkedin\"), screens)\n        if state == \"liked\":\n            return\n        if state is None:\n            visit[\"problems\"].append(\"the like before: the post's own Like was not on screen, so nothing was liked\")\n            return\n        walk.current = \"Like the post\"\n        press_bounds(walk, bounds)\n        walk.shot(\"Liked the post\")\n        time.sleep(random.uniform(2.0, 6.0))\n    except Cancelled:\n        raise\n    except Exception as failure:  # The comment still goes.\n        visit[\"problems\"].append(\"the like before: %s\" % short_words(failure))\n\n\ndef linkedin_composer_send(hierarchy_xml, screens, height):\n    \"\"\"Where Post is for the comment box on screen: the first shape of the\n    send button (its view id before its words) found beside the box, on its\n    row or just under it, never above, where the post's own action bar has a\n    Send of its own. One place, or a StepFailed: two of them, or none, is\n    refused rather than guessed, since a wrong press could send a comment\n    somewhere else.\"\"\"\n    boxes = next((hits for selector in screens[\"comment_box\"] for hits in [selector_hits(hierarchy_xml, selector)] if hits), [])\n    if not boxes:\n        raise StepFailed(\"Find Post\", \"The comment box was not on the screen, so Post beside it could not be told apart.\")\n    box = boxes[0]\n    low, high = box[1] - 30, box[3] + height * 0.10\n    for selector in screens[\"comment_send\"]:\n        near = []\n        for bounds in selector_hits(hierarchy_xml, selector):\n            middle = (bounds[1] + bounds[3]) / 2\n            if low <= middle <= high and bounds != box and bounds not in near:\n                near.append(bounds)\n        if len(near) == 1:\n            return near[0]\n        if len(near) > 1:\n            raise StepFailed(\"Find Post\", \"%d buttons beside the comment box could be Post, so none was pressed.\" % len(near))\n    raise StepFailed(\"Find Post\", \"No Post button was beside the comment box.\")\n\n\ndef final_at(walk, step, bounds):\n    \"\"\"final_first for a place read off the screen: pressed once in a real run,\n    only found in a rehearsal, which returns False.\"\"\"\n    walk.current = step\n    if walk.rehearse:\n        walk.shot(\"%s (found, not pressed)\" % step)\n        return False\n    press_bounds(walk, bounds)\n    time.sleep(1)\n    walk.shot(step)\n    return True\n\n\ndef action_linkedin_comment(serial, args, walk):\n    \"\"\"Writes one comment under a post in the LinkedIn app, inside a visit: a\n    little home feed, the post by its link, read for a while, a Like first\n    when `react` asks (part 26), the box under the post, the words typed with\n    a person's rhythm, and Post pressed once. A reply under one comment\n    (`parentCommentId`) opens the post with that comment first and presses\n    its Reply. Words of ours already under the post (an earlier try that went\n    out without saying so) count as sent, and nothing is typed. It counts as\n    sent when LinkedIn says so or the words show. Its id is \"\".\n\n    Comment as a company page is done in a browser, and is refused before\n    anything opens. In a rehearsal nothing is typed or liked: the post opens\n    (the feed's first post when none was sent), the box is found, Post is\n    found and not pressed.\n    \"\"\"\n    post_id = str(args.get(\"postId\") or \"\").strip()\n    parent = str(args.get(\"parentCommentId\") or \"\").strip()\n    text = str(args.get(\"text\") or \"\").strip()\n    if str(args.get(\"asPageId\") or \"\").strip():\n        raise RuntimeError(\"comment: a comment as a company page is made in a browser, not the LinkedIn app\")\n    if post_id and not LINKEDIN_POST_ID.match(post_id):\n        raise RuntimeError(\"comment: that is not a LinkedIn post id\")\n    if parent and not LINKEDIN_COMMENT_ID.match(parent):\n        raise RuntimeError(\"comment: that is not a LinkedIn comment id\")\n    if not walk.rehearse and (not post_id or not text):\n        raise RuntimeError(\"comment: a comment needs its post and its words\")\n    device = walk.screen()\n    device.screen_on()\n    screens = app_screens(serial, \"linkedin\")\n    package = package_for(serial, \"linkedin\")\n    visit = new_visit()\n    if not walk.rehearse:\n        linkedin_feed_before(serial, walk, visit)\n    before = 0\n    shown = set()\n    try:\n        linkedin_open_post(serial, walk, post_id, parent)\n        hierarchy = device.dump_hierarchy()\n        if signed_out(hierarchy, \"linkedin\"):\n            raise RuntimeError(\"comment: the app is not signed in to LinkedIn\")\n        if not walk.rehearse:\n            if x_words_under(hierarchy, package, text):\n                walk.shot(\"Our words are under the post already\")\n                walk.home()\n                return {\"commentId\": \"\", \"url\": \"\", \"visit\": visit}\n            # The Like before reading, while the post's own action bar is on\n            # screen and no comment's Like has scrolled in beside it.\n            if args.get(\"react\"):\n                linkedin_react_first(serial, walk, screens, visit)\n            read_post(serial, walk, len(\" \".join(screen_lines(hierarchy, app_packages(\"linkedin\")))), visit)\n            hierarchy = device.dump_hierarchy()\n            if x_words_under(hierarchy, package, text):\n                walk.shot(\"Our words are under the post already\")\n                walk.home()\n                return {\"commentId\": \"\", \"url\": \"\", \"visit\": visit}\n            if parent:\n                # The comment the link named shows first; its Reply opens the box under it.\n                walk.tap_first(\"Open the reply\", selectors=screens[\"comment_reply\"])\n                time.sleep(1.5)\n            hierarchy = device.dump_hierarchy()\n            before = times_shown(hierarchy, package, text)\n            shown = linkedin_lines(hierarchy)\n        box = walk.find_first(\"Find the comment box\", selectors=screens[\"comment_box\"])\n        if not walk.rehearse:\n            walk.press(box)\n            gaps = type_like_a_person(serial, device, text, walk.check)\n            walk.shot(\"Typed the comment\")\n            log(\"linkedin comment typed: %d characters, gaps %.2f to %.2f seconds\" % (len(text), min(gaps or [0]), max(gaps or [0])))\n            time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n            shown |= linkedin_lines(device.dump_hierarchy())\n        _, height = screen_size(device)\n        pressed = final_at(walk, \"Press Post\", linkedin_composer_send(device.dump_hierarchy(), screens, height))\n    except Cancelled:\n        raise\n    except Exception:\n        # Stopped before the last button: the draft is thrown away and nothing was sent.\n        if not walk.rehearse:\n            leave_app_screen(serial, walk, \"linkedin\", times=3)\n        raise\n    finally:\n        if walk.rehearse:\n            leave_app_screen(serial, walk, \"linkedin\", times=3)\n    if not pressed:\n        walk.home()\n        return {\"commentId\": \"\", \"url\": \"\"}\n    if not linkedin_after_press(\"comment\", lambda: linkedin_wait_landed(walk, package, text, before, \"comment\", shown)):\n        raise RuntimeError(\n            \"comment: Post was pressed but LinkedIn did not say it was posted, and the words did not show within %d seconds. %s\"\n            % (POST_LANDED_SECONDS, LINKEDIN_MAY_BE_SENT)\n        )\n    linkedin_feed_after(serial, walk, visit)\n    walk.home()\n    return {\"commentId\": \"\", \"url\": \"\", \"visit\": visit}\n\n\ndef linkedin_publish_refusal(args):\n    \"\"\"Why the app can't make this post, or \"\": a poll, a video, a repost, a\n    group post, tags and a company page are made in a browser.\"\"\"\n    if args.get(\"poll\"):\n        return \"a poll\"\n    if str(args.get(\"documentUrl\") or \"\").strip():\n        return \"a document post\"\n    if str(args.get(\"videoUrl\") or \"\").strip():\n        return \"a video post\"\n    if str(args.get(\"repostOf\") or \"\").strip():\n        return \"a repost\"\n    if str(args.get(\"groupId\") or \"\").strip():\n        return \"a post into a group\"\n    if args.get(\"tags\"):\n        return \"a post with tags\"\n    if str(args.get(\"asPageId\") or \"\").strip():\n        return \"a post as a company page\"\n    return \"\"\n\n\ndef action_linkedin_publish(serial, args, walk):\n    \"\"\"One post of the account's own, from LinkedIn's Start a post: a picture\n    from `pictureUrl` put on the phone first and picked in the post box, then\n    the words typed, and Post pressed once. It counts as sent when LinkedIn\n    says so or the words show on the feed. Its id is \"\".\n\n    A poll, a video, a repost, a group post, tags and a company page are made\n    in a browser, and are refused here before anything opens. In a rehearsal\n    no picture is fetched, nothing is typed, and Post is found, not pressed.\n    \"\"\"\n    refused = linkedin_publish_refusal(args)\n    if refused:\n        raise RuntimeError(\"publish: %s is made in a browser, not the LinkedIn app\" % refused)\n    text = str(args.get(\"text\") or \"\").strip()\n    picture = str(args.get(\"pictureUrl\") or \"\").strip()\n    if not walk.rehearse and not text:\n        raise RuntimeError(\"publish: a post needs its words\")\n    device = walk.screen()\n    device.screen_on()\n    has_picture = bool(picture) and not walk.rehearse\n    if has_picture:\n        x_put_picture(serial, walk, picture)\n    screens = app_screens(serial, \"linkedin\")\n    package = package_for(serial, \"linkedin\")\n    visit = new_visit()\n    try:\n        open_app(serial, \"linkedin\")\n        walk.shot(\"Opened LinkedIn\")\n        hierarchy = device.dump_hierarchy()\n        if signed_out(hierarchy, \"linkedin\"):\n            raise RuntimeError(\"publish: the app is not signed in to LinkedIn\")\n        shown = linkedin_lines(hierarchy)\n        walk.tap_first(\"Start a post\", selectors=screens[\"new_post\"])\n        time.sleep(2)\n        box = walk.find_first(\"Find the post box\", selectors=screens[\"composer_box\"])\n        if not walk.rehearse:\n            if has_picture:\n                walk.tap_first(\"Open the photos\", selectors=screens[\"media\"])\n                time.sleep(2)\n                walk.tap_first(\"Pick the newest picture\", selectors=screens[\"media_first\"])\n                time.sleep(1.5)\n                try:\n                    walk.tap_first(\"Add the picture\", timeout=4, selectors=screens[\"media_done\"])\n                    time.sleep(1.5)\n                except StepFailed:\n                    pass  # Added on the pick on this version.\n                box = walk.find_first(\"Find the post box\", selectors=screens[\"composer_box\"])\n            walk.press(box)\n            gaps = type_like_a_person(serial, device, text, walk.check)\n            walk.shot(\"Typed the words\")\n            log(\"linkedin post typed: %d characters, gaps %.2f to %.2f seconds\" % (len(text), min(gaps or [0]), max(gaps or [0])))\n            time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n            shown |= linkedin_lines(device.dump_hierarchy())\n        pressed = walk.final_first(\"Press Post\", selectors=screens[\"post_button\"])\n    except Cancelled:\n        raise\n    except Exception:\n        if not walk.rehearse:\n            leave_app_screen(serial, walk, \"linkedin\", times=3)\n        raise\n    finally:\n        if walk.rehearse:\n            leave_app_screen(serial, walk, \"linkedin\", times=3)\n    if not pressed:\n        walk.home()\n        return {\"postId\": \"\", \"url\": \"\"}\n    if not linkedin_after_press(\"publish\", lambda: linkedin_wait_landed(walk, package, text, 0, \"publish\", shown)):\n        raise RuntimeError(\"publish: Post was pressed but LinkedIn did not say it was posted, and the words did not show. %s\" % LINKEDIN_MAY_BE_SENT)\n    linkedin_feed_after(serial, walk, visit)\n    walk.home()\n    return {\"postId\": \"\", \"url\": \"\", \"visit\": visit}\n\n\ndef linkedin_profile_state(hierarchy_xml):\n    \"\"\"What a person's profile says about the account and them: \"connected\"\n    (\"· 1st\" or Remove connection), \"asked\" (a request is out), \"following\"\n    (followed, which is not connected: a creator's page offers Follow first\n    and Connect only by its own words), or \"\" for none of them.\"\"\"\n    lines = [plain(line) for line in screen_lines(hierarchy_xml, app_packages(\"linkedin\"))]\n    if any(LINKEDIN_CONNECTED.match(line) for line in lines):\n        return \"connected\"\n    if any(line in LINKEDIN_ASKED or line.startswith(\"pending\") for line in lines):\n        return \"asked\"\n    if \"following\" in lines:\n        return \"following\"\n    return \"\"\n\n\ndef linkedin_wait_asked(walk):\n    \"\"\"True once the profile shows Pending, the request being out.\"\"\"\n    device = walk.screen()\n    waiting_until = time.time() + POST_LANDED_SECONDS\n    while time.time() < waiting_until:\n        time.sleep(1)\n        try:\n            if linkedin_profile_state(device.dump_hierarchy()) in (\"asked\", \"connected\"):\n                return True\n        except Exception:  # A screen caught mid-change; look again.\n            continue\n    return False\n\n\ndef action_linkedin_connect(serial, args, walk):\n    \"\"\"One connection request from the person's profile, opened by its link\n    (part 39). Connect pressed once; when LinkedIn then asks about a note,\n    Add a note, the note typed and Send, or Send without a note. It counts as\n    done when the profile shows Pending. Somebody connected or asked already\n    is `already`, with no press. A rehearsal finds Connect and never presses\n    it; with no slug sent it only opens the app.\"\"\"\n    slug = str(args.get(\"slug\") or \"\").strip()\n    note = str(args.get(\"note\") or \"\").strip()\n    if slug and not LINKEDIN_SLUG.match(slug):\n        raise RuntimeError(\"connect: that is not a LinkedIn profile\")\n    if not walk.rehearse and not slug:\n        raise RuntimeError(\"connect: a request needs the person's profile\")\n    device = walk.screen()\n    device.screen_on()\n    screens = app_screens(serial, \"linkedin\")\n    if not slug:\n        open_app(serial, \"linkedin\")\n        walk.shot(\"Opened LinkedIn\")\n        walk.home()\n        return {\"done\": False, \"already\": False}\n    walk.check()\n    open_link(serial, \"linkedin\", \"https://www.linkedin.com/in/%s/\" % urllib.parse.quote(slug))\n    walk.shot(\"Opened the profile\")\n    hierarchy = device.dump_hierarchy()\n    if signed_out(hierarchy, \"linkedin\"):\n        raise RuntimeError(\"connect: the app is not signed in to LinkedIn\")\n    # Followed is not connected, so a creator's page still needs Connect by its\n    # words; with none on screen nothing is pressed (find_first refuses).\n    if linkedin_profile_state(hierarchy) in (\"connected\", \"asked\"):\n        walk.home()\n        return {\"done\": True, \"already\": True}\n    if not walk.final_first(\"Press Connect\", selectors=screens[\"connect\"]):\n        walk.home()\n        return {\"done\": False, \"already\": False}\n\n    def finish():\n        time.sleep(2)\n        if any(device(**selector).exists for selector in screens[\"send_invite\"] + screens[\"add_note\"]):\n            if note:\n                walk.tap_first(\"Add a note\", selectors=screens[\"add_note\"])\n                time.sleep(1.5)\n                box = walk.find_first(\"Find the note box\", selectors=screens[\"note_box\"])\n                walk.press(box)\n                type_like_a_person(serial, device, note, walk.check)\n                walk.shot(\"Typed the note\")\n                time.sleep(random.uniform(*BEFORE_SUBMIT_SECONDS))\n            # Connect only opened the question; Send is what sends the request.\n            send = walk.find_first(\"Press Send\", selectors=screens[\"send_invite\"])\n            walk.press(send)\n            time.sleep(1)\n            walk.shot(\"Pressed Send\")\n        elif note:\n            log(\"LinkedIn sent the request from %s with no note box, so the note was left off\" % serial)\n        return linkedin_wait_asked(walk)\n\n    if not linkedin_after_press(\"connect\", finish):\n        raise RuntimeError(\"connect: Connect was pressed but the profile did not show Pending within %d seconds. %s\" % (POST_LANDED_SECONDS, LINKEDIN_MAY_BE_SENT))\n    walk.shot(\"Looked for Pending\")\n    walk.home()\n    return {\"done\": True, \"already\": False}\n\n\ndef linkedin_invitation_rows(hierarchy_xml, height):\n    \"\"\"The waiting requests the invitations screen shows, each as the bounds\n    of the person's name and the lines under it: their headline and note.\n    A row is told by its Accept button.\"\"\"\n    root = ElementTree.fromstring(hierarchy_xml)\n    parents = {child: parent for parent in root.iter() for child in parent}\n    rows = []\n    for node in root.iter(\"node\"):\n        if not own_node(node, app_packages(\"linkedin\")) or not re.match(r\"(?i)^accept( .+)?$\", node_words(node)):\n            continue\n        holder = parents.get(node)\n        for _ in range(3):\n            if holder is None:\n                break\n            lines = [node_words(child) for child in holder.iter(\"node\") if node_words(child) and child is not node]\n            words = [line for line in lines if plain(line) not in (\"accept\", \"ignore\") and not plain(line).startswith((\"accept \", \"ignore \"))]\n            if words:\n                first = next(child for child in holder.iter(\"node\") if node_words(child) == words[0])\n                bounds = parse_bounds(first.get(\"bounds\"))\n                if bounds and height * 0.12 < (bounds[1] + bounds[3]) / 2 < height * 0.92:\n                    rows.append({\"bounds\": bounds, \"name\": words[0][:200], \"headline\": (words[1] if len(words) > 1 else \"\")[:300], \"note\": \" \".join(words[2:])[:1000]})\n                break\n            holder = parents.get(holder)\n    return rows\n\n\ndef action_linkedin_invites(serial, args, walk):\n    \"\"\"The connection requests waiting on the account (part 40): My Network,\n    the invitations, and each row's profile opened for its address, which the\n    app shows nowhere else, then Back. Read only: nothing is accepted here. A\n    rehearsal opens the invitations and reads nothing.\"\"\"\n    most = max(0, min(int(args.get(\"max\") or LINKEDIN_INVITES_MAX), LINKEDIN_INVITES_MAX))\n    device = walk.screen()\n    device.screen_on()\n    screens = app_screens(serial, \"linkedin\")\n    open_app(serial, \"linkedin\")\n    walk.shot(\"Opened LinkedIn\")\n    if signed_out(device.dump_hierarchy(), \"linkedin\"):\n        raise RuntimeError(\"invites: the app is not signed in to LinkedIn\")\n    walk.tap_first(\"Open My Network\", selectors=screens[\"network\"])\n    time.sleep(2)\n    walk.tap_first(\"Open the invitations\", selectors=screens[\"invitations\"])\n    time.sleep(2)\n    walk.shot(\"Opened the invitations\")\n    invites = []\n    if walk.rehearse:\n        walk.home()\n        return {\"invites\": invites}\n    _, height = screen_size(device)\n    seen = set()\n    slugs = set()\n    previous = None\n    for row in linkedin_invitation_rows(device.dump_hierarchy(), height)[:most]:\n        if row[\"name\"] in seen:\n            continue\n        seen.add(row[\"name\"])\n        press_bounds(walk, row[\"bounds\"])\n        time.sleep(2.5)\n        try:\n            slug = linkedin_copy_profile_link(serial, walk, screens, previous)\n        except StepFailed as failure:\n            log(\"Could not read the address of %s's profile on %s: %s\" % (row[\"name\"], serial, short_words(failure)))\n            slug = None\n        go_back(serial)\n        time.sleep(1.5)\n        # A slug already given to another row is never stored twice: Accept on\n        # one would accept the other.\n        if slug and slug.lower() not in slugs:\n            slugs.add(slug.lower())\n            previous = slug\n            invites.append({\"slug\": slug, \"name\": row[\"name\"], \"headline\": row[\"headline\"], \"note\": row[\"note\"]})\n    walk.home()\n    return {\"invites\": invites}\n\n\ndef action_linkedin_accept(serial, args, walk):\n    \"\"\"Accepts one waiting request from the person's profile, opened by its\n    link, where LinkedIn shows Accept beside Ignore (part 40). Accept pressed\n    once; done when the profile shows them connected. Somebody connected\n    already is done with no press. A rehearsal finds Accept and never presses\n    it; with no slug sent it only opens the app.\"\"\"\n    slug = str(args.get(\"slug\") or \"\").strip()\n    if slug and not LINKEDIN_SLUG.match(slug):\n        raise RuntimeError(\"accept: that is not a LinkedIn profile\")\n    if not walk.rehearse and not slug:\n        raise RuntimeError(\"accept: an accept needs the person's profile\")\n    device = walk.screen()\n    device.screen_on()\n    screens = app_screens(serial, \"linkedin\")\n    if not slug:\n        open_app(serial, \"linkedin\")\n        walk.shot(\"Opened LinkedIn\")\n        walk.home()\n        return {\"done\": False}\n    walk.check()\n    open_link(serial, \"linkedin\", \"https://www.linkedin.com/in/%s/\" % urllib.parse.quote(slug))\n    walk.shot(\"Opened the profile\")\n    hierarchy = device.dump_hierarchy()\n    if signed_out(hierarchy, \"linkedin\"):\n        raise RuntimeError(\"accept: the app is not signed in to LinkedIn\")\n    if linkedin_profile_state(hierarchy) == \"connected\":\n        walk.home()\n        return {\"done\": True}\n    had_message = \"message\" in [plain(line) for line in screen_lines(hierarchy, app_packages(\"linkedin\"))]\n    if not walk.final_first(\"Press Accept\", selectors=screens[\"accept\"]):\n        walk.home()\n        return {\"done\": False}\n\n    def look():\n        \"\"\"Only proof counts: \"· 1st\" or Remove connection on the profile, or\n        a Message button that was not there before the press. Accept merely\n        gone from the screen is any screen change, and proves nothing.\"\"\"\n        waiting_until = time.time() + POST_LANDED_SECONDS\n        while time.time() < waiting_until:\n            time.sleep(1)\n            try:\n                hierarchy = device.dump_hierarchy()\n            except Exception:  # A screen caught mid-change; look again.\n                continue\n            if linkedin_profile_state(hierarchy) == \"connected\":\n                return True\n            if not had_message and \"message\" in [plain(line) for line in screen_lines(hierarchy, app_packages(\"linkedin\"))]:\n                return True\n        return False\n\n    accepted = linkedin_after_press(\"accept\", look)\n    walk.shot(\"Looked for the connection\")\n    if not accepted:\n        raise RuntimeError(\n            \"accept: Accept was pressed but the profile did not show the two connected within %d seconds. %s\" % (POST_LANDED_SECONDS, LINKEDIN_MAY_BE_SENT)\n        )\n    walk.home()\n    return {\"done\": True}\n\n\ndef action_linkedin_warm_up(serial, args, walk):\n    \"\"\"A warming account's day in the LinkedIn app: its home feed read for a\n    few minutes. Nothing is written, liked, followed or connected from a\n    phone, and the browser's search or two on the topic is left out.\"\"\"\n    walk.screen().screen_on()\n    open_app(serial, \"linkedin\")\n    walk.shot(\"Opened LinkedIn\")\n    if walk.rehearse:\n        walk.home()\n        return {\"postsRead\": 0, \"problems\": []}\n    browse_app_feed(serial, walk, random.uniform(150, 360))\n    walk.home()\n    return {\"postsRead\": 0, \"problems\": []}\n\n\n# LinkedIn's rehearsals. The comment and the connect open what Promo sends (a\n# LinkedIn post found in the last week, and its writer); without one, the\n# comment opens the home feed's first post and the connect only opens the\n# app. The post walks to Post. linkedin/quick_state is linkedin/state's own\n# step, so it is walked once.\nREHEARSALS.update({\n    \"linkedin/state\": {},\n    \"linkedin/comment\": {\"postId\": \"\", \"parentCommentId\": \"\", \"text\": \"\", \"react\": False, \"asPageId\": \"\"},\n    \"linkedin/publish\": {\"text\": \"\", \"pictureUrl\": \"\", \"videoUrl\": \"\", \"poll\": None, \"tags\": [], \"repostOf\": \"\", \"groupId\": \"\", \"asPageId\": \"\"},\n    \"linkedin/connect\": {\"slug\": \"\", \"note\": \"\"},\n    \"linkedin/invites\": {\"max\": LINKEDIN_INVITES_MAX},\n    \"linkedin/accept\": {\"slug\": \"\"},\n    \"linkedin/warm_up\": {\"words\": []},\n    \"linkedin/inbox\": {\"kind\": \"message\", \"via\": \"inbox\", \"handle\": \"\"},\n    \"linkedin/reply_message\": {\"kind\": \"message\", \"thread\": \"\", \"author\": \"\", \"quote\": \"\", \"text\": \"\"},\n})\n\n\n# ---------------------------------------------------------------------------\n# Bans (Bans task, parts 19 and 26).\n\n# A warming Instagram or TikTok account's day: the feed for a few minutes,\n# and a few posts liked with a double tap on the post, the way a thumb likes\n# them. Promo sends how many (half as many at half pace).\nAPP_WARM_UP_SECONDS = (150, 360)\nMAX_WARM_UP_LIKES = 6\n\n\n# The post's own Like button, by its words or description, and the same\n# button once pressed. Instagram's and TikTok's say \"Like\" and \"Liked\" (or\n# \"Unlike\"), sometimes followed by the count.\nFEED_LIKE = re.compile(r\"(?i)^like( video| post)?([.,: ].*)?$\")\nFEED_LIKED = re.compile(r\"(?i)^(liked|unlike)( video| post)?([.,: ].*)?$\")\n\n\ndef feed_buttons(hierarchy_xml, package, pattern):\n    \"\"\"Bounds of the app's own nodes whose words or description match, top first.\"\"\"\n    found = []\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        if not own_node(node, package):\n            continue\n        words = [\" \".join((node.get(key) or \"\").split()) for key in (\"text\", \"content-desc\", \"label\")]\n        bounds = parse_bounds(node.get(\"bounds\"))\n        if bounds and any(word and pattern.match(word) for word in words):\n            found.append(bounds)\n    return sorted(found, key=lambda bounds: bounds[1])\n\n\ndef feed_like(hierarchy_xml, package):\n    \"\"\"The topmost post's own Like button not yet pressed, as bounds, or None.\n    Nothing else on the feed is ever pressed: never Follow, an ad, a name or\n    a Comment button.\"\"\"\n    liked = feed_buttons(hierarchy_xml, package, FEED_LIKED)\n    for bounds in feed_buttons(hierarchy_xml, package, FEED_LIKE):\n        if not any(same_row(bounds, other) for other in liked):\n            return bounds\n    return None\n\n\ndef like_landed(hierarchy_xml, package, bounds):\n    \"\"\"True when the button pressed now reads Liked.\"\"\"\n    return any(same_row(bounds, other) for other in feed_buttons(hierarchy_xml, package, FEED_LIKED))\n\n\ndef action_app_warm_up(app):\n    def action(serial, args, walk):\n        \"\"\"The day's visit: the feed scrolled and up to `likes` posts liked,\n        each by pressing the post's own Like button found on screen. Nothing\n        else is pressed, and a like counts only once the button reads Liked.\n        Nothing is posted, commented, followed or typed. A ban screen when the\n        app opens ends the visit at once.\"\"\"\n        device = walk.screen()\n        device.screen_on()\n        open_app(serial, app)\n        walk.shot(\"Opened %s\" % APP_NAMES.get(app, app))\n        if walk.rehearse or ban_screen_on(serial, app):\n            walk.home()\n            return {\"liked\": 0}\n        package = package_for(serial, app)\n        wanted = max(0, min(MAX_WARM_UP_LIKES, int(args.get(\"likes\") or 0)))\n        until = time.monotonic() + random.uniform(*APP_WARM_UP_SECONDS)\n        # The likes are spread over the visit, not all at its start.\n        like_at = sorted(random.uniform(0.15, 0.9) for _ in range(wanted))\n        started, length, liked = time.monotonic(), until - time.monotonic(), 0\n        while time.monotonic() < until:\n            walk.check()\n            scroll_once(serial, device, 1)\n            scroll_pause(until)\n            if liked < wanted and (time.monotonic() - started) / length >= like_at[liked]:\n                hierarchy = device.dump_hierarchy()\n                if ban_screen_in(hierarchy, app, package):\n                    break\n                bounds = feed_like(hierarchy, package)\n                if not bounds:\n                    continue\n                tap_at(serial, device, (bounds[0] + bounds[2]) // 2, (bounds[1] + bounds[3]) // 2)\n                time.sleep(random.uniform(0.6, 1.2))\n                if like_landed(device.dump_hierarchy(), package, bounds):\n                    liked += 1\n                    walk.shot(\"Liked a post\")\n        walk.home()\n        return {\"liked\": liked}\n    return action\n\n\ndef action_ban_look(app):\n    def action(serial, args, walk):\n        \"\"\"The weekly look at a banned account (part 26): the app opened and\n        its first screen read. It never taps, scrolls, posts or types. The\n        ban screen check after every app action reads the screen; this only\n        opens it and leaves it showing.\"\"\"\n        device = walk.screen()\n        device.screen_on()\n        open_app(serial, app)\n        time.sleep(3)\n        walk.shot(\"Opened %s\" % APP_NAMES.get(app, app))\n        # A disabled account is often only signed out, and a slow phone may\n        # still show the splash: neither is the account coming back.\n        try:\n            hierarchy = device.dump_hierarchy()\n            lines = screen_lines(hierarchy, package_for(serial, app))\n            return {\"looked\": True, \"signedOut\": signed_out(hierarchy, app), \"lines\": len(lines)}\n        except Exception as failure:  # A screen that cannot be read says nothing either way.\n            log(\"Could not read %s for the weekly look: %s\" % (serial, failure))\n            return {\"looked\": True, \"signedOut\": None, \"lines\": 0}\n    return action\n\n\nACTIONS = {\n    \"phone/list\": action_list,\n    \"phone/health\": action_health,\n    \"phone/android-version\": action_android_version,\n    \"phone/self-test\": action_self_test,\n    \"phone/check-updates\": action_check_updates,\n    \"phone/update-app\": action_update_app,\n    \"phone/setup-check\": action_setup_check,\n    \"phone/outside-address\": action_outside_address,\n    \"phone/icloud-state\": action_icloud_state,\n    \"phone/wipe\": action_wipe,\n    \"reddit/state\": action_reddit_state,\n    \"reddit/quick_state\": action_reddit_quick_state,\n    \"reddit/health\": action_reddit_health,\n    \"reddit/comment\": action_reddit_comment,\n    \"reddit/inbox\": action_app_inbox(\"reddit\"),\n    \"reddit/reply_message\": action_app_reply(\"reddit\"),\n}\nACTIONS.update({\n    \"medium/state\": medium_state,\n    \"medium/quick_state\": medium_state,\n    \"medium/respond\": action_medium_respond,\n    \"medium/warm_up\": action_medium_warm_up,\n})\nfor _app in (\"instagram\", \"tiktok\"):\n    ACTIONS.update({\n        \"%s/warm_up\" % _app: action_app_warm_up(_app),\n        \"%s/quick_state\" % _app: action_app_quick_state(_app),\n        \"%s/health\" % _app: action_app_health(_app),\n        \"%s/profile\" % _app: action_app_profile(_app),\n        \"%s/post\" % _app: action_app_post(_app),\n        \"%s/post_carousel\" % _app: action_app_carousel(_app),\n        \"%s/inbox\" % _app: action_app_inbox(_app),\n        \"%s/reply\" % _app: action_app_reply(_app),\n    })\nACTIONS.update({\n    \"x/state\": action_x_state,\n    \"x/quick_state\": action_x_state,\n    \"x/reply\": action_x_reply,\n    \"x/quote\": action_x_quote,\n    \"x/publish\": action_x_publish,\n    \"x/follow\": action_x_follow,\n    \"x/warm_up\": action_x_warm_up,\n    # Direct messages, through the shared inbox steps (see above).\n    \"x/inbox\": action_app_inbox(\"x\"),\n    \"x/reply_message\": action_app_reply(\"x\"),\n})\nACTIONS[\"instagram/post_story\"] = action_instagram_story\nACTIONS.update({\n    # YouTube (YouTube task): who is signed in, the daily reading, an upload,\n    # and the comments under its videos through the shared inbox steps.\n    \"youtube/quick_state\": action_youtube_quick_state,\n    \"youtube/health\": action_youtube_health,\n    \"youtube/upload\": action_youtube_upload,\n    \"youtube/inbox\": action_app_inbox(\"youtube\"),\n    \"youtube/reply\": action_app_reply(\"youtube\"),\n})\nACTIONS.update({\n    \"threads/warm_up\": action_app_warm_up(\"threads\"),\n    \"threads/quick_state\": action_app_quick_state(\"threads\"),\n    \"threads/health\": action_app_health(\"threads\"),\n    \"threads/profile\": action_app_profile(\"threads\"),\n    \"threads/post\": action_app_post(\"threads\"),\n    \"threads/inbox\": action_app_inbox(\"threads\"),\n    \"threads/reply\": action_app_reply(\"threads\"),\n})\nfor _app in (\"reddit\", \"instagram\", \"tiktok\", \"medium\", \"x\", \"linkedin\", \"threads\", \"youtube\"):\n    ACTIONS[\"%s/ban_look\" % _app] = action_ban_look(_app)\nACTIONS.update({\n    \"linkedin/state\": action_linkedin_state,\n    \"linkedin/quick_state\": action_linkedin_state,\n    \"linkedin/comment\": action_linkedin_comment,\n    \"linkedin/publish\": action_linkedin_publish,\n    \"linkedin/connect\": action_linkedin_connect,\n    \"linkedin/invites\": action_linkedin_invites,\n    \"linkedin/accept\": action_linkedin_accept,\n    \"linkedin/warm_up\": action_linkedin_warm_up,\n    # Messages, through the shared inbox steps (see above).\n    \"linkedin/inbox\": action_app_inbox(\"linkedin\"),\n    \"linkedin/reply_message\": action_app_reply(\"linkedin\"),\n})\n\n\n# ---------------------------------------------------------------------------\n# Ban screens. After any app action the screen is read for the app's\n# suspended, locked and \"confirm it's you\" screens. A match is sent with the\n# answer and Promo stops the account.\n#\n# The wording is what each app is known to show. A phrase only counts as a\n# whole line of the app's own text, on a screen with few lines, so a post\n# titled \"Account suspended after one comment?\" is not taken for one. Phrases\n# that also appear about other people are left out: Reddit shows \"This\n# account has been suspended\" on any suspended user's profile.\n\nBAN_SCREENS = [\n    (\"reddit\", \"suspended\", [\"your account has been suspended\", \"your account has been permanently suspended\"]),\n    (\"reddit\", \"locked\", [\"your account has been locked\", \"we've locked your account\"]),\n    (\"reddit\", \"confirm\", [\"confirm it's you\", \"verify it's you\", \"verify your identity\"]),\n    (\"instagram\", \"suspended\", [\n        \"we suspended your account\",\n        \"your account has been suspended\",\n        \"your account has been disabled\",\n        \"we disabled your account\",\n    ]),\n    (\"instagram\", \"locked\", [\n        \"your account has been locked\",\n        \"your account has been temporarily locked\",\n        \"we've locked your account\",\n    ]),\n    (\"instagram\", \"confirm\", [\"confirm it's you\", \"help us confirm it's you\", \"we detected unusual activity\"]),\n    (\"tiktok\", \"suspended\", [\n        \"your account was permanently banned\",\n        \"your account is permanently banned\",\n        \"your account has been banned\",\n        \"your account was suspended\",\n    ]),\n    (\"tiktok\", \"confirm\", [\"verify it's you\", \"confirm it's you\"]),\n    (\"medium\", \"suspended\", [\n        \"your account has been suspended\",\n        \"this account is under investigation or was found in violation of the medium rules\",\n    ]),\n    (\"medium\", \"confirm\", [\"verify it's you\", \"confirm it's you\"]),\n]\n\n# X's (X task, part 7), each with and without the full stop X ends some of\n# them with. Left out: \"Account suspended\" and \"This account is temporarily\n# restricted\", which X shows on anybody's profile, not only the account's own.\nX_BAN_PHRASES = [\n    (\"suspended\", [\n        \"your account is suspended\",\n        \"your account has been suspended\",\n        \"your account is permanently suspended\",\n        \"your account has been permanently suspended\",\n    ]),\n    (\"locked\", [\n        \"your account is locked\",\n        \"your account has been locked\",\n        \"your account is temporarily locked\",\n        \"we've temporarily limited some of your account features\",\n    ]),\n    (\"confirm\", [\n        \"confirm it's you\",\n        \"verify it's you\",\n        \"help us confirm it's you\",\n        \"we need to confirm it's you\",\n        \"confirm your identity\",\n        \"verify your identity\",\n        \"authenticate your account\",\n    ]),\n]\nBAN_SCREENS += [(\"x\", kind, [form for phrase in phrases for form in (phrase, phrase + \".\")]) for kind, phrases in X_BAN_PHRASES]\n\n# Threads' (18 Nov 2026 features task, part 9): Meta's words, as Instagram's\n# are, unproven on a phone. Anything else short and ban-like is still caught\n# as unknown.\nBAN_SCREENS += [\n    (\"threads\", \"suspended\", [\"we suspended your account\", \"your account has been suspended\", \"your profile has been suspended\"]),\n    (\"threads\", \"confirm\", [\"confirm it's you\", \"help us confirm it's you\", \"we detected unusual activity\"]),\n    # YouTube's (YouTube task, part 2): a terminated channel, a strike, and the\n    # Google account check. Words as YouTube is known to show them, unproven.\n    (\"youtube\", \"suspended\", [\n        \"your channel has been terminated\",\n        \"this channel was terminated\",\n        \"your account has been terminated\",\n        \"your account has been disabled\",\n        \"your channel received a community guidelines strike\",\n    ]),\n    (\"youtube\", \"confirm\", [\"verify it's you\", \"confirm it's you\"]),\n]\n\n# LinkedIn's (LinkedIn task, part 5), each with and without a full stop.\n# \"Restricted\" is LinkedIn's word for an account it stopped; its identity\n# and security checks ask the member to prove it is them. Left out: \"This\n# profile is not available\", which LinkedIn shows for anybody it hides, and\n# \"Let's do a quick verification\", which heads the emailed-code screen\n# (linkedin_code_asked), a sign-in step and no ban.\nLINKEDIN_BAN_PHRASES = [\n    (\"restricted\", [\n        \"your account has been restricted\",\n        \"your account is restricted\",\n        \"your account has been temporarily restricted\",\n        \"your account is temporarily restricted\",\n        \"we've restricted your account\",\n        \"we've temporarily restricted your account\",\n        \"your account has been suspended\",\n    ]),\n    (\"confirm\", [\n        \"verify your identity\",\n        \"we need to verify your identity\",\n        \"help us verify your identity\",\n        \"let's do a quick security check\",\n        \"security verification\",\n        \"security check\",\n    ]),\n]\nBAN_SCREENS += [(\"linkedin\", kind, [form for phrase in phrases for form in (phrase, phrase + \".\")]) for kind, phrases in LINKEDIN_BAN_PHRASES]\n\n# A ban screen is a page of a few lines. A feed has many more.\nBAN_SCREEN_MAX_LINES = 30\n\n\ndef screen_lines(hierarchy_xml, package=None):\n    \"\"\"The text on screen, in order, from the given app's own views only.\"\"\"\n    lines = []\n    for node in ElementTree.fromstring(hierarchy_xml).iter(\"node\"):\n        if not own_node(node, package):\n            continue\n        # text and content-desc are Android's; label an iPhone's. An iPhone\n        # node's value is what someone typed into a text box; on a switch it\n        # is \"1\" or \"0\", which is no line anyone reads.\n        keys = (\"text\", \"content-desc\", \"label\", \"value\") if is_text_box(node) else (\"text\", \"content-desc\", \"label\")\n        for key in keys:\n            text = \" \".join((node.get(key) or \"\").split())\n            if text and text not in lines:\n                lines.append(text)\n    return lines\n\n\ndef plain(text):\n    \"\"\"Lower case, with the curly apostrophe and iOS's non-breaking hyphen (as in its \"Wi-Fi\") made plain.\"\"\"\n    return text.lower().replace(u\"’\", \"'\").replace(u\"\\u2011\", \"-\").replace(u\"\\u2010\", \"-\")\n\n\n# Lines a person taught Promo (Bans task, part 9), sent with every action:\n# {\"bans\": {app: set(lines)}, \"harmless\": {app: set(lines)}}, plain.\nLEARNED = {\"bans\": {}, \"harmless\": {}}\n\n# A short screen holding one of these, in a line spoken to the account,\n# that matches no known line is a screen Promo does not know: it stops the\n# account and asks a person whether it is a ban (part 9).\nUNKNOWN_BAN_WORDS = (\"suspended\", \"banned\", \"disabled\", \"locked\", \"violat\", \"restricted\")\n# Longer than this, a line is somebody writing about a ban, not the app.\nUNKNOWN_LINE_CHARS = 120\n# A no or not just before the ban word is the app saying all is well, as the\n# Account status pages the daily reading opens do: \"You have no violations\",\n# \"Your account isn't restricted\". Further away it is part of a real ban:\n# \"disabled for not following our Terms\".\nUNKNOWN_NOT_A_BAN = re.compile(\n    r\"\\b(no|not|never|none|isn't|aren't|wasn't|haven't|hasn't)\\b(\\W+\\w+){0,2}\\W+(suspend|bann|disabl|lock|restrict|violat)|^none of\\b|good standing\"\n)\n\n\ndef learn_phrases(reply):\n    \"\"\"Takes the lines Promo sent with an action into LEARNED.\"\"\"\n    if not isinstance(reply, dict) or \"banPhrases\" not in reply:\n        return\n    for key, field in ((\"bans\", \"banPhrases\"), (\"harmless\", \"harmless\")):\n        learned = {}\n        for item in reply.get(field) or []:\n            if isinstance(item, dict) and item.get(\"app\") and item.get(\"line\"):\n                learned.setdefault(item[\"app\"], set()).add(plain(\" \".join(str(item[\"line\"]).split())))\n        LEARNED[key] = learned\n\n\ndef unknown_ban_line(line):\n    \"\"\"True when a line reads like an app telling the account it is stopped:\n    short, a ban word, spoken to \"you\", and not a question. \"This account has\n    been suspended\" on somebody else's profile, and a post titled \"Account\n    suspended after one comment?\", are not.\"\"\"\n    text = plain(line).strip()\n    if len(text) > UNKNOWN_LINE_CHARS or text.endswith(\"?\"):\n        return False\n    if not any(word in text for word in UNKNOWN_BAN_WORDS):\n        return False\n    if UNKNOWN_NOT_A_BAN.search(text):\n        return False\n    return re.search(r\"\\byou(r)?\\b\", text) is not None\n\n\ndef ban_screen_in(hierarchy_xml, app, package=None):\n    \"\"\"The ban screen showing, as {app, kind, words}, or None.\n\n    A known line gives its kind. A line a person called a ban gives the kind\n    \"learned\". A short screen with a ban line Promo does not know gives the\n    kind \"unknown\" and the line, unless a person called that line harmless.\n    \"\"\"\n    lines = screen_lines(hierarchy_xml, package or APP_PACKAGES.get(app))\n    if not lines or len(lines) > BAN_SCREEN_MAX_LINES:\n        return None\n    words = \" \".join(lines)[:500]\n    for screen_app, kind, phrases in BAN_SCREENS:\n        if screen_app != app:\n            continue\n        for line in lines:\n            if plain(line) in phrases:\n                return {\"app\": app, \"kind\": kind, \"words\": words}\n    taught = LEARNED[\"bans\"].get(app, set())\n    for line in lines:\n        if plain(line) in taught:\n            return {\"app\": app, \"kind\": \"learned\", \"words\": words, \"line\": line[:500]}\n    harmless = LEARNED[\"harmless\"].get(app, set())\n    for line in lines:\n        if plain(line) not in harmless and unknown_ban_line(line):\n            return {\"app\": app, \"kind\": \"unknown\", \"words\": words, \"line\": line[:500]}\n    return None\n\n\ndef ban_screen_on(serial, app):\n    try:\n        return ban_screen_in(connect_screen(serial).dump_hierarchy(), app, package_for(serial, app))\n    except Exception as failure:  # A screen that cannot be read is not a ban screen.\n        log(\"Could not read the screen of %s for a ban screen: %s\" % (serial, failure))\n        return None\n\n\ndef action_app(name):\n    \"\"\"The app an action works in: \"reddit\" for reddit/comment, or None.\"\"\"\n    app = name.split(\"/\", 1)[0]\n    return app if app in APP_PACKAGES else None\n\n\n# ---------------------------------------------------------------------------\n# Freezes. An action still running near the end of its time is given up on:\n# a phone that no longer answers adb is restarted, otherwise the app in front\n# is closed and opened again. An app Android itself says is not responding is\n# closed the same way when its action fails.\n\n# Enough to check adb, restart or reopen, read the screen and hand in the answer.\nFREEZE_MARGIN_SECONDS = 60\nRESTART_GAP_SECONDS = 30 * 60\n# A phone the rack restarted is reported as restarting, not unplugged, for this long.\nRESTART_GRACE_SECONDS = 4 * 60\n\nNOT_RESPONDING = (\"isn't responding\", \"is not responding\", \"keeps stopping\", \"has stopped\")\nCLOSE_BUTTONS = (\"Close app\", \"Close\", \"OK\")\n\nSCREEN_PACKAGES = {\n    \"phone/android-version\": \"com.android.settings\",\n    \"phone/check-updates\": PLAY_STORE,\n    \"phone/update-app\": PLAY_STORE,\n    \"phone/setup-check\": PLAY_STORE,\n    \"phone/wipe\": \"com.android.settings\",\n}\nIOS_SCREEN_PACKAGES = {\n    \"phone/android-version\": IOS_SETTINGS,\n    \"phone/check-updates\": APP_STORE,\n    \"phone/update-app\": APP_STORE,\n    \"phone/setup-check\": IOS_SETTINGS,\n    \"phone/icloud-state\": IOS_SETTINGS,\n    \"phone/wipe\": IOS_SETTINGS,\n}\n\n_RESTARTED_AT = {}\n_RESTART_WHY = {}\n_RESTART_LOCK = threading.Lock()\n\n\ndef phone_answers(serial):\n    \"\"\"True when the phone answers right now: adb's echo on an Android, a live\n    GET /status to WebDriverAgent on an iPhone. Nothing cached counts.\"\"\"\n    if is_iphone(serial):\n        try:\n            return bool(iphone_screen(serial).answers())\n        except Exception:  # No driver beside the program: the phone counts as frozen.\n            return False\n    try:\n        return shell(serial, \"echo ok\", timeout=10) == \"ok\"\n    except (RuntimeError, subprocess.TimeoutExpired):\n        return False\n\n\ndef restart_phone(serial, why):\n    \"\"\"Restarts a phone, at most once in half an hour, so a phone that keeps\n    freezing is left for a person rather than restarted over and over.\n    Returns (restarted, words): the words say why not, for Promo's answer.\"\"\"\n    with _RESTART_LOCK:\n        if time.time() - _RESTARTED_AT.get(serial, 0) < RESTART_GAP_SECONDS:\n            log(\"%s froze again within half an hour of a restart, so it is left for a person.\" % serial)\n            return False, \"The phone stopped answering again soon after a restart, so the rack left it for you.\"\n        _RESTARTED_AT[serial] = time.time()\n        _RESTART_WHY[serial] = why\n    try:\n        if is_iphone(serial):\n            iphone.restart(serial)\n        else:\n            adb([\"reboot\"], serial=serial, timeout=20)\n    except Exception as failure:  # adb's refusal, or the driver's.\n        log(\"Could not restart %s: %s\" % (serial, failure))\n        return False, \"The phone stopped answering, and the rack could not restart it (%s), so it is left for you.\" % short_words(failure)\n    log(\"Restarted %s: %s\" % (serial, why))\n    return True, \"\"\n\n\ndef restarting_as_such(phones):\n    \"\"\"Reports a phone the rack just restarted as \"restarting\" while it boots,\n    rather than as unplugged or offline.\"\"\"\n    now = time.time()\n    with _RESTART_LOCK:\n        booting = set(serial for serial, at in _RESTARTED_AT.items() if now - at < RESTART_GRACE_SECONDS)\n    listed = set()\n    for phone in phones:\n        listed.add(phone[\"serial\"])\n        if phone[\"serial\"] in booting and phone[\"state\"] != \"device\":\n            phone[\"state\"] = \"restarting\"\n    for serial in booting - listed:\n        phone = {\"serial\": serial, \"state\": \"restarting\", \"usb\": \"\", \"model\": \"\", \"android\": \"\"}\n        if is_iphone(serial):\n            phone[\"kind\"] = \"iphone\"\n        phones.append(phone)\n    return phones\n\n\ndef foreground_package(serial):\n    \"\"\"The app in front: Android's focused window, or on an iPhone the bundle\n    WebDriverAgent names (the driver's active_app).\"\"\"\n    if is_iphone(serial):\n        try:\n            return str(iphone_screen(serial).active_app() or \"\")\n        except Exception:  # No answer is no app known.\n            return \"\"\n    try:\n        found = re.search(r\"mCurrentFocus=\\S*\\s+\\S+\\s+([A-Za-z0-9_.]+)/\", shell(serial, \"dumpsys window | grep mCurrentFocus\", timeout=10))\n    except (RuntimeError, subprocess.TimeoutExpired):\n        return \"\"\n    return found.group(1) if found else \"\"\n\n\ndef reopen_app(serial, package):\n    if is_iphone(serial):\n        device = iphone_screen(serial)\n        device.app_stop(package)\n        device.app_start(package)\n        return\n    shell(serial, \"am force-stop %s\" % package, timeout=15)\n    shell(serial, \"monkey -p %s -c android.intent.category.LAUNCHER 1\" % package, timeout=15)\n\n\ndef action_package(name, serial=\"\"):\n    app = action_app(name)\n    if is_iphone(serial):\n        return APP_BUNDLES[app] if app else IOS_SCREEN_PACKAGES.get(name, \"\")\n    return APP_PACKAGES[app] if app else SCREEN_PACKAGES.get(name, \"\")\n\n\ndef recover_frozen(serial, name):\n    \"\"\"What to do about an action that did not finish in time: (what was done, words).\"\"\"\n    if not phone_answers(serial):\n        restarted, why_not = restart_phone(serial, \"It stopped answering during %s, so the rack restarted it.\" % name)\n        if restarted:\n            return \"phone\", \"The phone stopped answering, so the rack restarted it. %s was not finished.\" % name\n        return \"\", \"%s %s was not finished.\" % (why_not, name)\n    package = foreground_package(serial) or action_package(name, serial)\n    if not package:\n        return \"\", \"%s did not finish in time.\" % name\n    try:\n        reopen_app(serial, package)\n    except (RuntimeError, subprocess.TimeoutExpired) as failure:\n        return \"\", \"%s did not finish in time, and the app could not be closed: %s\" % (name, failure)\n    return \"app\", \"The app stopped responding, so the rack closed it and opened it again. %s was not finished; nothing more was pressed.\" % name\n\n\ndef close_not_responding(serial, name):\n    \"\"\"Closes Android's \"isn't responding\" box if one is up, and opens the app again.\n    Returns words for the answer, or empty when there was none. iOS shows no\n    such box: a frozen app is simply gone, so there is nothing to close.\"\"\"\n    if is_iphone(serial):\n        return \"\"\n    try:\n        device = connect_screen(serial)\n        lines = screen_lines(device.dump_hierarchy())\n    except Exception:  # No screen to read is no box to close.\n        return \"\"\n    said = next((line for line in lines if any(words in plain(line) for words in NOT_RESPONDING)), \"\")\n    if not said:\n        return \"\"\n    for label in CLOSE_BUTTONS:\n        try:\n            if device(text=label).exists:\n                device(text=label).click()\n                break\n        except Exception:  # The box went by itself.\n            break\n    package = action_package(name)\n    if package:\n        try:\n            reopen_app(serial, package)\n        except (RuntimeError, subprocess.TimeoutExpired):\n            pass\n    return 'Android said \"%s\", so the rack closed the app and opened it again.' % said\n\n\n# ---------------------------------------------------------------------------\n# Screens. While someone has a phone's window open in Promo, this sends a\n# picture of its screen a few times a second and carries back the taps and\n# typing, which Promo hands over only while that person has control on. It\n# also looks for a code texted to the phone. Texts are never written down.\n#\n# The wall (phone farm part 57) rides on the same turns: Promo names the\n# phones whose small picture it wants, and each gets one every 5 seconds,\n# 270 pixels wide, marked \"lane\": \"wall\" beside the window's own frames.\n\nSCREEN_GAP_SECONDS = 0.3\nIDLE_SCREEN_GAP_SECONDS = 2\nTEXT_GAP_SECONDS = 4\n# An iPhone's texts are read by opening Messages on its screen, so less often.\nIPHONE_TEXT_GAP_SECONDS = 6\n# A texted code older than this is not shown.\nTEXT_WINDOW_MS = 10 * 60 * 1000\nCODE_PATTERN = re.compile(r\"(?<![\\d])(\\d{4,8})(?![\\d])\")\n# The wall: one small picture per phone this often, this wide, and turns\n# this far apart when only the wall is open.\nWALL_GAP_SECONDS = 5\nWALL_WIDTH = 270\nWALL_TURN_SECONDS = 1\n# Promo holds a phone for 15 minutes after a tap with control on\n# (src/server/phones/screens.ts). Control is read here as a tap from Promo\n# within that time, which is all the reply says.\nCONTROL_HOLD_SECONDS = 15 * 60\n# How long after the last tap or key an iPhone's Messages is left alone, so\n# a read never lands in the middle of someone typing on the phone.\nTAP_QUIET_SECONDS = 20\n\nKEYCODES = {\n    \"back\": \"KEYCODE_BACK\",\n    \"home\": \"KEYCODE_HOME\",\n    \"recents\": \"KEYCODE_APP_SWITCH\",\n    \"enter\": \"KEYCODE_ENTER\",\n    \"delete\": \"KEYCODE_DEL\",\n}\n\n\ndef screen_frame(device, wide=SCREENSHOT_WIDTH):\n    \"\"\"A picture of the screen, shrunk, with the phone's own size for placing taps.\"\"\"\n    image = device.screenshot()\n    width, height = image.width, image.height\n    if width > wide:\n        image = image.resize((wide, round(height * wide / width)))\n    buffer = io.BytesIO()\n    image.convert(\"RGB\").save(buffer, format=\"JPEG\", quality=60)\n    return buffer.getvalue(), width, height\n\n\ndef typed_text(text):\n    \"\"\"`input text`'s own spelling, quoted for the phone's shell: spaces are %s.\"\"\"\n    return \"'%s'\" % text.replace(\"'\", \"'\\\\''\").replace(\" \", \"%s\")\n\n\ndef apply_input(serial, item, size):\n    width, height = size\n    kind = item.get(\"kind\")\n    if is_iphone(serial):\n        apply_iphone_input(iphone_screen(serial), item, size)\n    elif kind == \"tap\":\n        shell(serial, \"input tap %d %d\" % (round(item[\"x\"] * width), round(item[\"y\"] * height)))\n    elif kind == \"swipe\":\n        shell(serial, \"input swipe %d %d %d %d 300\" % (\n            round(item[\"x1\"] * width), round(item[\"y1\"] * height),\n            round(item[\"x2\"] * width), round(item[\"y2\"] * height),\n        ))\n    elif kind == \"text\":\n        shell(serial, \"input text %s\" % typed_text(str(item.get(\"text\", \"\"))[:500]))\n    elif kind == \"key\" and item.get(\"key\") in KEYCODES:\n        shell(serial, \"input keyevent %s\" % KEYCODES[item[\"key\"]])\n\n\ndef apply_iphone_input(device, item, size):\n    \"\"\"The window's taps on an iPhone, through the driver: the same key names,\n    which it turns into the iPhone's own swipes for back and recents.\"\"\"\n    width, height = size\n    kind = item.get(\"kind\")\n    if kind == \"tap\":\n        device.click(round(item[\"x\"] * width), round(item[\"y\"] * height))\n    elif kind == \"swipe\":\n        device.swipe(\n            round(item[\"x1\"] * width), round(item[\"y1\"] * height),\n            round(item[\"x2\"] * width), round(item[\"y2\"] * height),\n            duration=0.3,\n        )\n    elif kind == \"text\":\n        device.send_keys(str(item.get(\"text\", \"\"))[:500])\n    elif kind == \"key\" and item.get(\"key\") in KEYCODES:\n        device.press(item[\"key\"])\n\n\ndef newest_code(messages, now_ms):\n    \"\"\"The newest code in messages of (sender, body, time in ms) from the last ten minutes.\"\"\"\n    for sender, body, at in sorted(messages, key=lambda message: message[2], reverse=True):\n        if now_ms - at > TEXT_WINDOW_MS:\n            continue\n        found = CODE_PATTERN.search(body)\n        if found:\n            return {\"code\": found.group(1), \"from\": sender[:80]}\n    return None\n\n\ndef parse_sms_rows(output):\n    \"\"\"`content query` rows: Row: 0 address=..., body=..., date=...\"\"\"\n    messages = []\n    for line in output.splitlines():\n        found = re.match(r\"^Row: \\d+ address=(.*?), body=(.*), date=(\\d+)\\s*$\", line.strip())\n        if found:\n            messages.append((found.group(1), found.group(2), int(found.group(3))))\n    return messages\n\n\ndef parse_notification_texts(output, now_ms):\n    \"\"\"Message notifications' text, from `dumpsys notification --noredact`.\"\"\"\n    messages = []\n    block_is_messages = False\n    title = \"\"\n    for line in output.splitlines():\n        stripped = line.strip()\n        if stripped.startswith(\"NotificationRecord(\"):\n            block_is_messages = bool(re.search(r\"pkg=\\S*(messaging|mms|sms)\", stripped))\n            title = \"\"\n        elif block_is_messages and stripped.startswith(\"android.title=\"):\n            title = re.sub(r\"^android\\.title=\\w+ \\((.*)\\)$\", r\"\\1\", stripped)\n        elif block_is_messages and stripped.startswith(\"android.text=\"):\n            text = re.sub(r\"^android\\.text=\\w+ \\((.*)\\)$\", r\"\\1\", stripped)\n            messages.append((title, text, now_ms))\n    return messages\n\n\n# A conversation row's time on the iPhone's Messages list: \"Now\" or a clock\n# time today. Yesterday, a weekday or a date is older than ten minutes.\nIOS_ROW_TIME = re.compile(r\"(?i)^(now|(\\d{1,2}):(\\d{2})\\s*(am|pm)?)$\")\n\n\ndef ios_cells(hierarchy_xml):\n    \"\"\"The words in each cell of an iPhone list, in screen order. A cell's\n    children carry them; a cell with none of its own has them joined in its\n    label, \"Reddit, Now, Your code is 482913\".\"\"\"\n    cells = []\n\n    def visit(node):\n        kind = node.get(\"type\") or node.get(\"class\") or \"\"\n        if kind.endswith(\"Cell\"):\n            words = [text for text in (node_words(child) for child in node.iter() if child is not node) if text]\n            if not words:\n                words = [part.strip() for part in node_words(node).split(\",\") if part.strip()]\n            if words:\n                cells.append(words)\n            return\n        for child in node:\n            visit(child)\n\n    visit(ElementTree.fromstring(hierarchy_xml))\n    return cells\n\n\ndef ios_row_time_ms(stamp, now_ms, local=time.localtime):\n    \"\"\"When a row marked \"Now\" or \"9:41 AM\" arrived, in ms. A clock time later\n    than now is yesterday's.\"\"\"\n    found = IOS_ROW_TIME.match(stamp)\n    if found.group(1).lower() == \"now\":\n        return now_ms\n    hour, minute, half = int(found.group(2)), int(found.group(3)), (found.group(4) or \"\").lower()\n    if half == \"pm\" and hour < 12:\n        hour += 12\n    if half == \"am\" and hour == 12:\n        hour = 0\n    today = local(now_ms / 1000)\n    at = int(time.mktime((today.tm_year, today.tm_mon, today.tm_mday, hour, minute, 0, 0, 0, -1)) * 1000)\n    if at > now_ms + 60 * 1000:\n        at -= 24 * 3600 * 1000\n    return at\n\n\ndef messages_from_ios_screen(hierarchy_xml, now_ms, local=time.localtime):\n    \"\"\"The conversations on the iPhone's Messages list as (sender, preview,\n    time in ms), only the rows from today, each a cell of sender, time and\n    the preview lines.\"\"\"\n    messages = []\n    for words in ios_cells(hierarchy_xml):\n        at = next((index for index, text in enumerate(words) if IOS_ROW_TIME.match(text)), None)\n        if at is None:\n            continue\n        rest = words[:at] + words[at + 1:]\n        if not rest:\n            continue\n        messages.append((rest[0], \" \".join(rest[1:]), ios_row_time_ms(words[at], now_ms, local)))\n    return messages\n\n\ndef read_iphone_texted_code(serial):\n    \"\"\"Opens Messages on the iPhone, reads the newest code off its list, and\n    goes home. iOS hands a computer neither the inbox nor the notifications,\n    so the screen is the only way; the caller makes sure the window is\n    watched with control on. Never while an action runs on the phone, since\n    opening Messages would land in the middle of its steps.\"\"\"\n    if action_running_on(serial):\n        return None\n    now_ms = int(time.time() * 1000)\n    device = iphone_screen(serial)\n    try:\n        device.app_start(IOS_MESSAGES)\n        time.sleep(1.5)\n        hierarchy = device.dump_hierarchy()\n    finally:\n        try:\n            device.press(\"home\")\n        except Exception:  # The phone went away; nothing more to tidy.\n            pass\n    return newest_code(messages_from_ios_screen(hierarchy, now_ms), now_ms)\n\n\ndef read_texted_code(serial):\n    \"\"\"The newest code texted to the phone, from its inbox or, if Android refuses that, its notifications.\"\"\"\n    if is_iphone(serial):\n        try:\n            return read_iphone_texted_code(serial)\n        except Exception as failure:  # No code read is no code shown.\n            log(\"Could not read Messages on %s: %s\" % (serial, short_words(failure)))\n            return None\n    now_ms = int(time.time() * 1000)\n    since = now_ms - TEXT_WINDOW_MS\n    try:\n        output = shell(\n            serial,\n            \"content query --uri content://sms/inbox --projection address:body:date --where \\\"date>%d\\\"\" % since,\n            timeout=10,\n        )\n        if \"Error\" not in output and \"Exception\" not in output:\n            return newest_code(parse_sms_rows(output), now_ms)\n    except (RuntimeError, subprocess.TimeoutExpired):\n        pass\n    try:\n        return newest_code(parse_notification_texts(shell(serial, \"dumpsys notification --noredact\", timeout=10), now_ms), now_ms)\n    except (RuntimeError, subprocess.TimeoutExpired):\n        return None\n\n\ndef screen_loop(config):\n    \"\"\"Runs for as long as the program does. A turn that fails for any reason\n    is logged and the next one tried, so screens never stop for good.\"\"\"\n    state = {\"wanted\": [], \"wall\": [], \"devices\": {}, \"sizes\": {}, \"texts_read_at\": {}, \"warned\": set(), \"wall_sent_at\": {}, \"control_at\": {}}\n    while True:\n        try:\n            gap = screen_turn(config, state)\n        except Exception as failure:  # Anything unforeseen; the loop must outlive it.\n            log(\"Screens stopped a turn: %s\" % failure)\n            gap = 10\n        time.sleep(gap)\n\n\ndef may_read_texts(serial, control_at, now, control=None):\n    \"\"\"Android's inbox is read over USB whenever the window is open. An\n    iPhone's Messages app has to be opened on its screen, so only while the\n    watcher has control on, never under an action, and never within\n    TAP_QUIET_SECONDS of a tap or key, since opening Messages and pressing\n    Home would cut across whatever the person is typing. Promo's reply names\n    the phones someone has control of (`control`); an older Promo that does\n    not is read as a tap within the last 15 minutes.\"\"\"\n    if not is_iphone(serial):\n        return True\n    if action_running_on(serial):\n        return False\n    since_tap = now - control_at.get(serial, 0)\n    if since_tap < TAP_QUIET_SECONDS:\n        return False\n    if control is not None:\n        return serial in control\n    return since_tap < CONTROL_HOLD_SECONDS\n\n\ndef take_frame(state, serial, lane, wide):\n    \"\"\"One picture of a phone for the frames list, or None when it gave none\n    (said once in the log until it does again).\"\"\"\n    devices, warned = state[\"devices\"], state[\"warned\"]\n    try:\n        device = devices.get(serial) or connect_screen(serial)\n        devices[serial] = device\n        jpeg, width, height = screen_frame(device, wide)\n    except Exception as failure:  # A phone pulled out mid-picture; try again next turn.\n        devices.pop(serial, None)\n        if serial not in warned:\n            log(\"No picture from %s: %s\" % (serial, failure))\n            warned.add(serial)\n        return None\n    warned.discard(serial)\n    return {\"serial\": serial, \"jpeg\": base64.b64encode(jpeg).decode(\"ascii\"), \"width\": width, \"height\": height, \"lane\": lane}\n\n\ndef screen_turn(config, state):\n    \"\"\"One turn: pictures and texted codes for the watched phones and a small\n    picture for each phone on the wall, out; which phones to watch, which\n    are on the wall, and the taps, back. Returns how long to wait.\"\"\"\n    devices, sizes, texts_read_at = state[\"devices\"], state[\"sizes\"], state[\"texts_read_at\"]\n    wall_sent_at = state.setdefault(\"wall_sent_at\", {})\n    control_at = state.setdefault(\"control_at\", {})\n    frames, texts = [], []\n    now = time.time()\n    for serial in state[\"wanted\"]:\n        frame = take_frame(state, serial, \"window\", SCREENSHOT_WIDTH)\n        if frame:\n            sizes[serial] = (frame[\"width\"], frame[\"height\"])\n            frames.append(frame)\n        gap = IPHONE_TEXT_GAP_SECONDS if is_iphone(serial) else TEXT_GAP_SECONDS\n        if now - texts_read_at.get(serial, 0) > gap and may_read_texts(serial, control_at, now, state.get(\"control\")):\n            texts_read_at[serial] = time.time()\n            code = read_texted_code(serial)\n            if code:\n                texts.append(dict(code, serial=serial))\n    # The wall's pictures ride on whichever turn is due; a window's turns are never slowed for them.\n    for serial in state.get(\"wall\") or []:\n        if now - wall_sent_at.get(serial, 0) < WALL_GAP_SECONDS:\n            continue\n        frame = take_frame(state, serial, \"wall\", WALL_WIDTH)\n        if frame:\n            wall_sent_at[serial] = now\n            frames.append(frame)\n\n    try:\n        reply = call(config, \"/api/rack/screen\", {\"frames\": frames, \"texts\": texts})\n    except (CallFailed, Refused) as failure:\n        log(\"Screens: %s\" % failure)\n        return 10\n    wanted = [serial for serial in reply.get(\"wanted\") or [] if isinstance(serial, str)]\n    wall = [serial for serial in reply.get(\"wall\") or [] if isinstance(serial, str)]\n    state[\"wanted\"] = wanted\n    state[\"wall\"] = wall\n    # Who has control, when Promo says; None keeps the older reading from taps.\n    if \"control\" in reply:\n        state[\"control\"] = [serial for serial in reply.get(\"control\") or [] if isinstance(serial, str)]\n    else:\n        state[\"control\"] = None\n\n    for serial, items in (reply.get(\"inputs\") or {}).items():\n        # Promo hands taps over only while control is on, so a tap is the\n        # word that it is.\n        control_at[serial] = time.time()\n        if serial not in sizes:\n            continue\n        for item in items:\n            try:\n                apply_input(serial, item, sizes[serial])\n            except (RuntimeError, subprocess.TimeoutExpired, KeyError, TypeError, ValueError) as failure:\n                log(\"A tap on %s did not go through: %s\" % (serial, failure))\n    for serial in list(devices):\n        if serial not in wanted and serial not in wall:\n            devices.pop(serial, None)\n    for serial in list(texts_read_at):\n        if serial not in wanted:\n            texts_read_at.pop(serial, None)\n            control_at.pop(serial, None)\n    for serial in list(wall_sent_at):\n        if serial not in wall:\n            wall_sent_at.pop(serial, None)\n    if wanted:\n        return SCREEN_GAP_SECONDS\n    return WALL_TURN_SECONDS if wall else IDLE_SCREEN_GAP_SECONDS\n\n\n# ---------------------------------------------------------------------------\n# Readings. Once a minute each phone's battery, heat, storage, SIM signal and\n# time since it started, and every ten minutes each app's version, in one adb\n# call each. The newest goes to Promo with the next check-in. A phone that\n# misses three readings in a row while adb still lists it has frozen, and is\n# restarted.\n\nVITALS_SECONDS = 60\nAPPS_SECONDS = 600\nUNANSWERED_LIMIT = 3\n\nVITALS_COMMAND = (\n    \"dumpsys battery; echo @@; df /data; echo @@; cat /proc/uptime; echo @@; \"\n    \"dumpsys telephony.registry | grep mServiceState=\"\n)\n\nSERVICE_WORDS = {\n    \"0\": \"in_service\", \"IN_SERVICE\": \"in_service\",\n    \"1\": \"out_of_service\", \"OUT_OF_SERVICE\": \"out_of_service\",\n    \"2\": \"emergency_only\", \"EMERGENCY_ONLY\": \"emergency_only\",\n    \"3\": \"power_off\", \"POWER_OFF\": \"power_off\",\n}\n\n_VITALS = {}\n_VITALS_LOCK = threading.Lock()\n\n\ndef as_number(value, whole=True):\n    try:\n        return int(round(float(value))) if whole else float(value)\n    except (TypeError, ValueError):\n        return None\n\n\ndef vitals_from_driver(raw):\n    \"\"\"The driver's reading in the check-in's shape. The driver speaks the\n    check-in's own key names; a few plainer ones are taken too. Signal is\n    \"not_reported\": Apple's channel does not give it, and nothing is guessed.\"\"\"\n    raw = raw if isinstance(raw, dict) else {}\n\n    def pick(*names):\n        for name in names:\n            if raw.get(name) is not None:\n                return raw[name]\n        return None\n\n    apps = raw.get(\"apps\")\n    return {\n        \"batteryPercent\": as_number(pick(\"batteryPercent\", \"battery\")),\n        \"temperatureC\": as_number(pick(\"temperatureC\", \"temperature\"), whole=False),\n        \"storageUsedPercent\": as_number(pick(\"storageUsedPercent\", \"storage\")),\n        \"signal\": str(raw.get(\"signal\") or \"not_reported\"),\n        \"upSeconds\": as_number(pick(\"upSeconds\", \"uptime\")),\n        \"apps\": dict((str(app), str(version)) for app, version in apps.items()) if isinstance(apps, dict) else None,\n        \"restartWhy\": \"\",\n    }\n\n\ndef iphone_vitals(serial):\n    \"\"\"The minute's reading of an iPhone, through the driver.\"\"\"\n    if iphone is None:\n        raise RuntimeError(\"The iPhone driver (iphone.py) is not beside the program.\")\n    return vitals_from_driver(iphone.vitals(serial))\n\n\ndef iphone_app_versions(serial):\n    \"\"\"Each tracked app's version on an iPhone through the driver's\n    app_versions(udid); None (not read) when the phone could not be asked.\"\"\"\n    versions = iphone.app_versions(serial)\n    return dict((str(app), str(version)) for app, version in versions.items()) if isinstance(versions, dict) else None\n\n\ndef service_state(lines):\n    \"\"\"The best service any SIM slot has: in service beats the rest.\"\"\"\n    found = []\n    for line in lines:\n        for match in re.finditer(r\"m(?:Voice|Data)RegState=(\\d)(?:\\((\\w+)\\))?\", line):\n            found.append(SERVICE_WORDS.get(match.group(2) or match.group(1), \"\"))\n        # Older Androids print the voice state first: mServiceState=0 1 ...\n        old = re.match(r\"^\\s*mServiceState=(\\d)\\s\", line)\n        if old:\n            found.append(SERVICE_WORDS.get(old.group(1), \"\"))\n    found = [word for word in found if word]\n    if \"in_service\" in found:\n        return \"in_service\"\n    return found[0] if found else \"\"\n\n\ndef parse_vitals(output):\n    parts = (output.split(\"@@\") + [\"\", \"\", \"\", \"\"])[:4]\n    battery, storage, uptime, telephony = parts\n    level = re.search(r\"^\\s*level:\\s*(\\d+)\", battery, re.M)\n    temperature = re.search(r\"^\\s*temperature:\\s*(-?\\d+)\", battery, re.M)\n    used = None\n    rows = [line.split() for line in storage.strip().splitlines()[1:]]\n    if rows and len(rows[-1]) >= 4 and rows[-1][2].isdigit() and rows[-1][3].isdigit():\n        total = int(rows[-1][2]) + int(rows[-1][3])\n        used = round(100 * int(rows[-1][2]) / total) if total else None\n    up = uptime.split()\n    return {\n        \"batteryPercent\": int(level.group(1)) if level else None,\n        # dumpsys reports tenths of a degree.\n        \"temperatureC\": int(temperature.group(1)) / 10 if temperature else None,\n        \"storageUsedPercent\": used,\n        \"signal\": service_state(telephony.splitlines()),\n        \"upSeconds\": int(float(up[0])) if up and re.match(r\"^[\\d.]+$\", up[0]) else None,\n        \"apps\": None,\n        \"restartWhy\": \"\",\n    }\n\n\ndef keep_reading(serial, reading):\n    \"\"\"Holds the newest reading for the next check-in. A restart's reason or\n    app versions still waiting to be sent are carried onto it.\"\"\"\n    with _VITALS_LOCK:\n        waiting = _VITALS.get(serial)\n        if waiting and waiting.get(\"restartWhy\") and not reading.get(\"restartWhy\"):\n            reading[\"restartWhy\"] = waiting[\"restartWhy\"]\n        if waiting and waiting.get(\"apps\") is not None and reading.get(\"apps\") is None:\n            reading[\"apps\"] = waiting[\"apps\"]\n        _VITALS[serial] = reading\n\n\ndef put_back_reading(serial, reading):\n    \"\"\"A reading Promo did not receive goes back, unless a newer one is already\n    waiting, which then carries its restart reason and app versions.\"\"\"\n    with _VITALS_LOCK:\n        newer = _VITALS.get(serial)\n        if newer is None:\n            _VITALS[serial] = reading\n            return\n        if reading.get(\"restartWhy\") and not newer.get(\"restartWhy\"):\n            newer[\"restartWhy\"] = reading[\"restartWhy\"]\n        if reading.get(\"apps\") is not None and newer.get(\"apps\") is None:\n            newer[\"apps\"] = reading[\"apps\"]\n\n\ndef take_reading(serial):\n    with _VITALS_LOCK:\n        return _VITALS.pop(serial, None)\n\n\ndef vitals_turn(state, now=None):\n    now = now or time.time()\n    for phone in parse_devices(adb([\"devices\", \"-l\"], timeout=15)) + list_iphones_safely():\n        serial = phone[\"serial\"]\n        if phone[\"state\"] != \"device\" or now - state[\"read_at\"].get(serial, 0) < VITALS_SECONDS:\n            continue\n        state[\"read_at\"][serial] = now\n        an_iphone = phone.get(\"kind\") == \"iphone\"\n        if an_iphone:\n            _KINDS[serial] = \"iphone\"\n        else:\n            # The apps' notifications, read without opening an app; only which\n            # app and whether it was a message or a comment go to Promo. An\n            # iPhone hands a computer no notifications, so it has none here.\n            try:\n                keep_alerts(serial, new_alerts(shell(serial, \"dumpsys notification --noredact\", timeout=15), state[\"alerts\"].setdefault(serial, collections.OrderedDict())))\n            except Exception as failure:  # The vitals are still read this turn.\n                log(\"Could not read the notifications on %s: %s\" % (serial, failure))\n        try:\n            if an_iphone:\n                reading = iphone_vitals(serial)\n                if now - state[\"apps_at\"].get(serial, 0) >= APPS_SECONDS:\n                    reading[\"apps\"] = iphone_app_versions(serial)\n                    state[\"apps_at\"][serial] = now\n            else:\n                reading = parse_vitals(shell(serial, VITALS_COMMAND, timeout=20))\n                if now - state[\"apps_at\"].get(serial, 0) >= APPS_SECONDS:\n                    reading[\"apps\"] = parse_app_versions(shell(serial, APPS_COMMAND, timeout=30))\n                    state[\"apps_at\"][serial] = now\n        except Exception as failure:  # adb's refusal, or the driver's; three in a row is a frozen phone.\n            missed = state[\"missed\"].get(serial, 0) + 1\n            state[\"missed\"][serial] = missed\n            log(\"No reading from %s (%d in a row): %s\" % (serial, missed, failure))\n            if missed >= UNANSWERED_LIMIT:\n                state[\"missed\"][serial] = 0\n                restart_phone(serial, \"It stopped answering for three minutes, so the rack restarted it.\")\n            continue\n        state[\"missed\"][serial] = 0\n        # The reason for a restart the rack did goes with the first reading\n        # taken after it, which is the one Promo sees the time-since-start drop in.\n        with _RESTART_LOCK:\n            restarted_at = _RESTARTED_AT.get(serial, 0)\n            if serial in _RESTART_WHY and reading[\"upSeconds\"] is not None and reading[\"upSeconds\"] < now - restarted_at + 30:\n                reading[\"restartWhy\"] = _RESTART_WHY.pop(serial)\n        keep_reading(serial, reading)\n\n\ndef vitals_loop():\n    \"\"\"Runs for as long as the program does; a turn that fails is logged and the next one tried.\"\"\"\n    state = {\"read_at\": {}, \"apps_at\": {}, \"missed\": {}, \"alerts\": {}}\n    while True:\n        try:\n            vitals_turn(state)\n        except Exception as failure:  # Anything unforeseen; the loop must outlive it.\n            log(\"Readings stopped a turn: %s\" % failure)\n        time.sleep(5)\n\n\n# ---------------------------------------------------------------------------\n# The loop\n\ndef platform_name():\n    if sys.platform == \"darwin\":\n        return (\"macOS %s\" % platform.mac_ver()[0]).strip()\n    return platform.system() or sys.platform\n\n\ndef check_in(config):\n    state = load_state()\n    note = state.get(\"rolledBack\")\n    phones = list_phones()\n    taken = {}\n    alerted = {}\n    for phone in phones:\n        reading = take_reading(phone[\"serial\"]) if phone[\"state\"] == \"device\" else None\n        if reading:\n            phone[\"vitals\"] = taken[phone[\"serial\"]] = reading\n        alerts = take_alerts(phone[\"serial\"]) if phone[\"state\"] == \"device\" else []\n        if alerts:\n            phone[\"alerts\"] = alerted[phone[\"serial\"]] = alerts\n    try:\n        reply = call(config, \"/api/rack/check-in\", {\n            \"version\": VERSION,\n            \"platform\": platform_name(),\n            \"phones\": phones,\n            \"rolledBack\": note if isinstance(note, dict) else None,\n            # When WebDriverAgent's signature runs out, so the bell can warn\n            # the day before (part 49); null on a rack without iPhones.\n            \"wdaExpiresAt\": wda_expires_at(),\n        })\n    except (CallFailed, Refused):\n        # Not received, so the readings and alerts wait for the next check-in.\n        for serial, reading in taken.items():\n            put_back_reading(serial, reading)\n        for serial, alerts in alerted.items():\n            keep_alerts(serial, alerts)\n        raise\n    # Tells the launcher this version works, so it stops watching it.\n    if state.get(\"checkedIn\") != VERSION or state.get(\"pending\"):\n        update_state(checkedIn=VERSION, pending=None)\n    return reply\n\n\ndef install_update(config, latest):\n    \"\"\"Downloads a version Promo offers, checks it, and switches to it.\"\"\"\n    release = call(config, \"/api/rack/release\", {\"version\": latest})\n    source = release.get(\"source\") or \"\"\n    if release.get(\"version\") != latest:\n        raise CallFailed(\"Promo offered %s but sent %s.\" % (latest, release.get(\"version\")))\n    if sha256_hex(source.encode(\"utf-8\")) != release.get(\"sha256\"):\n        raise CallFailed(\"The download of %s did not match its checksum.\" % latest)\n    if ('VERSION = \"%s\"' % latest) not in source:\n        raise CallFailed(\"The download of %s does not say it is %s.\" % (latest, latest))\n    # The iPhone driver travels with the program, checked the same way, so\n    # `import iphone` finds it beside the new version. A Promo from before\n    # iPhones sends none, and the program is installed alone.\n    driver = release.get(\"driver\")\n    if driver is not None:\n        if not isinstance(driver, str) or sha256_hex(driver.encode(\"utf-8\")) != release.get(\"driverSha256\"):\n            raise CallFailed(\"The download of %s's iPhone driver did not match its checksum.\" % latest)\n    folder = os.path.join(HOME, \"versions\", latest)\n    os.makedirs(folder, exist_ok=True)\n    with open(os.path.join(folder, \"promo_rack.py\"), \"w\", encoding=\"utf-8\") as handle:\n        handle.write(source)\n    if driver is not None:\n        with open(os.path.join(folder, \"iphone.py\"), \"w\", encoding=\"utf-8\") as handle:\n            handle.write(driver)\n    update_state(\n        previous=VERSION,\n        current=latest,\n        pending={\"version\": latest, \"since\": time.time()},\n        rolledBack=None,\n    )\n    log(\"Installed %s. Restarting on it.\" % latest)\n    sys.exit(EXIT_SWITCH)\n\n\n# The actions running now, so the program never switches version under one,\n# and the phones they run on, so nothing else opens an app on one meanwhile.\n_RUNNING = set()\n_RUNNING_SERIALS = {}\n_RUNNING_LOCK = threading.Lock()\n\n\ndef start_action(config, action):\n    \"\"\"Runs one action on a thread of its own, so another phone's can start meanwhile.\"\"\"\n    serial = str(action.get(\"serial\") or \"\")\n    with _RUNNING_LOCK:\n        _RUNNING.add(action[\"id\"])\n        _RUNNING_SERIALS[serial] = _RUNNING_SERIALS.get(serial, 0) + 1\n\n    def work():\n        try:\n            run_action(config, action)\n        finally:\n            with _RUNNING_LOCK:\n                _RUNNING.discard(action[\"id\"])\n                left = _RUNNING_SERIALS.get(serial, 1) - 1\n                if left > 0:\n                    _RUNNING_SERIALS[serial] = left\n                else:\n                    _RUNNING_SERIALS.pop(serial, None)\n\n    threading.Thread(target=work, name=\"action-%s\" % action[\"id\"][:8], daemon=True).start()\n\n\ndef actions_running():\n    with _RUNNING_LOCK:\n        return len(_RUNNING)\n\n\ndef action_running_on(serial):\n    with _RUNNING_LOCK:\n        return _RUNNING_SERIALS.get(serial, 0) > 0\n\n\n# The rack's log inside Promo (phone farm part 61): when the reply to\n# /api/rack/next says sendLog, the last lines of rack.log go to\n# /api/rack/log, signed like every call, on a thread of their own so the\n# action poll is not held up. Never the whole file, and never more than once\n# at a time.\nLOG_LINES = 300\nLOG_LINE_CHARS = 2000\n# How much of the file's end is read to find the last lines.\nLOG_TAIL_BYTES = 2 * 1024 * 1024\n_LOG_LOCK = threading.Lock()\n\n\ndef last_log_lines(path=None, count=LOG_LINES):\n    \"\"\"The last `count` lines of the log, each cut to LOG_LINE_CHARS. No file\n    (Linux keeps the log in the journal) is no lines.\"\"\"\n    path = path or LOG_PATH\n    try:\n        with open(path, \"rb\") as handle:\n            handle.seek(0, os.SEEK_END)\n            size = handle.tell()\n            start = max(0, size - LOG_TAIL_BYTES)\n            handle.seek(start)\n            text = handle.read().decode(\"utf-8\", \"replace\")\n    except OSError:\n        return []\n    lines = text.splitlines()\n    if start > 0 and lines:\n        lines = lines[1:]  # A line cut in half by where the read began.\n    return [line[:LOG_LINE_CHARS] for line in lines[-count:]]\n\n\ndef send_log(config):\n    if not _LOG_LOCK.acquire(False):\n        return False\n    try:\n        call(config, \"/api/rack/log\", {\"lines\": last_log_lines()})\n        return True\n    except (CallFailed, Refused) as failure:\n        log(\"Could not send the log to Promo: %s\" % failure)\n        return False\n    finally:\n        _LOG_LOCK.release()\n\n\ndef maybe_send_log(config, reply):\n    \"\"\"Starts the log post when the action poll's reply asks for it. Returns the thread, or None.\"\"\"\n    if not (isinstance(reply, dict) and reply.get(\"sendLog\")):\n        return None\n    thread = threading.Thread(target=send_log, args=(config,), name=\"log\", daemon=True)\n    thread.start()\n    return thread\n\n\ndef run_action(config, action):\n    name = action.get(\"action\", \"\")\n    serial = action.get(\"serial\", \"\")\n    walk = Walk(serial)\n    ok, result, error, recovered = False, None, \"\", \"\"\n    handler = ACTIONS.get(name)\n    if handler is None:\n        error = \"This rack does not know the action %s.\" % name\n    else:\n        ok, result, error, recovered = run_watched(handler, serial, action, walk)\n    ban = ban_screen_on(serial, action_app(name)) if action_app(name) else None\n    log(\"%s on %s: %s\" % (name, serial, \"done\" if ok else error))\n    answer = {\n        \"id\": action[\"id\"],\n        \"ok\": ok,\n        \"result\": result,\n        \"error\": error,\n        \"steps\": [{\"step\": step, \"jpeg\": base64.b64encode(jpeg).decode(\"ascii\")} for step, jpeg in capped(list(walk.steps))],\n        \"banScreen\": ban,\n        \"recovered\": recovered,\n    }\n    # The answer is worth a few tries: a comment that went out must be\n    # reported, or Promo calls it failed when it was not.\n    for attempt in range(5):\n        try:\n            call(config, \"/api/rack/result\", answer)\n            return\n        except (CallFailed, Refused) as failure:\n            log(\"Could not hand in the answer to %s (%s). %s\" % (name, attempt + 1, failure))\n            time.sleep(5)\n\n\n# Promo keeps at most this many pictures an action.\nMAX_STEPS = 30\n\n\ndef capped(steps):\n    \"\"\"The first steps and the last, where an action stopped, when there are too many.\"\"\"\n    return steps if len(steps) <= MAX_STEPS else steps[:MAX_STEPS - 1] + steps[-1:]\n\n\n# However short an action's time, it gets at least this long before it counts as frozen.\nMIN_WATCH_SECONDS = 30\n\n\ndef watch_seconds(action):\n    \"\"\"How long an action may run here: its time in Promo, less a margin to reopen the app.\"\"\"\n    return max(MIN_WATCH_SECONDS, int(action.get(\"timeoutSeconds\") or 300) - FREEZE_MARGIN_SECONDS)\n\n\ndef run_watched(handler, serial, action, walk):\n    \"\"\"Runs one action, giving up on it shortly before Promo would.\n\n    Returns (ok, result, error, recovered). A frozen action's thread is left\n    behind; its Walk is cancelled, so it presses nothing more if it wakes.\n    \"\"\"\n    name = action.get(\"action\", \"\")\n    outcome = {}\n\n    def work():\n        try:\n            outcome[\"result\"] = handler(serial, action.get(\"args\") or {}, walk)\n        except Exception as failure:  # Reported below either way.\n            outcome[\"error\"] = failure\n\n    worker = threading.Thread(target=work, name=\"steps-%s\" % action[\"id\"][:8], daemon=True)\n    worker.start()\n    worker.join(watch_seconds(action))\n    if worker.is_alive():\n        walk.cancelled.set()\n        recovered, words = recover_frozen(serial, name)\n        return False, None, words, recovered\n    if \"error\" not in outcome:\n        return True, outcome.get(\"result\"), \"\", \"\"\n    failure = outcome[\"error\"]\n    error = str(failure) or failure.__class__.__name__\n    closed = close_not_responding(serial, name) if action_package(name) else \"\"\n    return False, None, (\"%s %s\" % (error, closed)).strip(), \"app\" if closed else \"\"\n\n\ndef run():\n    config = read_json(CONFIG_PATH, None)\n    if not config:\n        log(\"This rack is not paired. Run the install command from the Phones dashboard.\")\n        sys.exit(1)\n    log(\"Promo rack %s started, talking to %s.\" % (VERSION, config[\"url\"]))\n    threading.Thread(target=screen_loop, args=(config,), name=\"screens\", daemon=True).start()\n    threading.Thread(target=vitals_loop, name=\"readings\", daemon=True).start()\n    interval = DEFAULT_CHECK_IN_SECONDS\n    last_check_in = 0.0\n    while True:\n        current = load_state().get(\"current\")\n        if current and current != VERSION and not actions_running():\n            log(\"Switching to %s.\" % current)\n            sys.exit(EXIT_SWITCH)\n        try:\n            if time.time() - last_check_in >= interval:\n                reply = check_in(config)\n                last_check_in = time.time()\n                interval = int(reply.get(\"checkInSeconds\") or DEFAULT_CHECK_IN_SECONDS)\n                latest = reply.get(\"latestVersion\")\n                # Never under a running action: it would be cut off half-way.\n                if (\n                    latest\n                    and latest != VERSION\n                    and latest not in (load_state().get(\"failed\") or [])\n                    and not actions_running()\n                ):\n                    install_update(config, latest)\n            reply = call(config, \"/api/rack/next\", {})\n            maybe_send_log(config, reply)\n            learn_phrases(reply)\n            work = reply.get(\"action\")\n            if work:\n                start_action(config, work)\n                continue\n            time.sleep(POLL_SECONDS)\n        except Refused as refusal:\n            log(\"Promo refused this rack: %s Trying again in a minute.\" % refusal)\n            time.sleep(60)\n        except (CallFailed, RuntimeError, subprocess.TimeoutExpired) as failure:\n            log(str(failure))\n            time.sleep(10)\n\n\ndef pair(url, code, name):\n    body = json.dumps({\n        \"code\": code,\n        \"name\": name,\n        \"platform\": platform_name(),\n        \"version\": VERSION,\n    }).encode(\"utf-8\")\n    request = urllib.request.Request(\n        url.rstrip(\"/\") + \"/api/rack/pair\",\n        data=body,\n        method=\"POST\",\n        headers={\"content-type\": \"application/json\"},\n    )\n    try:\n        with urllib.request.urlopen(request, timeout=HTTP_TIMEOUT_SECONDS) as response:\n            answer = json.loads(response.read().decode(\"utf-8\"))\n    except urllib.error.HTTPError as error:\n        print(answer_message(error.read()) or \"Promo refused the code.\", file=sys.stderr)\n        sys.exit(1)\n    except (urllib.error.URLError, OSError) as error:\n        print(\"Could not reach Promo at %s: %s\" % (url, error), file=sys.stderr)\n        sys.exit(1)\n    write_json(CONFIG_PATH, {\"url\": url.rstrip(\"/\"), \"rackId\": answer[\"rackId\"], \"key\": answer[\"key\"]}, private=True)\n    update_state(current=VERSION, previous=None, pending=None, checkedIn=None, rolledBack=None)\n    print(\"Paired with %s as %s.\" % (url, name))\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Promo's rack program.\")\n    commands = parser.add_subparsers(dest=\"command\", required=True)\n    pairing = commands.add_parser(\"pair\", help=\"Swap a one-time code from the Phones dashboard for this rack's key.\")\n    pairing.add_argument(\"--url\", required=True)\n    pairing.add_argument(\"--code\", required=True)\n    pairing.add_argument(\"--name\", default=platform.node() or \"Rack\")\n    commands.add_parser(\"run\", help=\"Check in and run actions until stopped.\")\n    commands.add_parser(\"phones\", help=\"Print the phones adb can see.\")\n    arguments = parser.parse_args()\n    if arguments.command == \"pair\":\n        pair(arguments.url, arguments.code, arguments.name)\n    elif arguments.command == \"phones\":\n        print(json.dumps(list_phones(), indent=2))\n    else:\n        run()\n\n\nif __name__ == \"__main__\":\n    main()\n",
} as const
